                    {nepseChange >= 0 ? '▲ +' : '▼ -'}{Math.abs(Number(indices?.nepse?.change || 0)).toFixed(2)} pts ({nepseChange >= 0 ? '+' : '-'}{Math.abs(Number(indices?.nepse?.pChange || 0)).toFixed(2)}%)
