      if (s.wyckoff?.earlySignals?.effortVsResult?.churnRisk === 'HIGH_DISTRIBUTION_CHURN' || s.wyckoff?.earlySignals?.earlyAlertVerdict === 'EARLY_DISTRIBUTION_CHURN') {
