      }

      if (s.isTrap || s.isDumping) step4TrapCount++;
      else if (s.isAccumulation) step4AccumulationCount++;
    });

    const avgCMF = analyzedStocks.length > 0 ? totalCMF / analyzedStocks.length : 0;
    return {
      stealthCount,
