  const loadStockRetention = async (sym: string, force = false, asOfDate?: string) => {
    const targetSym = (sym || selectedStockRetention || 'BARUN').toUpperCase().trim();
    if (!targetSym) return;
    const effDate = asOfDate !== undefined ? asOfDate : (sessionDateFilter || '');
    setLoadingRetention(true);
    try {
      const res: any = await fetchBrokerAnalysis(targetSym, 'all', { refresh: force, days: 'all', date: effDate || undefined });
      // Robust unwrap: handle when res has topHoldings, or res.data has topHoldings, or res is already data
      let payload: any = (res && Array.isArray(res.topHoldings) && res.topHoldings.length > 0)
        ? res
        : (res?.data && Array.isArray(res.data.topHoldings) && res.data.topHoldings.length > 0)
          ? res.data
          : (res && (Array.isArray(res.brokers) || Array.isArray(res.allBrokers) || res.symbol))
            ? res
            : (res?.data || res);

      // Fallback: If network analysis returned nothing, synthesize retention directly from heatmapData scrips
      if (!payload && heatmapData?.matrix) {
        const brokersWithScrip: any[] = [];
        heatmapData.matrix.forEach((b: any) => {
          const scrips = Array.isArray(b.scrips) ? b.scrips : [];
          const match = scrips.find((s: any) => String(s.symbol || '').toUpperCase() === targetSym);
          if (match && ((match.buyQty || match.buy || 0) > 0 || (match.sellQty || match.sell || 0) > 0)) {
            const netKitta = Number(match.netQty || match.buyQty || 0);
            brokersWithScrip.push({
              id: String(b.broker || b.id || ''),
              brokerId: String(b.broker || b.id || ''),
              brokerName: b.brokerName || `Broker #${b.broker}`,
              netQty: netKitta,
              holdQty: netKitta,
              totalBuyVol: Number(match.buyQty || 0),
              totalSellVol: Number(match.sellQty || 0),
              avgBuyRate: Number(match.avgBuyRate || 0)
            });
          }
        });
        if (brokersWithScrip.length > 0) {
          brokersWithScrip.sort((a, b) => b.netQty - a.netQty);
          const totalHeld = brokersWithScrip.reduce((sum, b) => sum + Math.max(0, b.netQty), 0);
          payload = {
            symbol: targetSym,
            totalSharesHeldTillNow: totalHeld,
            topHoldings: brokersWithScrip.map(b => ({
              ...b,
              holdingSharePct: totalHeld > 0 ? Number(((Math.max(0, b.netQty) / totalHeld) * 100).toFixed(2)) : 0
            }))
          };
        }
      }

      if (payload) {
        // Guarantee topHoldings is always populated from positive net accumulators
        if (!Array.isArray(payload.topHoldings) || payload.topHoldings.length === 0) {
          const rawBrokers = Array.isArray(payload.brokers)
            ? payload.brokers
            : (Array.isArray(payload.allBrokers) ? payload.allBrokers : (Array.isArray(payload.data) ? payload.data : (Array.isArray(payload) ? payload : [])));

          const accumulators = rawBrokers
            .filter((b: any) => Number(b.netQty ?? b.holdQty ?? b.netVolume ?? 0) > 0)
            .sort((a: any, b: any) => Number(b.netQty ?? b.holdQty ?? b.netVolume ?? 0) - Number(a.netQty ?? a.holdQty ?? a.netVolume ?? 0));

          const totalHeld = accumulators.reduce((sum: number, b: any) => sum + Number(b.netQty ?? b.holdQty ?? b.netVolume ?? 0), 0);

          payload.topHoldings = accumulators.map((b: any) => {
            const bId = String(b.brokerId || b.id || b.broker || '');
            const netKitta = Number(b.netQty ?? b.holdQty ?? b.netVolume ?? 0);
            return {
              ...b,
              id: bId,
              brokerId: bId,
              name: b.brokerName || b.name,
              brokerName: b.brokerName || b.name,
              netQty: netKitta,
              holdQty: netKitta,
              holdingSharePct: totalHeld > 0 ? Number(((netKitta / totalHeld) * 100).toFixed(2)) : 0
            };
          });
          payload.totalSharesHeldTillNow = totalHeld;
        }

        if (!payload.symbol) payload.symbol = targetSym;
        setStockRetentionData(payload);
      } else {
        setStockRetentionData(null);
      }
    } catch (err) {
      console.error('Failed to load stock retention:', err);
      setStockRetentionData(null);
    } finally {
      setLoadingRetention(false);
    }
  };

  useEffect(() => {
    if (activeMode === 'stockRetention' && retentionViewType === 'byStock' && selectedStockRetention) {
      loadStockRetention(selectedStockRetention, false, sessionDateFilter);
