    text += `📊 Total Retained Kitta (Net Accumulators): ${totalHeld.toLocaleString()} kitta\n`;
    text += `━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
    topHoldings.slice(0, 10).forEach((b: any, idx: number) => {
