  const handleCopySocialCard = () => {
    let text = '';
    if (brokerWiseTab === 'whole_day_net') {
      text = `🔥 TOP 10 NET BOUGHT STOCKS (WHOLE DAY)\n`;
      text += `📅 As of ${sessionDate}\n`;
