          const top3Str = st.top3Accumulators.map((a: any) => `B#${a.broker}: +${Number(a.netQty).toLocaleString()} (${a.shareOfLockPct || 0}%) @ Rs. ${a.avgBuyRate}`).join(' | ');
          text += `   • Top 3: ${top3Str}\n`;
