                        <th className="py-2 px-3">Date</th>
                        <th className="py-2 px-3 text-right">Buy Qty</th>
                        <th className="py-2 px-3 text-right">Sell Qty</th>
                        <th className="py-2 px-3 text-right">Net Qty</th>
                        <th className="py-2 px-3 text-right">Broker Rate</th>
                        <th className="py-2 px-3 text-right">Close LTP</th>
                        <th className="py-2 px-3 text-center">Cycle Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/40 font-mono text-[11px]">
                      {[...(inspectedStock.dailySeries || [])]
                        .sort((a, b) => (b.date || '').localeCompare(a.date || ''))
                        .map((day, idx) => {
                          const isBuy = day.netVol > 0;
                          const isStart = day.date === inspectedStock.actionStartDate;
                          return (
                            <tr key={day.date || idx} className={`hover:bg-slate-800/40 ${isStart ? 'bg-amber-500/10' : ''}`}>
                              <td className="py-2 px-3 font-bold text-white flex items-center gap-1.5">
                                {day.date}
                                {isStart && (
                                  <span className="px-1 py-0.2 rounded bg-amber-500/20 text-amber-300 text-[9px] font-sans font-bold border border-amber-500/30">
                                    Cycle Start
                                  </span>
                                )}
                              </td>
                              <td className="py-2 px-3 text-right text-slate-300">{day.buyVol.toLocaleString()}</td>
                              <td className="py-2 px-3 text-right text-slate-400">{day.sellVol.toLocaleString()}</td>
                              <td className={`py-2 px-3 text-right font-black ${isBuy ? 'text-emerald-400' : 'text-rose-400'}`}>
                                {day.netVol > 0 ? '+' : ''}{day.netVol.toLocaleString()}
                              </td>
                              <td className="py-2 px-3 text-right text-slate-200">
                                {day.avgBuyPrice ? `Rs. ${day.avgBuyPrice}` : '—'}
                              </td>
                              <td className="py-2 px-3 text-right text-slate-300">
                                {day.close ? `Rs. ${day.close}` : '—'}
                              </td>
                              <td className="py-2 px-3 text-center font-sans text-[10px]">
                                {isBuy ? (
                                  <span className="text-emerald-400 font-bold">Accumulating</span>
                                ) : day.netVol < 0 ? (
                                  <span className="text-rose-400 font-bold">Dumping</span>
                                ) : (
                                  <span className="text-slate-500">Neutral</span>
                                )}
                              </td>
                            </tr>
                          );
                        })}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="flex items-center justify-between p-4 border-t border-slate-800 bg-slate-950/80">
              <span className="text-xs text-slate-400">
                Verified against 32-day NEPSE exchange ledger
              </span>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => {
                    onSelectStock?.(inspectedStock);
                    setInspectedStock(null);
                  }}
                  className="px-4 py-2 bg-emerald-500 hover:bg-emerald-400 text-slate-950 font-bold text-xs rounded-xl shadow-md transition-all flex items-center gap-1.5"
                >
                  <ExternalLink className="w-3.5 h-3.5" />
                  Open Full Stock Analytics
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { calculateBuyDetails, calculateSellDetails, adjustForBonusShare, adjustForRightShare, adjustSimultaneousBonusAndRight, auditBonusDilution } from '../utils/calculations';
import { HelpCircle, Copy, Check, Calculator as CalcIcon, Percent, TrendingUp, Sparkles, RefreshCw, AlertTriangle, ShieldCheck, Shield } from 'lucide-react';
import { calculatePositionSize, calculateStopLossTargets, calculateNetProfit, formatRiskReward } from '../utils/riskManagement';
import CapitalRiskSimulatorBar from './CapitalRiskSimulatorBar';
import { getUserConfiguredCapital, setUserConfiguredCapital } from '../utils/dynamicCapitalEngine';

export default function Calculator() {
  const [activeTab, setActiveTab] = useState('buy');
  const [copiedBuyWacc, setCopiedBuyWacc] = useState(false);

  // ── 1. Buy State ──
  const [buyQty, setBuyQty] = useState(100);
  const [buyPrice, setBuyPrice] = useState(250);
  const [buyResult, setBuyResult] = useState(null);

  // ── 2. Sell State ──
  const [sellQty, setSellQty] = useState(100);
  const [sellPrice, setSellPrice] = useState(300);
  const [buyWacc, setBuyWacc] = useState(250);
  const [holdingType, setHoldingType] = useState('short'); // 'short' (7.5% - Individual <= 365d), 'long' (5.0% - Individual > 365d), 'institutional' (10.0%)
  const [sellResult, setSellResult] = useState(null);

  // ── 3. Bonus & Right Adjustment State ──
  const [adjLtp, setAdjLtp] = useState(450);
  const [bonusPct, setBonusPct] = useState(10);
  const [rightPct, setRightPct] = useState(0);
  const [rightIssuePrice, setRightIssuePrice] = useState(100);
  const [userShares, setUserShares] = useState(100);

  // ── 4. SIP & Wealth Compounder State ──
  const [sipMonthly, setSipMonthly] = useState(10000);
  const [sipReturnRate, setSipReturnRate] = useState(15);
  const [sipYears, setSipYears] = useState(10);

  // ── 5. Margin Loan State (NRB Directive) ──
  const [marginUnits, setMarginUnits] = useState(1000);
  const [marginLtp, setMarginLtp] = useState(600);
  const [marginAvg180, setMarginAvg180] = useState(550);
  const [marginLtv, setMarginLtv] = useState(70);
  const [marginRate, setMarginRate] = useState(9.5);
  const [marginMaintenance, setMarginMaintenance] = useState(130);
  const [borrowerType, setBorrowerType] = useState('individual');

  // ── 6. Position Sizing & Risk Management State ──
  const [riskCapital, setRiskCapital] = useState(() => getUserConfiguredCapital());
  const [riskPercent, setRiskPercent] = useState(2);
  const [riskEntryPrice, setRiskEntryPrice] = useState(480);
  const [riskStopLoss, setRiskStopLoss] = useState(455);
  const [riskTargetPrice, setRiskTargetPrice] = useState(530);
  const [riskInvestorType, setRiskInvestorType] = useState('individual');

  useEffect(() => {
    const handleCap = (e) => {
      if (e.detail?.userCapital) {
        setRiskCapital(e.detail.userCapital);
      }
    };
    window.addEventListener('nepse_capital_updated', handleCap);
    return () => window.removeEventListener('nepse_capital_updated', handleCap);
  }, []);

  // Update Buy/Sell calculations
  useEffect(() => {
    const q = Number(buyQty) || 0;
    const p = Number(buyPrice) || 0;
    if (q > 0 && p > 0) {
      setBuyResult(calculateBuyDetails(q, p));
    } else {
      setBuyResult(null);
    }
  }, [buyQty, buyPrice]);

  useEffect(() => {
    const q = Number(sellQty) || 0;
    const p = Number(sellPrice) || 0;
    const w = Number(buyWacc) || 0;
    if (q > 0 && p > 0 && w > 0) {
      setSellResult(calculateSellDetails(q, p, w, holdingType));
    } else {
      setSellResult(null);
    }
  }, [sellQty, sellPrice, buyWacc, holdingType]);

  const formatRs = (value) => {
    if (value == null || isNaN(value)) return 'Rs. 0.00';
    return new Intl.NumberFormat('en-NP', {
      style: 'currency',
      currency: 'NPR',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(value).replace('NPR', 'Rs.');
  };

  const handleCopyBuyWacc = () => {
    if (!buyResult) return;
    navigator.clipboard.writeText(buyResult.costPerShare.toFixed(2));
    setCopiedBuyWacc(true);
    setTimeout(() => setCopiedBuyWacc(false), 2000);
  };

  // ── Break-Even Calculation ──
  const breakEvenResult = useMemo(() => {
    if (sellQty <= 0 || buyWacc <= 0) return null;

    let low = buyWacc;
    let high = buyWacc * 2 + 50;
    let breakEvenPrice = buyWacc;

    for (let i = 0; i < 60; i++) {
      const mid = (low + high) / 2;
      const sellDetails = calculateSellDetails(sellQty, mid, buyWacc, holdingType);
      if (sellDetails.netProfitLoss >= 0) {
        breakEvenPrice = mid;
        high = mid;
      } else {
        low = mid;
      }
    }

    const details = calculateSellDetails(sellQty, breakEvenPrice, buyWacc, holdingType);
    return {
      price: breakEvenPrice,
      ...details
    };
  }, [sellQty, buyWacc, holdingType]);

  // ── Bonus & Right Price Adjustment Calculation ──
  const adjustmentResult = useMemo(() => {
    const p0 = parseFloat(adjLtp) || 0;
    const bonusPctNum = parseFloat(bonusPct) || 0;
    const rightPctNum = parseFloat(rightPct) || 0;
    const pr = parseFloat(rightIssuePrice) || 100;
    const qty = parseInt(userShares) || 0;
    const currentWacc = parseFloat(buyWacc) || p0;

    if (p0 <= 0) return null;

    // Use the official NEPSE simultaneous adjustment formula
    const sim = adjustSimultaneousBonusAndRight(qty, currentWacc, p0, bonusPctNum, rightPctNum, pr);
    const bonusTax = Math.floor(sim.bonusUnits) * 100 * 0.05;

    // Estimate baseline EPS from LTP (assuming standard P/E 20) or audit post-bonus dilution
    const estimatedEps = p0 > 0 ? Number((p0 / 22).toFixed(2)) : 20;
    const dilutionAudit = auditBonusDilution(estimatedEps, bonusPctNum);

    return {
      adjustedPrice: sim.adjustedPrice,
      bonusUnits: Math.floor(sim.bonusUnits),
      rightUnits: Math.floor(sim.rightUnits),
      totalNewUnits: Math.floor(sim.totalNewUnits),
      rightCost: sim.rightSubscriptionCost,
      newWacc: sim.newWacc,
      bonusTax,
      preValue: qty * p0,
      postValue: Math.floor(sim.totalNewUnits) * sim.adjustedPrice,
      dilutionAudit
    };
  }, [adjLtp, bonusPct, rightPct, rightIssuePrice, userShares, buyWacc]);

  // ── SIP Calculation ──
  const sipResult = useMemo(() => {
    const p = parseFloat(sipMonthly) || 0;
    const annualRate = parseFloat(sipReturnRate) || 0;
    const years = parseFloat(sipYears) || 0;

    if (p <= 0 || years <= 0) return null;

    const months = years * 12;
    const i = annualRate / 12 / 100;

    let maturity = 0;
    if (i > 0) {
      maturity = p * ((Math.pow(1 + i, months) - 1) / i) * (1 + i);
    } else {
      maturity = p * months;
    }

    const totalInvested = p * months;
    const estReturns = Math.max(0, maturity - totalInvested);

    return {
      totalInvested: Math.round(totalInvested),
      estReturns: Math.round(estReturns),
      maturity: Math.round(maturity),
      months
    };
  }, [sipMonthly, sipReturnRate, sipYears]);

  // ── NRB Margin Loan Calculation ──
  const marginLoanResult = useMemo(() => {
    if (marginUnits <= 0 || marginLtp <= 0) return null;
    const avg = marginAvg180 > 0 ? marginAvg180 : marginLtp;
    const valuationPrice = Math.min(marginLtp, avg);
    const collateralValuation = marginUnits * valuationPrice;
    const currentMarketValuation = marginUnits * marginLtp;
    const effectiveLtv = Math.min(70, Math.max(10, marginLtv));
    const calculatedLoan = collateralValuation * (effectiveLtv / 100);
    const ceiling = borrowerType === 'individual' ? 150000000 : 200000000;
    const approvedLoan = Math.min(calculatedLoan, ceiling);
    const isCapped = calculatedLoan > ceiling;

    const maintRatio = (parseFloat(marginMaintenance) || 130) / 100;
    const callPrice = (approvedLoan * maintRatio) / marginUnits;
    const cushion = ((marginLtp - callPrice) / marginLtp) * 100;

    const annualInterest = approvedLoan * (parseFloat(marginRate) / 100);
    const monthlyInterest = annualInterest / 12;

    return {
      valuationPrice,
      effectiveLtv,
      collateralValuation,
      currentMarketValuation,
      approvedLoan,
      isCapped,
      ceiling,
      callPrice,
      cushion,
      annualInterest,
      monthlyInterest
    };
  }, [marginUnits, marginLtp, marginAvg180, marginLtv, marginRate, marginMaintenance, borrowerType]);

  // ── Position Sizing & Risk Management Calculations ──
  const positionSizeResult = useMemo(() => {
    return calculatePositionSize({
      capital: Number(riskCapital) || 0,
      riskPct: Number(riskPercent) || 2,
      entryPrice: Number(riskEntryPrice) || 0,
      stopLossPrice: Number(riskStopLoss) || 0
    });
  }, [riskCapital, riskPercent, riskEntryPrice, riskStopLoss]);

  const riskNetProfitResult = useMemo(() => {
    const shares = positionSizeResult?.shares || 0;
    const entry = Number(riskEntryPrice) || 0;
    const target = Number(riskTargetPrice) || 0;
    if (shares <= 0 || entry <= 0 || target <= entry) return null;
    return calculateNetProfit({
      shares,
      buyPrice: entry,
      sellPrice: target,
      investorType: riskInvestorType
    });
  }, [positionSizeResult, riskEntryPrice, riskTargetPrice, riskInvestorType]);

  const riskRewardResult = useMemo(() => {
    const entry = Number(riskEntryPrice) || 0;
    const stop = Number(riskStopLoss) || 0;
    const target = Number(riskTargetPrice) || 0;
    if (entry <= 0 || stop <= 0 || target <= entry || stop >= entry) return null;
    const r = entry - stop;
    const w = target - entry;
    return formatRiskReward(w / r);
  }, [riskEntryPrice, riskStopLoss, riskTargetPrice]);

  return (
    <div className="calculator-view-container" style={{ width: '100%', boxSizing: 'border-box', padding: '12px 10px 20px', flex: '1 0 auto', display: 'flex', flexDirection: 'column' }}>
      {/* 7-Tab Selector (Dashboard Pill Chips) */}
      <div style={{
        display: 'flex',
        gap: 6,
        overflowX: 'auto',
        scrollbarWidth: 'none',
        borderBottom: '1px solid var(--border)',
        paddingBottom: 12,
        marginBottom: 16
      }}>
        {[
          { id: 'buy', label: 'Buy WACC', icon: '🛒', color: 'var(--primary-light)' },
          { id: 'sell', label: 'Sell Profit', icon: '💰', color: 'var(--bull)' },
          { id: 'breakeven', label: 'Break-Even', icon: '🎯', color: '#f59e0b' },
          { id: 'adjustment', label: 'Bonus / Right', icon: '🎁', color: '#ec4899' },
          { id: 'sip', label: 'SIP Growth', icon: '📈', color: '#06b6d4' },
          { id: 'margin_loan', label: 'Margin Loan (NRB)', icon: '🏛️', color: '#8b5cf6' },
          { id: 'risk_pos', label: 'Position Sizing & Risk', icon: '🛡️', color: '#10b981' }
        ].map(t => {
          const isActive = activeTab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setActiveTab(t.id)}
              style={{
                flex: '1 0 auto',
                padding: '8px 14px',
                textAlign: 'center',
                fontWeight: 800,
                fontSize: 12,
                whiteSpace: 'nowrap',
                border: `1px solid ${isActive ? 'var(--primary)' : 'var(--border)'}`,
                borderRadius: 12,
                background: isActive ? 'var(--primary)' : 'rgba(255,255,255,0.03)',
                boxShadow: isActive ? '0 0 16px rgba(79,70,229,0.3)' : 'none',
                cursor: 'pointer',
                transition: 'all 0.15s ease',
                color: isActive ? '#ffffff' : 'var(--text-secondary)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 6
              }}
            >
              <span>{t.icon}</span> {t.label}
            </button>
          );
        })}
      </div>

      {/* ── TAB 1: BUY SHARE CALCULATOR ── */}
      {activeTab === 'buy' && (
        <div>
          <div className="card">
            <h3 className="section-title" style={{ marginBottom: 16 }}>Buy Specifications</h3>

            <div style={{ marginBottom: 12 }}>
              <label className="input-label">Number of Shares (Quantity)</label>
              <input
                type="number"
                value={buyQty}
                onChange={(e) => setBuyQty(e.target.value === '' ? '' : Math.max(0, parseInt(e.target.value) || 0))}
                className="input"
                placeholder="Enter quantity"
              />
            </div>

            <div style={{ marginBottom: 8 }}>
              <label className="input-label">Share Purchase Price (Rs.)</label>
              <input
                type="number"
                value={buyPrice}
                onChange={(e) => setBuyPrice(e.target.value === '' ? '' : Math.max(0, parseFloat(e.target.value) || 0))}
                className="input"
                placeholder="Enter price per share"
              />
            </div>
          </div>

          {buyResult && (
            <div className="card">
              <h3 className="section-title" style={{ marginBottom: 16 }}>Cost Breakdown</h3>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 12, fontSize: 13.5 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>Total Share Value:</span>
                  <span style={{ fontWeight: 600 }}>{formatRs(buyResult.shareValue)}</span>
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: 4 }}>
                    Broker Commission (Tiered)
                    <HelpCircle style={{ width: 14, height: 14, opacity: 0.7 }} />
                  </span>
                  <span style={{ fontWeight: 600, color: 'var(--bear)' }}>+{formatRs(buyResult.commission)}</span>
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>SEBON Fee (0.015%):</span>
                  <span style={{ fontWeight: 600, color: 'var(--bear)' }}>+{formatRs(buyResult.sebonFee)}</span>
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>DP Charge:</span>
                  <span style={{ fontWeight: 600, color: 'var(--bear)' }}>+{formatRs(buyResult.dpFee)}</span>
                </div>

                <div style={{ borderTop: '1px solid var(--border)', margin: '10px 0', paddingTop: 10, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontWeight: 'bold', fontSize: 15 }}>Total Amount Payable:</span>
                  <span style={{ fontWeight: 900, fontSize: 18, color: 'var(--primary-light)', fontFamily: 'var(--font-mono)' }}>{formatRs(buyResult.totalAmount)}</span>
                </div>

                <div className="card-sm" style={{ background: 'var(--primary-subtle)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: 12, borderRadius: 10 }}>
                  <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--primary-light)' }}>Effective WACC per Share:</span>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontWeight: 900, fontSize: 15, color: 'var(--primary-light)', fontFamily: 'var(--font-mono)' }}>{formatRs(buyResult.costPerShare)}</span>
                    <button 
                      type="button" 
                      onClick={handleCopyBuyWacc} 
                      className="icon-btn" 
                      style={{ width: 26, height: 26, borderRadius: '4px', background: 'rgba(255,255,255,0.08)' }}
                      title="Copy WACC value"
                    >
                      {copiedBuyWacc ? <Check style={{ width: 12, height: 12, color: 'var(--bull)' }} /> : <Copy style={{ width: 12, height: 12 }} />}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── TAB 2: SELL SHARE CALCULATOR ── */}
      {activeTab === 'sell' && (
        <div>
          <div className="card">
            <h3 className="section-title" style={{ marginBottom: 16 }}>Sell Specifications</h3>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, marginBottom: 12 }}>
              <div>
                <label className="input-label">Quantity</label>
                <input
                  type="number"
                  value={sellQty}
                  onChange={(e) => setSellQty(e.target.value === '' ? '' : Math.max(0, parseInt(e.target.value) || 0))}
                  className="input"
                />
              </div>
              <div>
                <label className="input-label">Selling Rate (Rs.)</label>
                <input
                  type="number"
                  value={sellPrice}
                  onChange={(e) => setSellPrice(e.target.value === '' ? '' : Math.max(0, parseFloat(e.target.value) || 0))}
                  className="input"
                />
              </div>
            </div>

            <div style={{ marginBottom: 12 }}>
              <label className="input-label">Purchase WACC (Rs.)</label>
              <input
                type="number"
                value={buyWacc}
                onChange={(e) => setBuyWacc(e.target.value === '' ? '' : Math.max(0, parseFloat(e.target.value) || 0))}
                className="input"
              />
            </div>

            <div style={{ marginBottom: 8 }}>
              <label className="input-label">Capital Gains Holding Period</label>
              <select
                value={holdingType}
                onChange={(e) => setHoldingType(e.target.value)}
                className="select-input"
              >
                <option value="short">Individual Short Term (≤ 365 Days, 7.5% CGT — Final Tax)</option>
                <option value="long">Individual Long Term (&gt; 365 Days, 5.0% CGT — Final Tax)</option>
                <option value="institutional">Institutional Investor (10.0% CGT)</option>
              </select>
            </div>
          </div>

          {sellResult && (
            <div className="card">
              <h3 className="section-title" style={{ marginBottom: 16 }}>Net Realization & Tax Breakdown</h3>

              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, fontSize: 13.5 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>Gross Turnover:</span>
                  <span style={{ fontWeight: 600 }}>{formatRs(sellResult.sellValue)}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>Broker Commission:</span>
                  <span style={{ color: 'var(--bear)' }}>-{formatRs(sellResult.commission)}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>SEBON Fee (0.015%):</span>
                  <span style={{ color: 'var(--bear)' }}>-{formatRs(sellResult.sebonFee)}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>DP Fee:</span>
                  <span style={{ color: 'var(--bear)' }}>-{formatRs(sellResult.dpFee)}</span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ color: 'var(--text-muted)' }}>Capital Gains Tax (CGT):</span>
                  <span style={{ color: 'var(--bear)', fontWeight: 700 }}>-{formatRs(sellResult.cgt)}</span>
                </div>

                <div style={{ borderTop: '1px solid var(--border)', paddingTop: 10, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ fontWeight: 'bold' }}>Net Receivable Amount:</span>
                  <span style={{ fontWeight: 900, fontSize: 17, color: '#ffffff', fontFamily: 'var(--font-mono)' }}>{formatRs(sellResult.netReceivable)}</span>
                </div>

                <div className="card-sm" style={{
                  background: sellResult.netProfitLoss >= 0 ? 'var(--bull-subtle)' : 'var(--bear-subtle)',
                  border: `1px solid ${sellResult.netProfitLoss >= 0 ? 'rgba(16,217,138,0.3)' : 'rgba(239,68,68,0.3)'}`,
                  padding: 12, borderRadius: 10, marginTop: 4
                }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
