      const ltp = Number(s.ltp || 0);
      const to = Number(s.turnover || s.totalTradedValue || (ltp * vol) || 0);
      calculatedTurnover += to;
      totalVolume += vol;
      totalTrades += Number(s.trades || s.transactions || s.totalTrades || 0);
