    const floatVal = indices?.float?.value || 174.35;
    const floatChg = indices?.float?.change || 0.15;
    const floatPChg = indices?.float?.pChange || 0.08;

    return {
      totalTurnover,
      totalVolume,
      totalTrades,
      adv,
      dec,
      unc,
      breadthRatio,
