function loadLocalAccounts() {
  try {
    const raw = localStorage.getItem(BULK_ACCOUNTS_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.map(acc => decryptProfileCredentials(acc)) : [];
  } catch {
