}

// Safe fetch that handles non-JSON responses gracefully
function parseSafeJsonBody(data) {
  if (!data) return null;
  if (typeof data === 'object') return data;
  if (typeof data === 'string') {
    const trimmed = data.trim();
    if (trimmed.startsWith('<') || trimmed.startsWith('<!DOCTYPE') || trimmed.startsWith('<?xml')) {
      return null;
    }
    try {
      return JSON.parse(trimmed);
    } catch {
      return null;
    }
  }
  return null;
}

async function safeFetch(url, options = {}) {
  let res;
  try {
    res = await fetch(url, options);
  } catch (netErr) {
    throw new Error('Network error: ' + netErr.message);
  }
  let text;
  try { text = await res.text(); } catch (_) { throw new Error(`Could not read response (${res.status})`); }
  let json;
  try { json = JSON.parse(text); } catch (_) {
    if (!res.ok) throw new Error(`Server error ${res.status}`);
    return text;
  }
  return json;
}

