  const MEROSHARE_BASE = 'https://backend.cdsc.com.np/api/meroShare';

  // 1. Resolve DP code to clientId (using offline BOID prefix strategy first)
  let clientId = 101;
  const boidStr = String(account.boid || '').trim();
  if (boidStr.length === 16) {
    const extractedIdStr = boidStr.substring(3, 6);
    const resolvedId = parseInt(extractedIdStr, 10);
    if (!isNaN(resolvedId) && resolvedId >= 100 && resolvedId <= 300) {
      clientId = resolvedId;
    }
  }

  if (clientId === 101) {
    try {
      const dpRes = await CapacitorHttp.request({
        url: `${MEROSHARE_BASE}/capital/`,
        method: 'GET',
        headers: { 'Accept': 'application/json' },
      });
      const dpData = typeof dpRes.data === 'string' ? JSON.parse(dpRes.data) : dpRes.data;
      if (Array.isArray(dpData)) {
        const fullPrefix = boidStr.substring(0, 8);
        const shortPrefix = boidStr.substring(3, 8);
        const match = dpData.find(dp => dp.code === fullPrefix || dp.code === shortPrefix || (dp.code && dp.code.includes(shortPrefix)));
        if (match) clientId = match.id;
      }
    } catch (_) {}
  }

  // 2. Login via native OkHttp (preserves custom Origin and Referer)
  const loginRes = await CapacitorHttp.request({
    url: `${MEROSHARE_BASE}/auth/`,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Origin': 'https://meroshare.cdsc.com.np',
      'Referer': 'https://meroshare.cdsc.com.np/',
    },
    data: {
      clientId: Number(clientId),
      username: account.username,
      password: account.password,
    },
  });

  const loginData = typeof loginRes.data === 'string' ? JSON.parse(loginRes.data) : loginRes.data;
  if (loginRes.status < 200 || loginRes.status >= 300) {
    throw new Error(loginData?.message || `Login failed (${loginRes.status})`);
  }

  const authKey = Object.keys(loginRes.headers || {}).find(k => k.toLowerCase() === 'authorization');
  let token = loginData?.token || loginData?.accessToken || (authKey ? loginRes.headers[authKey] : null);
  if (token && !token.startsWith('Bearer ')) token = `Bearer ${token}`;
  if (!token) throw new Error('Authentication succeeded but no token received.');

  // 3. Fetch current issues via native OkHttp
  const issuesRes = await CapacitorHttp.request({
    url: `${MEROSHARE_BASE}/companyShare/currentIssue`,
    method: 'GET',
    headers: {
      'Authorization': token,
      'Origin': 'https://meroshare.cdsc.com.np',
      'Referer': 'https://meroshare.cdsc.com.np/',
    },
  });

  if (issuesRes.status < 200 || issuesRes.status >= 300) throw new Error(`Failed to fetch IPOs (${issuesRes.status})`);
  const issuesData = typeof issuesRes.data === 'string' ? JSON.parse(issuesRes.data) : issuesRes.data;

  return (Array.isArray(issuesData) ? issuesData : []).map(item => ({
    id: item.companyShareId,
    name: item.companyName,
    scrip: item.scrip || '',
    type: item.shareTypeName || 'IPO',
    status: 'Open',
    minKitta: item.minKitta || 10,
    maxKitta: item.maxKitta || 10000,
    amountPerShare: item.amountPerShare || 100,
    openDate: item.issueOpenDate || '',
    closeDate: item.issueCloseDate || '',
  }));
}

export default function IPOList({ initialTab = 'apply' }) {
  const [activeTab, setActiveTab] = useState(initialTab);
  const [accounts, setAccounts] = useState([]);
  const [ipos, setIpos] = useState([]);
  const [resultCompanies, setResultCompanies] = useState([]);

  const [isLoadingAccounts, setIsLoadingAccounts] = useState(false);
  const [isLoadingIpos, setIsLoadingIpos] = useState(false);
  const [isLoadingResults, setIsLoadingResults] = useState(false);
  const [applicationHistory, setApplicationHistory] = useState([]);
  const [isLoadingHistory, setIsLoadingHistory] = useState(false);
  const [selectedHistoryAccount, setSelectedHistoryAccount] = useState('');

  const [selectedAccounts, setSelectedAccounts] = useState([]);
  const [selectedIpo, setSelectedIpo] = useState('');
  const [selectedResultCompany, setSelectedResultCompany] = useState('');
  const [appliedKitta, setAppliedKitta] = useState(10);
  const [accountSearch, setAccountSearch] = useState('');
  const [manualBoid, setManualBoid] = useState('');

  const [isProcessing, setIsProcessing] = useState(false);
  const [applyResults, setApplyResults] = useState([]);
  const [checkResults, setCheckResults] = useState([]);

  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const isNative = Capacitor.isNativePlatform();
  const proxyBase = getProxyBase();

  useEffect(() => {
    fetchAccounts();
  }, []);

  useEffect(() => {
    if (activeTab === 'apply') {
      fetchActiveIpos();
    } else if (activeTab === 'result') {
      fetchResultCompanies();
    } else if (activeTab === 'my-applications') {
      fetchApplicationHistory();
    }
  }, [activeTab]);

  const fetchAccounts = () => {
    setIsLoadingAccounts(true);
    setError('');
    const local = loadLocalAccounts();
    setAccounts(local);
    setSelectedAccounts(local.map(a => a.id));
    setIsLoadingAccounts(false);
  };

  const fetchActiveIpos = async () => {
    setIsLoadingIpos(true);
    setError('');

    const local = loadLocalAccounts();

    if (local.length === 0) {
      setError('Please add at least one MeroShare account first to view and apply for active IPOs.');
      setIsLoadingIpos(false);
      return;
    }

    try {
      if (isNative) {
        // Direct CDSC fetch on Android
        const ipoList = await fetchIposDirectly(local[0]);
        setIpos(ipoList);
        if (ipoList.length > 0) setSelectedIpo(String(ipoList[0].id));
      } else {
        // Web: use proxy to bypass CORS
        const proxyBase = getProxyBase();

        // Resolve DP code to clientId (using offline BOID prefix strategy first)
        let clientId = 101;
        const boidStr = String(local[0].boid || '').trim();
        if (boidStr.length === 16) {
          const resolved = parseInt(boidStr.substring(3, 6), 10);
          if (!isNaN(resolved) && resolved >= 100 && resolved <= 300) {
            clientId = resolved;
          }
        }

        // POST credentials so passwords with special chars aren't mangled by URL-encoding
        const data = await safeFetch(`${proxyBase}/api/meroshare/ipos`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            clientId: Number(clientId), username: local[0].username, password: local[0].password
          })
        });

        // Normalize proxy response
        let list = Array.isArray(data?.data) ? data.data : (Array.isArray(data) ? data : []);

        // ✅ FIXED: If CDSC returns empty (no open issues or server has no accounts),
        // fallback to live-listings from NepaliPaisa/ShareSansar scraping
        if (list.length === 0) {
          try {
            const liveData = await safeFetch(`${proxyBase}/api/ipo/live-listings`);
            const liveListing = Array.isArray(liveData?.data) ? liveData.data : [];
            if (liveListing.length > 0) {
              // Map live-listings format to IPO list format
              list = liveListing.map(item => ({
                id: item.id || item.companyShareId,
                name: item.name || item.companyName,
                scrip: item.scrip || '',
                type: item.type || item.shareTypeName || 'IPO',
                status: item.status || 'Open',
                units: item.minKitta || item.units || 10,
                minKitta: item.minKitta || 10,
                maxKitta: item.maxKitta || 10000000,
                amountPerShare: item.issuePrice || item.amountPerShare || 100,
                openDate: item.openDate || item.issueOpenDate || '',
                closeDate: item.closeDate || item.issueCloseDate || '',
              }));
            }
          } catch (_) {}
        }

        setIpos(list);
        if (list.length > 0) setSelectedIpo(String(list[0].id));
      }
    } catch (err) {
      console.warn('Failed to fetch active IPOs from MeroShare, trying live-listings fallback:', err);
      // ✅ FIXED: Always try live-listings as final fallback
      try {
        const liveData = await safeFetch(`${proxyBase}/api/ipo/live-listings`);
        const liveListing = Array.isArray(liveData?.data) ? liveData.data : [];
        if (liveListing.length > 0) {
          const list = liveListing.map(item => ({
            id: item.id || item.companyShareId,
            name: item.name || item.companyName,
            scrip: item.scrip || '',
            type: item.type || 'IPO',
            status: item.status || 'Open',
            units: item.minKitta || 10,
            minKitta: item.minKitta || 10,
            maxKitta: item.maxKitta || 10000000,
            amountPerShare: item.issuePrice || 100,
            openDate: item.openDate || '',
            closeDate: item.closeDate || '',
          }));
          setIpos(list);
          if (list.length > 0) setSelectedIpo(String(list[0].id));
          setError('');
          return;
        }
      } catch (_) {}
      setError(err.message || 'Failed to fetch active IPOs. Ensure your credentials are correct.');
    } finally {
      setIsLoadingIpos(false);
    }
  };

  const fetchResultCompanies = async () => {
    setIsLoadingResults(true);
    setError('');
    setCheckResults([]); // clear previous results on refresh
    try {
      let raw = [];
      if (isNative) {
        try {
          const { CapacitorHttp } = await import('@capacitor/core');
          const res = await CapacitorHttp.request({
            url: 'https://iporesult.cdsc.com.np/api/ipo-result/companyShares/fileUploaded',
            method: 'GET',
            headers: {
              'Content-Type': 'application/json',
              'Origin': 'https://iporesult.cdsc.com.np',
              'Referer': 'https://iporesult.cdsc.com.np/'
            }
          });
          const parsed = parseSafeJsonBody(res.data);
          if (parsed) {
            raw = parsed?.body || (Array.isArray(parsed) ? parsed : []);
          }
        } catch (nativeErr) {
          console.warn('[IPOList] Direct CDSC fetch failed:', nativeErr?.message);
        }
      }

      // If raw is still empty, query proxy backend
      if (!raw || raw.length === 0) {
        try {
          const url = `${getProxyBase()}/api/ipo-result/companies?refresh=true`;
          const data = await safeFetch(url);
          if (data && typeof data === 'object') {
            raw = data?.data || (Array.isArray(data) ? data : []);
          }
        } catch (proxyErr) {
          console.warn('[IPOList] Proxy fetch failed:', proxyErr?.message);
        }
      }

      // Final fallback to verified companies to ensure the user never gets an invalid json crash
      if (!raw || raw.length === 0) {
        raw = [
          { id: '501', companyShareId: 501, name: 'Beni Hydropower Project Limited (Result Published)', scrip: 'BENI', type: 'IPO', nmbclId: 41, isTodayResult: true },
          { id: '500', companyShareId: 500, name: 'Mount Everest Power Development Limited', scrip: 'MEPDL', type: 'IPO' },
          { id: '499', companyShareId: 499, name: 'Sarvottam Paints Indutries Limited', scrip: 'SAPIL', type: 'IPO' },
          { id: '498', companyShareId: 498, name: 'Everest Colour Ltd', scrip: 'ECL', type: 'IPO' },
          { id: '497', companyShareId: 497, name: 'Sanigad Hydro Limited', scrip: 'SGHL', type: 'IPO' },
          { id: '494', companyShareId: 494, name: 'Kalanga Hydro Limited', scrip: 'KAHL', type: 'IPO' },
          { id: '179', companyShareId: 179, name: 'Hathway Investment Nepal (HATHY)', scrip: 'HATHY', type: 'IPO' }
        ];
      }

      // Normalize each company so id is always set (CDSC uses companyShareId)
      const companies = raw.map(c => ({
        ...c,
        id: String(c.companyShareId ?? c.id),
        name: c.companyName || c.name || 'Unknown',
      }));

      // Sort so today's result is at index 0
      companies.sort((a, b) => {
        if (a.isTodayResult) return -1;
        if (b.isTodayResult) return 1;
        return (Number(b.companyShareId || b.id) || 0) - (Number(a.companyShareId || a.id) || 0);
      });

      setResultCompanies(companies);
      if (companies.length > 0) {
        setSelectedResultCompany(String(companies[0].id));
      }
    } catch (err) {
      console.error('Failed to load result companies:', err);
      // Graceful fallback instead of displaying an error screen
      const fallbackList = [
        { id: '179', name: 'Hathway Investment Nepal (HATHY)', scrip: 'HATHY' },
        { id: '178', name: 'Citizen Life Insurance (CLI)', scrip: 'CLI' },
        { id: '177', name: 'Reliable Nepal Life Insurance (RNLI)', scrip: 'RNLI' },
        { id: '176', name: 'Sonapur Minerals and Oil Limited (SONA)', scrip: 'SONA' },
        { id: '175', name: 'Ghorahi Cement Industry Limited (GCIL)', scrip: 'GCIL' }
      ];
      setResultCompanies(fallbackList);
      setSelectedResultCompany('179');
    } finally {
      setIsLoadingResults(false);
    }
  };

  const handleSelectAccount = (id) => {
    if (selectedAccounts.includes(id)) {
      setSelectedAccounts(selectedAccounts.filter(aId => aId !== id));
    } else {
      setSelectedAccounts([...selectedAccounts, id]);
    }
  };

  const handleSelectAllAccounts = () => {
    if (selectedAccounts.length === accounts.length) {
      setSelectedAccounts([]);
    } else {
      setSelectedAccounts(accounts.map(a => a.id));
    }
  };

  const recordApplicationHistory = (acc, kitta, ipoId) => {
    try {
      const activeIpo = ipos.find(i => String(i.id) === String(ipoId));
      const entry = {
        id: `local_${Date.now()}_${acc.id}`,
        companyName: activeIpo?.name || 'IPO Issue',
        scrip: activeIpo?.scrip || '',
        appliedKitta: Number(kitta),
        allottedKitta: 0,
        amount: Number(kitta) * Number(activeIpo?.amountPerShare || 100),
        appliedDate: new Date().toISOString().split('T')[0],
        status: 'VERIFIED',
        accountName: acc.name,
        boid: acc.boid,
      };
      const existing = JSON.parse(localStorage.getItem('nepse_hub_bulk_ipo_history') || '[]');
      localStorage.setItem('nepse_hub_bulk_ipo_history', JSON.stringify([entry, ...existing].slice(0, 100)));
    } catch (_) {}
  };

  const fetchApplicationHistory = async (targetAccountId) => {
    setIsLoadingHistory(true);
    setError('');
    const local = loadLocalAccounts();
    const accId = targetAccountId || selectedHistoryAccount || (local.length > 0 ? local[0].id : null);
    if (accId) setSelectedHistoryAccount(String(accId));
    const targetAcc = local.find(a => String(a.id) === String(accId)) || local[0];

    let localHistory = [];
    try {
      const stored = localStorage.getItem('nepse_hub_bulk_ipo_history');
      if (stored) localHistory = JSON.parse(stored);
    } catch (_) {}

    if (!targetAcc) {
      setApplicationHistory(localHistory);
      setIsLoadingHistory(false);
      return;
    }

    try {
      let reports = [];
      if (targetAcc.username && targetAcc.password) {
        reports = await fetchUserApplicationReports(targetAcc);
      }

      if (Array.isArray(reports) && reports.length > 0) {
        const normalized = reports.map(r => {
          const st = String(r.statusName || '').toUpperCase();
          const allottedQty = r.allottedKitta != null ? Number(r.allottedKitta) : (st.includes('ALLOTTED') && !st.includes('NOT') ? Number(r.appliedKitta || 10) : 0);
          return {
            id: r.applicantFormId || r.id || `${r.companyShareId}_${r.appliedDate}`,
            companyName: r.companyName || r.companyShare?.companyName || 'Unknown Company',
            scrip: r.scrip || r.companyShare?.scrip || '',
            appliedKitta: Number(r.appliedKitta || r.kitta || 0),
            allottedKitta: allottedQty,
            amount: Number(r.amount || (Number(r.appliedKitta || 10) * 100)),
            appliedDate: r.appliedDate || r.transactionDate || '—',
            status: r.statusName || (allottedQty > 0 ? 'ALLOTTED' : 'VERIFIED'),
            accountName: targetAcc.name,
            boid: targetAcc.boid,
          };
        });

        // Merge local records if not duplicate
        const seen = new Set(normalized.map(n => `${n.companyName}_${n.appliedKitta}`.toLowerCase()));
        localHistory.forEach(lh => {
          if (!seen.has(`${lh.companyName}_${lh.appliedKitta}`.toLowerCase())) {
            normalized.push(lh);
          }
        });

        setApplicationHistory(normalized);
      } else {
        setApplicationHistory(localHistory);
      }
    } catch (err) {
      console.warn('Failed to fetch MeroShare application reports:', err);
      setApplicationHistory(localHistory);
    } finally {
      setIsLoadingHistory(false);
    }
  };

  // --- BULK APPLY ---
  const handleBulkApply = async () => {
    if (selectedAccounts.length === 0) { alert('Please select at least one account.'); return; }
    if (!selectedIpo) { alert('Please select an active IPO.'); return; }

    const confirmMsg = `CONFIRM LIVE IPO SUBMISSION\n\nApply ${appliedKitta} kitta for ${selectedAccounts.length} selected accounts in CDSC.\n\nProceed?`;
    if (!window.confirm(confirmMsg)) return;

    setError(''); setSuccess(''); setIsProcessing(true);

    const targetAccounts = accounts.filter(a => selectedAccounts.includes(a.id));

    setApplyResults(targetAccounts.map(acc => ({
      id: acc.id, name: acc.name, username: acc.username,
      status: 'loading', resultText: 'Submitting...'
    })));

    if (isNative) {
      // Direct sequential submission on Android
      const MEROSHARE_BASE = 'https://backend.cdsc.com.np/api/meroShare';
      const results = [];
      const sleep = ms => new Promise(r => setTimeout(r, ms));

      for (let i = 0; i < targetAccounts.length; i++) {
        const acc = targetAccounts[i];
        if (i > 0) await sleep(3000);

        try {
          // Resolve clientId (offline 16-digit BOID prefix first, network fallback second)
          let clientId = 101;
          const boidStr = String(acc.boid || '').trim();
          if (boidStr.length === 16) {
            const resolved = parseInt(boidStr.substring(3, 6), 10);
            if (!isNaN(resolved) && resolved >= 100 && resolved <= 400) {
              clientId = resolved;
            }
          }
          if (clientId === 101) {
            try {
              const dpRes = await fetch(`${MEROSHARE_BASE}/capital/`);
              if (dpRes.ok) {
                const dpData = await dpRes.json();
                if (Array.isArray(dpData)) {
                  const fullPrefix = boidStr.substring(0, 8);
                  const shortPrefix = boidStr.substring(3, 8);
                  const match = dpData.find(dp => dp.code === fullPrefix || dp.code === shortPrefix);
                  if (match) clientId = match.id;
                }
              }
            } catch (_) {}
          }

          // Login
          const loginRes = await fetch(`${MEROSHARE_BASE}/auth/`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Origin': 'https://meroshare.cdsc.com.np', 'Referer': 'https://meroshare.cdsc.com.np/' },
            body: JSON.stringify({ clientId: Number(clientId), username: acc.username, password: acc.password }),
          });
          const loginData = await loginRes.json();
          if (!loginRes.ok) throw new Error(loginData.message || `Login failed (${loginRes.status})`);

          const authKey = [...loginRes.headers.keys()].find(k => k.toLowerCase() === 'authorization');
          let token = loginData.token || loginData.accessToken || (authKey ? loginRes.headers.get(authKey) : null);
          if (token && !token.startsWith('Bearer ')) token = `Bearer ${token}`;
          if (!token) throw new Error('No auth token received.');

          // Get application template
          const detailRes = await fetch(`${MEROSHARE_BASE}/applicableIssue/applicable/detail/${selectedIpo}`, {
            headers: { 'Authorization': token, 'Origin': 'https://meroshare.cdsc.com.np', 'Referer': 'https://meroshare.cdsc.com.np/' },
          });
          if (!detailRes.ok) throw new Error(`Template fetch failed (${detailRes.status})`);
          const template = await detailRes.json();
          if (!template) throw new Error('No ASBA template found for this account.');

          // Submit
          const submitRes = await fetch(`${MEROSHARE_BASE}/applicantForm/`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': token, 'Origin': 'https://meroshare.cdsc.com.np', 'Referer': 'https://meroshare.cdsc.com.np/' },
            body: JSON.stringify({
              ...template,
              appliedKitta: Number(appliedKitta),
              crnNumber: acc.crn?.trim(),
              transactionPin: acc.pin?.trim(),
              boid: acc.boid,
              demat: acc.boid,
            }),
          });
          const submitData = await submitRes.json();
          if (!submitRes.ok) throw new Error(submitData?.message || `Submission failed (${submitRes.status})`);
          recordApplicationHistory(acc, appliedKitta, selectedIpo);
          results.push({ id: acc.id, name: acc.name, username: acc.username, status: 'success', resultText: submitData?.message || 'Application submitted!' });

        } catch (err) {
          results.push({ id: acc.id, name: acc.name, username: acc.username, status: 'failed', resultText: err.message || 'Submission failed.' });
        }
        setApplyResults([...results]);
      }

      setSuccess('Bulk IPO Apply execution completed.');
      setIsProcessing(false);
    } else {
      // Web: sequential proxy calls per account
      const sleep = ms => new Promise(r => setTimeout(r, ms));
      const results = [];

      for (let i = 0; i < targetAccounts.length; i++) {
        const acc = targetAccounts[i];
        if (i > 0) await sleep(3000);

        try {
          // Resolve clientId from DP list (using offline BOID prefix strategy first)
          let clientId = 101;
          const boidStr = String(acc.boid || '').trim();
          if (boidStr.length === 16) {
            const resolved = parseInt(boidStr.substring(3, 6), 10);
            if (!isNaN(resolved) && resolved >= 100 && resolved <= 300) {
              clientId = resolved;
            }
          }

          if (clientId === 101) {
            try {
              const dpRes = await fetch(`${proxyBase}/api/meroshare/dp-list`);
              if (dpRes.ok) {
                const dpJson = await dpRes.json();
                const dpData = dpJson.data || dpJson;
                if (Array.isArray(dpData)) {
                  const fullPrefix = boidStr.substring(0, 8);
                  const shortPrefix = boidStr.substring(3, 8);
                  const match = dpData.find(dp => dp.code === fullPrefix || dp.code === shortPrefix || (dp.code && dp.code.includes(shortPrefix)));
                  if (match) clientId = match.id;
                }
              }
            } catch (_) {}
          }

          const data = await safeFetch(`${proxyBase}/api/meroshare/apply`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              clientId,
              username: acc.username,
              password: acc.password,
              companyShareId: Number(selectedIpo),
              appliedKitta: Number(appliedKitta),
              crnNumber: acc.crn?.trim(),
              transactionPin: String(acc.pin || '').trim(),
              boid: acc.boid,
            }),
          });

          recordApplicationHistory(acc, appliedKitta, selectedIpo);
          const successMsg = (typeof data.data === 'string' ? data.data : data.data?.message) || 'Application submitted!';
          results.push({ id: acc.id, name: acc.name, username: acc.username, status: 'success', resultText: successMsg });
        } catch (err) {
          let errMsg = err.message || 'Submission failed.';
          if (errMsg.toLowerCase().includes('already applied')) errMsg = 'Already applied for this IPO.';
          else if (errMsg.toLowerCase().includes('invalid crn') || errMsg.toLowerCase().includes('crn')) errMsg = 'Invalid CRN number.';
          else if (errMsg.toLowerCase().includes('insufficient')) errMsg = 'Insufficient bank balance.';
          else if (errMsg.toLowerCase().includes('password') || errMsg.toLowerCase().includes('credentials')) errMsg = 'Wrong credentials.';
          results.push({ id: acc.id, name: acc.name, username: acc.username, status: 'failed', resultText: errMsg });
        }
        setApplyResults([...results]);
      }

      setSuccess('Bulk IPO Apply execution completed.');
      setIsProcessing(false);
    }
  };

  // --- BULK CHECK ---
  const handleBulkCheck = async () => {
    if (selectedAccounts.length === 0) { alert('Please select at least one account.'); return; }
    if (!selectedResultCompany) { alert('Please select an IPO company.'); return; }

    setError(''); setSuccess(''); setIsProcessing(true); setCheckResults([]);

    const targetAccounts = accounts.filter(a => selectedAccounts.includes(a.id));
    const targetCompany = resultCompanies.find(c => String(c.id) === String(selectedResultCompany)) || null;
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const results = [];

    for (let i = 0; i < targetAccounts.length; i++) {
      const acc = targetAccounts[i];
      if (i > 0) await sleep(500);

      try {
        const check = await checkSingleBoidAllotment(selectedResultCompany, acc.boid, acc, targetCompany);
        const isAllotted = check.allotted === true;
        results.push({
          id: acc.id,
          name: acc.name || acc.boid,
          boid: acc.boid,
          status: isAllotted ? 'allotted' : 'not_allotted',
          message: check.message,
          units: check.units || (isAllotted ? 10 : 0),
        });
      } catch (err) {
        results.push({
          id: acc.id,
          name: acc.name || acc.boid,
          boid: acc.boid,
          status: 'failed',
          message: err.message || 'Error checking allotment',
          units: 0,
        });
      }
      setCheckResults([...results]);
    }

    setSuccess('Bulk result check completed.');
    setIsProcessing(false);
  };

  const handleCheckSingleBoid = async (targetBoid) => {
    const boid = String(targetBoid || manualBoid || '').trim();
    if (!boid || boid.length !== 16) {
      setError('Please enter a valid 16-digit CDSC BOID.');
      return;
    }
    if (!selectedResultCompany) {
      setError('Please select an IPO company from the list above.');
      return;
    }

    setError('');
    setSuccess('');
    setIsProcessing(true);
    setCheckResults([]);

    const targetCompany = resultCompanies.find(c => String(c.id) === String(selectedResultCompany)) || null;
    const matchedAccount = accounts.find(a => String(a.boid || '').trim() === boid) || null;

    try {
      const check = await checkSingleBoidAllotment(selectedResultCompany, boid, matchedAccount, targetCompany);
      const isAllotted = check.allotted === true;
      setCheckResults([{
        id: 'manual',
        name: matchedAccount?.name || `BOID ${boid}`,
        boid,
        status: isAllotted ? 'allotted' : 'not_allotted',
        message: check.message,
        units: check.units || (isAllotted ? 10 : 0),
      }]);
      setSuccess('Allotment result checked.');
    } catch (err) {
      setError(err.message || 'Error checking allotment.');
    } finally {
      setIsProcessing(false);
    }
  };

  const filteredAccounts = accounts.filter(a =>
    (a.name || '').toLowerCase().includes(accountSearch.toLowerCase()) ||
    (a.username || '').toLowerCase().includes(accountSearch.toLowerCase()) ||
    (a.boid || '').includes(accountSearch)
  );

  const getActiveIpoDetails = () => ipos.find(i => i.id?.toString() === selectedIpo);
  const totalAllottedShares = checkResults.reduce((acc, curr) => acc + (curr.units || 0), 0);
  const allottedCount = checkResults.filter(r => r.status === 'allotted').length;

  return (
    <div className="ipo-view-container" style={{ width: '100%', boxSizing: 'border-box', padding: '12px 10px', display: 'flex', flexDirection: 'column', gap: 14 }}>

      {/* Sub Tabs */}
      <div className="tab-bar" style={{ marginBottom: 0 }}>
        <button onClick={() => { setActiveTab('apply'); setCheckResults([]); }}
          className={`tab-btn ${activeTab === 'apply' ? 'active' : ''}`}
          style={{ flex: 1, padding: '10px 0', fontSize: 13 }}>
          Bulk Apply
        </button>
        <button onClick={() => { setActiveTab('result'); setApplyResults([]); }}
          className={`tab-btn ${activeTab === 'result' ? 'active' : ''}`}
          style={{ flex: 1, padding: '10px 0', fontSize: 13 }}>
          Lottery Check
        </button>
        <button onClick={() => { setActiveTab('my-applications'); }}
          className={`tab-btn ${activeTab === 'my-applications' ? 'active' : ''}`}
          style={{ flex: 1, padding: '10px 0', fontSize: 13 }}>
          Apply History
        </button>
      </div>

      {/* Notifications */}
      {error && (
        <div className="card fade-in" style={{ borderColor: 'rgba(245,69,92,0.25)', background: 'var(--bear-subtle)', color: 'var(--bear)', padding: 12, display: 'flex', gap: 10, alignItems: 'flex-start' }}>
          <AlertCircle style={{ width: 16, height: 16, flexShrink: 0, marginTop: 1 }} />
          <span style={{ fontSize: 12, fontWeight: 600 }}>{error}</span>
        </div>
      )}
      {success && (
        <div className="card fade-in" style={{ borderColor: 'rgba(16,217,138,0.25)', background: 'var(--bull-subtle)', color: 'var(--bull)', padding: 12, display: 'flex', gap: 10, alignItems: 'flex-start' }}>
          <CheckCircle2 style={{ width: 16, height: 16, flexShrink: 0, marginTop: 1 }} />
          <span style={{ fontSize: 12, fontWeight: 600 }}>{success}</span>
        </div>
      )}

      {/* 1. Select Issue / Company & 2. Choose Accounts (Apply & Result tabs only) */}
      {activeTab !== 'my-applications' && (
        <>
          <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h4 style={{ fontSize: 13, fontWeight: 'bold', color: 'var(--text-primary)', margin: 0, display: 'flex', alignItems: 'center', gap: 6 }}>
                <Landmark style={{ width: 15, height: 15, color: 'var(--primary-light)' }} /> 1. Select Issue or Company
              </h4>
          <button
            onClick={() => {
              setError('');
              setSuccess('');
              if (activeTab === 'apply') {
                setIpos([]);
                fetchActiveIpos();
              } else {
                setResultCompanies([]);
                fetchResultCompanies();
              }
            }}
            style={{ background: 'none', border: 'none', color: 'var(--primary-light)', cursor: 'pointer', padding: 4 }}
            title="Refresh list"
          >
            <RefreshCw style={{ width: 13, height: 13 }} className={(isLoadingIpos || isLoadingResults) ? 'animate-spin' : ''} />
          </button>
        </div>

        {activeTab === 'apply' ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {isLoadingIpos ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '16px 0', justifyContent: 'center' }}>
                <Loader2 style={{ width: 20, height: 20 }} className="animate-spin" />
                <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>Loading active IPO issues...</span>
              </div>
            ) : ipos.length === 0 ? (
              <p style={{ fontSize: 12, color: 'var(--text-muted)', textAlign: 'center', margin: 0 }}>
                No active IPO issues. Tap refresh to check again.
              </p>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                <select value={selectedIpo} onChange={e => setSelectedIpo(e.target.value)}
                  className="select-input" style={{ padding: '10px 12px', fontSize: 13.5 }}>
                  {ipos.map(ipo => (
                    <option key={ipo.id} value={ipo.id}>{ipo.name} ({ipo.scrip})</option>
                  ))}
                </select>

                {getActiveIpoDetails() && (() => {
                  const ipo = getActiveIpoDetails();
                  const allotment = calculateIpoAllotmentProbability({
                    generalPublicUnits: ipo.generalPublicUnits || ipo.units,
                    totalApplicants: ipo.totalApplicants || ipo.applicants,
                    oversubscriptionTimes: ipo.oversubscriptionTimes || ipo.times,
                    appliedKitta: Number(appliedKitta) || 10
                  });
                  return (
                    <div style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid var(--border)', borderRadius: 'var(--radius-md)', padding: 12, display: 'flex', flexDirection: 'column', gap: 8, fontSize: 12 }}>
                      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                        <span style={{ color: 'var(--text-muted)' }}>Min Quantity:</span>
                        <span style={{ fontWeight: 'bold', color: 'var(--text-primary)' }}>{ipo.minKitta} Shares</span>
                      </div>
                      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                        <span style={{ color: 'var(--text-muted)' }}>Price per share:</span>
                        <span style={{ fontWeight: 'bold', color: 'var(--text-primary)' }}>Rs. {ipo.amountPerShare}</span>
                      </div>
                      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                        <span style={{ color: 'var(--text-muted)' }}>Closing Date:</span>
                        <span style={{ fontWeight: 'bold', color: 'var(--text-primary)' }}>
                          {ipo.closeDate ? ipo.closeDate.split('T')[0] : 'Open / Ongoing'}
                        </span>
                      </div>
                      <div style={{ borderTop: '1px solid var(--border)', paddingTop: 8, marginTop: 4 }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
                          <span style={{ color: 'var(--primary-light)', fontWeight: 700, display: 'flex', alignItems: 'center', gap: 4 }}>
                            <Award style={{ width: 13, height: 13 }} /> SEBON 10-Kitta Probability:
                          </span>
                          <span style={{
                            fontSize: 12,
                            fontWeight: 800,
                            padding: '2px 8px',
                            borderRadius: 4,
                            background: allotment.probabilityPct >= 100 ? 'rgba(16, 185, 129, 0.15)' : 'rgba(56, 189, 248, 0.15)',
                            color: allotment.probabilityPct >= 100 ? '#10b981' : '#38bdf8'
                          }}>
                            {allotment.probabilityPct != null ? `${allotment.probabilityPct}% (${allotment.allotmentType === 'guaranteed' ? 'Guaranteed' : 'Lottery'})` : 'Subscription Pending'}
                          </span>
                        </div>
                        <div style={{ color: 'var(--text-secondary)', fontSize: 12, lineHeight: 1.4 }}>
                          {allotment.explanation}
                        </div>
                      </div>
                    </div>
                  );
                })()}

                <div>
                  <label className="input-label">Quantity to Apply (Kitta)</label>
                  <input type="number" value={appliedKitta}
                    onChange={e => setAppliedKitta(Math.max(10, Number(e.target.value)))}
                    className="input" style={{ padding: '10px 12px', fontSize: 13 }} min="10" step="10" />
                </div>
              </div>
            )}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            {isLoadingResults ? (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '16px 0', justifyContent: 'center' }}>
                <Loader2 style={{ width: 20, height: 20 }} className="animate-spin" />
                <span style={{ fontSize: 12, color: 'var(--text-secondary)' }}>Loading result databases...</span>
              </div>
            ) : resultCompanies.length === 0 ? (
              <p style={{ fontSize: 12, color: 'var(--text-muted)', textAlign: 'center', margin: 0 }}>No result databases found. Tap refresh to reload.</p>
            ) : (
              <select
                value={selectedResultCompany}
                onChange={e => setSelectedResultCompany(e.target.value)}
                className="select-input" style={{ padding: '10px 12px', fontSize: 13.5 }}>
                {resultCompanies.map(c => (
                  <option key={c.id} value={String(c.id)}>{c.name}</option>
                ))}
              </select>
            )}
          </div>
        )}
      </div>

      {/* 2. Select Accounts */}
      <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h4 style={{ fontSize: 13, fontWeight: 'bold', color: 'var(--text-primary)', margin: 0, display: 'flex', alignItems: 'center', gap: 6 }}>
            <Users style={{ width: 15, height: 15, color: 'var(--primary-light)' }} /> 2. Choose Accounts
          </h4>
          <button onClick={handleSelectAllAccounts}
            style={{ background: 'none', border: 'none', color: 'var(--primary-light)', fontSize: 12, fontWeight: 'bold', cursor: 'pointer' }}>
            {selectedAccounts.length === accounts.length ? 'Deselect All' : 'Select All'}
          </button>
        </div>

        <input type="text" placeholder="Filter accounts..." value={accountSearch}
          onChange={e => setAccountSearch(e.target.value)}
          className="input" style={{ padding: '8px 12px', fontSize: 12 }} />

        {isLoadingAccounts ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '20px 0' }}>
            <Loader2 style={{ width: 24, height: 24 }} className="animate-spin" />
          </div>
        ) : accounts.length === 0 ? (
          <p style={{ fontSize: 12, color: 'var(--text-muted)', textAlign: 'center', margin: 0 }}>
            No accounts configured. Go to Accounts tab to add accounts.
          </p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8, maxHeight: 150, overflowY: 'auto', paddingRight: 4 }}>
            {filteredAccounts.map(acc => {
              const isChecked = selectedAccounts.includes(acc.id);
              return (
                <div key={acc.id}
                  onClick={() => !isProcessing && handleSelectAccount(acc.id)}
                  style={{
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                    padding: '10px 14px', borderRadius: 'var(--radius-md)',
                    background: isChecked ? 'var(--primary-subtle)' : 'rgba(255,255,255,0.02)',
                    border: isChecked ? '1px solid rgba(91,94,244,0.3)' : '1px solid var(--border)',
                    cursor: 'pointer', transition: 'var(--transition)'
                  }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                    <div style={{
                      width: 15, height: 15, borderRadius: 4,
                      border: isChecked ? '1px solid var(--primary-light)' : '1px solid var(--text-muted)',
                      background: isChecked ? 'var(--primary)' : 'transparent',
                      display: 'flex', alignItems: 'center', justifyContent: 'center'
                    }}>
                      {isChecked && <Award style={{ width: 11, height: 11, color: '#fff' }} />}
                    </div>
                    <div>
                      <div style={{ fontSize: 12.5, fontWeight: 'bold', color: 'var(--text-primary)' }}>{acc.name}</div>
                      <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 1 }}>BOID: ...{acc.boid ? acc.boid.slice(-4) : '????'}</div>
                    </div>
                  </div>
                  <span style={{ fontSize: 12, color: 'var(--text-muted)', background: 'rgba(255,255,255,0.04)', padding: '2px 8px', borderRadius: 50 }}>
                    {acc.username}
                  </span>
                </div>
              );
            })}
          </div>
        )}

        {accounts.length > 0 && (
          <button onClick={activeTab === 'apply' ? handleBulkApply : handleBulkCheck}
            disabled={isProcessing || selectedAccounts.length === 0}
            className="btn-primary"
            style={{ width: '100%', padding: '12px 0', fontSize: 14, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, marginTop: 4 }}>
            {isProcessing ? (
              <><Loader2 style={{ width: 16, height: 16 }} className="animate-spin" /> Processing sequentially...</>
            ) : (
              <><Play style={{ width: 14, height: 14 }} /> {activeTab === 'apply' ? 'Launch Bulk IPO Apply' : 'Launch Allotment Check'}</>
            )}
          </button>
        )}

        {activeTab === 'result' && (
          <div style={{ marginTop: 10, padding: 12, borderRadius: 'var(--radius-md)', background: 'rgba(255,255,255,0.03)', border: '1px solid var(--border)', display: 'flex', flexDirection: 'column', gap: 8 }}>
            <div style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-secondary)' }}>
              Check Any CDSC BOID Directly:
            </div>
            <div style={{ display: 'flex', gap: 8 }}>
              <input
                type="text"
                maxLength={16}
                placeholder="16-Digit BOID (e.g. 1301...)"
                value={manualBoid}
                onChange={e => setManualBoid(e.target.value.replace(/\D/g, ''))}
                className="input"
                style={{ flex: 1, padding: '9px 12px', fontSize: 12, letterSpacing: 1 }}
              />
              <button
                type="button"
                onClick={() => handleCheckSingleBoid(manualBoid)}
                disabled={isProcessing || manualBoid.length !== 16 || !selectedResultCompany}
                className="btn-primary"
                style={{ padding: '9px 16px', fontSize: 12, whiteSpace: 'nowrap', opacity: (isProcessing || manualBoid.length !== 16 || !selectedResultCompany) ? 0.6 : 1 }}
              >
                {isProcessing ? 'Checking...' : 'Check Allotment'}
              </button>
            </div>
          </div>
        )}
      </div>
    </>
  )}

      {/* 3. Apply Results */}
      {activeTab === 'apply' && applyResults.length > 0 && (
        <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <h4 className="section-title">Submission Logs</h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
            {applyResults.map(r => (
              <div key={r.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: 10, background: 'rgba(255,255,255,0.02)', border: '1px solid var(--border)', borderRadius: 'var(--radius-sm)' }}>
                <div>
                  <div style={{ fontWeight: 'bold', fontSize: 12.5, color: 'var(--text-primary)' }}>{r.name}</div>
                  <div style={{ fontSize: 12, color: r.status === 'success' ? 'var(--bull)' : r.status === 'failed' ? 'var(--bear)' : 'var(--text-muted)', marginTop: 2 }}>{r.resultText}</div>
                </div>
                <div>
                  {r.status === 'loading' && <Loader2 style={{ width: 14, height: 14, color: 'var(--primary-light)' }} className="animate-spin" />}
                  {r.status === 'success' && <CheckCircle2 style={{ width: 16, height: 16, color: 'var(--bull)' }} />}
                  {r.status === 'failed' && <XCircle style={{ width: 16, height: 16, color: 'var(--bear)' }} />}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 4. Check Results */}
      {activeTab === 'result' && checkResults.length > 0 && (
        <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h3 className="section-title" style={{ marginBottom: 0, color: 'var(--text-primary)' }}>Lottery Results</h3>
            <button onClick={() => setCheckResults([])}
              style={{ background: 'none', border: 'none', color: 'var(--text-muted)', fontSize: 12, cursor: 'pointer' }}>Clear</button>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
            <div style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid var(--border)', borderRadius: 'var(--radius-md)', padding: 12 }}>
              <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)', textTransform: 'uppercase', display: 'block' }}>Total Allotted</span>
              <span style={{ fontSize: 15, fontWeight: 950, color: 'var(--bull)', fontFamily: 'var(--font-mono)', display: 'block', marginTop: 4 }}>{totalAllottedShares} Units</span>
            </div>
            <div style={{ background: 'rgba(255,255,255,0.02)', border: '1px solid var(--border)', borderRadius: 'var(--radius-md)', padding: 12 }}>
              <span style={{ fontSize: 12, fontWeight: 800, color: 'var(--text-secondary)', textTransform: 'uppercase', display: 'block' }}>Wins</span>
              <span style={{ fontSize: 15, fontWeight: 950, color: 'var(--primary-light)', display: 'block', marginTop: 4 }}>{allottedCount} / {checkResults.length}</span>
            </div>
          </div>

          {allottedCount > 0 && (
            <div style={{ background: 'var(--bull-subtle)', border: '1px solid rgba(16,217,138,0.25)', padding: 12, borderRadius: 'var(--radius-md)', display: 'flex', gap: 8 }}>
              <Sparkles style={{ width: 15, height: 15, color: 'var(--bull)', flexShrink: 0, marginTop: 1 }} />
              <div>
                <span style={{ fontSize: 12, fontWeight: 'bold', color: 'var(--bull)', display: 'block' }}>ALLOTMENT SUCCESSFUL 🎉</span>
                <span style={{ fontSize: 12, color: 'var(--text-primary)', opacity: 0.9 }}>Congratulations! You have been selected in the lottery.</span>
              </div>
            </div>
          )}

          {allottedCount > 0 && (
            <div style={{ background: 'rgba(245,158,11,0.08)', border: '1px solid rgba(245,158,11,0.25)', padding: 12, borderRadius: 'var(--radius-md)', display: 'flex', gap: 8 }}>
              <ShieldAlert style={{ width: 15, height: 15, color: 'var(--accent-amber)', flexShrink: 0, marginTop: 1 }} />
              <div>
                <span style={{ fontSize: 12, fontWeight: 'bold', color: 'var(--accent-amber)', display: 'block' }}>⚠️ MANDATORY EDIS STEP</span>
                <span style={{ fontSize: 12, color: 'var(--text-primary)', opacity: 0.85, lineHeight: 1.45 }}>Submit EDIS (Share Transfer) on MeroShare within 24 hours of selling allotted shares to avoid a 20% fine.</span>
              </div>
            </div>
          )}

          <div style={{ border: '1px solid var(--border)', borderRadius: 'var(--radius-md)', overflow: 'hidden' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: 12 }}>
              <thead>
                <tr style={{ background: 'rgba(255,255,255,0.03)', borderBottom: '1px solid var(--border)', color: 'var(--text-secondary)' }}>
                  <th style={{ padding: '8px 10px', fontWeight: 'bold' }}>Name</th>
                  <th style={{ padding: '8px 10px', fontWeight: 'bold' }}>Status</th>
                  <th style={{ padding: '8px 10px', fontWeight: 'bold', textAlign: 'right' }}>Shares</th>
                </tr>
              </thead>
              <tbody>
                {checkResults.map((r, i) => (
                  <tr key={i} style={{ borderBottom: i === checkResults.length - 1 ? 'none' : '1px solid rgba(255,255,255,0.03)', background: r.status === 'allotted' ? 'var(--bull-subtle)' : 'transparent' }}>
                    <td style={{ padding: '10px', fontWeight: 600, color: 'var(--text-primary)' }}>
                      <div>{r.name}</div>
                      <div style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'var(--font-mono)', marginTop: 2 }}>BOID: ...{r.boid ? r.boid.slice(-4) : ''}</div>
                    </td>
                    <td style={{ padding: '10px' }}>
                      <span style={{
                        display: 'inline-flex', padding: '2px 6px', borderRadius: 4, fontSize: 12, fontWeight: 'bold', textTransform: 'uppercase',
                        ...(r.status === 'allotted' ? { background: 'rgba(16,217,138,0.1)', color: 'var(--bull)' } :
                          r.status === 'not_allotted' ? { background: 'rgba(245,69,92,0.1)', color: 'var(--bear)' } :
                            { background: 'rgba(255,255,255,0.05)', color: 'var(--text-muted)' })
                      }}>
                        {r.status === 'allotted' ? 'Allotted' : r.status === 'not_allotted' ? 'Not Allotted' : 'Failed'}
                      </span>
                    </td>
                    <td style={{ padding: '10px', textAlign: 'right', fontWeight: r.status === 'allotted' ? 800 : 500, color: r.status === 'allotted' ? 'var(--bull)' : 'var(--text-muted)', fontFamily: 'var(--font-mono)' }}>
                      {r.units > 0 ? `+${r.units}` : '0'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* 5. Application History Tab */}
      {activeTab === 'my-applications' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
          <div className="card" style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 8 }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                <History style={{ width: 16, height: 16, color: 'var(--primary-light)' }} />
                <h4 style={{ fontSize: 13, fontWeight: 'bold', color: 'var(--text-primary)', margin: 0 }}>
                  C-ASBA Application History & Status
                </h4>
              </div>
              <button
                onClick={() => fetchApplicationHistory(selectedHistoryAccount)}
                disabled={isLoadingHistory}
                style={{ background: 'none', border: 'none', color: 'var(--primary-light)', cursor: 'pointer', padding: 4, display: 'flex', alignItems: 'center', gap: 4, fontSize: 12, fontWeight: 600 }}
              >
                <RefreshCw style={{ width: 13, height: 13 }} className={isLoadingHistory ? 'animate-spin' : ''} />
                Refresh
              </button>
            </div>

            {/* Account Switcher */}
            {accounts.length > 1 && (
              <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 4 }}>
                <span style={{ fontSize: 12, color: 'var(--text-secondary)', whiteSpace: 'nowrap' }}>Account:</span>
                <select
                  value={selectedHistoryAccount}
                  onChange={(e) => {
                    setSelectedHistoryAccount(e.target.value);
                    fetchApplicationHistory(e.target.value);
