                    const isVerified = st.includes('VERIFIED') || st.includes('APPROV');
                    return (
                      <tr key={h.id || i} style={{ background: isAllotted ? 'var(--bull-subtle)' : 'transparent', borderBottom: '1px solid rgba(255,255,255,0.03)' }}>
