  // Sub Tabs & Portfolio state
  const [activeSubTab, setActiveSubTab] = useState(() => initialTab || 'accounts'); // 'accounts', 'ipo', 'portfolio'
  const [ipoSubTab, setIpoSubTab] = useState('apply'); // 'apply' | 'check'

  useEffect(() => {
