                <div>
                  <label className="text-[11px] font-semibold text-slate-400 block mb-1">4-Digit PIN (Optional)</label>
                  <input
                    type="password"
                    maxLength={4}
                    placeholder="Transaction PIN"
                    value={newAcc.pin}
                    onChange={(e) => setNewAcc({ ...newAcc, pin: e.target.value.replace(/\D/g, '') })}
                    className="w-full rounded-xl border border-slate-700 bg-slate-800 px-3 py-2 text-xs text-white outline-none font-mono focus:border-blue-500"
                  />
                </div>
              </div>

              <div className="flex items-center justify-end gap-2 pt-2">
                <button
                  type="button"
                  onClick={() => setShowAddForm(false)}
                  className="px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-semibold text-slate-300 cursor-pointer"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-1.5 rounded-xl bg-blue-600 hover:bg-blue-700 text-xs font-bold text-white cursor-pointer"
                >
                  Save to Vault
                </button>
              </div>
            </form>
          )}

          {/* Accounts List */}
          {accounts.length === 0 ? (
            <div className="rounded-2xl border border-slate-800 bg-slate-900/40 p-8 text-center space-y-2">
              <Lock size={28} className="mx-auto text-slate-500" />
              <h5 className="text-sm font-bold text-white">No MeroShare accounts in vault</h5>
              <p className="text-xs text-slate-400 max-w-sm mx-auto">
                Add your family MeroShare accounts to apply for IPOs with a single click and check batch lottery results simultaneously.
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              {accounts.map(acc => {
                const isPwVisible = showPassword[acc.id];
                return (
                  <div key={acc.id} className="rounded-2xl border border-slate-800 bg-slate-900/60 p-4 space-y-2 relative">
                    <div className="flex items-start justify-between">
                      <div>
                        <div className="text-sm font-bold text-white">{acc.name}</div>
                        <div className="text-xs text-slate-400 font-mono mt-0.5">
                          BOID: {acc.boid ? `${acc.boid.slice(0, 4)}...${acc.boid.slice(-4)}` : '—'}
                        </div>
                      </div>
                      <button
                        onClick={() => handleDeleteAccount(acc.id, acc.name)}
                        className="text-slate-500 hover:text-rose-400 p-1 cursor-pointer transition"
                        title="Delete account"
                      >
                        <Trash2 size={13} />
                      </button>
                    </div>

                    <div className="text-xs text-slate-300 space-y-1 pt-1 border-t border-slate-800/80 font-mono">
                      <div className="flex items-center justify-between">
                        <span className="text-slate-500">User:</span>
                        <span>{acc.username}</span>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-slate-500">Pass:</span>
                        <div className="flex items-center gap-1.5">
                          <span>{isPwVisible ? acc.password : '••••••••'}</span>
                          <button
                            type="button"
                            onClick={() => setShowPassword(prev => ({ ...prev, [acc.id]: !isPwVisible }))}
                            className="text-slate-500 hover:text-slate-300 p-0.5 cursor-pointer"
                          >
                            {isPwVisible ? <EyeOff size={11} /> : <Eye size={11} />}
                          </button>
                        </div>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-slate-500">CRN:</span>
                        <span className={acc.crn ? 'text-emerald-400' : 'text-slate-500'}>{acc.crn ? 'Configured' : 'Missing'}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* ────────────────── 2. DESK PREFERENCES ────────────────── */}
      {activeTab === 'preferences' && (
        <div className="space-y-3">
          {/* Active Portfolio Capital Configuration */}
          <div className="rounded-2xl border border-indigo-500/30 bg-gradient-to-r from-slate-900 via-slate-900 to-indigo-950/40 p-4 space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-xs font-extrabold uppercase tracking-wider text-indigo-400 flex items-center gap-1.5">
                <Coins size={14} className="text-indigo-400" /> Active Portfolio Capital &amp; Risk Sizing
              </h4>
              <span className="text-[10px] font-bold font-mono px-2 py-0.5 rounded-full bg-indigo-500/20 text-indigo-300 border border-indigo-500/30">
                {getCapitalTierConfig(userCapital).tierName}
              </span>
            </div>
            <p className="text-xs text-slate-400">
              Live updates all alert execution tickets, recommended kitta position sizing, broker commission brackets, and 1% portfolio risk caps.
            </p>
            <div className="flex flex-col sm:flex-row sm:items-center gap-3 pt-1">
              <div className="flex-1 flex items-center gap-2">
                <span className="text-xs font-bold text-slate-400">Rs.</span>
                <input
                  type="number"
                  min="10000"
                  step="5000"
                  value={userCapital}
                  onChange={(e) => {
                    const next = Math.max(10000, Number(e.target.value) || 10000);
                    setUserCapitalState(next);
                    setUserConfiguredCapital(next);
                  }}
                  className="w-full rounded-xl border border-slate-700 bg-slate-800 px-3 py-2 text-sm font-black font-mono text-white outline-none focus:border-indigo-500"
                />
              </div>
              <div className="flex items-center gap-1.5">
                {[50000, 100000, 500000, 1000000].map(amt => (
                  <button
                    key={amt}
                    type="button"
                    onClick={() => {
                      triggerHaptic(25);
                      setUserCapitalState(amt);
                      setUserConfiguredCapital(amt);
                    }}
                    className={`px-2.5 py-1.5 rounded-xl text-[11px] font-bold font-mono transition cursor-pointer ${
                      userCapital === amt
                        ? 'bg-indigo-600 text-white shadow'
                        : 'bg-slate-800 text-slate-400 hover:text-white border border-slate-700'
                    }`}
                  >
                    Rs. {amt >= 100000 ? `${amt / 100000}L` : `${amt / 1000}k`}
                  </button>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-3 gap-2 pt-1 text-[11px] font-mono text-slate-400 border-t border-slate-800/80">
              <div>Slots: <b className="text-white">{getCapitalTierConfig(userCapital).maxSlots}</b></div>
              <div>Risk: <b className="text-rose-400">{(getCapitalTierConfig(userCapital).riskPerTradePct * 100).toFixed(2)}%</b></div>
              <div>Slot Max: <b className="text-emerald-400">{(getCapitalTierConfig(userCapital).maxSlotAllocationPct * 100).toFixed(0)}%</b></div>
            </div>
          </div>

