function SessionDateDropdown({
  selectedSessionDate,
  onSelectDate,
  availableDates,
}: {
  selectedSessionDate: string;
  onSelectDate: (d: string) => void;
  availableDates: string[];
}) {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent | TouchEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
      document.addEventListener('touchstart', handleClickOutside);
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('touchstart', handleClickOutside);
    };
  }, [isOpen]);

  return (
    <div ref={dropdownRef} style={{ position: 'relative', display: 'inline-flex', alignItems: 'center' }}>
      <button
        type="button"
        onClick={() => setIsOpen(!isOpen)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 6,
          background: selectedSessionDate ? 'rgba(56, 189, 248, 0.14)' : 'rgba(255, 255, 255, 0.06)',
          border: selectedSessionDate ? '1px solid rgba(56, 189, 248, 0.45)' : '1px solid rgba(255, 255, 255, 0.12)',
          borderRadius: 8,
          padding: '4px 9px',
          color: selectedSessionDate ? '#38bdf8' : '#e2e8f0',
          fontSize: 11,
          fontWeight: 800,
          cursor: 'pointer',
          outline: 'none',
          whiteSpace: 'nowrap',
          transition: 'all 0.15s ease',
        }}
        title={selectedSessionDate ? `Filtered to session ${selectedSessionDate}` : 'Viewing Latest Session'}
      >
        <Calendar size={12} color={selectedSessionDate ? '#38bdf8' : '#94a3b8'} />
        <span>{selectedSessionDate || 'Latest Session'}</span>
        <ChevronDown size={11} color={selectedSessionDate ? '#38bdf8' : '#94a3b8'} style={{ transform: isOpen ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }} />
      </button>

      {selectedSessionDate && (
        <button
          type="button"
          onClick={() => onSelectDate('')}
          style={{
            background: 'none',
            border: 'none',
            color: '#f43f5e',
            fontSize: 12,
            fontWeight: 900,
            cursor: 'pointer',
            padding: '2px 4px',
            marginLeft: 2,
          }}
          title="Reset to Latest Session"
        >
          ×
        </button>
      )}

      {isOpen && (
        <div
          style={{
            position: 'absolute',
            top: 'calc(100% + 6px)',
            left: 0,
            zIndex: 9999,
            minWidth: 220,
            maxWidth: 'calc(100vw - 24px)',
            maxHeight: 280,
            overflowY: 'auto',
            background: '#0B0E14',
            border: '1px solid rgba(255, 255, 255, 0.16)',
            borderRadius: 12,
            boxShadow: '0 16px 36px rgba(0, 0, 0, 0.85)',
            padding: 6,
            display: 'flex',
            flexDirection: 'column',
            gap: 2,
          }}
        >
          <div style={{ padding: '6px 10px', fontSize: 10, fontWeight: 800, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
            Select Trading Session
          </div>
          <button
            type="button"
            onClick={() => { onSelectDate(''); setIsOpen(false); }}
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              padding: '8px 10px',
              borderRadius: 8,
              background: !selectedSessionDate ? 'rgba(56, 189, 248, 0.15)' : 'transparent',
              color: !selectedSessionDate ? '#38bdf8' : '#e2e8f0',
              border: 'none',
              fontSize: 12,
              fontWeight: 700,
              cursor: 'pointer',
              textAlign: 'left',
              width: '100%',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
              <span style={{ width: 6, height: 6, borderRadius: '50%', background: '#10b981' }} />
              <span>Latest Session (Live)</span>
            </div>
            {!selectedSessionDate && <Check size={14} color="#38bdf8" />}
          </button>

          <div style={{ height: 1, background: 'rgba(255,255,255,0.06)', margin: '4px 0' }} />

          {availableDates.map(dt => (
            <button
              key={dt}
              type="button"
              onClick={() => { onSelectDate(dt); setIsOpen(false); }}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                padding: '7px 10px',
                borderRadius: 8,
                background: selectedSessionDate === dt ? 'rgba(56, 189, 248, 0.15)' : 'transparent',
                color: selectedSessionDate === dt ? '#38bdf8' : '#cbd5e1',
                border: 'none',
                fontSize: 12,
                fontWeight: 600,
                cursor: 'pointer',
                textAlign: 'left',
                width: '100%',
              }}
            >
              <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
                <Calendar size={12} color="#64748b" />
                <span>{dt}</span>
              </div>
              {selectedSessionDate === dt && <Check size={14} color="#38bdf8" />}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export default function ServicesHub({
  stocks = [],
  indices,
  apiStatus,
  userId,
  onNavigateTab,
  onSelectStock,
  onAskGuruAi,
}: ServicesHubProps = {}) {
  const [activeFilter, setActiveFilter] = useState('all');
  const [search, setSearch] = useState('');
  const [selectedSessionDate, setSelectedSessionDate] = useState<string>('');
  const [availableTradingDates, setAvailableTradingDates] = useState<string[]>([]);
  const [dateStocks, setDateStocks] = useState<any[]>([]);
  const [dateStocksLoading, setDateStocksLoading] = useState<boolean>(false);

  const [dateSubfile, setDateSubfile] = useState<any>(null);

  useEffect(() => {
    // 1. Fetch available trading sessions from subfiles index (bundled first for APK offline, then proxy)
    const loadManifest = async () => {
      const base = getProxyBase();
      for (const p of ['./data/subfiles/historical_subfiles_index.json', '/data/subfiles/historical_subfiles_index.json', `${base}/api/ledger/subfiles/index`]) {
        try {
          const res = await fetch(p);
          if (res.ok) {
            const manifest = await res.json();
            if (manifest?.available_sessions && Array.isArray(manifest.available_sessions) && manifest.available_sessions.length > 0) {
              setAvailableTradingDates(manifest.available_sessions);
              return;
            }
          }
        } catch (_) {}
      }
    };
    loadManifest();

    // 2. Also check available trading dates from legacy
    fetchAvailableTradingDates().then(dates => {
      if (Array.isArray(dates) && dates.length > 0) {
        setAvailableTradingDates(prev => Array.from(new Set([...(prev || []), ...dates])));
      }
    }).catch(() => {});
  }, []);

  useEffect(() => {
    if (!selectedSessionDate) {
      setDateStocks([]);
      setDateSubfile(null);
      return;
    }
    let active = true;
    setDateStocksLoading(true);

    // Fast Path: Check dedicated sub-file via getHistoricalSubfileDirect (< 2ms)
    getHistoricalSubfileDirect(selectedSessionDate).then((subfile: any) => {
      if (!active) return;
      if (subfile && subfile.scrips) {
        const mapped = Object.values(subfile.scrips).map((s: any) => ({
            symbol: s.symbol,
            companyName: s.company_name,
            name: s.company_name,
            sector: s.sector,
            ltp: s.card_1_quote?.ltp,
            closePrice: s.card_1_quote?.ltp,
            pChange: s.card_1_quote?.p_change,
            percentageChange: s.card_1_quote?.p_change,
            open: s.card_1_quote?.open,
            high: s.card_1_quote?.high,
            low: s.card_1_quote?.low,
            volume: s.card_1_quote?.volume,
            totalTradedQuantity: s.card_1_quote?.volume,
            turnover: s.card_1_quote?.turnover,
            totalTurnover: s.card_1_quote?.turnover,
            vwap: s.card_1_quote?.vwap,
            pivots: s.card_2_pivot_points,
            rsi: s.card_3_oscillators_risk?.rsi_14,
            atr: s.card_3_oscillators_risk?.atr_14,
            leadBroker: s.card_4_broker_smart_flow?.lead_accumulator,
            topAccumulator: s.card_4_broker_smart_flow?.lead_accumulator?.broker_id,
            bcr3BuyPct: s.card_4_broker_smart_flow?.concentration?.bcr3_buy_pct,
            brokerAnalysis: s.card_4_broker_smart_flow,
            stealthAccumulation: s.card_5_wyckoff_and_dump_guard?.wyckoff_phase,
            isTrap: s.card_5_wyckoff_and_dump_guard?.is_trap,
            trapAudit: s.card_5_wyckoff_and_dump_guard,
            tacticalLevels: s.card_6_tactical_execution,
            subfileScrip: s
          }));
          if (active && mapped.length > 0) {
            setDateStocks(mapped);
            setDateSubfile(subfile);
            setDateStocksLoading(false);
            return;
          }
        }
        // Fallback to fetchLiveMarketData
        fetchLiveMarketData(selectedSessionDate).then(data => {
          const stockArr = Array.isArray(data) ? data : (data?.stocks || data?.data || []);
          if (active && Array.isArray(stockArr) && stockArr.length > 0) {
            setDateStocks(stockArr);
          }
        }).catch(() => {}).finally(() => {
          if (active) setDateStocksLoading(false);
        });
      }).catch(() => {
        fetchLiveMarketData(selectedSessionDate).then(data => {
          const stockArr = Array.isArray(data) ? data : (data?.stocks || data?.data || []);
          if (active && Array.isArray(stockArr) && stockArr.length > 0) {
            setDateStocks(stockArr);
          }
        }).catch(() => {}).finally(() => {
          if (active) setDateStocksLoading(false);
        });
      });

    return () => { active = false; };
  }, [selectedSessionDate]);

  const activeStocks = (selectedSessionDate && dateStocks.length > 0) ? dateStocks : stocks;
  const [selectedService, setSelectedService] = useState<ServiceDef | null>(() => {
    try {
      const openId = typeof window !== 'undefined' ? localStorage.getItem('open_service_id') : null;
      if (openId) {
        const found = ALL_SERVICES.find((s) => s.id === openId);
        if (found) {
          localStorage.removeItem('open_service_id');
          return found;
        }
      }
    } catch (_) {}
    return null;
  });
  const [serviceInitialSymbol, setServiceInitialSymbol] = useState<string>(() => {
    try {
      return (typeof window !== 'undefined' ? localStorage.getItem('selected_entry_exit_symbol') : '') || '';
    } catch (_) {
      return '';
    }
  });

