                {tradePlanCorridor.t1 && <span>T1: <strong style={{ color: '#34d399' }}>Rs. {tradePlanCorridor.t1}</strong></span>}
                {tradePlanCorridor.t2 && <span>T2: <strong style={{ color: '#10b981' }}>Rs. {tradePlanCorridor.t2}</strong></span>}
