export class StockBrokerAnalysisErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }

  componentDidCatch(error, info) {
    console.error('[StockBrokerAnalysisTab] Caught render exception:', error, info);
  }

  componentDidUpdate(prevProps) {
    if (this.state.hasError && (prevProps.symbol !== this.props.symbol || prevProps.selectedDays !== this.props.selectedDays || prevProps.selectedDate !== this.props.selectedDate)) {
      this.setState({ hasError: false, error: null });
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          background: '#111827',
          border: '1px solid rgba(245, 158, 11, 0.4)',
          borderRadius: 16,
          padding: 16,
          color: '#e2e8f0',
          textAlign: 'center'
        }}>
          <div style={{ fontSize: 14, fontWeight: 800, color: '#f59e0b', marginBottom: 6 }}>
            ⚠️ Broker Flow Telemetry Recovery Mode
          </div>
          <p style={{ fontSize: 12, color: '#94a3b8', marginBottom: 12 }}>
            A temporary microstructure aggregation mismatch occurred ({this.state.error?.message || 'Incomplete broker data'}).
          </p>
          <button
            type="button"
            onClick={() => this.setState({ hasError: false, error: null })}
            style={{
              padding: '6px 14px',
              borderRadius: 8,
              border: 'none',
              background: '#0284c7',
              color: '#ffffff',
              fontSize: 12,
              fontWeight: 800,
              cursor: 'pointer'
            }}
          >
            Retry Broker Flow
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function StockBrokerAnalysisTab(props) {
  return (
    <StockBrokerAnalysisErrorBoundary symbol={props.symbol} selectedDays={props.selectedDays} selectedDate={props.selectedDate}>
      <StockBrokerAnalysisTabInner {...props} />
    </StockBrokerAnalysisErrorBoundary>
  );
}

