class CardLocalErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(err) {
    console.warn("[StockDetail] Card error caught:", err);
  }
  componentDidUpdate(prevProps) {
    if (this.state.hasError && prevProps.children !== this.props.children) {
      this.setState({ hasError: false });
    }
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ background: '#111827', border: '1px solid rgba(244, 63, 94, 0.3)', borderRadius: 16, padding: 16, color: '#f8fafc', margin: '8px 0' }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: '#f43f5e', marginBottom: 4 }}>
            ⚠️ Flow Telemetry Syncing
          </div>
          <div style={{ fontSize: 12, color: '#94a3b8', marginBottom: 10 }}>
            Unable to compute multi-day diagnostics for this timeframe. Reverting to 1-Day verified flow.
          </div>
          <button
            type="button"
            onClick={() => this.setState({ hasError: false })}
            style={{ padding: '6px 14px', borderRadius: 8, background: '#38bdf8', color: '#000', fontWeight: 800, fontSize: 12, border: 'none', cursor: 'pointer' }}
          >
            Reset View
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

// ── 1B. Beginner Confidence & Rupee Profit Simulator Card ──
function BeginnerConfidenceCard({
  d,
  entryExitPlan,
  realBrokerAnalysis,
  brokerConcentration,
  brokerDays = 1,
  onSelectBrokerDays,
  brokerLoading = false,
  realPriceHistory = null
}) {
  const [selectedCapital, setSelectedCapital] = useState(25000);

  // Check 1: Financial Health
  const epsVal = Number(d?.eps);
  const bvVal = Number(d?.bookValue || d?.bv || 0);
  const hasEpsData = d?.eps !== undefined && d?.eps !== null && !isNaN(epsVal) && epsVal !== 0;
  const isLossMaking = hasEpsData && epsVal < 0;
  const isGoodEps = hasEpsData && epsVal > 10 && bvVal >= 100;
  const isModEps = hasEpsData && epsVal > 0;

  let check1Badge = '⚪ Data Pending / Filing Interim';
  let check1Desc = 'Company quarterly filings are being updated from exchange reports.';
  let check1Color = '#94a3b8';
  let check1Bg = 'rgba(148, 163, 184, 0.08)';
  let check1Border = 'rgba(148, 163, 184, 0.25)';

  if (isLossMaking) {
    check1Badge = '🔴 Operating Loss / High Risk';
    check1Desc = `Warning: Company reported negative earnings (EPS -Rs. ${Math.abs(epsVal).toFixed(1)}). Exercise caution.`;
    check1Color = '#f43f5e';
    check1Bg = 'rgba(244, 63, 94, 0.08)';
    check1Border = 'rgba(244, 63, 94, 0.25)';
  } else if (isGoodEps) {
    check1Badge = '🟢 Strong & Profitable';
    check1Desc = `Profitable company earning Rs. ${epsVal.toFixed(1)} per share with a solid Rs. ${bvVal.toFixed(1)} Book Value.`;
    check1Color = '#10b981';
    check1Bg = 'rgba(16, 185, 129, 0.08)';
    check1Border = 'rgba(16, 185, 129, 0.25)';
  } else if (isModEps) {
    check1Badge = '🟡 Moderate Earnings';
    check1Desc = `Company is profitable (EPS Rs. ${epsVal.toFixed(1)}), though earnings growth is moderate.`;
    check1Color = '#f59e0b';
    check1Bg = 'rgba(245, 158, 11, 0.08)';
    check1Border = 'rgba(245, 158, 11, 0.25)';
  }

  const dailyHistory = useMemo(() => {
    try {
      const hist = (Array.isArray(realPriceHistory) && realPriceHistory.length > 0)
        ? realPriceHistory
        : (Array.isArray(d?.history) ? d.history : (Array.isArray(d?.candles) ? d.candles : []));
      return buildDailyHistoryFromStockData(d, realBrokerAnalysis, hist) || [];
    } catch (_) {
      return [];
    }
  }, [d, realBrokerAnalysis, realPriceHistory]);

  const multiDayDiag = useMemo(() => {
    try {
      return calculateMultiDayDiagnostics(dailyHistory, brokerDays);
    } catch (_) {
      return null;
    }
  }, [dailyHistory, brokerDays]);
  const diag = multiDayDiag;

  // Check 2: Big Broker / Smart Money Activity (Dynamically bound to brokerDays via rolling-window microstructure)
  // When dailyHistory contains fewer sessions than brokerDays, prefer the authoritative backend multi-day rollup in realBrokerAnalysis
  const isHistorySufficient = Boolean(multiDayDiag && multiDayDiag.timeframeDays >= brokerDays && dailyHistory.length >= brokerDays);

  const bcr3Buy = Number(realBrokerAnalysis?.bcr3BuyPct ?? brokerConcentration?.bcr3BuyPct ?? 0);
  const bcr3Sell = Number(realBrokerAnalysis?.bcr3SellPct ?? brokerConcentration?.bcr3SellPct ?? 0);
  const grossBuyPct = Number(
    (isHistorySufficient ? multiDayDiag?.grossBuyConcentrationPct : null) ??
    realBrokerAnalysis?.grossBuyConcentrationPct ??
    realBrokerAnalysis?.bcr5BuyPct ??
    realBrokerAnalysis?.bcr3BuyPct ??
    multiDayDiag?.grossBuyConcentrationPct ??
    bcr3Buy ??
    0
  );
  const grossSellPct = Number(
    (isHistorySufficient ? multiDayDiag?.grossSellConcentrationPct : null) ??
    realBrokerAnalysis?.grossSellConcentrationPct ??
    realBrokerAnalysis?.scr3SellPct ??
    realBrokerAnalysis?.bcr3SellPct ??
    multiDayDiag?.grossSellConcentrationPct ??
    bcr3Sell ??
    0
  );
  const nbar = Number(realBrokerAnalysis?.nbar ?? (grossSellPct > 0 ? grossBuyPct / grossSellPct : 1.0));
  const rawWhaleVwap = (isHistorySufficient ? multiDayDiag?.bigBrokerVWAP : null) ??
    realBrokerAnalysis?.bigBrokerVWAP ??
    multiDayDiag?.bigBrokerVWAP;
  const whaleVwap = (rawWhaleVwap != null && !isNaN(Number(rawWhaleVwap)) && Number(rawWhaleVwap) > 0)
    ? Number(rawWhaleVwap).toFixed(1)
    : null;

  const rawBcr5Net = (isHistorySufficient ? multiDayDiag?.bcr5NetPct : null) ??
    realBrokerAnalysis?.bcr5NetPct ??
    multiDayDiag?.bcr5NetPct ??
    grossBuyPct;
  const bcr5Net = Number(rawBcr5Net).toFixed(1);

  const currentPhase = (isHistorySufficient ? multiDayDiag?.phase : null) ??
    realBrokerAnalysis?.phase ??
    multiDayDiag?.phase;

  const hasBrokerData = Boolean(
    realBrokerAnalysis ||
    (dailyHistory && dailyHistory.length > 0) ||
    (brokerConcentration && (Number(brokerConcentration.bcr3BuyPct) > 0 || Number(brokerConcentration.totalVolume) > 0))
  );

  let check2Badge = '⚪ Normal Retail Flow';
  let check2Desc = `Buying (${grossBuyPct.toFixed(1)}%) and selling (${grossSellPct.toFixed(1)}%) are evenly spread across retail brokers.`;
  let check2Color = '#94a3b8';
  let check2Bg = 'rgba(148, 163, 184, 0.06)';
  let check2Border = 'rgba(148, 163, 184, 0.2)';

  if (brokerLoading || (!hasBrokerData && grossBuyPct === 0 && grossSellPct === 0)) {
    check2Badge = '🔄 Analyzing Smart Money Flow...';
    check2Desc = `Verifying session floorsheet transactions, broker concentrations, and accumulation metrics for ${d?.symbol || 'stock'}...`;
    check2Color = '#38bdf8';
    check2Bg = 'rgba(56, 189, 248, 0.08)';
    check2Border = 'rgba(56, 189, 248, 0.25)';
  } else {
    const cardOrderFlowVeto = evaluateOrderFlowVeto(realBrokerAnalysis, d);
    // Only evaluate Distribution/Trap if there is genuine sell dominance and activity
    const isDistributionOrTrap = Boolean(
      cardOrderFlowVeto.isVetoed ||
      currentPhase === 'DISTRIBUTION_DANGER' ||
      currentPhase === 'BULL_TRAP' ||
      (realBrokerAnalysis?.adSignal === 'Distribution' && grossSellPct >= 35 && grossSellPct > grossBuyPct) ||
      (grossSellPct >= 38 && grossSellPct > grossBuyPct && nbar <= 0.85) ||
      (grossSellPct >= 35 && nbar <= 0.70)
    );

    // Harmonize with BrokerSmartMoneyCard gauge: Accumulation requires >= 62% net dominance or strong buy-tilt
    const totalTop5 = grossBuyPct + grossSellPct;
    const accumulationPressurePct = totalTop5 > 0 ? Math.round((grossBuyPct / totalTop5) * 100) : 50;

    const isStrongAccumulation = Boolean(
      !isDistributionOrTrap && (
        accumulationPressurePct >= 62 ||
        (grossBuyPct >= 42 && grossBuyPct > grossSellPct * 1.3 && nbar >= 1.2) ||
        currentPhase === 'ACTIVE_MARKUP'
      )
    );

    const isStrongDistribution = Boolean(
      isDistributionOrTrap ||
      accumulationPressurePct <= 38 ||
      (grossSellPct >= 42 && grossSellPct > grossBuyPct * 1.3 && nbar <= 0.8)
    );

    if (isStrongDistribution) {
      const cardOrderFlowVeto = evaluateOrderFlowVeto(realBrokerAnalysis, d);
      check2Badge = cardOrderFlowVeto.isVetoed ? '🚨 Order Flow Veto: Whale Dump' : '🚨 Big Players Selling (Distribution Warning)';
      check2Desc = cardOrderFlowVeto.isVetoed
        ? `Order Flow Veto: ${cardOrderFlowVeto.reason}. Heavy institutional selling overrides all accumulation patterns.`
        : `Caution: Top selling brokers account for ${grossSellPct.toFixed(1)}% of volume (vs ${grossBuyPct.toFixed(1)}% buy). Big players are offloading inventory.`;
      check2Color = '#f43f5e';
      check2Bg = 'rgba(244, 63, 94, 0.12)';
      check2Border = 'rgba(244, 63, 94, 0.35)';
    } else if (isStrongAccumulation) {
      check2Badge = '🟢 Big Players Accumulating';
      check2Desc = `Top 5 brokers absorbed ${grossBuyPct.toFixed(1)}% of all shares bought${whaleVwap ? ` at Big Broker VWAP of Rs. ${whaleVwap}` : ''} (Net absorption: ${bcr5Net}%).`;
      check2Color = '#10b981';
      check2Bg = 'rgba(16, 185, 129, 0.08)';
      check2Border = 'rgba(16, 185, 129, 0.25)';
    } else {
      check2Badge = '⚖️ Balanced Two-Way Rotation';
      check2Desc = `Top 5 broker flow is in equilibrium (${grossBuyPct.toFixed(1)}% buy vs ${grossSellPct.toFixed(1)}% sell). Two-way inventory rotation without directional cornering.`;
      check2Color = '#94a3b8';
      check2Bg = 'rgba(148, 163, 184, 0.06)';
      check2Border = 'rgba(148, 163, 184, 0.2)';
    }
  }

  // Check 3: Entry Price Timing & Safety (Fixed Math Logic & Anchored to Big Broker VWAP)
  const validPositive = (v) => {
    const n = Number(v);
    return (!isNaN(n) && isFinite(n) && n > 0) ? n : null;
  };

  const ltp = Number(d?.ltp || 100);
  const pChange = Number(d?.pChange || 0);
  const lv = entryExitPlan?.levels;
  const entryLow = Number(
    (isHistorySufficient ? validPositive(multiDayDiag?.buyZoneMin) : null) ??
    validPositive(realBrokerAnalysis?.buyZoneMin) ??
    validPositive(multiDayDiag?.buyZoneMin) ??
    validPositive(lv?.entryZone?.low) ??
    validPositive(lv?.pullbackAnchor) ??
    +(ltp * 0.98).toFixed(1)
  );
  const entryHigh = Number(
    (isHistorySufficient ? validPositive(multiDayDiag?.buyZoneMax) : null) ??
    validPositive(realBrokerAnalysis?.buyZoneMax) ??
    validPositive(multiDayDiag?.buyZoneMax) ??
    validPositive(lv?.entryZone?.high) ??
    validPositive(lv?.entryZone?.max) ??
    validPositive(lv?.breakoutPivot) ??
    +(ltp * 1.02).toFixed(1)
  );
  const isCircuitTrap = Boolean(entryExitPlan?.riskGate?.isCircuitTrap || pChange >= 10);

  const fallbackPullbackTarget = (whaleVwap && Number(whaleVwap) > 0)
    ? Number(whaleVwap)
    : (entryHigh > 0 ? entryHigh : +(ltp * 0.98).toFixed(1));

  // Sanitize description: If multiDayDiag?.entryDescription contains '0–0' or 'Rs. 0' or '0.0', discard and regenerate cleanly
  const rawDiagDesc = multiDayDiag?.entryDescription;
  const isDiagDescInvalid = !rawDiagDesc ||
    rawDiagDesc.includes('0–0') ||
    rawDiagDesc.includes(' 0-0') ||
    rawDiagDesc.includes('Rs. 0.0') ||
    rawDiagDesc.includes('Rs. 0)') ||
    rawDiagDesc.includes('Rs. 0 ');

  let check3Badge = '🟡 Extended Above Buy Zone';
  let check3Desc = (!isDiagDescInvalid ? rawDiagDesc : null) ||
    `Price (Rs. ${ltp}) is extended above the ideal Buy Zone (Rs. ${entryLow}–${entryHigh}). Wait for a pullback toward Rs. ${fallbackPullbackTarget} instead of chasing.`;
  let check3Color = '#f59e0b';
  let check3Bg = 'rgba(245, 158, 11, 0.08)';
  let check3Border = 'rgba(245, 158, 11, 0.25)';

  if (isCircuitTrap) {
    check3Badge = '🛑 Too High / Circuit Trap Risk';
    check3Desc = `High Risk: Stock has already surged +${pChange.toFixed(1)}%. Never chase near the circuit limit due to T+2 settlement lockup.`;
    check3Color = '#f43f5e';
    check3Bg = 'rgba(244, 63, 94, 0.08)';
    check3Border = 'rgba(244, 63, 94, 0.25)';
  } else if (ltp < entryLow) {
    check3Badge = '🔵 Discounted / Below Buy Zone';
    check3Desc = `Current price (Rs. ${ltp}) is trading below the Safe Buy Zone (Rs. ${entryLow}–${entryHigh})${whaleVwap ? `, near/below Big Broker VWAP of Rs. ${whaleVwap}` : ` (Support at Rs. ${entryLow})`}.`;
    check3Color = '#38bdf8';
    check3Bg = 'rgba(56, 189, 248, 0.08)';
    check3Border = 'rgba(56, 189, 248, 0.25)';
  } else if (ltp >= entryLow && ltp <= entryHigh) {
    check3Badge = '🟢 Within Safe Buy Zone';
    check3Desc = `Current price (Rs. ${ltp}) is strictly inside the Safe Buy Zone (Rs. ${entryLow}–${entryHigh})${whaleVwap ? ` anchored by Big Broker VWAP of Rs. ${whaleVwap}` : ''}.`;
    check3Color = '#10b981';
    check3Bg = 'rgba(16, 185, 129, 0.08)';
    check3Border = 'rgba(16, 185, 129, 0.25)';
  } else {
    check3Badge = '🟡 Extended Above Buy Zone';
    check3Desc = (!isDiagDescInvalid ? rawDiagDesc : null) ||
      `Current price (Rs. ${ltp}) is extended above the Safe Buy Zone (Rs. ${entryLow}–${entryHigh}). Wait for a pullback toward Rs. ${fallbackPullbackTarget} instead of chasing.`;
    check3Color = '#f59e0b';
    check3Bg = 'rgba(245, 158, 11, 0.08)';
    check3Border = 'rgba(245, 158, 11, 0.25)';
  }

  // DISCREPANCY FIX: Override "Within Safe Buy Zone" (green) when the Master Consensus
  // from the Entry/Exit Analyzer says AVOID / EXIT / NO TRADE.
  // Showing a green "Safe Buy Zone" badge while the quantitative engine says AVOID is dangerously
  // misleading — the price band check alone does NOT constitute a safe entry when technical
  // consensus, momentum gates, or broker flow all contradict a buy.
  const _eeVerdictForCheck3 = String(entryExitPlan?.verdict || '').toUpperCase();
  const _eeSetupScoreForCheck3 = Number(entryExitPlan?.setupScore ?? entryExitPlan?.combinedScore ?? 0);
  const _isAvoidVerdict =
    _eeVerdictForCheck3.includes('NO TRADE') ||
    _eeVerdictForCheck3.includes('AVOID') ||
    _eeVerdictForCheck3.startsWith('EXIT') ||
    _eeVerdictForCheck3.startsWith('REDUCE') ||
    _eeVerdictForCheck3.startsWith('STAY OUT') ||
    Boolean(entryExitPlan?.riskGate?.isInstitutionalDumping) ||
    _eeSetupScoreForCheck3 < 40;
  if (_isAvoidVerdict && check3Badge.includes('Within Safe Buy Zone')) {
    // Price is geometrically inside the zone, but ALL technical/flow signals say AVOID.
    // Downgrade to amber CAUTION — do not show green for an avoid-rated setup.
    check3Badge = '⚠️ Caution: Zone Violated by Consensus';
    check3Desc = `Price (Rs. ${ltp}) is inside the Rs. ${entryLow}–${entryHigh} range, but the Entry/Exit Analyzer verdict is "${entryExitPlan?.verdict || 'AVOID'}". A price inside the buy zone is NOT a safe entry when the quantitative engine flags this as high-risk.`;
    check3Color = '#f59e0b';
    check3Bg = 'rgba(245, 158, 11, 0.08)';
    check3Border = 'rgba(245, 158, 11, 0.35)';
  }

  // Check 4: Historical Win Rate & Setup Score
  const winRate = entryExitPlan?.analogResult?.stats?.winRate != null ? Math.round(Number(entryExitPlan.analogResult.stats.winRate)) : null;
  const setupScore = Math.round(Number(entryExitPlan?.setupScore || 0));

  let check4Badge = `⚪ Developing Setup (${setupScore}/100)`;
  let check4Color = '#94a3b8';
  let check4Bg = 'rgba(148, 163, 184, 0.06)';
  let check4Border = 'rgba(148, 163, 184, 0.2)';

  if (setupScore >= 70) {
    check4Badge = `🟢 High Conviction (${setupScore}/100)`;
    check4Color = '#10b981';
    check4Bg = 'rgba(16, 185, 129, 0.08)';
    check4Border = 'rgba(16, 185, 129, 0.25)';
