  initialTab,
  selectedDate: propSelectedDate = '',
  sessionDate: propSessionDate = '',
  date: propDate = '',
}) {
  const initialEffectiveDate = propSelectedDate || propSessionDate || propDate || (typeof stock === 'object' ? (stock?.sessionDate || stock?.businessDate || stock?.date) : '') || '';
  const marketStatus = useMemo(() => propMarketStatus || getDetailedMarketStatus(), [propMarketStatus]);
  const { setActiveTab: setGlobalActiveTab } = useNavigation();
  const [activeTab, setActiveTab] = useState(() => (typeof stock === 'object' && stock?.initialTab) || initialTab || 'overview');
  const [tabCategory, setTabCategory] = useState('all'); // 'all' | 'trading' | 'financials' | 'tools'
  const tabBarRef = useRef(null);
  const [chartTimeframe, setChartTimeframe] = useState('1M');
  const [chartMode, setChartMode] = useState('line');
  const [liveDetail, setLiveDetail] = useState(null);
  const initialSym = (
    typeof stock === 'string'
      ? stock
      : (stock?.symbol || stock?.stockSymbol || stock?.sym || stock?.scrip || stock?.ticker || stock?.item?.symbol || stock?.name || '')
  ).toUpperCase();
  const [isFavorite, setIsFavorite] = useState(() => isWatched(initialSym));
  const [showAdvancedModal, setShowAdvancedModal] = useState(false);
  const [showAlertModal, setShowAlertModal] = useState(false);
  const [showHubModal, setShowHubModal] = useState(false);
  const [corporateAlert, setCorporateAlert] = useState(null);
  const [historyTimeframe, setHistoryTimeframe] = useState('1Y');
  const scrollRef = useRef(null);

  // Auto-scroll active tab into view smoothly
  useEffect(() => {
    if (tabBarRef.current) {
      const activeBtn = tabBarRef.current.querySelector('[data-active="true"]');
      if (activeBtn) {
        activeBtn.scrollIntoView({ behavior: 'smooth', inline: 'nearest', block: 'nearest' });
      }
    }
  }, [activeTab]);

  // ── Real data state (declared before useMemo/useCallback dependencies) ──
  const [history, setHistory] = useState(() => {
    const cached = getCachedRealPriceHistory(initialSym);
    if (Array.isArray(cached) && cached.length > 0) {
      return cached.map(item => ({
        date: item.date,
        time: item.date,
        open: Number(item.open) || Number(item.close),
        high: Number(item.high) || Number(item.close),
        low: Number(item.low) || Number(item.close),
        close: Number(item.close),
        volume: Number(item.volume) || 0
      }));
    }
    return [];
  });
  const [realPriceHistory, setRealPriceHistory] = useState(() => {
    const cached = getCachedRealPriceHistory(initialSym);
    if (Array.isArray(cached) && cached.length > 0) return cached;
    return (Array.isArray(stock?.history) && stock.history.length > 0) ? stock.history : (Array.isArray(stock?.candles) ? stock.candles : null);
  });
  const [realHistoryLoading, setRealHistoryLoading] = useState(() => {
    const cached = getCachedRealPriceHistory(initialSym);
    return !(Array.isArray(cached) && cached.length > 0);
  });
  const [historyFilterDate, setHistoryFilterDate] = useState(initialEffectiveDate);
  const [realFloorsheet, setRealFloorsheet] = useState(null);
  const [floorsheetLoading, setFloorsheetLoading] = useState(false);
  const [floorsheetPage, setFloorsheetPage] = useState(1);
  const [floorsheetPageSize, setFloorsheetPageSize] = useState(50);
  const [availableTradingDates, setAvailableTradingDates] = useState([]);
  const [modalSessionDate, setModalSessionDate] = useState(initialEffectiveDate);
  const [floorsheetDate, setFloorsheetDate] = useState(initialEffectiveDate);
  const [floorsheetBuyerInput, setFloorsheetBuyerInput] = useState('');
  const [floorsheetSellerInput, setFloorsheetSellerInput] = useState('');
  const [floorsheetAppliedBuyer, setFloorsheetAppliedBuyer] = useState('');
  const [floorsheetAppliedSeller, setFloorsheetAppliedSeller] = useState('');
  const [floorsheetSubTab, setFloorsheetSubTab] = useState('floorsheet'); // 'floorsheet' | 'bulk' | 'price_volume'
  const [showFloorsheetExportHub, setShowFloorsheetExportHub] = useState(false);
  const [fsExportDataset, setFsExportDataset] = useState('transactions');
  const [fsExportDateMode, setFsExportDateMode] = useState('current'); // 'current' | 'days' | 'range'
  const [fsExportDays, setFsExportDays] = useState(7);
  const [fsExportFromDate, setFsExportFromDate] = useState('');
  const [fsExportToDate, setFsExportToDate] = useState('');
  const [fsExportBrokerAny, setFsExportBrokerAny] = useState('');
  const [fsExportFormat, setFsExportFormat] = useState('csv');
  const [fsExporting, setFsExporting] = useState(false);
  const [fsExportNotice, setFsExportNotice] = useState('');
  const [realBrokerAnalysis, setRealBrokerAnalysis] = useState(() => {
    const cached1D = getCachedRealBrokerAnalysis(initialSym, 1);
    if (cached1D) return cached1D;
    const parentBa = stock?.brokerAnalysis || stock?.realBrokerAnalysis;
    // Guard: only accept parent brokerAnalysis if strictly for 1 session!
    // Stocks passed from multi-day scanners or 30D radars have multi-day timeframes which poison 1D state
    if (parentBa && (parentBa.tradingDays === 1 || parentBa.timeframeDays === 1 || parentBa.timeframe === '1D' || parentBa.days === 1)) {
      return parentBa;
    }
    return null;
  });
  const [broker1DData, setBroker1DData] = useState(() => {
    const cached1D = getCachedRealBrokerAnalysis(initialSym, 1);
    if (cached1D) return cached1D;
    const parentBa = stock?.brokerAnalysis || stock?.realBrokerAnalysis;
    if (parentBa && (parentBa.tradingDays === 1 || parentBa.timeframeDays === 1 || parentBa.timeframe === '1D' || parentBa.days === 1)) {
      return parentBa;
    }
    return null;
  });
  const [allTimeBrokerAnalysis, setAllTimeBrokerAnalysis] = useState(() => {
    return getCachedRealBrokerAnalysis(initialSym, 'all') || null;
  });
  const [overviewBrokerTapeMode, setOverviewBrokerTapeMode] = useState('1D_LIVE'); // '1D_LIVE' | '5D_SWING' | 'ALL_TIME'
  const [brokerAnalysisLoading, setBrokerAnalysisLoading] = useState(() => {
    const cached = getCachedRealBrokerAnalysis(initialSym, 1);
    if (cached) return false;
    const parentBa = stock?.brokerAnalysis || stock?.realBrokerAnalysis;
    if (parentBa && (parentBa.tradingDays === 1 || parentBa.timeframeDays === 1 || parentBa.timeframe === '1D' || parentBa.days === 1)) {
      return false;
    }
    return true;
  });
  const [brokerDays, setBrokerDays] = useState(1);
  const [brokerDate, setBrokerDate] = useState(initialEffectiveDate);
