          ];

          const fundRows = [
            { label: 'Market Capitalization', v1: Number(m1.marketCap || s1.marketCap || 0), v2: m2 ? Number(m2.marketCap || s2?.marketCap || 0) : null, fmt: v => v > 0 ? fmtCr(v) : '—', higher: 'up' },
