                  <span style={{ fontSize: 11, color: '#10b981', fontWeight: 700 }}>{d.sector || 'Sector Peers'}</span>
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                  <input
                    value={compareSymbol}
                    onChange={e => setCompareSymbol(e.target.value.toUpperCase())}
