        {/* ════ TAB 9: FINANCIAL REPORTS & REGULATORY ANNOUNCEMENTS ════ */}
        {activeTab === 'reports' && (
          <div style={{ padding: '0 4px' }}>
            <StockReportsAnnouncementsCard symbol={d.symbol} companyName={d.name} />
          </div>
