                      <span style={{ color: '#F43F5E' }}>Rs. {fmt(calcResult.cgtAmount)}</span>
                    </div>
                  )}
                  <div style={{ display: 'flex', justifyContent: 'space-between', paddingTop: 8, borderTop: '1px solid rgba(255, 255, 255, 0.07)', fontSize: 13, fontWeight: 900 }}>
