  }, [rawSector, backendIndustryData]);

  // Multi-Quarter historical trend data points
  const quartersList = [
    { id: '082/083 Q4', short: '082/083, q4', label: '082/083 Q4', fiscalYear: '2082/83', period: 'Q4', mult: 1.0 },
