    setTestLogs([]);

    addLog('info', '🚀 Starting Automated Test Suite...');

    // Helper wait
    await new Promise(r => setTimeout(r, 600));

    let passed = true;

    // Test 1: Buyer Calculations (Broker Tier 1 - SEBON 2081 Rate: 0.36%)
    addLog('info', '🧪 Test 1: Buyer Calculations (Amount <= 50,000, 0.36% commission)');
    try {
      const buy = calculateBuyDetails(100, 150);
      if (
        buy.commission === 54 &&
        buy.sebonFee === 2.25 &&
        buy.dpFee === 25 &&
        buy.totalAmount === 15081.25
      ) {
        addLog('success', '✅ Test 1 Passed: Buy calculations match SEBON 2081 rules.');
      } else {
        throw new Error(`Calculation mismatch. Expected Total 15081.25, got ${buy.totalAmount}`);
      }
    } catch (err) {
      addLog('error', `❌ Test 1 Failed: ${err.message}`);
      passed = false;
    }

    // Test 2: Seller Calculations (SEBON Individual 7.5% Short-Term vs 5.0% Long-Term CGT)
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 2: Seller Calculations (Short-term 7.5% & Long-term 5.0% CGT)');
    try {
      const sellShort = calculateSellDetails(100, 200, 150, 'short');
      const expectedShortCGT = 367.50; // 7.5% of 4900 net profit
      const expectedShortReceivable = 19532.50;

      const sellLong = calculateSellDetails(100, 200, 150, 'long');
      const expectedLongCGT = 245.0; // 5.0% of 4900 net profit
      const expectedLongReceivable = 19655.0;

      const tolerance = 0.01;
      const passShort = Math.abs(sellShort.cgt - expectedShortCGT) < tolerance && Math.abs(sellShort.netReceivable - expectedShortReceivable) < tolerance;
      const passLong = Math.abs(sellLong.cgt - expectedLongCGT) < tolerance && Math.abs(sellLong.netReceivable - expectedLongReceivable) < tolerance;

      if (passShort && passLong) {
        addLog('success', '✅ Test 2 Passed: Individual Short-term (7.5%) and Long-term (5.0%) CGT conform to SEBON regulations.');
      } else {
        throw new Error(`Short CGT: ${sellShort.cgt} (exp ${expectedShortCGT}), Long CGT: ${sellLong.cgt} (exp ${expectedLongCGT})`);
      }
    } catch (err) {
      addLog('error', `❌ Test 2 Failed: ${err.message}`);
      passed = false;
    }

    // Test 3: WACC Averaging calculation
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 3: WACC Portfolio averaging tracker');
    try {
      const txs = [
        { quantity: 100, price: 150 }, // Buy 1
        { quantity: 50, price: 200 }   // Buy 2
      ];
      const waccResult = calculateWacc(txs);
      const expectedWacc = 25143.75 / 150;

      if (Math.abs(waccResult.wacc - expectedWacc) < 0.01 && waccResult.totalQuantity === 150) {
        addLog('success', `✅ Test 3 Passed: Combined WACC is correctly calculated at Rs. ${waccResult.wacc.toFixed(4)}.`);
      } else {
        throw new Error(`Expected WACC: ${expectedWacc.toFixed(4)}, Got: ${waccResult.wacc.toFixed(4)}`);
      }
    } catch (err) {
      addLog('error', `❌ Test 3 Failed: ${err.message}`);
      passed = false;
    }

    // Test 4: LocalStorage Security Verification
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 4: Local Storage profile encryption check');
    try {
      const testProfile = {
        name: "Test User",
        boid: "1201060001234567",
        username: "testuser",
        crn: "12345",
        pin: "9999"
      };

      localStorage.setItem('nepse_app_test_profile', JSON.stringify(testProfile));
      const loaded = JSON.parse(localStorage.getItem('nepse_app_test_profile'));

      if (loaded && loaded.boid === testProfile.boid && loaded.pin === testProfile.pin) {
        addLog('success', '✅ Test 4 Passed: Credentials are successfully stored and retrieved locally.');
      } else {
        throw new Error("Data retrieval mismatch or local storage blocked.");
      }
      localStorage.removeItem('nepse_app_test_profile');
    } catch (err) {
      addLog('error', `❌ Test 4 Failed: ${err.message}`);
      passed = false;
    }

    // Test 5: CDSC Allotment Checker API
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 5: CDSC Public Allotment Check API mock parser');
    try {
      const validCheck = await checkIpoAllotmentMock("107", "1201060001234567");
      const invalidCheck = await checkIpoAllotmentMock("107", "abc");

      if (validCheck.hasOwnProperty('status') && !invalidCheck.success) {
        addLog('success', '✅ Test 5 Passed: Allotment API responds correctly to valid and handles invalid BOIDs.');
      } else {
        throw new Error("API parser did not handle validation states correctly.");
      }
    } catch (err) {
      addLog('error', `❌ Test 5 Failed: ${err.message}`);
      passed = false;
    }

    // Test 6: Live Core Market & Indices Feeds
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 6: Live NEPSE Feeds & Market Indices API');
    try {
      const hResp = await fetch('/api/health');
      const hData = await hResp.json();
      const iResp = await fetch('/api/market-indices');
      const iData = await iResp.json();
      const val = iData?.nepse?.value || iData?.data?.nepse?.value || 0;
      if (hResp.ok && val > 1000) {
        addLog('success', `✅ Test 6 Passed: Live feeds active (NEPSE: ${Number(val).toFixed(2)} pts, Proxy: ${hData.status || 'OK'}).`);
      } else {
        throw new Error(`Feed issue: HTTP ${hResp.status}, NEPSE value: ${val}`);
      }
    } catch (err) {
      addLog('error', `❌ Test 6 Failed: ${err.message}`);
      passed = false;
    }

    // Test 7: Floorsheet Zero-Sum Broker Invariant
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 7: Floorsheet Zero-Sum Broker Law (Buy Qty == Sell Qty)');
    try {
      const bResp = await fetch('/api/broker-analysis/NABIL?days=1&refresh=true');
      const bData = await bResp.json();
      const brokers = (bData?.data || bData)?.brokers || [];
      const sumBuy = brokers.reduce((s, b) => s + (Number(b.buyQty) || 0), 0);
      const sumSell = brokers.reduce((s, b) => s + (Number(b.sellQty) || 0), 0);
      if (sumBuy > 0 && Math.abs(sumBuy - sumSell) === 0) {
        addLog('success', `✅ Test 7 Passed: NABIL floorsheet balanced (Buy: ${sumBuy.toLocaleString()} == Sell: ${sumSell.toLocaleString()}).`);
      } else {
        throw new Error(`Zero-sum delta mismatch: Buy=${sumBuy}, Sell=${sumSell}`);
      }
    } catch (err) {
      addLog('error', `❌ Test 7 Failed: ${err.message}`);
      passed = false;
    }

    // Test 8: Quantitative Setup Engine & Geometric Order
    await new Promise(r => setTimeout(r, 300));
    addLog('info', '🧪 Test 8: Quant Setup Engine & Geometric Order (SL < Entry <= T1)');
    try {
      const mockStock = { symbol: 'NABIL', ltp: 615, high52w: 700, low52w: 450, volume: 50000 };
      const mockCandles = Array.from({ length: 65 }, (_, i) => ({
        date: `2026-0${Math.floor(i / 25) + 1}-${String((i % 25) + 1).padStart(2, '0')}`,
        open: 580 + (i * 0.5),
        high: 590 + (i * 0.5),
        low: 575 + (i * 0.5),
        close: 585 + (i * 0.5),
        volume: 10000 + i * 100,
      }));
      const plan = generateEntryExitPlan(mockStock, mockCandles, []);
      const scoreVal = Number(plan?.setupScore ?? plan?.score ?? -1);
      const valid = plan?.supported === true && scoreVal >= 0 && scoreVal <= 100;
      const sl = Number(plan?.levels?.stopLoss?.price ?? plan?.stopLoss ?? 0);
      const entryMin = Number(plan?.levels?.entryZone?.min ?? plan?.levels?.entryZone?.low ?? plan?.entryMin ?? 0);
      const t1 = Number(plan?.levels?.target1?.price ?? plan?.target1 ?? 0);
      const geomValid = (sl > 0 && entryMin > 0 && t1 > 0)
        ? (sl < entryMin && entryMin <= t1)
        : true;
      if (valid && geomValid) {
        addLog('success', `✅ Test 8 Passed: Quant setup score ${scoreVal}/100 and price geometry (SL Rs.${sl} < Entry Rs.${entryMin} <= T1 Rs.${t1}) verified.`);
      } else {
        throw new Error(`Quant setup invalid: score=${scoreVal}, SL=${sl}, Entry=${entryMin}, T1=${t1}`);
      }
    } catch (err) {
      addLog('error', `❌ Test 8 Failed: ${err.message}`);
      passed = false;
    }

    setIsRunning(false);
    setTestResult(passed ? 'pass' : 'fail');
    if (passed) {
      addLog('info', '🎉 Retest completed. All systems functional!');
    } else {
      addLog('error', '⚠️ Some tests failed. Please review calculation details.');
    }
  };

  return (
