      const quoteMap: Record<string, number> = {};
      list.forEach((s: any) => {
        if (s.symbol) quoteMap[s.symbol.toUpperCase()] = Number(s.ltp || s.price || 0);
      });
      setMarketQuotes(quoteMap);
    } catch (_) {
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    reloadData();
  }, [reloadData]);

  // Add a new stock with auto-derived entry, stop, and target levels
  const handleAddStock = (sym: string) => {
    if (!sym) return;
    const s = sym.toUpperCase().trim();
    const ltp = marketQuotes[s] || 500;
    const entryMin = Number((ltp * 0.992).toFixed(1));
    const entryMax = Number((ltp * 1.004).toFixed(1));
    const stopLoss = Number((ltp * 0.954).toFixed(1)); // 4.6% stop
    const target1 = Number((ltp * 1.069).toFixed(1)); // 6.9% target
    const target2 = Number((ltp * 1.115).toFixed(1)); // 11.5% target

    const newCfg = {
      symbol: s,
      entryZone: [entryMin, entryMax],
      stopLoss,
      target1,
      target2,
      alertEnabled: true,
      lastTriggered: null
    };

    saveWatchlistAlertConfig(s, newCfg);
    setNewSymbol('');
    reloadData();
  };

  const handleToggle = (sym: string) => {
    const cfg = configs[sym];
    if (!cfg) return;
    saveWatchlistAlertConfig(sym, { ...cfg, alertEnabled: !cfg.alertEnabled });
    reloadData();
  };

  const handleRemove = (sym: string) => {
    removeWatchlistAlertConfig(sym);
    reloadData();
  };

  // Evaluate alerts against live quotes
  const activeAlertItems = useMemo(() => {
    return Object.keys(configs).map(sym => {
      const cfg = configs[sym];
      const ltp = marketQuotes[sym] || cfg.entryZone?.[0] || 0;
      const [entryMin, entryMax] = cfg.entryZone || [ltp * 0.99, ltp * 1.01];
      const sl = cfg.stopLoss || (ltp * 0.95);
      const t1 = cfg.target1 || (ltp * 1.07);
      const t2 = cfg.target2 || (ltp * 1.12);

      const inEntryZone = ltp >= entryMin && ltp <= entryMax;
      const nearStopLoss = ltp <= (sl * 1.015);
      const target1Reached = ltp >= t1;
      const target2Reached = ltp >= t2;

      // Trigger alerts if newly fired
      if (cfg.alertEnabled && (inEntryZone || nearStopLoss || target1Reached || target2Reached)) {
        if (audioEnabled) {
          playBreakoutChime();
          triggerBreakoutVibration();
        }
      }

      return {
        symbol: sym,
        entryZone: [entryMin, entryMax] as [number, number],
        stopLoss: sl,
        target1: t1,
        target2: t2,
        currentPrice: ltp,
        inEntryZone,
        nearStopLoss,
        target1Reached,
        target2Reached,
        alertEnabled: cfg.alertEnabled !== false
      };
    });
  }, [configs, marketQuotes, audioEnabled]);

  return (
    <div className="space-y-6 pb-12">
      {/* Header */}
      <div className="rounded-2xl border border-slate-800 bg-slate-900/60 p-5 shadow-sm">
        <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
          <div className="flex items-center gap-2.5">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-amber-500/10 text-amber-400">
              <BellRing size={20} />
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white">
                Watchlist Execution & Entry Zone Alerts
              </h1>
              <p className="text-xs text-slate-400">
                Real-time tracking of planned Entry Zones, trailing Stop-Losses, and Targets with synthesized audio chimes
              </p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button
              onClick={() => setAudioEnabled(!audioEnabled)}
              className={`flex items-center gap-1.5 rounded-xl border px-3 py-2 text-xs font-semibold transition-all ${
                audioEnabled
                  ? 'border-emerald-500/40 bg-emerald-500/10 text-emerald-300'
                  : 'border-slate-700 bg-slate-800 text-slate-400'
              }`}
            >
              {audioEnabled ? <Volume2 size={14} /> : <VolumeX size={14} />}
              <span>{audioEnabled ? 'Sound ON' : 'Muted'}</span>
            </button>
            <button
              onClick={reloadData}
              disabled={loading}
              className="flex items-center gap-1.5 rounded-xl border border-slate-700 bg-slate-800 px-3.5 py-2 text-xs font-medium text-slate-200 transition-colors hover:bg-slate-700 disabled:opacity-50"
            >
              <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
              <span>Refresh</span>
            </button>
          </div>
        </div>

        {/* Add Ticker Bar */}
        <div className="mt-4 flex flex-col sm:flex-row items-center gap-3 border-t border-slate-800/80 pt-4">
          <div className="w-full sm:w-64">
            <StockSearchSelect
              value={newSymbol}
              onChange={(s) => {
                setNewSymbol(s);
                handleAddStock(s);
              }}
              placeholder="Add stock to entry alerts..."
            />
          </div>
          <span className="text-[11px] text-slate-500">
            Automatically calculates entry zone, ATR stop-loss, and profit targets
          </span>
        </div>
      </div>

      {/* Active Alert Table */}
      <div className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900/60 shadow-sm">
        <div className="border-b border-slate-800 p-4 flex items-center justify-between">
          <h3 className="text-sm font-bold text-white">Active Watchlist Price Gates ({activeAlertItems.length})</h3>
          <span className="text-xs text-slate-500">Live order matching vs NEPSE feed</span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="border-b border-slate-800 bg-slate-950/40 text-slate-400">
              <tr>
                <th className="p-3">Symbol</th>
                <th className="p-3">Live LTP</th>
                <th className="p-3">Planned Entry Zone</th>
                <th className="p-3">Stop-Loss</th>
                <th className="p-3">Target 1 / Target 2</th>
                <th className="p-3">Live Alert Status</th>
                <th className="p-3 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/60 text-slate-200">
              {activeAlertItems.length === 0 ? (
                <tr>
                  <td colSpan={7} className="p-8 text-center text-slate-500">
                    No active watchlist alerts. Select a stock above to begin real-time entry zone tracking.
                  </td>
                </tr>
              ) : (
                activeAlertItems.map((item, idx) => (
                  <tr key={idx} className="hover:bg-slate-800/30">
                    <td className="p-3 font-bold text-white font-mono text-sm">{item.symbol}</td>
                    <td className="p-3 font-mono font-bold">Rs. {item.currentPrice}</td>
                    <td className="p-3 font-mono text-slate-300">
                      Rs. {item.entryZone[0]} – {item.entryZone[1]}
                    </td>
                    <td className="p-3 font-mono text-red-400 font-semibold">
                      Rs. {item.stopLoss}
                    </td>
                    <td className="p-3 font-mono text-emerald-400 font-semibold">
                      Rs. {item.target1} / {item.target2}
                    </td>
                    <td className="p-3">
                      {item.inEntryZone && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-emerald-500/20 px-2.5 py-0.5 text-[10px] font-bold text-emerald-400 border border-emerald-500/40">
                          🎯 Inside Entry Zone!
                        </span>
                      )}
                      {item.nearStopLoss && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-red-500/20 px-2.5 py-0.5 text-[10px] font-bold text-red-400 border border-red-500/40">
                          🛑 Near Stop Loss!
                        </span>
                      )}
                      {item.target1Reached && !item.target2Reached && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-purple-500/20 px-2.5 py-0.5 text-[10px] font-bold text-purple-400 border border-purple-500/40">
                          ✨ Target 1 Breached!
                        </span>
                      )}
                      {item.target2Reached && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-emerald-500/20 px-2.5 py-0.5 text-[10px] font-bold text-emerald-300 border border-emerald-500/40">
                          🚀 Target 2 Reached!
                        </span>
                      )}
                      {!item.inEntryZone && !item.nearStopLoss && !item.target1Reached && !item.target2Reached && (
                        <span className="inline-flex items-center gap-1 text-slate-500 text-[11px]">
                          <Clock size={11} /> Monitoring
                        </span>
                      )}
                    </td>
                    <td className="p-3 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          onClick={() => handleToggle(item.symbol)}
                          className={`rounded-lg px-2 py-1 text-[10px] font-semibold transition-colors ${
                            item.alertEnabled
                              ? 'bg-emerald-950/60 text-emerald-400 border border-emerald-800'
                              : 'bg-slate-800 text-slate-400 border border-slate-700'
                          }`}
                        >
                          {item.alertEnabled ? 'Active' : 'Paused'}
                        </button>
                        <button
                          onClick={() => handleRemove(item.symbol)}
                          className="rounded-lg p-1 text-slate-500 hover:text-red-400 transition-colors"
                          title="Remove alert"
                        >
                          <Trash2 size={13} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
export default WatchlistEntryAlertModal;

import React, { useState, useEffect, useMemo } from 'react';
import { Target, ShieldAlert, TrendingUp, Info, Calculator, Coins, AlertTriangle, CheckCircle2, Lock, ArrowRight } from 'lucide-react';
import { calculateNetProfit, formatRiskReward } from '../../utils/riskManagement';

interface EntryRiskCardProps {
  levels: {
    entryZone?: { low: number; high: number; label: string };
    stopLoss?: { price: number; pct: number; label: string };
    target1?: { price: number; pct: number; horizon?: string; label: string; netReturnPct?: number; netGainPerShare?: number; grossUpsidePct?: number; capped?: boolean };
    target2?: { price: number; pct: number; horizon?: string; label: string; netReturnPct?: number; netGainPerShare?: number; grossUpsidePct?: number; capped?: boolean };
    riskPerShare?: number;
    rewardToTarget1?: number;
    rewardToTarget2?: number;
    rrr1?: number;
    rrr2?: number;
    feeFrictionPct?: number;
    cgtTaxRatePct?: number;
    isValidTradeSetup?: boolean;
    statutoryBreakeven?: {
      entryPrice: number;
      breakevenPrice: number;
      hurdlePct: number;
      roundTripExpenses: number;
      totalBuyCost: number;
      label: string;
    };
    t2Risk?: {
      score: number;
      tier: string;
      worst2DayDropPct: number;
      t2DrawdownBufferPct: number;
      circuitDropsCount: number;
      isIlliquid: boolean;
      holdingSessions: number;
      recommendedPositionMultiplier: number;
      warning: string | null;
      detail: string;
    };
    recommendedPositionMultiplier?: number;
  };
  currentPrice?: number;
  quantMetrics?: {
    kelly?: {
      rawKelly?: number;
      fullKellyPct?: number;
      halfKellyPct?: number;
      recommendationPct?: number;
      isViable?: boolean;
      rationale?: string;
    };
    expectancy?: {
      ev?: number;
      profitFactor?: number;
      breakEvenWinRate?: number;
    };
  };
  verdict?: string;
  setupScore?: number;
  riskGate?: any;
  isAvoid?: boolean;
}

const CAPITAL_PRESETS = [50000, 100000, 250000, 500000, 1000000];

export function EntryRiskCard({ levels, currentPrice, quantMetrics, verdict, setupScore, riskGate, isAvoid }: EntryRiskCardProps) {
  if (!levels) return null;

  const isSetupGated = Boolean(
    isAvoid ||
    (verdict && (
      verdict.includes('AVOID') ||
      verdict.includes('NO TRADE') ||
      verdict.includes('EXIT') ||
      verdict.includes('REDUCE') ||
      verdict.includes('STAY OUT') ||
      verdict.includes('DUMPING')
    )) ||
    riskGate?.isInstitutionalDumping ||
    riskGate?.isHardCeilingDowntrend ||
    riskGate?.isCircuitTrap ||
    (setupScore !== undefined && setupScore < 45)
  );

  const [showHypotheticalSizing, setShowHypotheticalSizing] = useState(false);

  // ── User-Configured Position Sizing State (Persisted in localStorage) ──
  const [portfolioCapital, setPortfolioCapital] = useState<number>(() => {
    try {
      const saved = localStorage.getItem('entry_exit_portfolio_capital');
      if (saved) {
        const parsed = Number(saved);
        if (parsed >= 10000) return parsed;
      }
    } catch (_) {}
    return 100000;
  });

  const [riskTolerancePct, setRiskTolerancePct] = useState<number>(1.5); // 1.0%, 1.5%, 2.0%

  const handleCapitalChange = (val: number) => {
    const safeVal = Math.max(5000, Math.min(100000000, val));
    setPortfolioCapital(safeVal);
    try {
      localStorage.setItem('entry_exit_portfolio_capital', String(safeVal));
    } catch (_) {}
  };

  // ── Derived Friction-Adjusted Position Sizing Calculations ──
  const entryPx = currentPrice || levels.entryZone?.low || 100;
  const stopPx = levels.stopLoss?.price || +(entryPx * 0.945).toFixed(1);
  const chaseCapPx = (levels as any).chaseCap || +(Number(levels.entryZone?.high || entryPx * 1.01) * 1.025).toFixed(1);
  const isChaseExceeded = Boolean(currentPrice && currentPrice > chaseCapPx);

  // Enforce max 1.5% - 2.0% portfolio risk ceiling across all tiers
  const effectiveRiskPct = Math.min(2.0, Math.max(0.75, riskTolerancePct));
  const maxCapitalAtRisk = portfolioCapital * (effectiveRiskPct / 100);

  // Include round-trip broker commission (0.36% starter / 0.33% standard, min Rs. 10), SEBON (0.015%), and Rs. 50 round-trip DP fee
  const estBrokerRate = portfolioCapital <= 150000 ? 0.0036 : 0.0033;
  const rawPriceRisk = Math.max(0.5, entryPx - stopPx);
  const perShareVarFriction = (entryPx + stopPx) * (estBrokerRate + 0.00015);
  const effectiveRiskPerShare = rawPriceRisk + perShareVarFriction;

  const rawQuantity = Math.floor(Math.max(0, maxCapitalAtRisk - 50) / effectiveRiskPerShare);

  // Maximum single-stock allocation cap (25% of portfolio) AND 5% of 20-day median turnover cap
  const median20DTurnover = Number((levels as any).median20DayTurnover || (levels as any).t2Risk?.median20DayTurnover || 8000000);
  const maxLiquidityOrderValue = Math.floor(0.05 * median20DTurnover);
  const maxSlotValue = Math.min(portfolioCapital * 0.25, maxLiquidityOrderValue);
  const maxAllocationShares = Math.floor(Math.max(0, maxSlotValue - 25) / (entryPx * (1 + estBrokerRate + 0.00015)));

  const t2Multiplier = levels.t2Risk?.recommendedPositionMultiplier ?? levels.recommendedPositionMultiplier ?? 1.0;
  const scaledShares = Math.floor((Math.min(rawQuantity, maxAllocationShares) * t2Multiplier) / 10) * 10;

  // Verify 10-kitta minimum lot does not breach 2.0% hard portfolio loss cap
  const lossAt10Kitta = 10 * effectiveRiskPerShare + 50;
  const finalShares = scaledShares >= 10
    ? scaledShares
    : (lossAt10Kitta <= portfolioCapital * 0.02 && 10 * entryPx <= maxSlotValue ? 10 : 0);

  const buyOrderVal = finalShares * entryPx;
  const buyBrokerComm = finalShares > 0 ? Math.max(10, +(buyOrderVal * estBrokerRate).toFixed(2)) : 0;
  const buySebon = finalShares > 0 ? +(buyOrderVal * 0.00015).toFixed(2) : 0;
  const buyDp = finalShares > 0 ? 25 : 0;
  const totalPositionOutlay = Math.round(buyOrderVal + buyBrokerComm + buySebon + buyDp);

  const portfolioAllocationPct = portfolioCapital > 0 ? +((totalPositionOutlay / portfolioCapital) * 100).toFixed(1) : 0;
  const actualRiskRupees = finalShares > 0 ? Math.round(finalShares * effectiveRiskPerShare + 50) : 0;
  const actualRiskPctOfCapital = portfolioCapital > 0 ? +((actualRiskRupees / portfolioCapital) * 100).toFixed(2) : 0;

  const statutoryBePx = levels.statutoryBreakeven?.breakevenPrice || +(entryPx * 1.0085).toFixed(1);
  const scaleOutShares = finalShares >= 20 ? Math.floor((finalShares * 0.5) / 10) * 10 : Math.floor(finalShares * 0.5);
  const runnerShares = Math.max(0, finalShares - scaleOutShares);

  // Expected Net Return in Rupees at Target 1
  const t1NetGainPerShare = levels.target1?.netGainPerShare || (levels.target1?.price ? levels.target1.price - entryPx : entryPx * 0.08);
  const target1NetGainRupees = Math.round(finalShares * t1NetGainPerShare);

  // ── E-batch: Net P&L Calculator State ──
  const [showNetCalc, setShowNetCalc] = useState(false);

  // Real levels only — no invented %-of-price fallbacks.
  const effPrice = Number(currentPrice || levels.entryZone?.low || levels.entryZone?.high || 0) || null;
  const effStop = levels.stopLoss?.price != null ? Number(levels.stopLoss.price) : null;
  const effT1 = levels.target1?.price != null ? Number(levels.target1.price) : null;
  const effT2 = levels.target2?.price != null ? Number(levels.target2.price) : null;

  const displayRisk = levels.riskPerShare != null
    ? levels.riskPerShare
    : (effPrice != null && effStop != null && effPrice > effStop ? +(effPrice - effStop).toFixed(1) : +(Math.max(1.0, entryPx - stopPx)).toFixed(1));

  const displayRewardT1 = levels.rewardToTarget1 != null
    ? levels.rewardToTarget1
    : (effPrice != null && effT1 != null && effT1 > effPrice ? +(effT1 - effPrice).toFixed(1) : +(Math.max(1.0, (effT1 || entryPx * 1.08) - entryPx)).toFixed(1));

  const displayRewardT2 = levels.rewardToTarget2 != null
    ? levels.rewardToTarget2
    : (effPrice != null && effT2 != null && effT2 > effPrice ? +(effT2 - effPrice).toFixed(1) : +(Math.max(2.0, (effT2 || entryPx * 1.16) - entryPx)).toFixed(1));

  const displayRrr1 = levels.rrr1 != null
    ? `${levels.rrr1} : 1`
    : `${+(displayRewardT1 / Math.max(0.5, displayRisk)).toFixed(1)} : 1`;

  const displayRrr2 = levels.rrr2 != null
    ? `${levels.rrr2} : 1`
    : `${+(displayRewardT2 / Math.max(0.5, displayRisk)).toFixed(1)} : 1`;
  const [calcSellPrice, setCalcSellPrice] = useState<number>(0);
  const [calcShares, setCalcShares] = useState<number>(0);
  const [calcHoldingType, setCalcHoldingType] = useState<'short' | 'long'>('short');

  // Sync calc inputs when levels/entryPx change
  const t1Price = levels.target1?.price || entryPx * 1.10;
  const netCalcResult = useMemo(() => {
    if (!showNetCalc || !entryPx || !calcSellPrice || !calcShares) return null;
    try {
      return calculateNetProfit({
        shares: calcShares || finalShares,
        buyPrice: entryPx,
        sellPrice: calcSellPrice || t1Price,
        holdingDays: calcHoldingType === 'long' ? 520 : 90,
        investorType: 'individual',
      });
    } catch { return null; }
  }, [showNetCalc, entryPx, calcSellPrice, calcShares, calcHoldingType, finalShares, t1Price]);

  const t2Risk = levels.t2Risk;

  return (
    <div className="rounded-2xl border border-slate-800 bg-[#090d16] p-4 sm:p-5 text-slate-100 shadow-xl space-y-4">
      {/* ── Header ── */}
      <div className="flex items-center justify-between flex-wrap gap-2 pb-2 border-b border-slate-800">
        <div className="flex items-center gap-2">
          <div className="rounded-lg p-1.5 bg-blue-500/15 border border-blue-500/30 text-blue-400">
            <Target size={16} />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white uppercase tracking-wider">
              Entry, Stop & Position Sizing Plan
            </h3>
            <p className="text-[11px] text-slate-400">
              Risk-reward aligned with nearby support, T+2 settlement lockup & overhead resistance
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 flex-wrap">
          {/* Gated Stance Badge */}
          {isSetupGated && (
            <span className="text-xs font-bold px-2.5 py-1 rounded-full border flex items-center gap-1.5 bg-rose-950/60 border-rose-700/80 text-rose-300">
              <ShieldAlert size={12} />
              ENTRY GATED (CAPITAL PRESERVATION)
            </span>
          )}

          {/* T+2 Lockup Risk Badge */}
          {t2Risk && (
            <span
              className={`text-xs font-bold px-2.5 py-1 rounded-full border flex items-center gap-1.5 ${
                t2Risk.tier === 'LOW'
                  ? 'bg-emerald-950/60 border-emerald-700/80 text-emerald-300'
                  : t2Risk.tier === 'MODERATE'
                  ? 'bg-sky-950/60 border-sky-700/80 text-sky-300'
                  : t2Risk.tier === 'HIGH'
                  ? 'bg-amber-950/60 border-amber-700/80 text-amber-300'
                  : 'bg-rose-950/60 border-rose-700/80 text-rose-300'
              }`}
              title={t2Risk.detail}
            >
              <Lock size={12} />
              T+2 Lockup: {t2Risk.tier} (±{t2Risk.t2DrawdownBufferPct}%)
            </span>
          )}

          {levels.isValidTradeSetup !== undefined && (
            <span
              className={`text-xs font-bold px-2.5 py-1 rounded-full border ${
                !isSetupGated && levels.isValidTradeSetup
                  ? 'bg-emerald-950/60 border-emerald-700/80 text-emerald-300'
                  : 'bg-amber-950/60 border-amber-700/80 text-amber-300'
              }`}
            >
              {isSetupGated ? '⚠️ Setup Inactive' : levels.isValidTradeSetup ? '✓ Favorable R:R Setup' : '⚠️ Moderate R:R'}
            </span>
          )}
        </div>
      </div>

      {/* ── Key Levels Grid ── */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        {/* Entry Zone */}
        {/* Box 1: Dual Entry Architecture (Pullback & Breakout) */}
        <div className={`rounded-xl p-3 ${isSetupGated ? 'bg-slate-900/90 border border-amber-900/50' : 'bg-slate-900/80 border border-blue-900/40'}`}>
          <div className={`text-[11px] font-semibold uppercase tracking-wide ${isSetupGated ? 'text-amber-400' : 'text-blue-400'}`}>
            {isSetupGated ? 'Reversal Pivot (Above)' : 'Actionable Entry Zones'}
          </div>
          <div className="mt-1 space-y-1">
            <div className="flex items-baseline justify-between text-xs sm:text-sm">
              <span className="text-slate-400 text-[10.5px]">Pullback Dip:</span>
              <span className="font-bold text-sky-300">
                {levels.pullbackZone?.label || (levels.entryZone?.low ? `Rs. ${levels.entryZone.low} – ${levels.entryZone.high || levels.entryZone.low}` : (currentPrice ? `Rs. ${+(currentPrice * 0.985).toFixed(1)} – ${+(currentPrice * 0.998).toFixed(1)}` : '—'))}
              </span>
            </div>
            <div className="flex items-baseline justify-between text-xs sm:text-sm pt-0.5 border-t border-slate-800/60">
              <span className="text-slate-400 text-[10.5px]">Breakout Pivot:</span>
              <span className="font-bold text-emerald-300">
                {levels.breakoutZone?.pivot ? `> Rs. ${levels.breakoutZone.pivot}` : (levels.breakoutPrice ? `> Rs. ${levels.breakoutPrice}` : (currentPrice ? `> Rs. ${+(currentPrice * 1.02).toFixed(1)}` : '—'))}
              </span>
            </div>
          </div>
          <div className="text-[10px] text-slate-400 mt-1.5 flex items-center justify-between">
            <span>{isSetupGated ? 'Do NOT front-run. Gated until close above pivot.' : (levels.pullbackZone?.supportRef || 'Buy dip near 20-EMA or on breakout')}</span>
            {levels.breakoutZone?.chaseCap && <span className="text-amber-400/90">Cap: Rs. {levels.breakoutZone.chaseCap}</span>}
          </div>
        </div>

