/**
 * FundamentalValuationCard — Batch D UI
 * Shows sector-relative PE/PBV/ROE vs sector median, valuation verdict,
 * fundamental score, peer rank, and always-visible disclaimer.
 */
export function FundamentalValuationCard({ stock, allStocks = [] }) {
  const summary = useMemo(() => {
    if (!stock || !stock.symbol) return null;
    return calculateFundamentalSummary(stock);
  }, [stock]);

  const peerComp = useMemo(() => {
    if (!allStocks || allStocks.length < 4 || !stock?.symbol) return null;
    return computeSectorComparison(allStocks, stock.symbol);
  }, [allStocks, stock?.symbol]);

  if (!summary) return null;

  const { valuation, fundamentalScore, fundamentalRating, fundamentalReasons, sectorName, disclaimer } = summary;
  const bench = getSectorBenchmark(stock?.sector || '');
  const isBfi = bench.minCAR != null;

  // Colour mapping
  const verdictColor = {
    UNDERVALUED: '#10b981',
    SLIGHTLY_UNDERVALUED: '#34d399',
    FAIR: '#60a5fa',
    SLIGHTLY_OVERVALUED: '#fbbf24',
    OVERVALUED: '#f87171',
  }[valuation.verdict] || '#94a3b8';

  const ratingColor = {
    'Strong Buy': '#10b981',
    'Buy': '#34d399',
    'Hold': '#60a5fa',
    'Underperform': '#fbbf24',
    'Avoid': '#f87171',
  }[fundamentalRating] || '#94a3b8';

  const metricStatus = (val, median, lowerIsBetter = false) => {
    if (!val || !median) return '#64748b';
    const r = val / median;
    if (lowerIsBetter) return r <= 0.85 ? '#10b981' : r <= 1.15 ? '#60a5fa' : r > 1.5 ? '#f87171' : '#fbbf24';
    return r >= 1.2 ? '#10b981' : r >= 0.8 ? '#60a5fa' : '#f87171';
  };

  const Row = ({ label, val, median, unit = '', lowerIsBetter = false, warn }) => {
    const isNegative = typeof val === 'number' && val < 0;
    const color = warn || isNegative ? '#f87171' : metricStatus(val, median, lowerIsBetter);
    let formattedVal = '—';
    if (val !== null && val !== undefined && !isNaN(val)) {
      const absVal = Math.abs(val).toFixed(1);
      if (label === 'P/E') {
        formattedVal = isNegative ? `-${absVal}x (Loss)` : `${absVal}x`;
      } else if (label.includes('Rs') || unit.includes('Rs')) {
        formattedVal = isNegative ? `-Rs. ${absVal}` : `Rs. ${absVal}`;
      } else if (unit.includes('%') || label.includes('%')) {
        formattedVal = isNegative ? `-${absVal}%` : `${absVal}%`;
      } else {
        formattedVal = `${isNegative ? '-' : ''}${unit}${absVal}`;
      }
    }

    let formattedMedian = '—';
    if (median !== null && median !== undefined && !isNaN(Number(median))) {
      const medNum = Number(median);
      const absMed = Math.abs(medNum).toFixed(1);
      if (label === 'P/E') {
        formattedMedian = medNum < 0 ? `-${absMed}x` : `${absMed}x`;
      } else if (label.includes('Rs') || unit.includes('Rs')) {
        formattedMedian = medNum < 0 ? `-Rs. ${absMed}` : `Rs. ${absMed}`;
      } else if (unit.includes('%') || label.includes('%')) {
        formattedMedian = medNum < 0 ? `-${absMed}%` : `${absMed}%`;
      } else {
        formattedMedian = `${medNum < 0 ? '-' : ''}${unit}${absMed}`;
      }
    } else if (median) {
      formattedMedian = `${unit}${median}`;
    }

    return (
      <div style={{ display: 'grid', gridTemplateColumns: '90px 1fr 1fr', gap: 6, padding: '5px 0', borderBottom: '1px solid rgba(255,255,255,0.04)', alignItems: 'center' }}>
        <span style={{ fontSize: 12, color: '#94a3b8', fontWeight: 600 }}>{label}</span>
        <span style={{ fontSize: 12, fontWeight: 800, color, fontFamily: 'var(--font-mono)' }}>
          {formattedVal}
        </span>
        <span style={{ fontSize: 12, color: '#475569' }}>
          {formattedMedian !== '—' ? `Sector: ${formattedMedian}` : '—'}
        </span>
      </div>
    );
  };

  // Explanation bullets (combine valuation explanation + fundamentalReasons, deduplicate, max 3)
  const bullets = [...(valuation.explanation || []), ...(fundamentalReasons || [])]
    .filter((v, i, a) => a.indexOf(v) === i)
    .slice(0, 3);

  return (
    <div style={{
      background: '#0f1520',
      border: '1px solid rgba(255,255,255,0.07)',
      borderRadius: 14,
      padding: '14px 16px',
      marginTop: 12,
    }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10, flexWrap: 'wrap', gap: 8 }}>
        <div>
          <div style={{ fontSize: 12, fontWeight: 700, color: '#64748b', letterSpacing: '0.06em', textTransform: 'uppercase' }}>
            Fundamental Valuation
          </div>
          <div style={{ fontSize: 12, color: '#475569', marginTop: 1 }}>{sectorName}</div>
        </div>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
          {/* Valuation verdict pill */}
          <span style={{
            fontSize: 12, fontWeight: 800, padding: '3px 10px', borderRadius: 20,
            background: `${verdictColor}18`, border: `1px solid ${verdictColor}40`, color: verdictColor,
          }}>
            {valuation.verdict.replace('_', ' ')}
          </span>
          {/* Rating chip */}
          <span style={{
            fontSize: 12, fontWeight: 800, padding: '3px 10px', borderRadius: 20,
            background: `${ratingColor}18`, border: `1px solid ${ratingColor}40`, color: ratingColor,
          }}>
            {fundamentalRating}
          </span>
        </div>
      </div>

      {/* Reporting Period & Data Freshness Banner */}
      <div style={{
        display: 'flex', alignItems: 'center', gap: 8,
        padding: '7px 11px', borderRadius: 8,
        background: 'rgba(251,191,36,0.06)', border: '1px solid rgba(251,191,36,0.22)',
        marginBottom: 12, fontSize: 12, lineHeight: 1.45
      }}>
        <span style={{ fontSize: 14, flexShrink: 0 }}>⏱️</span>
        <div>
          <span style={{ fontWeight: 800, color: '#ffffff' }}>Filing: {summary.reportingPeriod || 'Audited Annual'}</span>
          <span style={{ color: '#94a3b8', marginLeft: 6 }}>
            NEPSE fundamental metrics (EPS, P/E) reflect periodic filings and are not real-time. Verify with latest quarterly results.
          </span>
        </div>
      </div>

      {/* Score bar */}
      <div style={{ marginBottom: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
          <span style={{ fontSize: 12, color: '#64748b' }}>Fundamental Score</span>
          <span style={{ fontSize: 12, fontWeight: 800, color: ratingColor, fontFamily: 'var(--font-mono)' }}>
            {fundamentalScore}/100
          </span>
        </div>
        <div style={{ height: 4, background: 'rgba(255,255,255,0.07)', borderRadius: 4, overflow: 'hidden' }}>
          <div style={{
            height: '100%', borderRadius: 4,
            width: `${fundamentalScore}%`,
            background: fundamentalScore >= 70 ? '#10b981' : fundamentalScore >= 50 ? '#60a5fa' : fundamentalScore >= 35 ? '#fbbf24' : '#f87171',
            transition: 'width 0.5s ease',
          }} />
        </div>
      </div>

      {/* Metrics vs sector */}
      {(summary.pe != null || summary.eps != null || summary.pbv > 0 || summary.roe != null) ? (
        <div style={{ marginBottom: 10 }}>
          <Row label="P/E" val={summary.pe} median={bench.medianPE} lowerIsBetter />
          <Row label="P/BV" val={summary.pbv} median={bench.medianPBV} lowerIsBetter />
          <Row label="ROE %" val={summary.roe} median={bench.medianROE} unit="%" />
          <Row label="EPS Rs." val={summary.eps} median={bench.medianEPS} />
          {summary.bookValue > 0 && (
            <Row label="Book Value" val={summary.bookValue} median={null} unit="Rs. " />
          )}
          {summary.divYield > 0 && (
            <Row label="Div Yield %" val={summary.divYield} median={null} unit="%" />
          )}
          {isBfi && summary.npl > 0 && (
            <Row label="NPL %" val={summary.npl} median={bench.medianNPL} lowerIsBetter warn={summary.npl > bench.maxNPL} unit="%" />
          )}
          {isBfi && summary.car > 0 && (
            <Row label="CAR %" val={summary.car} median={bench.minCAR} warn={summary.car < bench.minCAR} unit="%" />
          )}
        </div>
      ) : (
        <div style={{ marginBottom: 10 }}>
          <div style={{
            fontSize: 12,
            fontWeight: 700,
            color: '#f87171',
            background: 'rgba(248, 113, 113, 0.1)',
            border: '1px solid rgba(248, 113, 113, 0.25)',
            padding: '6px 10px',
            borderRadius: 6,
            marginBottom: 8
          }}>
            ⚠️ Insufficient Fundamental Filing Data (Company filings pending — showing {bench.name || 'sector'} medians for reference)
          </div>
          <Row label="P/E" val={null} median={bench.medianPE} lowerIsBetter />
          <Row label="P/BV" val={null} median={bench.medianPBV} lowerIsBetter />
          <Row label="ROE %" val={null} median={bench.medianROE} unit="%" />
          <Row label="EPS Rs." val={null} median={bench.medianEPS} />
          <Row label="Book Value" val={null} median={null} unit="Rs. " />
          {isBfi && (
            <>
              <Row label="NPL %" val={null} median={bench.medianNPL} lowerIsBetter unit="%" />
              <Row label="CAR %" val={null} median={bench.minCAR} unit="%" />
            </>
          )}
        </div>
      )}

      {/* Explanation bullets */}
      {bullets.length > 0 && (
        <div style={{ marginBottom: 10 }}>
          {bullets.map((b, i) => {
            const isWarn = b.includes('⚠️') || b.includes('below') || b.includes('Loss') || b.includes('expensive') || b.includes('Overval');
            return (
              <div key={i} style={{ display: 'flex', gap: 6, marginBottom: 4, alignItems: 'flex-start' }}>
                <span style={{ fontSize: 12, color: isWarn ? '#f59e0b' : '#10b981', flexShrink: 0, marginTop: 1 }}>
                  {isWarn ? '⚠' : '✓'}
                </span>
                <span style={{ fontSize: 12, color: '#94a3b8', lineHeight: 1.45 }}>{b}</span>
              </div>
            );
          })}
        </div>
      )}

      {/* Peer Rank */}
      {peerComp && peerComp.peerCount >= 3 && peerComp.pe?.rank && (
        <div style={{ display: 'flex', gap: 12, marginBottom: 10, flexWrap: 'wrap' }}>
          {peerComp.pe?.rank && (
            <div style={{ fontSize: 12, color: '#64748b' }}>
              P/E Rank: <span style={{ fontWeight: 700, color: peerComp.pe.percentile >= 60 ? '#10b981' : '#fbbf24' }}>
                #{peerComp.pe.rank}/{peerComp.pe.totalPeers}
              </span>
              <span style={{ color: '#475569' }}> in {peerComp.sectorName}</span>
            </div>
          )}
          {peerComp.eps?.rank && (
            <div style={{ fontSize: 12, color: '#64748b' }}>
              EPS Rank: <span style={{ fontWeight: 700, color: peerComp.eps.percentile >= 60 ? '#10b981' : '#fbbf24' }}>
                #{peerComp.eps.rank}/{peerComp.eps.totalPeers}
              </span>
            </div>
          )}
        </div>
      )}

      {/* Confidence */}
      {valuation.confidence && (
        <div style={{ fontSize: 12, color: '#475569', marginBottom: 6 }}>
          Confidence: <span style={{ color: valuation.confidence === 'HIGH' ? '#10b981' : valuation.confidence === 'MEDIUM' ? '#fbbf24' : '#64748b', fontWeight: 600 }}>
            {valuation.confidence}
          </span>
        </div>
      )}

      {/* Notes */}
      {valuation.notes && (
        <div style={{ fontSize: 12, color: '#475569', marginBottom: 6, fontStyle: 'italic' }}>{valuation.notes}</div>
      )}

      {/* Disclaimer */}
      <div style={{ fontSize: 12, color: '#374151', lineHeight: 1.5, marginTop: 4, paddingTop: 6, borderTop: '1px solid rgba(255,255,255,0.04)' }}>
        {disclaimer}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import {
  Shield,
  ShieldCheck,
  ShieldAlert,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Info,
  Scale,
  Sparkles,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { calculateGrahamIntrinsicValue, calculateInterestAdjustedGrahamValue, calculateEarningsYieldAndRiskPremium } from '../../utils/quantEngine';
import { getCachedStockFundamentals } from '../../utils/historyCache';
import { getSectorBenchmark } from '../../utils/fundamentals';

interface GrahamSafetyCardProps {
  symbol: string;
  ltp: number;
  fundamentals?: {
    eps?: number;
    bookValue?: number;
    pe?: number;
    pb?: number;
    pbv?: number;
    sector?: string;
  } | null;
  setupScore?: number;
  verdict?: string;
  loading?: boolean;
}

export function GrahamSafetyCard({
  symbol,
  ltp,
  fundamentals,
  setupScore = 50,
  verdict = '',
  loading = false,
}: GrahamSafetyCardProps) {
  const [showFormulaDetails, setShowFormulaDetails] = useState(false);

  const sym = String(symbol || '').toUpperCase().trim();
  const currentPrice = Number(ltp || 0);

  // 1. Resolve raw inputs
  let eps = fundamentals?.eps !== undefined && fundamentals?.eps !== null ? Number(fundamentals.eps) : null;
  let bookValue = (fundamentals?.bookValue || fundamentals?.bvps) ? Number(fundamentals.bookValue || fundamentals.bvps) : null;
  let sector = fundamentals?.sector || '';

  // 2. Check cached fundamentals if missing
  if (eps === null || bookValue === null) {
    const cached = getCachedStockFundamentals(sym);
    if (cached) {
      if (eps === null && cached.eps !== undefined && cached.eps !== null) eps = Number(cached.eps);
      if (bookValue === null && (cached.bookValue || cached.bvps)) bookValue = Number(cached.bookValue || cached.bvps);
      if (!sector && cached.sector) sector = cached.sector;
    }
  }

  // 3. Reject synthetic estimation: if real eps or bookValue is missing or <= 0, show explicit insufficient state
  if (eps === null || bookValue === null || eps <= 0 || bookValue <= 0) {
    return (
      <div
        style={{
          borderRadius: 16,
          border: '1px solid rgba(255, 255, 255, 0.08)',
          background: 'var(--bg-card, #151922)',
          padding: '16px',
          boxShadow: '0 8px 24px rgba(0,0,0,0.25)',
          display: 'flex',
          flexDirection: 'column',
          gap: 14,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 9 }}>
            <div
              style={{
                width: 32,
                height: 32,
                borderRadius: 10,
                background: 'rgba(245, 158, 11, 0.15)',
                border: '1px solid rgba(245, 158, 11, 0.35)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                color: '#fbbf24',
              }}
            >
              <ShieldAlert size={17} />
            </div>
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                <span style={{ fontSize: 13, fontWeight: 800, color: '#ffffff', letterSpacing: '-0.01em' }}>
                  Graham Margin of Safety & Capital Preservation Shield
                </span>
                <span
                  style={{
                    fontSize: 12,
                    fontWeight: 800,
                    textTransform: 'uppercase',
                    padding: '2px 6px',
                    borderRadius: 6,
                    background: 'rgba(255, 255, 255, 0.06)',
                    color: '#94a3b8',
                  }}
                >
                  Intelligent Investor
                </span>
              </div>
              <div style={{ fontSize: 12, color: '#64748b', marginTop: 1 }}>
                Defensive equity framework: Valuation shock-absorber & permanent capital preservation
              </div>
            </div>
          </div>
        </div>

        <div
          style={{
            borderRadius: 12,
            padding: '14px 16px',
            background: 'rgba(245, 158, 11, 0.08)',
            border: '1px solid rgba(245, 158, 11, 0.3)',
            display: 'flex',
            alignItems: 'flex-start',
            gap: 12,
          }}
        >
          <AlertTriangle size={20} className="text-amber-400 flex-shrink-0 mt-0.5" />
          <div>
            <div style={{ fontSize: 13, fontWeight: 800, color: '#fbbf24', marginBottom: 3 }}>
              Insufficient Fundamental Filing Data
            </div>
            <div style={{ fontSize: 12, color: '#cbd5e1', lineHeight: 1.5 }}>
              Authentic quarterly filings for {sym} are currently unverified or non-positive (Reported EPS: {eps != null ? `Rs. ${eps}` : 'Missing'}, BVPS: {bookValue != null ? `Rs. ${bookValue}` : 'Missing'}). Benjamin Graham’s Intrinsic Value formulation requires verified positive operational earnings and tangible equity. Synthetic estimation from current stock price is strictly disabled to prevent artificial valuation anchors.
            </div>
          </div>
        </div>
      </div>
    );
  }

  const grahamFloor = +(bookValue * 0.67).toFixed(1);
  const graham = calculateGrahamIntrinsicValue(eps, bookValue, currentPrice);
  const interestAdjusted = calculateInterestAdjustedGrahamValue(eps, 7.0, 7.5, currentPrice);
  const erpMetrics = calculateEarningsYieldAndRiskPremium(eps, currentPrice, 7.5);

  const effectiveIntrinsic = graham.intrinsicValue;
  const mosPct = graham.marginOfSafetyPct;
  const pePb = graham.pePbProduct > 0 ? graham.pePbProduct : +((currentPrice / eps) * (currentPrice / bookValue)).toFixed(1);
  const isLossMaking = Boolean(eps !== null && eps <= 0);

  // Determine Dual-Shield Alignment
  let shieldTier: 'dual' | 'value' | 'momentum' | 'warning' | 'unsupported' = 'warning';
  let tierTitle = '';
  let tierDescription = '';
  let tierBadgeBg = '';
  let tierBadgeBorder = '';
  let tierBadgeText = '';
  let TierIcon = Shield;

  if (mosPct >= 15 && setupScore >= 58) {
    shieldTier = 'dual';
    tierTitle = 'Institutional Dual-Shield Setup (Value + Timing Aligned)';
    tierDescription = `Both balance sheet safety (Rs. ${effectiveIntrinsic.toFixed(1)} Graham Number with a +${mosPct.toFixed(1)}% margin of safety) and technical entry zone are aligned. Highest empirical defense against permanent capital loss.`;
    tierBadgeBg = 'rgba(16, 185, 129, 0.15)';
    tierBadgeBorder = 'rgba(16, 185, 129, 0.4)';
    tierBadgeText = '#34d399';
    TierIcon = ShieldCheck;
  } else if (mosPct >= 15) {
    shieldTier = 'value';
    tierTitle = 'Deep Value Accumulation (Patience Required)';
    tierDescription = `Trading at a +${mosPct.toFixed(1)}% discount to Graham Intrinsic Value (V* Rs. ${effectiveIntrinsic.toFixed(1)}). Excellent fundamental balance-sheet buffer, but intermediate technical momentum is consolidating.`;
    tierBadgeBg = 'rgba(56, 189, 248, 0.15)';
    tierBadgeBorder = 'rgba(56, 189, 248, 0.4)';
    tierBadgeText = '#38bdf8';
    TierIcon = Scale;
  } else if (setupScore >= 58) {
    shieldTier = 'momentum';
    tierTitle = 'Tactical Momentum Play (Strict Stop-Loss Mandatory)';
    tierDescription = `Technically strong setup (${setupScore}/100), but trading at a ${Math.abs(mosPct).toFixed(1)}% premium above Graham Fair Value (V* Rs. ${effectiveIntrinsic.toFixed(1)}). Valid for quantitative swing trading only; structural stop-loss is mandatory.`;
    tierBadgeBg = 'rgba(245, 158, 11, 0.15)';
    tierBadgeBorder = 'rgba(245, 158, 11, 0.4)';
    tierBadgeText = '#fbbf24';
    TierIcon = AlertTriangle;
  } else {
    shieldTier = 'warning';
    tierTitle = 'High Capital Loss Risk (Fails Value & Timing Criteria)';
    tierDescription = `Negative margin of safety (${mosPct.toFixed(1)}% vs V* Rs. ${effectiveIntrinsic.toFixed(1)}) combined with deteriorating technical momentum. Avoid long exposure until valuation compresses.`;
    tierBadgeBg = 'rgba(244, 63, 94, 0.15)';
    tierBadgeBorder = 'rgba(244, 63, 94, 0.4)';
    tierBadgeText = '#fb7185';
    TierIcon = ShieldAlert;
  }

  // 5-Point Graham Checklist
  const checklist = [
    {
      label: 'Positive Operational Earnings Power (EPS > 0)',
      passed: eps > 0,
      value: eps > 0 ? `Rs. ${eps.toFixed(2)}` : `Loss: Rs. ${eps.toFixed(2)}`,
      sub: 'Proof of commercial vitality',
    },
    {
      label: 'Tangible Asset Backing (BVPS > 0)',
      passed: bookValue > 0,
      value: bookValue > 0 ? `Rs. ${bookValue.toFixed(1)}` : 'Deficient',
      sub: 'Net assets protecting liquidation parity',
    },
    {
      label: isLossMaking ? 'Trading Below Asset Floor (LTP ≤ Floor)' : 'Trading Below Graham Fair Value (LTP ≤ V*)',
      passed: currentPrice <= effectiveIntrinsic,
      value: `LTP Rs. ${currentPrice.toFixed(1)} vs ${isLossMaking ? 'Floor' : 'V*'} Rs. ${effectiveIntrinsic.toFixed(1)}`,
      sub: 'Avoids overpaying for future growth',
    },
    {
      label: 'Graham Multiple Ceiling (P/E × P/B ≤ 22.5)',
      passed: !isLossMaking && pePb > 0 && pePb <= 22.5,
      value: isLossMaking ? 'N/A (Loss)' : pePb > 0 ? `${pePb.toFixed(1)}x (Max 22.5x)` : 'Stretched',
      sub: 'Prevents speculative multiple compression',
    },
    {
      label: 'Margin of Safety Buffer (Discount ≥ 15%)',
      passed: mosPct >= 15,
      value: `${mosPct >= 0 ? '+' : ''}${mosPct.toFixed(1)}%`,
      sub: 'Shock-absorber for recessions & adverse events',
    },
  ];

  return (
    <div
      style={{
        borderRadius: 16,
        border: '1px solid rgba(255, 255, 255, 0.08)',
        background: 'var(--bg-card, #151922)',
        padding: '16px',
        boxShadow: '0 8px 24px rgba(0,0,0,0.25)',
        display: 'flex',
        flexDirection: 'column',
        gap: 14,
      }}
    >
      {/* ── Header Title Strip ── */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap', gap: 8 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 9 }}>
          <div
            style={{
              width: 32,
              height: 32,
              borderRadius: 10,
              background: 'linear-gradient(135deg, rgba(16, 185, 129, 0.2), rgba(59, 130, 246, 0.2))',
              border: '1px solid rgba(16, 185, 129, 0.35)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#34d399',
            }}
          >
            <Shield size={17} />
          </div>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <span style={{ fontSize: 13, fontWeight: 800, color: '#ffffff', letterSpacing: '-0.01em' }}>
                Graham Margin of Safety & Capital Preservation Shield
              </span>
              <span
                style={{
                  fontSize: 12,
                  fontWeight: 800,
                  textTransform: 'uppercase',
                  padding: '2px 6px',
                  borderRadius: 6,
                  background: 'rgba(255, 255, 255, 0.06)',
                  color: '#94a3b8',
                }}
              >
                Intelligent Investor
              </span>
            </div>
            <div style={{ fontSize: 12, color: '#64748b', marginTop: 1 }}>
              Defensive equity framework: Valuation shock-absorber & permanent capital preservation
            </div>
          </div>
        </div>

        <button
          type="button"
          onClick={() => setShowFormulaDetails(!showFormulaDetails)}
          style={{
            background: 'transparent',
            border: 'none',
            color: '#60a5fa',
            fontSize: 12,
            fontWeight: 700,
            display: 'flex',
            alignItems: 'center',
            gap: 4,
            cursor: 'pointer',
            padding: '4px 6px',
          }}
        >
          <Info size={12} />
          <span>{showFormulaDetails ? 'Hide Formula' : 'Formula Mechanics'}</span>
          {showFormulaDetails ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
        </button>
      </div>

      {/* ── Expandable Formula Explanation ── */}
      {showFormulaDetails && (
        <div
          style={{
            background: 'rgba(15, 23, 42, 0.7)',
            borderRadius: 12,
            border: '1px solid rgba(59, 130, 246, 0.25)',
            padding: '12px 14px',
