                title="Remove Lot"
              >
                ✕
              </button>
            )}
          </div>
        ))}

        {/* Optional Bonus & Right Share Dilution Inputs */}
        <div className="grid grid-cols-3 gap-2 pt-2">
          <div>
            <label className="text-[11px] font-semibold text-slate-400 block mb-1">Bonus Share %</label>
            <input
              type="number"
