export function AlertsTool() {
  const [alerts, setAlerts] = useLocal<any[]>('nepse_alerts_v1', []);
  const [f, setF] = useState({ symbol: '', level: '', dir: 'above' });
  const [stocks, setStocks] = useState<EnrichedStock[]>([]);
  useEffect(() => { loadNepseData().then(({ stocks }) => setStocks(stocks)); }, []);
  const hit = (al: any) => {
    const s = stocks.find((x) => x.symbol === al.symbol);
    if (!s) return false;
    return al.dir === 'above' ? s.ltp >= al.level : s.ltp <= al.level;
  };
  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-3 bg-slate-900/60 p-3.5 rounded-2xl border border-slate-800">
        <h3 className="text-base font-bold text-white tracking-wide">Stock Target Alerts & Triggers</h3>
      </div>
      <InfoBanner type="success"><Bell size={13} className="mr-1 inline" /> Price alerts are evaluated against live LTP every time you open this tab.</InfoBanner>
      <div className="mb-4 grid grid-cols-1 gap-2 sm:grid-cols-2 md:grid-cols-4 items-end">
        <div>
          <label className="mb-1 block text-[11px] font-semibold text-slate-400">Stock Symbol</label>
          <StockSearchSelect value={f.symbol} onChange={(sym) => setF({ ...f, symbol: sym })} placeholder="Stock symbol…" />
        </div>
        <div>
          <label className="mb-1 block text-[11px] font-semibold text-slate-400">Condition</label>
          <select value={f.dir} onChange={(e) => setF({ ...f, dir: e.target.value })} className="w-full rounded-xl border border-slate-700 bg-slate-900 px-3 py-2.5 text-xs text-white">
            <option value="above">Crosses above</option>
            <option value="below">Falls below</option>
          </select>
        </div>
        <div>
          <label className="mb-1 block text-[11px] font-semibold text-slate-400">Price Level (Rs.)</label>
          <input type="number" placeholder="Price level" value={f.level} onChange={(e) => setF({ ...f, level: e.target.value })} className="w-full rounded-xl border border-slate-700 bg-slate-900 px-3.5 py-2.5 text-xs text-white placeholder:text-slate-500" />
        </div>
        <button onClick={() => { if (f.level && f.symbol) { setAlerts([{ id: Date.now(), ...f, level: parseFloat(f.level) }, ...alerts]); setF({ ...f, level: '' }); } }} className="cursor-pointer rounded-xl bg-blue-600 px-4 py-2.5 text-xs font-bold text-white hover:bg-blue-700 h-[38px]">+ Alert</button>
      </div>
      {alerts.length === 0 ? <NoData message="No alerts set." /> : (
        <div className="grid gap-2">
          {alerts.map((al) => {
            const h = hit(al);
            return (
              <div key={al.id} className={`flex items-center justify-between rounded-lg border p-3 text-sm ${h ? 'border-emerald-800/60 bg-emerald-950/40 text-emerald-200' : 'border-slate-800 bg-slate-900/80 text-white'}`}>
                <div><strong>{al.symbol}</strong> {al.dir === 'above' ? '≥' : '≤'} Rs. {al.level} {h && <span className="ml-2 rounded-full bg-emerald-600 px-2 py-0.5 text-[11px] font-bold text-white">TRIGGERED</span>}</div>
                <button onClick={() => setAlerts(alerts.filter((x) => x.id !== al.id))} className="cursor-pointer text-xs font-bold text-red-400">Remove</button>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ── API status dashboard & Live Full-App Math Auditor ──
export function ApiStatusService() {
  const [liveCount, setLiveCount] = useState(0);
  const [auditState, setAuditState] = useState<{
    running: boolean;
    done: boolean;
    passedCount: number;
    totalCount: number;
    durationMs: number;
    results: Array<{
      category: string;
      name: string;
      pass: boolean;
      details: string;
      durationMs?: number;
    }>;
  }>({
    running: false,
    done: false,
    passedCount: 0,
    totalCount: 0,
    durationMs: 0,
    results: [],
  });

  useEffect(() => { setLiveCount(getCachedStocks().length); }, []);

  const runLiveAudit = async () => {
    setAuditState({
      running: true,
      done: false,
      passedCount: 0,
      totalCount: 0,
      durationMs: 0,
      results: [],
    });
    const startTime = Date.now();
    const resList: Array<{ category: string; name: string; pass: boolean; details: string; durationMs?: number }> = [];

    const record = (category: string, name: string, pass: boolean, details: string, durationMs?: number) => {
      resList.push({ category, name, pass, details, durationMs });
      setAuditState((prev) => ({
        ...prev,
        results: [...resList],
        passedCount: resList.filter((r) => r.pass).length,
        totalCount: resList.length,
      }));
    };

    try {
      // ── Category A: Core Market Feeds ──
      const t0 = Date.now();
      try {
        const resp = await fetch('/api/health');
        const d = await resp.json();
        const ok = resp.ok && (d.status === 'HEALTHY' || d.status === 'OK' || d.status === 'ok');
        record('Category A: Market Feeds', 'Proxy Health & NPT Clock (/api/health)', ok, `Status: ${d.status || 'OK'} • Market: ${d.nepseTime || d.time || 'NPT'}`, Date.now() - t0);
      } catch (e: any) {
        record('Category A: Market Feeds', 'Proxy Health & NPT Clock (/api/health)', false, e.message, Date.now() - t0);
      }

      const t1 = Date.now();
      try {
        const resp = await fetch('/api/market-indices');
        const d = await resp.json();
        const val = d?.nepse?.value || d?.data?.nepse?.value || 0;
        const subCount = (d?.subIndices || d?.data?.subIndices || []).length;
        record('Category A: Market Feeds', 'Market Indices (/api/market-indices)', val > 1000 && subCount >= 8, `NEPSE: ${Number(val).toFixed(2)} pts • Sub-indices: ${subCount} sectors`, Date.now() - t1);
      } catch (e: any) {
        record('Category A: Market Feeds', 'Market Indices (/api/market-indices)', false, e.message, Date.now() - t1);
      }

      const t2 = Date.now();
      try {
        const resp = await fetch('/api/today-prices');
        const d = await resp.json();
        const rows = Array.isArray(d) ? d : (d?.data || []);
        const enrichedCount = rows.filter((r: any) => r.brokerAnalysis || r.bcr3BuyPct != null).length;
        record('Category A: Market Feeds', 'Today Prices & Equities (/api/today-prices)', rows.length >= 50, `Active equities: ${rows.length} • Broker-enriched: ${enrichedCount}`, Date.now() - t2);
      } catch (e: any) {
        record('Category A: Market Feeds', 'Today Prices & Equities (/api/today-prices)', false, e.message, Date.now() - t2);
      }

      // ── Category B: Broker Mathematical Invariants & Floorsheet ──
      const t3 = Date.now();
      try {
        const brokerResp = await fetch('/api/broker-analysis/NABIL?days=1&refresh=true');
        const bData = await brokerResp.json();
        const payload = bData?.data || bData;
        const brokers = payload?.brokers || [];
        const sumBuy = brokers.reduce((s: number, b: any) => s + (Number(b.buyQty) || 0), 0);
        const sumSell = brokers.reduce((s: number, b: any) => s + (Number(b.sellQty) || 0), 0);
        const isZeroSum = sumBuy > 0 && Math.abs(sumBuy - sumSell) === 0;
        record('Category B: Broker Invariants', 'Zero-Sum Broker Law (Buy Qty == Sell Qty)', isZeroSum, `NABIL (1D) • Buy: ${sumBuy.toLocaleString()} • Sell: ${sumSell.toLocaleString()} • Delta: ${sumBuy - sumSell}`, Date.now() - t3);

        const netAccPass = brokers.length > 0 && brokers.slice(0, 10).every((b: any) => {
          const expectedNet = (Number(b.buyQty) || 0) - (Number(b.sellQty) || 0);
          return Math.abs((Number(b.netQty) || 0) - expectedNet) === 0;
        });
        record('Category B: Broker Invariants', 'Net Accumulation Identity (netQty = buyQty - sellQty)', netAccPass, `Verified across top 10 brokers of NABIL`, Date.now() - t3);
      } catch (e: any) {
        record('Category B: Broker Invariants', 'Zero-Sum Broker Invariants', false, e.message, Date.now() - t3);
      }

      // ── Category C: Quantitative Setup Engine & Geometric Order ──
      const t4 = Date.now();
      try {
        const mockStock = { symbol: 'NABIL', ltp: 600, high52: 700, low52: 450, volume: 50000 };
        const mockCandles = Array.from({ length: 60 }, (_, i) => ({
          t: `2026-0${Math.floor(i / 25) + 1}-${String((i % 25) + 1).padStart(2, '0')}`,
          o: 580 + (i * 0.5),
