export function StockSearchSelect({
  value,
  onChange,
  placeholder = 'Search by ticker or company name…',
  label,
  allowClear = true,
  className = '',
  stocks = [],
}: {
  value: string;
  onChange: (symbol: string) => void;
  placeholder?: string;
  label?: string;
  allowClear?: boolean;
  className?: string;
  stocks?: any[];
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const wrapperRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleClear = (e: SyntheticEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setSearch('');
    onChange('');
    setIsOpen(false);
    if (inputRef.current) {
      inputRef.current.value = '';
      inputRef.current.focus();
    }
  };

  // Map of live stock prices from props if available
  const livePriceMap = useMemo(() => {
    const map: Record<string, { ltp: number; pChange?: number }> = {};
    if (Array.isArray(stocks) && stocks.length > 0) {
      for (const s of stocks) {
        if (s && s.symbol) {
          map[s.symbol.toUpperCase()] = {
            ltp: Number(s.ltp ?? s.price) || 0,
            pChange: s.pChange !== undefined ? Number(s.pChange) : undefined,
          };
        }
      }
    }
    return map;
  }, [stocks]);

  // Merged stock universe combining UNIFIED_UNIVERSE and live traded stocks from props
  const allAvailableStocks = useMemo(() => {
    const list = [...UNIFIED_UNIVERSE];
    const seen = new Set(list.map((c) => c.symbol.toUpperCase()));
    if (Array.isArray(stocks) && stocks.length > 0) {
      for (const s of stocks) {
        if (s && s.symbol) {
          const sym = String(s.symbol).toUpperCase().trim();
          if (!seen.has(sym)) {
            seen.add(sym);
            list.push({
              symbol: sym,
              name: s.companyName || s.name || sym,
              sector: s.sector || 'Others',
              basePrice: Number(s.ltp ?? s.price) || 100,
            });
          }
        }
      }
    }
    return list;
  }, [stocks]);

  const selectedCompany = useMemo(() => {
    if (!value) return null;
    const vUpper = value.toUpperCase();
    return allAvailableStocks.find((c) => c.symbol.toUpperCase() === vUpper) || null;
  }, [value, allAvailableStocks]);

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) {
      // Default suggestions when search is empty: show active stocks with volume, or top universe names
      if (Array.isArray(stocks) && stocks.length > 0) {
        const topByVol = [...stocks]
          .sort((a, b) => (Number(b.turnover || b.volume) || 0) - (Number(a.turnover || a.volume) || 0))
          .slice(0, 15)
          .map((s) => {
            const sym = s.symbol.toUpperCase();
            return allAvailableStocks.find((c) => c.symbol.toUpperCase() === sym) || {
              symbol: sym,
              name: s.companyName || sym,
              sector: s.sector || 'Others',
              basePrice: Number(s.ltp ?? s.price) || 100,
            };
          });
        return topByVol;
      }
      return allAvailableStocks.slice(0, 15);
    }

    const exactSym: UnifiedStockItem[] = [];
    const startsWithSym: UnifiedStockItem[] = [];
    const containsSym: UnifiedStockItem[] = [];
    const startsWithName: UnifiedStockItem[] = [];
    const containsName: UnifiedStockItem[] = [];
    const containsSector: UnifiedStockItem[] = [];

    for (const c of allAvailableStocks) {
      const sym = c.symbol.toLowerCase();
      const name = c.name.toLowerCase();
      const sector = c.sector.toLowerCase();

      if (sym === q) {
        exactSym.push(c);
      } else if (sym.startsWith(q)) {
        startsWithSym.push(c);
      } else if (sym.includes(q)) {
        containsSym.push(c);
      } else if (name.startsWith(q)) {
        startsWithName.push(c);
      } else if (name.includes(q)) {
        containsName.push(c);
      } else if (sector.includes(q)) {
        containsSector.push(c);
      }
    }

    return [...exactSym, ...startsWithSym, ...containsSym, ...startsWithName, ...containsName, ...containsSector].slice(0, 35);
  }, [search, allAvailableStocks, stocks]);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
        setIsOpen(false);
        const q = search.trim().toUpperCase();
        if (q) {
          const exact = allAvailableStocks.find(c => c.symbol.toUpperCase() === q);
          if (exact && exact.symbol !== value) {
            onChange(exact.symbol);
          }
        }
        setSearch('');
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [search, allAvailableStocks, value, onChange]);

  const displayValue = isOpen
    ? search
    : (selectedCompany ? `${selectedCompany.symbol} — ${selectedCompany.name}` : (value || ''));

  const handleSelect = (sym: string) => {
    onChange(sym);
    setIsOpen(false);
    setSearch('');
  };

  return (
    <div ref={wrapperRef} className={`relative w-full ${className}`}>
      {label && <label className="mb-1.5 block text-xs font-bold text-slate-300 tracking-wide">{label}</label>}
      <div style={{ position: 'relative', display: 'flex', alignItems: 'center', width: '100%' }}>
        <Search
          size={15}
          style={{
            position: 'absolute',
            left: '12px',
            top: '50%',
            transform: 'translateY(-50%)',
            color: '#94a3b8',
            pointerEvents: 'none',
            zIndex: 2,
          }}
        />
        <input
          ref={inputRef}
          type="text"
          value={displayValue}
          onChange={(e) => {
            const val = e.target.value;
            setSearch(val);
            setIsOpen(true);
          }}
          onFocus={(e) => {
            setSearch(value || '');
            setIsOpen(true);
            e.target.select();
          }}
          onKeyDown={(e) => {
            if (e.key === 'Escape') {
              setIsOpen(false);
              setSearch('');
            } else if (e.key === 'Enter') {
              e.preventDefault();
              const q = search.trim().toLowerCase();
              const exact = allAvailableStocks.find(c => c.symbol.toLowerCase() === q);
              if (exact) {
                handleSelect(exact.symbol);
              } else if (filtered.length > 0) {
                handleSelect(filtered[0].symbol);
              }
            }
          }}
          autoComplete="off"
          autoCorrect="off"
          autoCapitalize="none"
          spellCheck={false}
          data-form-type="other"
          placeholder={placeholder}
          style={{
            width: '100%',
            backgroundColor: '#151922',
            color: '#ffffff',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            borderRadius: '12px',
            paddingLeft: '38px',
            paddingRight: '38px',
            paddingTop: '10px',
            paddingBottom: '10px',
            fontSize: '13.5px',
            fontWeight: 600,
            outline: 'none',
            boxShadow: '0 2px 8px rgba(0,0,0,0.3)',
            boxSizing: 'border-box',
          }}
        />
        {(Boolean(value) || Boolean(search)) && allowClear && (
          <button
