class RootErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, errorInfo) {
    console.error('Root ErrorBoundary caught:', error, errorInfo);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{
          minHeight: '100vh',
          background: '#0B0E14',
          color: '#fff',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: 24,
          textAlign: 'center'
        }}>
          <div style={{ fontSize: 36, marginBottom: 12 }}>⚠️</div>
          <h2 style={{ fontSize: 18, color: '#f87171', marginBottom: 8 }}>Something went wrong</h2>
          <p style={{ fontSize: 12, color: '#94a3b8', maxWidth: 360, marginBottom: 16 }}>
            {this.state.error?.message || 'An unexpected error occurred while starting the app.'}
          </p>
          <button
            onClick={() => {
              try { localStorage.clear(); } catch (_) {}
              try { sessionStorage.clear(); } catch (_) {}
              if (typeof window !== 'undefined' && 'caches' in window) {
                try {
                  caches.keys().then(names => {
                    for (let name of names) caches.delete(name);
                  });
                } catch (_) {}
              }
              window.location.reload();
            }}
            style={{
              padding: '10px 20px',
              background: '#5b5ef4',
              color: '#fff',
              border: 'none',
              borderRadius: 10,
              fontWeight: 700,
              cursor: 'pointer'
            }}
          >
            Clear Cache & Restart
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <RootErrorBoundary>
      <App />
    </RootErrorBoundary>
  </React.StrictMode>,
)

