// ── Quantitative Offline Report Generator (Grounded in Authentic History) ──
export function generateOfflineStockReport(stock, customNewsPulse = null, realPriceHistory = null, realBrokerAnalysis = null) {
  if (!stock) return '';
  const actualStock = (stock?.stock) ? stock.stock : stock;
  const sym = (actualStock.symbol || actualStock.stockSymbol || actualStock.sym || actualStock.scrip || actualStock.ticker || actualStock.item?.symbol || 'STOCK').toUpperCase();
  const name = actualStock.name || actualStock.companyName || sym;
  let ltp = Number(
    actualStock.ltp ||
    actualStock.currentPrice ||
    actualStock.lastTradedPrice ||
    actualStock.closePrice ||
    actualStock.close ||
    actualStock.price ||
    actualStock.entry_price ||
    actualStock.prevClose ||
    0
  );

  // Fallback 1: Extract latest close from realPriceHistory
  if ((!ltp || isNaN(ltp) || ltp <= 0) && Array.isArray(realPriceHistory) && realPriceHistory.length > 0) {
    for (let i = realPriceHistory.length - 1; i >= 0; i--) {
      const c = realPriceHistory[i];
      const p = Number(c?.close || c?.closePrice || c?.ltp || c?.y || 0);
      if (p > 0) {
        ltp = p;
        break;
      }
    }
  }

  // Fallback 2: Extract from candle history if attached on stock
  if ((!ltp || isNaN(ltp) || ltp <= 0) && Array.isArray(actualStock.history || actualStock.candles)) {
    const arr = actualStock.history || actualStock.candles;
    for (let i = arr.length - 1; i >= 0; i--) {
      const c = arr[i];
      const p = Number(c?.close || c?.closePrice || c?.ltp || 0);
      if (p > 0) {
        ltp = p;
        break;
      }
    }
  }

  if (!ltp || isNaN(ltp) || ltp <= 0) {
    return `### ⚠️ Data Insufficient for **${sym}**
• Real market price is unavailable from the exchange feed.
• Quantitative analysis cannot be performed without verified price telemetry.`;
  }

  const rsi = stock.rsi != null && !isNaN(Number(stock.rsi)) ? Number(stock.rsi) : null;
  const pe = stock.pe != null && !isNaN(Number(stock.pe)) && Number(stock.pe) > 0 ? Number(stock.pe) : null;
  const eps = stock.eps != null && !isNaN(Number(stock.eps)) ? Number(stock.eps) : null;
  const bookValue = stock.bookValue != null && Number(stock.bookValue) > 0 ? Number(stock.bookValue) : (stock.bvps != null && Number(stock.bvps) > 0 ? Number(stock.bvps) : null);
  const pChg = Number(stock.pChange) || 0;
  const volume = stock.volume != null && !isNaN(Number(stock.volume)) ? Number(stock.volume) : null;
  const turnover = stock.turnover != null && !isNaN(Number(stock.turnover)) ? Number(stock.turnover) : (volume != null ? (ltp * volume) : null);

  const hasRealHistory = Array.isArray(realPriceHistory) && realPriceHistory.length > 0;
  const historyList = hasRealHistory
    ? realPriceHistory.slice().filter(c => c && (c.date || c.t || c.time)).sort((a, b) => new Date(a.date || a.t || a.time) - new Date(b.date || b.t || b.time))
    : [];

  const high12M = (stock.high52w && Number(stock.high52w) > 0)
    ? Number(stock.high52w)
    : (hasRealHistory ? Math.max(...historyList.map(h => Number(h.high || h.close))) : null);

  const low12M = (stock.low52w && Number(stock.low52w) > 0)
    ? Number(stock.low52w)
    : (hasRealHistory ? Math.min(...historyList.map(h => Number(h.low || h.close))) : null);

  const yearAgoClose = hasRealHistory && historyList[0]?.close
    ? Number(historyList[0].close)
    : (Number(stock.prevYearClose) || null);
  const return12M = (yearAgoClose && yearAgoClose > 0) ? (((ltp - yearAgoClose) / yearAgoClose) * 100).toFixed(2) : null;

  const closes = historyList.map(h => Number(h.close || h.ltp)).filter(c => !isNaN(c) && c > 0);
  const sma50 = closes.length >= 50
    ? Number((closes.slice(-50).reduce((a, b) => a + b, 0) / 50).toFixed(1))
    : null;
  const sma200 = closes.length >= 200
    ? Number((closes.slice(-200).reduce((a, b) => a + b, 0) / 200).toFixed(1))
    : null;
  const smaTrend = sma200 != null
    ? (ltp >= sma200 ? 'Bullish (Above 200 SMA)' : 'Bearish (Below 200 SMA)')
    : 'Insufficient history for 200 SMA';

  const wyckoff = detectWyckoffPhase(historyList, volume || 0);
  const atrVal = calculateATR(historyList);
  const targets = (high12M != null && low12M != null && atrVal != null)
    ? calculateMultiHorizonTargets(ltp, high12M, low12M, atrVal, pChg)
    : { target1: null, target2: null, stopLoss: null };

  const newsHighlight = customNewsPulse || null;
  const probMatrix = calculateProbabilisticMatrix(stock, historyList, newsHighlight);

  const graham = (eps != null && bookValue != null)
    ? calculateGrahamIntrinsicValue(eps, bookValue, ltp)
    : { intrinsicValue: null, marginOfSafetyPct: null };
  const actionZone = classifyActionZone({ ...stock, eps, bookValue, ltp, candles: historyList, history: historyList });
  const zVol = volume != null
    ? calculateVolumeZScore(volume, stock.avgVolume20D || volume)
    : { zScore: '—' };

  const chg = stock.change != null ? Number(stock.change) : (pChg ? Number((ltp * (pChg / 100)).toFixed(2)) : 0);
  const pClose = stock.prevClose != null ? Number(stock.prevClose) : (chg ? Number((ltp - chg).toFixed(2)) : null);
  const dayHigh = stock.high != null ? Number(stock.high) : null;
  const dayLow = stock.low != null ? Number(stock.low) : null;

  const dataGaps = [];
  if (volume == null) dataGaps.push('Trading volume');
  if (eps == null) dataGaps.push('EPS / earnings statement');
  if (bookValue == null) dataGaps.push('Book value (BVPS)');
  if (sma200 == null) dataGaps.push('200-session price history');
  if (high12M == null) dataGaps.push('52-week range');

  const warningSection = dataGaps.length > 0
    ? `> ⚠️ **Data Completeness Notice**: The following inputs are unavailable from the exchange: **${dataGaps.join(', ')}**. Analysis has reduced confidence.\n\n`
    : '';

  return `${warningSection}### 📌 Live Market Price: **${sym}** (${name})
• **Official Final Price (LTP)**: **Rs. ${ltp.toFixed(2)}** (${pChg >= 0 ? '+' : ''}${chg.toFixed(2)} / ${pChg >= 0 ? '+' : ''}${pChg.toFixed(2)}%)
• **Previous Closing Price**: ${pClose != null ? `**Rs. ${pClose.toFixed(2)}**` : '—'} | **Today's Range**: Low **Rs. ${dayLow != null ? dayLow.toFixed(2) : '—'}** — High **Rs. ${dayHigh != null ? dayHigh.toFixed(2) : '—'}**
• **Today's Volume**: ${volume != null ? `${volume.toLocaleString()} shares` : '—'} · Turnover: ${turnover != null ? (turnover >= 10000000 ? `Rs. ${(turnover/10000000).toFixed(2)} Cr` : `Rs. ${(turnover/100000).toFixed(2)} Lakh`) : '—'}
• **Volume Expansion (RVOL)**: **${probMatrix.rvol || '—'}x** (Z-Score: **${zVol.zScore || '—'}**)

---

### 🎯 1. GURU AI OPERATIONAL ACTION ZONE: **${actionZone.zoneBadge}**
• **Strategic Verdict**: ${actionZone.zone} — ${actionZone.systematicStrategy}
• **Wyckoff Cycle Phase**: **${wyckoff.phase}** (${wyckoff.action})
• **Graham Intrinsic Value**: Rs. ${graham.intrinsicValue ? graham.intrinsicValue.toFixed(2) : 'N/A'} (Margin of Safety: ${graham.marginOfSafetyPct != null ? (graham.marginOfSafetyPct >= 0 ? '+' : '') + graham.marginOfSafetyPct.toFixed(1) + '%' : 'N/A'})
• **Targets**: Target 1: Rs. ${targets.target1?.price ?? 'N/A'} (+${targets.target1?.pct ?? '—'}%) | Target 2: Rs. ${targets.target2?.price ?? 'N/A'} (+${targets.target2?.pct ?? '—'}%) | Stop-Loss: Rs. ${targets.stopLoss?.price ?? 'N/A'} (-${targets.stopLoss?.pct ?? '—'}%)`;
}


/**
 * Deterministic Context Builder Selector for Guru AI
 * Synthesizes live market breadth, selected stock metrics, and portfolio summary
 * from the unified store into a structured context block to eliminate hallucinations.
 */
export function getGuruAiLiveContext({
  marketStocks = [],
  selectedStock = null,
  userPortfolio = null,
  activeTab = null
} = {}) {
  const stocks = Array.isArray(marketStocks) ? marketStocks : [];
  const totalScrips = stocks.length;

  let advances = 0;
  let declines = 0;
  let unchanged = 0;
  let totalTurnover = 0;

  for (const s of stocks) {
    const chg = Number(s.pChange || s.pointChange || 0);
    if (chg > 0) advances++;
    else if (chg < 0) declines++;
    else unchanged++;
    totalTurnover += Number(s.turnover || 0);
  }

  const topGainers = stocks.slice().sort((a, b) => Number(b.pChange || 0) - Number(a.pChange || 0)).slice(0, 3).map(s => `${s.symbol} (+${Number(s.pChange || 0).toFixed(1)}%)`);
  const topLosers = stocks.slice().sort((a, b) => Number(a.pChange || 0) - Number(b.pChange || 0)).slice(0, 3).map(s => `${s.symbol} (${Number(s.pChange || 0).toFixed(1)}%)`);

  let context = `[LIVE NEPSE CONTEXT - VERIFIED DATA]\n`;
  context += `• Traded Universe: ${totalScrips} Scrips | Advances: ${advances} | Declines: ${declines} | Unchanged: ${unchanged}\n`;
  if (totalTurnover > 0) {
    context += `• Total Market Turnover: Rs. ${(totalTurnover / 10000000).toFixed(2)} Crore\n`;
  }
  if (topGainers.length) context += `• Top Gainers: ${topGainers.join(', ')}\n`;
  if (topLosers.length) context += `• Top Losers: ${topLosers.join(', ')}\n`;

  if (activeTab) {
    context += `• User Active Tab: ${activeTab}\n`;
  }

  if (selectedStock && (selectedStock.symbol || selectedStock.scrip)) {
    const sym = String(selectedStock.symbol || selectedStock.scrip).toUpperCase();
    const ltp = Number(selectedStock.ltp || selectedStock.close || selectedStock.price || 0);
    const pChg = Number(selectedStock.pChange || 0);
    context += `• Inspected Scrip: ${sym} (LTP: Rs. ${ltp.toFixed(1)}, Change: ${pChg >= 0 ? '+' : ''}${pChg.toFixed(2)}%)\n`;
  }

  if (userPortfolio && typeof userPortfolio === 'object') {
    const holdingsCount = Array.isArray(userPortfolio.holdings) ? userPortfolio.holdings.length : 0;
    const totalVal = Number(userPortfolio.totalValue || userPortfolio.totalCurrentValue || 0);
    if (holdingsCount > 0) {
      context += `• User Portfolio: ${holdingsCount} active holdings | Value: Rs. ${totalVal.toLocaleString()}\n`;
    }
  }

  return context.trim();
}

/**
 * CDSC MeroShare Authentic REST Client & Live Extraction Engine
 * 
 * Direct MeroShare Extraction Architecture:
 * - Direct CDSC REST endpoint: https://webbackend.cdsc.com.np/api/meroShare and /api/meroShareView
 * - F5 WAF Bypass: Uses stateless requests (clears and strips TS* cookies)
 * - Mobile User-Agent: 'Dart/2.19 (dart:io)' matching official CDSC mobile app network signature
 * - Auth: clientId MUST be sent as STRING type ("128", "174", etc.) per CDSC API spec
 * - Auth JWT: Returned in Authorization RESPONSE HEADER
 * - Live Portfolio: POST to /api/meroShareView/myPortfolio/ with { sortBy: 'script', demat: [dematId], clientCode: dpCode, page: 1, size: 200, sortAsc: true }
 * - Cross-Platform: CapacitorHttp + CapacitorCookies on Native Android/iOS, cookie-stripping reverse proxy on Web
 * - Multi-layer fallback: Direct REST -> CSV/Excel file import -> Manual scrip entry
 */

import { Capacitor, CapacitorHttp, CapacitorCookies } from '@capacitor/core';
import { getProxyBase } from '../utils/liveData';

// ─── Platform Detection ────────────────────────────────────────────────────
export const isNativeMobile = Capacitor.isNativePlatform();

// Clear native cookie jar to prevent F5 WAF TS* cookie rejection
export async function clearCdscCookies() {
  if (Capacitor.isNativePlatform()) {
    try {
      await CapacitorCookies.clearAllCookies();
    } catch {}
  }
}

// On web: use Vite proxy (strips cookies, rewrites headers)
// On native Android/iOS: direct HTTPS (bypasses browser CORS + WAF cookie issue via native OkHttp/URLSession)
export const MEROSHARE_BASE = isNativeMobile
  ? 'https://webbackend.cdsc.com.np/api/meroShare'
  : '/api/meroShare';

export const MEROSHARE_VIEW_BASE = isNativeMobile
  ? 'https://webbackend.cdsc.com.np/api/meroShareView'
  : '/api/meroShareView';

export const CDSC_IPO_BASE = isNativeMobile
  ? 'https://iporesult.cdsc.com.np'
  : '/cdsc-ipo';

// ─── Unified Cross-Platform CDSC HTTP Client ─────────────────────────────────
export async function cdscRequest(options) {
  const method = options.method || 'GET';
  const isNative = Capacitor.isNativePlatform();

  if (isNative) {
    // Native Mobile HTTP request via Android OkHttp / Java network stack
    // Matches official CDSC mobile app network signature
    const mobileHeaders = {
      'User-Agent': 'Dart/2.19 (dart:io)',
      'Accept': 'application/json, text/plain, */*',
      ...(options.headers || {})
    };
    if (options.data && !mobileHeaders['Content-Type']) {
      mobileHeaders['Content-Type'] = 'application/json';
    }

    const res = await CapacitorHttp.request({
      url: options.url,
      method,
      headers: mobileHeaders,
      data: options.data,
      connectTimeout: 20000,
      readTimeout: 25000
    });

    const status = res.status;
    let data = res.data;
    let text = '';

    if (typeof data === 'string') {
      text = data;
      try {
        data = JSON.parse(text);
      } catch {
        // Keep string data
      }
    } else {
      text = JSON.stringify(data);
    }

    const headersMap = {};
    if (res.headers) {
      for (const [k, v] of Object.entries(res.headers)) {
        headersMap[k.toLowerCase()] = String(v);
        headersMap[k] = String(v);
      }
    }

    const isWafBlocked = typeof text === 'string' && (text.includes('Request Rejected') || text.includes('The requested URL was rejected') || text.includes('support ID is:'));

    return {
      status: isWafBlocked ? 403 : status,
      ok: (status >= 200 && status < 300) && !isWafBlocked,
      data: isWafBlocked ? { message: 'CDSC security firewall rejected the request (WAF). Please check bank details and credentials.' } : data,
      text: isWafBlocked ? 'CDSC security firewall rejected the request (WAF). Please check bank details and credentials.' : text,
      headers: headersMap
    };
  } else {
    // Web browser fetch via Vite / Express proxy
    const webHeaders = {
      'Accept': 'application/json, text/plain, */*',
      ...(options.headers || {})
    };
    if (options.data && !webHeaders['Content-Type']) {
      webHeaders['Content-Type'] = 'application/json';
    }

    const fetchRes = await fetch(options.url, {
      method,
      headers: webHeaders,
      body: options.data ? (typeof options.data === 'string' ? options.data : JSON.stringify(options.data)) : undefined
    });

    const text = await fetchRes.text();
    let data = {};
    try {
      data = JSON.parse(text);
    } catch {
      data = text;
    }

    const headersMap = {};
    fetchRes.headers.forEach((v, k) => {
      headersMap[k.toLowerCase()] = v;
      headersMap[k] = v;
    });

    const isWafBlocked = typeof text === 'string' && (text.includes('Request Rejected') || text.includes('The requested URL was rejected') || text.includes('support ID is:'));

    return {
      status: isWafBlocked ? 403 : fetchRes.status,
      ok: fetchRes.ok && !isWafBlocked,
      data: isWafBlocked ? { message: 'CDSC security firewall rejected the request (WAF). Please check bank details and credentials.' } : data,
      text: isWafBlocked ? 'CDSC security firewall rejected the request (WAF). Please check bank details and credentials.' : text,
      headers: headersMap
    };
  }
}

