/**
 * Retrieves the complete verified quantitative dossier for a scrip.
 * Returns technical indicators, broker flow, execution geometry, and fundamentals.
 *
 * @param {string} symbol - Stock symbol (e.g. "KBL", "HDL", "SBL")
 * @returns {Promise<object>} Complete analytical dossier
 */
export async function fetchAgentScripDossier(symbol) {
  const normSym = String(symbol || '').toUpperCase().trim();
  if (!normSym) throw new Error('Symbol is required');

  // 1. Primary: Try backend /api/agent/stock/:symbol
  try {
    const res = await fetchFromBackend(`/api/agent/stock/${encodeURIComponent(normSym)}`, 8000);
    if (res && res.success && res.data && res.data.quote && res.data.quote.ltp > 0) {
      return res.data;
    }
  } catch (err) {
    console.warn(`[agentTools] Backend /api/agent/stock/${normSym} unavailable, using client quant engine:`, err.message);
  }

  // 2. Client-side verified aggregator fallback:
  // Use real multi-source exchange endpoints so data is ALWAYS authentic, never fake.
  const uItem = UNIVERSE_MAP.get(normSym) || {};

  const [todayPriceRes, historyRes, fundRes, brokerRes] = await Promise.allSettled([
    fetchTodayPrice(normSym),
    fetchPriceHistory(normSym, 120),
    fetchStockSnapshot(normSym),
    fetchRealBrokerAnalysis(normSym, 30)
  ]);

  const liveQuote = todayPriceRes.status === 'fulfilled' && todayPriceRes.value ? todayPriceRes.value : null;
  const rawCandles = historyRes.status === 'fulfilled' && Array.isArray(historyRes.value)
    ? historyRes.value
    : (historyRes.status === 'fulfilled' && Array.isArray(historyRes.value?.data) ? historyRes.value.data : []);
  const fundamentals = fundRes.status === 'fulfilled' && fundRes.value ? fundRes.value : {};
  const broker = brokerRes.status === 'fulfilled' && brokerRes.value ? brokerRes.value : null;

  // Derive authentic current price (no invented default)
  const ltpRaw = Number(
    liveQuote?.ltp ??
    liveQuote?.closePrice ??
    liveQuote?.lastTradedPrice ??
    liveQuote?.data?.ltp ??
    rawCandles[rawCandles.length - 1]?.close ??
    NaN
  );
  if (!isFinite(ltpRaw) || ltpRaw <= 0) {
    throw new Error(`Live price for ${normSym} is unavailable right now. Analysis was not generated to avoid using invented data.`);
  }
  const ltp = ltpRaw;

  const prevClose = Number(
    liveQuote?.prevClose ??
    liveQuote?.previousClose ??
    (rawCandles.length > 1 ? rawCandles[rawCandles.length - 2]?.close : ltp) ??
    ltp
  );

  const pChange = Number(
    liveQuote?.pChange ??
    liveQuote?.percentageChange ??
    (prevClose > 0 ? +(((ltp - prevClose) / prevClose) * 100).toFixed(2) : 0)
  );

  const volRaw = Number(
    liveQuote?.totalTradedQuantity ??
    liveQuote?.volume ??
    rawCandles[rawCandles.length - 1]?.volume ??
    NaN
  );
  const volume = isFinite(volRaw) ? volRaw : null;

  // 15% statutory NEPSE daily equity circuit band limits
  const circuitFloor = +(prevClose * 0.85).toFixed(1);
  const circuitCeiling = +(prevClose * 1.15).toFixed(1);

  // Prepare candles
  const candles = rawCandles.map(c => ({
    date: c.date || c.t || '',
    open: Number(c.open ?? c.o ?? c.close ?? c.c ?? ltp),
    high: Number(c.high ?? c.h ?? c.close ?? c.c ?? ltp),
    low: Number(c.low ?? c.l ?? c.close ?? c.c ?? ltp),
    close: Number(c.close ?? c.c ?? ltp),
    volume: Number(c.volume ?? c.v ?? c.totalTradeQuantity ?? 0)
  })).filter(c => isFinite(c.close) && c.close > 0);

  const closes = candles.map(c => c.close);
  const volumes = candles.map(c => c.volume);

  // Calculate quantitative indicators — null when history is insufficient (never invented)
  const rsiVal = closes.length >= 15 ? calculateRSI(closes, 14) : null;
  const validE20 = closes.length >= 20 ? calculateEMA(closes, 20).filter(v => v !== null && isFinite(v)) : [];
  const ema20Val = validE20.length > 0 ? validE20[validE20.length - 1] : null;
  const validE50 = closes.length >= 50 ? calculateEMA(closes, 50).filter(v => v !== null && isFinite(v)) : [];
  const ema50Val = validE50.length > 0 ? validE50[validE50.length - 1] : null;
  const macdObj = closes.length >= 35 ? calculateMACD(closes) : null;
  const bbObj = closes.length >= 20 ? calculateBollingerBands(closes, 20, 2) : null;
  const atrVal = candles.length >= 15 ? calculateATR(candles, 14) : null;

  const recent20Vols = volumes.slice(-20);
  const avgVol20 = recent20Vols.length >= 5
    ? Math.round(recent20Vols.reduce((a, b) => a + b, 0) / recent20Vols.length)
    : null;
  const rvol20 = (avgVol20 && volume != null) ? +(volume / avgVol20).toFixed(2) : null;

  // Broker smart money metrics — computed only from the real broker feed
  const topBuyers = Array.isArray(broker?.topBuyers) ? broker.topBuyers : (Array.isArray(broker?.buyers) ? broker.buyers : []);
  const topSellers = Array.isArray(broker?.topSellers) ? broker.topSellers : (Array.isArray(broker?.sellers) ? broker.sellers : []);
  const totalVol = Number(broker?.totalVolume || broker?.totalQty || 0);
  const sumQty = (arr, n, keys) => arr.slice(0, n).reduce((acc, b) => acc + Number(keys.map(k => b[k]).find(v => v != null) || 0), 0);
  const top3BuyVol = sumQty(topBuyers, 3, ['buyQty', 'volume', 'shares']);
  const top5BuyVol = sumQty(topBuyers, 5, ['buyQty', 'volume', 'shares']);
  const top3SellVol = sumQty(topSellers, 3, ['sellQty', 'volume', 'shares']);
  const pctOf = (v) => (totalVol > 0 && v > 0) ? +((v / totalVol) * 100).toFixed(1) : null;
  const bcr3Buy = broker?.bcr3BuyPct != null ? Number(broker.bcr3BuyPct) : pctOf(top3BuyVol);
  const bcr5Buy = broker?.bcr5BuyPct != null ? Number(broker.bcr5BuyPct)
    : (broker?.crb5 != null ? +((Number(broker.crb5) <= 1 ? Number(broker.crb5) * 100 : Number(broker.crb5))).toFixed(1) : pctOf(top5BuyVol));
  const bcr3Sell = broker?.bcr3SellPct != null ? Number(broker.bcr3SellPct) : pctOf(top3SellVol);
  const smartMoneyBias = bcr3Buy == null
    ? 'Broker data unavailable'
    : (bcr3Buy >= 40 ? 'Institutional Cornering' : ((bcr3Sell ?? 0) >= 45 ? 'Operator Offloading' : 'Neutral Flow'));

  // Run authentic execution geometry through setupAnalyzer
  const stockForPlan = {
    symbol: normSym,
    ltp,
    prevClose,
    previousClose: prevClose,
    pChange,
    volume,
    high52w: Number(liveQuote?.high52w || uItem.high52 || 0),
    low52w: Number(liveQuote?.low52w || uItem.low52 || 0),
    sector: uItem.sector || fundamentals.sector || 'Others',
    companyName: uItem.name || liveQuote?.companyName || normSym,
    eps: Number(fundamentals.eps || liveQuote?.eps || uItem.eps || 0),
    pe: Number(fundamentals.pe || liveQuote?.pe || 0),
    bookValue: Number(fundamentals.bookValue || liveQuote?.bookValue || uItem.bvps || 0)
  };

  const plan = generateEntryExitPlan(stockForPlan, candles.length >= 10 ? candles : [], [], { brokerAnalysis: broker });
  const levels = plan.levels || {};

  return {
    symbol: normSym,
    companyName: stockForPlan.companyName,
    sector: stockForPlan.sector,
    quote: {
      ltp,
      prevClose,
      pChange,
      volume,
      turnover: Number(liveQuote?.turnover || 0),
      circuitFloor,
      circuitCeiling,
      high52w: stockForPlan.high52w,
      low52w: stockForPlan.low52w,
      avgVolume20D: avgVol20
    },
    technicals: {
      candlesAnalyzed: closes.length,
      rsi14: (rsiVal != null && isFinite(rsiVal)) ? +Number(rsiVal).toFixed(1) : null,
      macd: macdObj ? {
        line: +Number(macdObj.macd ?? 0).toFixed(2),
        signal: +Number(macdObj.signal ?? 0).toFixed(2),
        histogram: +(Number(macdObj.macd ?? 0) - Number(macdObj.signal ?? 0)).toFixed(2),
        isBullishCross: Boolean(Number(macdObj.macd) > Number(macdObj.signal))
      } : null,
      ema20: ema20Val != null ? +Number(ema20Val).toFixed(1) : null,
      ema50: ema50Val != null ? +Number(ema50Val).toFixed(1) : null,
      trendStructure: (ema20Val == null || ema50Val == null)
        ? 'INSUFFICIENT_HISTORY'
        : (ltp >= ema20Val && ema20Val >= ema50Val ? 'BULLISH_STACK' : (ltp < ema20Val && ema20Val < ema50Val ? 'BEARISH_STACK' : 'NEUTRAL_CONSOLIDATION')),
      atr14: (atrVal != null && isFinite(atrVal)) ? +Number(atrVal).toFixed(1) : null,
      rvol20,
      bollinger: bbObj ? {
        upper: +Number(bbObj.upper || 0).toFixed(1),
        middle: +Number(bbObj.middle || 0).toFixed(1),
        lower: +Number(bbObj.lower || 0).toFixed(1),
        isSqueeze: Boolean(bbObj.upper && bbObj.lower && ((bbObj.upper - bbObj.lower) / bbObj.middle) < 0.08)
      } : null
    },
    brokerFlow: {
      bcr3BuyPct: bcr3Buy,
      bcr5BuyPct: bcr5Buy,
      bcr3SellPct: bcr3Sell,
      smartMoneyBias,
      available: bcr3Buy != null
    },
    fundamentals: {
      pe: stockForPlan.pe,
      eps: stockForPlan.eps,
      bookValue: stockForPlan.bookValue
    },
    executionPlan: (() => {
      const hasLevels = plan.supported !== false && levels.stopLoss?.price != null && levels.target1?.price != null;
      if (!hasLevels) {
        return {
          available: false,
          reason: plan.reason || `Only ${candles.length} sessions of history — at least 20 are required for entry/exit levels.`,
          stance: 'INSUFFICIENT DATA',
          setupScore: null,
          pullbackZone: null,
          breakoutZone: null,
          stopLoss: null,
          targets: [],
          riskPerShare: null,
          rewardToTarget1: null
        };
      }
      const toTarget = (t, label) => t?.price != null ? {
        price: t.price,
        netReturnPct: t.netReturnPct ?? null,
        label
      } : null;
      return {
        available: true,
        stance: plan.verdict || 'HOLD / WAIT',
        setupScore: plan.setupScore ?? null,
        pullbackZone: levels.pullbackZone ? {
          low: levels.pullbackZone.low,
          high: levels.pullbackZone.high,
          label: levels.pullbackZone.label,
          supportRef: levels.pullbackZone.supportRef
        } : null,
        breakoutZone: levels.breakoutZone ? {
          pivot: levels.breakoutZone.pivot ?? levels.breakoutPivot,
          chaseCap: levels.breakoutZone.chaseCap ?? levels.chaseCap,
          label: `> Rs. ${levels.breakoutZone.pivot ?? levels.breakoutPivot} (Cap: Rs. ${levels.breakoutZone.chaseCap ?? levels.chaseCap})`
        } : null,
        stopLoss: {
          price: levels.stopLoss.price,
          pct: levels.stopLoss.pct ?? +(((ltp - levels.stopLoss.price) / ltp) * 100).toFixed(1),
          label: levels.stopLoss.label || `Rs. ${levels.stopLoss.price}`
        },
        targets: [
          toTarget(levels.target1, 'Target 1'),
          toTarget(levels.target2, 'Target 2')
        ].filter(Boolean),
        riskPerShare: levels.riskPerShare ?? null,
        rewardToTarget1: levels.rewardToTarget1 ?? null
      };
    })(),
    meta: {
      asOf: new Date().toISOString(),
      dataSource: 'Official NEPSE Feed & NOTS Live Floor Sheet'
    }
  };
}

/**
 * Runs an intelligent, evidence-based analysis for a stock using Gemini 3.1 Pro.
 *
 * @param {object} params
 * @param {string} params.symbol - Stock symbol (e.g. "KBL", "SBL")
 * @param {string} [params.query] - Custom user inquiry or prompt
 * @param {string} [params.model='gemini-3.1-pro'] - Target Gemini model
 * @param {string} [params.apiKey] - Optional custom Gemini API key
 * @returns {Promise<object>} Structured Agent verdict, execution levels, and scenarios
 */
export async function runAgentAnalysis({
  symbol,
  query = '',
  model = 'gemini-3.1-pro',
  apiKey = null
}) {
  const normSym = String(symbol || '').toUpperCase().trim();
  if (!normSym) throw new Error('Symbol is required');

  const base = getProxyBase();
  const clientKey = apiKey || (typeof localStorage !== 'undefined' ? (localStorage.getItem('nepse_gemini_api_key') || localStorage.getItem('nepse_hub_gemini_api_key') || '') : '');

  // Always assemble authentic dossier first
  const dossier = await fetchAgentScripDossier(normSym);

  // 1. Primary: Try backend /api/agent/analyze
  try {
    const res = await fetch(`${base}/api/agent/analyze`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        symbol: normSym,
        query,
        model,
        apiKey: clientKey || undefined
      })
    });

    if (res.ok) {
      const json = await res.json();
      if (json && json.success) {
        const payloadData = json.analysis || json.data || {};
        return {
          ...payloadData,
          dossier: json.dossier || dossier,
          meta: {
            modelUsed: json.modelUsed || json.provider || model,
            isAiOffline: json.isAiOffline || false,
            durationMs: json.durationMs,
            timestamp: json.timestamp || new Date().toISOString()
          }
        };
      }
    }
  } catch (err) {
    console.warn(`[agentTools] /api/agent/analyze request failed, evaluating direct client reasoning:`, err.message);
  }

  // Null-safe accessors — never invent values; show N/A when unavailable.
  const NA = 'N/A';
  const fmt = (v, suffix = '') => (v === null || v === undefined || Number.isNaN(v)) ? NA : `${v}${suffix}`;
  const ep = dossier.executionPlan || { available: false, reason: 'Execution plan unavailable', stance: 'INSUFFICIENT DATA', targets: [] };
  const tech = dossier.technicals || {};
  const bf = dossier.brokerFlow || {};
  const q = dossier.quote || {};
  const pullLbl = ep.pullbackZone?.label || NA;
  const boLbl = ep.breakoutZone?.label || NA;
  const slLbl = ep.stopLoss?.label || NA;
  const slPx = ep.stopLoss?.price ?? null;
  const tLbl = (t) => t?.price != null ? `Rs. ${t.price}${t.netReturnPct != null ? ` (${t.netReturnPct >= 0 ? '+' : ''}${t.netReturnPct}% net)` : ''}` : NA;
  const t1 = tLbl(ep.targets?.[0]);
  const t2 = tLbl(ep.targets?.[1]);
  const rr = (ep.riskPerShare > 0 && ep.rewardToTarget1 != null) ? `1 : ${(ep.rewardToTarget1 / ep.riskPerShare).toFixed(2)}` : NA;

  // 2. Client-side Direct Gemini API Call if user key is available
  if (clientKey) {
    try {
      const prompt = `You are the Drabyashree NEPSE Analysis Agent for NEPSE scrip ${dossier.symbol} (${dossier.companyName}).
Use ONLY the data below. Values marked N/A are unavailable — do not estimate or invent them.
Current LTP: Rs. ${fmt(q.ltp)} (Change: ${fmt(q.pChange, '%')}).
RSI(14): ${fmt(tech.rsi14)}, MACD Histogram: ${fmt(tech.macd?.histogram)}, 20-EMA: ${fmt(tech.ema20)}, 50-EMA: ${fmt(tech.ema50)}.
BCR3 Concentration: ${fmt(bf.bcr3BuyPct, '%')}, Bias: ${bf.smartMoneyBias || NA}.
Execution plan available: ${ep.available ? 'yes' : `no (${ep.reason})`}. Pullback: ${pullLbl}, Breakout: ${boLbl}, Stop-Loss: ${slLbl}.
Target 1: ${t1}, Target 2: ${t2}. Risk:Reward: ${rr}.
Circuit limits (±15% of previous close): Floor Rs. ${fmt(q.circuitFloor)} | Ceiling Rs. ${fmt(q.circuitCeiling)}.
User Query: "${query || 'Provide trade plan and scenarios.'}"

Return valid JSON with keys:
{"symbol":"${dossier.symbol}","verdict":"${ep.stance}","confidenceScore":${ep.setupScore ?? null},"executiveSummary":"...","technicalPosture":"...","smartMoneyFlow":"...","executionPlan":{"recommendedStrategy":"...","pullbackDipZone":"${pullLbl}","breakoutTrigger":"${boLbl}","stopLoss":"${slLbl}","target1":"${t1}","target2":"${t2}","riskRewardRatio":"${rr}"},"scenarios":{"bullishCase":"...","baseCase":"...","bearishInvalidation":"..."},"t2SettlementRisk":"...","nepaliSummary":"..."}`;

      const modelsToTry = [model, 'gemini-2.5-pro', 'gemini-2.0-flash', 'gemini-1.5-flash'];
      for (const m of modelsToTry) {
        try {
          const directUrl = `https://generativelanguage.googleapis.com/v1beta/models/${m}:generateContent?key=${clientKey}`;
          const directRes = await fetch(directUrl, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              contents: [{ parts: [{ text: prompt }] }],
              generationConfig: { temperature: 0.2, maxOutputTokens: 2000, responseMimeType: 'application/json' }
            })
          });
          if (directRes.ok) {
            const data = await directRes.json();
            const text = data?.candidates?.[0]?.content?.parts?.[0]?.text;
            if (text) {
              const parsed = JSON.parse(text);
              return {
                ...parsed,
                dossier,
                meta: { modelUsed: m, isDirectClientGemini: true, timestamp: new Date().toISOString() }
              };
            }
          }
        } catch (_) {}
      }
    } catch (_) {}
  }

  // 3. Deterministic fallback — reports only computed values; N/A where data is missing.
  const pivotVal = ep.breakoutZone?.pivot ?? null;
  const atrVal = tech.atr14 ?? null;
  return {
    symbol: normSym,
    verdict: ep.stance,
    confidenceScore: ep.setupScore ?? null,
    executiveSummary: `${dossier.symbol} (${dossier.companyName}) is trading at Rs. ${fmt(q.ltp)} (${q.pChange >= 0 ? '+' : ''}${fmt(q.pChange)}%). Trend structure: ${tech.trendStructure || NA}; 20-EMA: ${fmt(tech.ema20)}.${ep.available ? ` Setup score: ${fmt(ep.setupScore)}/100.` : ` Trade plan unavailable: ${ep.reason}`}`,
    technicalPosture: `RSI(14): ${fmt(tech.rsi14)}, MACD histogram: ${fmt(tech.macd?.histogram)}. Bollinger squeeze: ${tech.bollinger ? (tech.bollinger.isSqueeze ? 'Active' : 'No') : NA}. 20-day relative volume: ${fmt(tech.rvol20, 'x')}.`,
    smartMoneyFlow: bf.available ? `BCR3 buyer concentration ${bf.bcr3BuyPct}% (${bf.smartMoneyBias}). Top-5 broker concentration ${fmt(bf.bcr5BuyPct, '%')}.` : 'Broker floorsheet data unavailable.',
    executionPlan: {
      recommendedStrategy: !ep.available ? 'No plan — insufficient data' : (String(ep.stance).includes('BREAKOUT') ? 'Breakout Momentum' : 'Pullback Dip Entry'),
      pullbackDipZone: pullLbl,
      breakoutTrigger: boLbl,
      stopLoss: slLbl,
      target1: t1,
      target2: t2,
      riskRewardRatio: rr
    },
    scenarios: {
      bullishCase: (pivotVal != null && atrVal != null)
        ? `High-volume close above breakout pivot Rs. ${pivotVal} (RVOL > 1.4x) opens a move toward ~Rs. ${+(pivotVal + atrVal * 1.5).toFixed(1)} (pivot + 1.5×ATR).`
        : 'Bullish scenario unavailable — breakout pivot or ATR not computable from available history.',
      baseCase: ep.pullbackZone ? `Consolidation within support corridor ${pullLbl}.` : 'Base case unavailable — no support corridor computed.',
      bearishInvalidation: slPx != null ? `Daily close below stop-loss Rs. ${slPx} invalidates the setup.` : 'Invalidation level unavailable.'
    },
    t2SettlementRisk: `Session circuit range Rs. ${fmt(q.circuitFloor)} to Rs. ${fmt(q.circuitCeiling)} (±15%). Avoid buying near the ceiling due to T+2 settlement lockup.`,
    nepaliSummary: ep.available
      ? `${dossier.symbol}: स्टप लस Rs. ${fmt(slPx)}, पुलब्याक जोन ${pullLbl}। २०-दिने EMA ${fmt(tech.ema20)}।`
      : `${dossier.symbol}: पर्याप्त डाटा नभएकाले ट्रेड योजना उपलब्ध छैन।`,
    dossier,
    meta: {
      modelUsed: 'QuantEngine-Deterministic',
      isAiOffline: true,
      timestamp: new Date().toISOString()
    }
  };
}

import { getCachedRealPriceHistory } from '../utils/historyCache.js';
import { getNepseBrokerCommissionRate } from '../utils/calculations.js';

const STORAGE_KEY = 'drabyashree_signals';

/**
 * Deduplicate raw signals array by symbol and date/status.
 * If multiple identical open signals exist for the same symbol, collapses them into one.
 */
export const deduplicateStoredSignals = (rawSignals = []) => {
  if (!Array.isArray(rawSignals)) return [];
  const seenOpenSymbols = new Set();
  const seenSignatures = new Set();
  const result = [];

  for (const s of rawSignals) {
    if (!s || !s.symbol) continue;
    const sym = String(s.symbol).toUpperCase().trim();
    const sigKey = `${sym}_${s.signalDate || ''}_${s.entryPrice || ''}_${s.status || ''}`;

    if (s.status === 'open') {
      if (seenOpenSymbols.has(sym)) {
        continue; // Keep only first open signal per symbol
      }
      seenOpenSymbols.add(sym);
    } else {
      if (seenSignatures.has(sigKey)) {
        continue; // Keep only one instance of duplicate closed signal
      }
      seenSignatures.add(sigKey);
    }

    result.push({
      ...s,
      symbol: sym
    });
  }

  return result;
};

const getStoredSignals = () => {
  try {
    if (typeof localStorage === 'undefined') return [];
    const data = localStorage.getItem(STORAGE_KEY);
    if (!data) return [];
    const parsed = JSON.parse(data);
    const deduplicated = deduplicateStoredSignals(parsed);
    if (deduplicated.length !== parsed.length) {
      saveSignals(deduplicated);
    }
    return deduplicated;
  } catch (e) {
    console.error('Error reading signals from local storage', e);
    return [];
  }
};

const saveSignals = (signals) => {
  try {
    if (typeof localStorage === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(signals));
  } catch (e) {
    console.error('Error saving signals to local storage', e);
  }
};

/**
 * Calculates statutory NEPSE tiered brokerage commission (0.36% down to 0.24%), SEBON fee (0.015%), DP fee (Rs 25), and 7.5% short-term / 5.0% long-term CGT.
 */
export const calculateNetReturn = (entryPrice, exitPrice, holdingDays = 1, tradeAmount = 50000) => {
  const entry = Number(entryPrice || 0);
  const exit = Number(exitPrice || 0);
  if (entry <= 0 || exit <= 0) {
    return { grossReturnPct: 0, netReturnPct: 0, totalFeesPct: 0, cgtPct: 0, cgtRatePct: 7.5 };
  }

  // Tiered brokerage per SEBON schedule (0.36% down to 0.24%)
  const buyBrokerageRate = getNepseBrokerCommissionRate(tradeAmount);
  const exitAmount = tradeAmount * (exit / entry);
  const sellBrokerageRate = getNepseBrokerCommissionRate(exitAmount);

  // SEBON regulatory fee: 0.015% per leg
  const sebonRate = 0.00015;
  // DP transaction charge: Rs 25 flat per leg (normalized against trade size)
  const dpBuyRate = Math.min(0.005, 25 / Math.max(tradeAmount, 1000));
  const dpSellRate = Math.min(0.005, 25 / Math.max(exitAmount, 1000));

  const buyFeeRate = buyBrokerageRate + sebonRate + dpBuyRate;
  const sellFeeRate = sellBrokerageRate + sebonRate + dpSellRate;

  const totalCost = entry * (1 + buyFeeRate);
  const grossProceeds = exit * (1 - sellFeeRate);

  const grossReturnPct = +(((exit - entry) / entry) * 100).toFixed(2);
  const rawPnl = grossProceeds - totalCost;

  // Individual Capital Gains Tax: 7.5% for holdings <= 365 days, 5.0% for > 365 days
  const isLongTerm = Number(holdingDays) > 365;
  const cgtRate = isLongTerm ? 0.050 : 0.075;
  const cgtAmount = rawPnl > 0 ? rawPnl * cgtRate : 0;

  const netPnl = rawPnl - cgtAmount;
  const netReturnPct = +((netPnl / totalCost) * 100).toFixed(2);
  const totalFeesPct = +(((totalCost - entry + (exit - grossProceeds)) / entry) * 100).toFixed(2);
  const cgtPct = +((cgtAmount / entry) * 100).toFixed(2);

  return {
    grossReturnPct,
    netReturnPct,
    totalFeesPct,
    cgtPct,
    cgtRatePct: cgtRate * 100
  };
};

export const recordSignal = (signalInput) => {
  if (!signalInput || !signalInput.symbol) return null;
  const symbol = String(signalInput.symbol).toUpperCase().trim();
  const today = new Date().toISOString().split('T')[0];

  const signals = getStoredSignals();

  // Deduplication check:
  // 1. If an 'open' signal already exists for this symbol, do NOT duplicate it.
  const existingOpenIndex = signals.findIndex(
    s => s.symbol === symbol && s.status === 'open'
  );

  if (existingOpenIndex !== -1) {
    const existing = signals[existingOpenIndex];
    // Update levels if new levels were calculated, but preserve signal date & initial entry
    let changed = false;
    if (signalInput.targetPrice && Number(signalInput.targetPrice) !== existing.targetPrice) {
      existing.targetPrice = Number(signalInput.targetPrice);
      changed = true;
    }
    const target2Val = signalInput.target2Price || signalInput.target2;
    if (target2Val && Number(target2Val) !== existing.target2Price) {
      existing.target2Price = Number(target2Val);
      changed = true;
    }
    if (signalInput.stopLoss && Number(signalInput.stopLoss) !== existing.stopLoss) {
      existing.stopLoss = Number(signalInput.stopLoss);
      changed = true;
    }
    if (signalInput.setupScore && signalInput.setupScore !== existing.setupScore) {
      existing.setupScore = signalInput.setupScore;
      changed = true;
    }
    if (signalInput.verdict && signalInput.verdict !== existing.verdict) {
      existing.verdict = signalInput.verdict;
      changed = true;
    }
    if (changed) {
      signals[existingOpenIndex] = existing;
      saveSignals(signals);
    }
    return existing;
  }

  // 2. If a signal for this symbol was already recorded today (even if closed), don't spam duplicate records
  const existingToday = signals.find(
    s => s.symbol === symbol && s.signalDate === today
  );
  if (existingToday) {
    return existingToday;
  }

  const entryPrice = Number(signalInput.entryPrice || 0);
  const target2Val = signalInput.target2Price || signalInput.target2;

  const newSignal = {
    id: `SIG-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
    signalDate: today,
    outcome: null,
    status: 'open',
    signalType: signalInput.signalType || 'BUY',
    highestSeen: entryPrice > 0 ? entryPrice : null,
    lowestSeen: entryPrice > 0 ? entryPrice : null,
    ...signalInput,
    symbol,
    entryPrice,
    targetPrice: signalInput.targetPrice ? Number(signalInput.targetPrice) : null,
    target2Price: target2Val ? Number(target2Val) : null,
    stopLoss: signalInput.stopLoss ? Number(signalInput.stopLoss) : null,
    rrr: signalInput.rrr != null ? Number(signalInput.rrr) : (signalInput.rrr1 != null ? Number(signalInput.rrr1) : null)
  };

  signals.push(newSignal);
  saveSignals(signals);
  return newSignal;
};

export const getSignals = (filters = {}) => {
  let signals = getStoredSignals();

  if (filters.symbol) {
    const sym = String(filters.symbol).toUpperCase().trim();
    signals = signals.filter(s => s.symbol === sym);
  }
  if (filters.source) {
    signals = signals.filter(s => s.source === filters.source);
  }
  if (filters.status) {
    signals = signals.filter(s => s.status === filters.status);
  }

  return signals;
};

export const deleteSignal = (signalId) => {
  if (!signalId) return false;
  const signals = getStoredSignals();
  const next = signals.filter(s => s.id !== signalId);
  if (next.length !== signals.length) {
    saveSignals(next);
    return true;
  }
  return false;
};

export const closeSignalManually = (signalId, exitPrice = null) => {
  if (!signalId) return null;
  const signals = getStoredSignals();
  const idx = signals.findIndex(s => s.id === signalId);
  if (idx === -1) return null;

  const sig = signals[idx];
  if (sig.status !== 'open') return sig;

  const resolvedExit = exitPrice != null ? Number(exitPrice) : (sig.highestSeen || sig.entryPrice);
  const entryDate = new Date(sig.signalDate);
  const exitDateObj = new Date();
  const holdingDays = Math.max(1, Math.floor((exitDateObj - entryDate) / (1000 * 60 * 60 * 24)));
  const entryPrice = sig.entryPrice || resolvedExit;
  const returnPct = +(((resolvedExit - entryPrice) / entryPrice) * 100).toFixed(2);
  const { netReturnPct, totalFeesPct, cgtPct } = calculateNetReturn(entryPrice, resolvedExit, holdingDays);

  const effectiveLow = sig.lowestSeen || Math.min(entryPrice, resolvedExit);
  const effectiveHigh = sig.highestSeen || Math.max(entryPrice, resolvedExit);

  sig.status = 'manual_close';
  sig.outcome = {
    exitDate: exitDateObj.toISOString().split('T')[0],
    exitPrice: resolvedExit,
    hitTarget: sig.targetPrice ? resolvedExit >= sig.targetPrice : false,
    hitStop: sig.stopLoss ? resolvedExit <= sig.stopLoss : false,
    returnPct,
    netReturnPct,
    totalFeesPct,
    cgtPct,
    holdingDays,
    maxDrawdownPct: effectiveLow ? +(((effectiveLow - entryPrice) / entryPrice) * 100).toFixed(2) : Math.min(0, returnPct),
    maxUpsidePct: effectiveHigh ? +(((effectiveHigh - entryPrice) / entryPrice) * 100).toFixed(2) : Math.max(0, returnPct)
  };

  signals[idx] = sig;
  saveSignals(signals);
  return sig;
};

export const updateSignalOutcome = (signalId, currentPrice, highSince, lowSince) => {
  const signals = getStoredSignals();
  const signalIndex = signals.findIndex(s => s.id === signalId);

  if (signalIndex === -1) return null;

  const signal = signals[signalIndex];
  if (signal.status !== 'open') return signal; // Already closed

  let newStatus = 'open';
  let exitPrice = null;
  let hitTarget = false;
  let hitStop = false;

  const effectiveHigh = highSince != null ? Number(highSince) : Number(currentPrice || 0);
  const effectiveLow = lowSince != null ? Number(lowSince) : Number(currentPrice || 0);

  if (signal.targetPrice && effectiveHigh >= signal.targetPrice) {
    newStatus = 'hit_target';
    exitPrice = signal.targetPrice;
    hitTarget = true;
  } else if (signal.stopLoss && effectiveLow <= signal.stopLoss) {
    newStatus = 'hit_stop';
    exitPrice = signal.stopLoss;
    hitStop = true;
  }

  if (newStatus !== 'open') {
    const entryDate = new Date(signal.signalDate);
    const exitDateObj = new Date();
    const holdingDays = Math.max(1, Math.floor((exitDateObj - entryDate) / (1000 * 60 * 60 * 24)));
    // Invariant: Under NEPSE T+2 settlement, shares cannot be exited prior to Demat delivery
    if (holdingDays < 2) return signal;
    const entryPrice = signal.entryPrice || currentPrice;
    const returnPct = +(((exitPrice - entryPrice) / entryPrice) * 100).toFixed(2);
    const { netReturnPct, totalFeesPct, cgtPct } = calculateNetReturn(entryPrice, exitPrice, holdingDays);

    const maxDrawdownPct = effectiveLow ? ((effectiveLow - entryPrice) / entryPrice) * 100 : Math.min(0, returnPct);
    const maxUpsidePct = effectiveHigh ? ((effectiveHigh - entryPrice) / entryPrice) * 100 : Math.max(0, returnPct);

    signal.status = newStatus;
    signal.outcome = {
      exitDate: exitDateObj.toISOString().split('T')[0],
      exitPrice,
      hitTarget,
      hitStop,
      returnPct: parseFloat(returnPct.toFixed(2)),
      netReturnPct,
      totalFeesPct,
      cgtPct,
      holdingDays,
      maxDrawdownPct: parseFloat(maxDrawdownPct.toFixed(2)),
      maxUpsidePct: parseFloat(maxUpsidePct.toFixed(2))
    };

    signals[signalIndex] = signal;
    saveSignals(signals);
  }

  return signal;
};

export const getSignalStats = (filters = {}) => {
  const signals = getSignals(filters);
  const total = signals.length;

  const openSignals = signals.filter(s => s.status === 'open');
  // Include expired and manual_close signals in closedSignals so there is zero survivorship bias!
  const closedSignals = signals.filter(
    s => ['hit_target', 'hit_stop', 'manual_close', 'expired'].includes(s.status) && s.outcome
  );

  const openCount = openSignals.length;
  const closedCount = closedSignals.length;

  let winCount = 0;
  let lossCount = 0;
  let totalReturnPct = 0;
  let totalNetReturnPct = 0;
  let totalHoldingDays = 0;
  let totalWinsPct = 0;
  let totalLossesPct = 0;

  let bestTrade = { symbol: '-', returnPct: -Infinity };
  let worstTrade = { symbol: '-', returnPct: Infinity };

  const bySource = {};

  // Initialize bySource for total stats
  signals.forEach(s => {
    const src = s.source || 'default';
    if (!bySource[src]) {
      bySource[src] = { total: 0, wins: 0, closed: 0 };
    }
    bySource[src].total += 1;
  });

  closedSignals.forEach(s => {
    const returnPct = s.outcome.returnPct;
    const netReturnPct = s.outcome.netReturnPct != null ? s.outcome.netReturnPct : returnPct;

    if (returnPct > 0) {
      winCount++;
      totalWinsPct += returnPct;
    } else {
      lossCount++;
      totalLossesPct += Math.abs(returnPct);
    }

    totalReturnPct += returnPct;
    totalNetReturnPct += netReturnPct;
    totalHoldingDays += (s.outcome.holdingDays || 1);

    if (returnPct > bestTrade.returnPct) {
      bestTrade = { symbol: s.symbol, returnPct, netReturnPct };
    }
    if (returnPct < worstTrade.returnPct) {
      worstTrade = { symbol: s.symbol, returnPct, netReturnPct };
    }

    const src = s.source || 'default';
    if (bySource[src]) {
      bySource[src].closed += 1;
      if (returnPct > 0) bySource[src].wins += 1;
    }
  });

  const winRate = closedCount > 0 ? (winCount / closedCount) * 100 : 0;
  const avgReturnPct = closedCount > 0 ? (totalReturnPct / closedCount) : 0;
  const avgNetReturnPct = closedCount > 0 ? (totalNetReturnPct / closedCount) : 0;
  const avgHoldingDays = closedCount > 0 ? (totalHoldingDays / closedCount) : 0;
  const profitFactor = totalLossesPct > 0
    ? +(totalWinsPct / totalLossesPct).toFixed(2)
    : (totalWinsPct > 0 ? 9.99 : 1.0);

  const avgWinPct = winCount > 0 ? +(totalWinsPct / winCount).toFixed(2) : 0;
  const avgLossPct = lossCount > 0 ? +(totalLossesPct / lossCount).toFixed(2) : 0;
  const expectancy = closedCount > 0
    ? +(((winRate / 100) * avgWinPct) - (((100 - winRate) / 100) * avgLossPct)).toFixed(2)
    : 0;

  Object.keys(bySource).forEach(source => {
    const sourceData = bySource[source];
    sourceData.winRate = sourceData.closed > 0 ? (sourceData.wins / sourceData.closed) * 100 : 0;
  });

  const expiredCount = signals.filter(s => s.status === 'expired').length;

  return {
    total,
    openCount,
    closedCount,
    winCount,
    lossCount,
    expiredCount,
    profitFactor,
    winRate: parseFloat(winRate.toFixed(2)),
    avgReturnPct: parseFloat(avgReturnPct.toFixed(2)),
    avgNetReturnPct: parseFloat(avgNetReturnPct.toFixed(2)),
    avgHoldingDays: parseFloat(avgHoldingDays.toFixed(1)),
    avgWinPct,
    avgLossPct,
    expectancy,
    bestTrade: bestTrade.returnPct !== -Infinity ? bestTrade : null,
    worstTrade: worstTrade.returnPct !== Infinity ? worstTrade : null,
    bySource,
    disclaimer: 'Based on quantitative signals generated by Drabyashree NEPSE. Real execution subject to broker fees, slippage, and SEBON market conditions.'
  };
};

export const expireOldSignals = (maxAgeDays = 60) => {
  const signals = getStoredSignals();
  const now = new Date();
  let changed = false;

  signals.forEach(s => {
    if (s.status === 'open') {
      const signalDate = new Date(s.signalDate);
      const ageDays = (now - signalDate) / (1000 * 60 * 60 * 24);
      if (ageDays > maxAgeDays) {
        s.status = 'expired';
        s.outcome = {
          exitDate: now.toISOString().split('T')[0],
          exitPrice: s.entryPrice,
          hitTarget: false,
          hitStop: false,
          returnPct: 0,
          netReturnPct: 0,
          totalFeesPct: 0,
          cgtPct: 0,
          holdingDays: Math.round(ageDays),
          maxDrawdownPct: 0,
          maxUpsidePct: 0
        };
        changed = true;
      }
    }
  });

  if (changed) saveSignals(signals);
};

/**
 * Automatically evaluates all open signals against current market prices and historical candles.
 * Tracks highest and lowest price seen over time while signal is open.
 * Replays past trading sessions if historical candles are cached to ensure zero missed exits.
 */
export const evaluateOpenSignals = (marketStocks, options = {}) => {
  if (!Array.isArray(marketStocks) || marketStocks.length === 0) return { updated: 0, closed: 0 };

  const signals = getStoredSignals();
  if (signals.length === 0) return { updated: 0, closed: 0 };

  const stockMap = new Map();
  for (const s of marketStocks) {
    if (s && s.symbol) stockMap.set(String(s.symbol).toUpperCase().trim(), s);
  }

  let updatedCount = 0;
  let closedCount = 0;
  const now = Date.now();
  const todayStr = new Date().toISOString().split('T')[0];

  for (let i = 0; i < signals.length; i++) {
    const sig = signals[i];
    if (sig.status !== 'open') continue;

    const sym = String(sig.symbol || '').toUpperCase().trim();
    const stock = stockMap.get(sym);
    if (!stock) continue;

    const currentPrice = Number(stock.ltp || stock.marketPrice || stock.close || 0);
    if (!currentPrice || currentPrice <= 0) continue;

    const todayHigh = stock.high != null && Number(stock.high) > 0 ? Number(stock.high) : currentPrice;
    const todayLow = stock.low != null && Number(stock.low) > 0 ? Number(stock.low) : currentPrice;

    // Multi-session historical candle walk-forward check
    const candleHistory = options.candleHistoryMap?.get?.(sym)
      || (typeof getCachedRealPriceHistory === 'function' ? getCachedRealPriceHistory(sym) : null);

    let resolvedFromHistory = false;

    if (Array.isArray(candleHistory) && candleHistory.length > 0 && sig.signalDate) {
      const relevantCandles = candleHistory
        .filter(c => c && c.date && c.date >= sig.signalDate)
        .sort((a, b) => (a.date > b.date ? 1 : -1));

      for (const c of relevantCandles) {
        const cHigh = Number(c.high || c.close || 0);
        const cLow = Number(c.low || c.close || 0);
        const cOpen = Number(c.open || c.close || 0);
        const cClose = Number(c.close || 0);
        if (cHigh <= 0 || cLow <= 0) continue;

        sig.highestSeen = Math.max(sig.highestSeen ?? sig.entryPrice ?? cHigh, cHigh);
        sig.lowestSeen = Math.min(sig.lowestSeen ?? sig.entryPrice ?? cLow, cLow);

        let cStatus = 'open';
        let cExit = null;
        let hitTarget = false;
        let hitStop = false;

        const targetHit = sig.targetPrice && cHigh >= sig.targetPrice;
        const stopHit = sig.stopLoss && cLow <= sig.stopLoss;

        if (targetHit && stopHit) {
          if (cOpen <= sig.stopLoss) {
            cStatus = 'hit_stop';
            cExit = sig.stopLoss;
            hitStop = true;
          } else if (cOpen >= sig.targetPrice) {
            cStatus = 'hit_target';
            cExit = sig.targetPrice;
            hitTarget = true;
          } else if (cClose < cOpen) {
            cStatus = 'hit_stop';
            cExit = sig.stopLoss;
            hitStop = true;
          } else {
            cStatus = 'hit_target';
            cExit = sig.targetPrice;
            hitTarget = true;
          }
        } else if (targetHit) {
          cStatus = 'hit_target';
          cExit = sig.targetPrice;
          hitTarget = true;
        } else if (stopHit) {
          cStatus = 'hit_stop';
          cExit = sig.stopLoss;
          hitStop = true;
        }

        if (cStatus !== 'open') {
          const entryDate = new Date(sig.signalDate);
          const exitDate = new Date(c.date);
          const holdingDays = Math.max(1, Math.round((exitDate - entryDate) / (1000 * 60 * 60 * 24)));
          const entryPrice = sig.entryPrice || currentPrice;
          const returnPct = +(((cExit - entryPrice) / entryPrice) * 100).toFixed(2);
          const { netReturnPct, totalFeesPct, cgtPct } = calculateNetReturn(entryPrice, cExit, holdingDays);

          sig.status = cStatus;
          sig.outcome = {
            exitDate: c.date,
            exitPrice: cExit,
            hitTarget,
            hitStop,
            returnPct,
            netReturnPct,
            totalFeesPct,
            cgtPct,
            holdingDays,
            maxDrawdownPct: sig.lowestSeen ? +(((sig.lowestSeen - entryPrice) / entryPrice) * 100).toFixed(2) : Math.min(0, returnPct),
            maxUpsidePct: sig.highestSeen ? +(((sig.highestSeen - entryPrice) / entryPrice) * 100).toFixed(2) : Math.max(0, returnPct)
          };
          closedCount++;
          updatedCount++;
          resolvedFromHistory = true;
          break;
        }
      }
    }

    if (resolvedFromHistory) continue;

    // Track running peak and trough across sessions with live quote
    sig.highestSeen = Math.max(sig.highestSeen ?? sig.entryPrice ?? currentPrice, todayHigh);
    sig.lowestSeen = Math.min(sig.lowestSeen ?? sig.entryPrice ?? currentPrice, todayLow);

    const highSince = sig.highestSeen;
    const lowSince = sig.lowestSeen;

    // Check expiration (> 60 days)
    const sigTime = new Date(sig.signalDate).getTime();
    const ageDays = (now - sigTime) / (1000 * 60 * 60 * 24);

    let newStatus = 'open';
    let exitPrice = null;
    let hitTarget = false;
    let hitStop = false;

    if (sig.targetPrice && highSince >= sig.targetPrice) {
      newStatus = 'hit_target';
      exitPrice = sig.targetPrice;
      hitTarget = true;
    } else if (sig.stopLoss && lowSince <= sig.stopLoss) {
      newStatus = 'hit_stop';
      exitPrice = sig.stopLoss;
      hitStop = true;
    } else if (ageDays > 60) {
      newStatus = 'expired';
      exitPrice = currentPrice;
    }

    if (newStatus !== 'open') {
      const holdingDays = Math.max(1, Math.round(ageDays));
      const entryPrice = sig.entryPrice || currentPrice;
      const returnPct = +(((exitPrice - entryPrice) / entryPrice) * 100).toFixed(2);
      const { netReturnPct, totalFeesPct, cgtPct } = calculateNetReturn(entryPrice, exitPrice, holdingDays);
      const maxDrawdownPct = lowSince ? +(((lowSince - entryPrice) / entryPrice) * 100).toFixed(2) : Math.min(0, returnPct);
      const maxUpsidePct = highSince ? +(((highSince - entryPrice) / entryPrice) * 100).toFixed(2) : Math.max(0, returnPct);

      sig.status = newStatus;
      sig.outcome = {
        exitDate: todayStr,
        exitPrice,
        hitTarget,
        hitStop,
        returnPct,
        netReturnPct,
        totalFeesPct,
        cgtPct,
        holdingDays,
        maxDrawdownPct,
        maxUpsidePct
      };
      closedCount++;
      updatedCount++;
    } else {
      // Still open, but highestSeen / lowestSeen may have updated
      updatedCount++;
    }
  }

  if (updatedCount > 0) {
    saveSignals(signals);
  }

  return { updated: updatedCount, closed: closedCount };
};

export const clearSignals = () => {
  try {
    if (typeof localStorage === 'undefined') return;
    localStorage.removeItem(STORAGE_KEY);
  } catch (e) {
    console.error('Error clearing signals from local storage', e);
  }
};

import { fetchLiveStockDetail } from '../utils/liveData.js';
import { NEPSE_UNIVERSE } from '../data/nepseUniverse.js';
import { classifyLiquidity } from '../utils/priceAdjustment.js';

// In-memory Map cache
const snapshotCache = new Map();
const CACHE_TTL_MS = 30 * 1000;

export function getSnapshotCache(symbol) {
  if (!symbol) return null;
  const key = symbol.toUpperCase();
  const cached = snapshotCache.get(key);
  if (cached && (Date.now() - cached.timestamp < CACHE_TTL_MS)) {
    return cached.data;
  }
  return null;
}

export function clearSnapshotCache(symbol = null) {
  if (symbol) {
    snapshotCache.delete(symbol.toUpperCase());
  } else {
    snapshotCache.clear();
  }
}

export async function fetchStockSnapshot(symbol) {
  const sym = String(symbol || '').toUpperCase().trim();
  if (!sym) throw new Error('Symbol is required');

  const cached = getSnapshotCache(sym);
  if (cached) return cached;

  const snapshot = {
    symbol: sym,
    companyName: null,
    sector: null,
    ltp: null, pChange: null, change: null, open: null, high: null, low: null, prevClose: null, volume: null, turnover: null,
    trades: null, totalTransactions: null,
    high52w: null, low52w: null,
    eps: null, pe: null, pb: null, bookValue: null, roe: null, dividendYield: null,
    listedShares: null, paidUpCapital: null, promoterPercentage: null, publicPercentage: null,
    marketCap: null,
    floatMarketCap: null,
    rvol: null, avgVolume20D: null, liquidityClass: null, liquidityLabel: null, isIlliquid: null, liquidityWarning: null,
    bonusShare: null, cashDiv: null,
    dataTimestamp: new Date().toISOString(),
    dataSource: 'nepse-api'
  };

  try {
    const staticData = NEPSE_UNIVERSE.find(s => s.symbol === sym) || {};
    snapshot.companyName = staticData.name || null;
    snapshot.sector = staticData.sector || null;
    snapshot.listedShares = (staticData.sharesOut * 1000000) || null;

    let liveDetail = null;
    try {
      if (typeof fetchLiveStockDetail === 'function') {
        liveDetail = await fetchLiveStockDetail(sym);
      }
    } catch (e) {
      console.warn("fetchLiveStockDetail error", e);
      snapshot.dataSource = 'partial';
    }

    if (liveDetail) {
      snapshot.companyName = liveDetail.companyName || liveDetail.securityName || snapshot.companyName;
      snapshot.sector = liveDetail.sector || snapshot.sector;

      snapshot.ltp = liveDetail.lastTradedPrice ?? liveDetail.ltp ?? liveDetail.marketPrice ?? liveDetail.closePrice ?? null;
      snapshot.pChange = liveDetail.percentageChange ?? liveDetail.pChange ?? null;
      snapshot.change = liveDetail.change ?? null;
      snapshot.open = liveDetail.openPrice ?? liveDetail.open ?? null;

      const rawH = liveDetail.highPrice ?? liveDetail.high ?? null;
      const rawL = liveDetail.lowPrice ?? liveDetail.low ?? null;
      if (rawH != null && rawL != null && Number(rawH) > 0 && Number(rawL) > 0) {
        snapshot.high = Math.max(Number(rawH), Number(rawL));
        snapshot.low = Math.min(Number(rawH), Number(rawL));
      } else {
        snapshot.high = rawH;
        snapshot.low = rawL;
      }

      snapshot.prevClose = liveDetail.previousClose ?? liveDetail.prevClose ?? null;
      snapshot.volume = liveDetail.totalTradeQuantity ?? liveDetail.volume ?? null;
      snapshot.turnover = liveDetail.totalTradeValue ?? liveDetail.turnover ?? null;
      snapshot.trades = liveDetail.totalTransactions ?? liveDetail.trades ?? liveDetail.transactions ?? null;
      snapshot.totalTransactions = snapshot.trades;

      snapshot.high52w = liveDetail.fiftyTwoWeekHigh ?? liveDetail.high52w ?? null;
      snapshot.low52w = liveDetail.fiftyTwoWeekLow ?? liveDetail.low52w ?? null;

      // Do not overwrite with 0 placeholders: EPS can be negative (loss-maker) or positive, but 0 is a scrape failure sentinel
      if (liveDetail.eps !== undefined && liveDetail.eps !== null && Number(liveDetail.eps) !== 0) {
        snapshot.eps = Number(liveDetail.eps);
      }
      if (liveDetail.pe && Number(liveDetail.pe) > 0) {
        snapshot.pe = Number(liveDetail.pe);
      }
      if ((liveDetail.pb || liveDetail.pbv) && Number(liveDetail.pb || liveDetail.pbv) > 0) {
        snapshot.pb = Number(liveDetail.pb || liveDetail.pbv);
      }
      if (liveDetail.bookValue && Number(liveDetail.bookValue) > 0) {
        snapshot.bookValue = Number(liveDetail.bookValue);
      }
      if (liveDetail.roe && Number(liveDetail.roe) !== 0) {
        snapshot.roe = Number(liveDetail.roe);
      }
      snapshot.dividendYield = liveDetail.dividendYield ?? null;

      snapshot.listedShares = liveDetail.listedShares ?? liveDetail.sharesOutstanding ?? snapshot.listedShares;
      snapshot.paidUpCapital = liveDetail.paidUpCapital ?? null;
      snapshot.promoterPercentage = liveDetail.promoterPercentage ?? liveDetail.promoterHolding ?? null;
      snapshot.publicPercentage = liveDetail.publicPercentage ?? (liveDetail.promoterPercentage ? 100 - liveDetail.promoterPercentage : null);

      snapshot.rvol = liveDetail.rvol ?? null;
      snapshot.avgVolume20D = liveDetail.avgVolume20D ?? null;

      snapshot.bonusShare = liveDetail.bonusShare ?? null;
      snapshot.cashDiv = liveDetail.cashDividend ?? liveDetail.cashDiv ?? null;
      snapshot.fiscalYear = liveDetail.fiscalYear ?? null;
      snapshot.quarter = liveDetail.quarter ?? null;
    }

    if (snapshot.listedShares && snapshot.ltp) {
        snapshot.marketCap = snapshot.listedShares * snapshot.ltp;
        if (snapshot.publicPercentage) {
            snapshot.floatMarketCap = snapshot.marketCap * (snapshot.publicPercentage / 100);
        }
    }

    const liquidityInfo = classifyLiquidity({ turnover: snapshot.turnover, volume: snapshot.volume });
    snapshot.liquidityClass = liquidityInfo.class || null;
    snapshot.liquidityLabel = liquidityInfo.label || null;
    snapshot.isIlliquid = liquidityInfo.isIlliquid ?? null;
    snapshot.liquidityWarning = liquidityInfo.warning || null;

    snapshotCache.set(sym, { timestamp: Date.now(), data: snapshot });

    return snapshot;
  } catch (error) {
    snapshot.dataSource = 'partial';
    return snapshot;
  }
}

export function enrichStockFromSnapshot(snapshot, liveDetail) {
    if (!snapshot) return liveDetail;
    return {
        ...snapshot,
        ...liveDetail,
        marketCap: snapshot.marketCap ?? liveDetail.marketCap,
        floatMarketCap: snapshot.floatMarketCap ?? liveDetail.floatMarketCap,
    };
}

// src/services/whaleDailyArchive.js
/**
 * Daily Top 5 Whale Archive & Consecutive Alert Tracker
 * ─────────────────────────────────────────────────────────────────────────────
 * Automatically records, timestamps, and preserves daily Top 5 Slow Unusual
 * Accumulation and Top 5 Unusual Distribution stocks across NEPSE trading sessions.
 *
 * Provides:
 * 1. Persistent multi-day storage in localStorage ('drabyashree_whale_daily_archive')
 * 2. Multi-session consecutive accumulation counters (Day 1, Day 2 Prime Entry, Pause Day)
 * 3. Pre-dump exit countdowns (Day 1 Distribution: 2-3 Day Exit Window)
 * 4. Outcome & return tracking (LTP at signal vs current LTP)
 */

import { calculateBrokerConcentration, calculateQuietAccumulationIndex, estimateTradablePublicFloat } from '../utils/accumulationDistributionEngine.ts';
import { NEPSE_UNIVERSE } from '../data/nepseUniverse.js';

const STORAGE_KEY = 'drabyashree_whale_daily_archive';
const MAX_ARCHIVE_DAYS = 30; // Keep up to 30 trading sessions

// Module-level cumulative trade vault across multi-scan session queries (prevents morning trade eviction)
// Maps: marketDate (YYYY-MM-DD) -> Map<tradeKey, tradeObject>
const SESSION_FLOORSHEET_REGISTRY = new Map();

// Fast static lookup map for sharesOut and sector
const UNIVERSE_MAP = new Map();
if (Array.isArray(NEPSE_UNIVERSE)) {
  NEPSE_UNIVERSE.forEach(u => {
    if (u?.symbol) UNIVERSE_MAP.set(String(u.symbol).toUpperCase().trim(), u);
  });
}

export const SEED_WHALE_ARCHIVE = [];

export function getStoredWhaleArchive() {
  if (typeof globalThis === 'undefined' || typeof globalThis.localStorage === 'undefined') {
    return [];
  }
  try {
    const raw = globalThis.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(entry => entry && !entry.isMock && !entry.isSeed);
  } catch (e) {
    console.error('[WhaleArchive] Failed to parse stored archive:', e);
    return [];
  }
}

export function initWhaleArchiveWithSeeds() {
  return getStoredWhaleArchive();
}

export function saveStoredWhaleArchive(archive) {
  if (typeof globalThis === 'undefined' || typeof globalThis.localStorage === 'undefined') {
    return;
  }
  try {
    const trimmed = (archive || []).slice(0, MAX_ARCHIVE_DAYS);
    globalThis.localStorage.setItem(STORAGE_KEY, JSON.stringify(trimmed));
  } catch (e) {
    console.error('[WhaleArchive] Failed to save archive:', e);
  }
}

/**
 * Exports current whale archive as formatted JSON string for mobile/cloud backup.
 */
export function exportWhaleArchiveJSON() {
  const archive = getStoredWhaleArchive();
  return JSON.stringify(archive, null, 2);
}

/**
 * Imports and validates an external whale archive JSON backup.
 */
export function importWhaleArchiveJSON(jsonString) {
  try {
    if (!jsonString || typeof jsonString !== 'string') {
      return { success: false, error: 'Empty or invalid JSON data.' };
    }
    const parsed = JSON.parse(jsonString);
    if (!Array.isArray(parsed)) {
      return { success: false, error: 'Archive data must be an array of daily snapshots.' };
    }
    const valid = parsed.filter(s => s && s.date && Array.isArray(s.topAccumulation) && Array.isArray(s.topDistribution));
    if (valid.length === 0) {
      return { success: false, error: 'No valid daily snapshots found in backup.' };
    }
    saveStoredWhaleArchive(valid);
    return { success: true, count: valid.length };
  } catch (err) {
    return { success: false, error: err?.message || 'JSON parse error.' };
  }
}

/**
 * Builds or updates the Daily Whale Snapshot from live market stocks and floorsheet trades.
 */
export function captureDailyWhaleSnapshot(stocks = [], floorsheet = [], customDate = null) {
  if (!Array.isArray(stocks) || stocks.length === 0) {
    return null;
  }

  // Determine market business date from floorsheet or fallback to today's date
  let marketDate = customDate;
  if (!marketDate && Array.isArray(floorsheet) && floorsheet.length > 0) {
    const firstWithDate = floorsheet.find(t => t.businessDate || t.date || t.tradeDate);
    if (firstWithDate) {
      marketDate = String(firstWithDate.businessDate || firstWithDate.date || firstWithDate.tradeDate).split('T')[0];
    }
  }
  if (!marketDate) {
    marketDate = new Date().toISOString().split('T')[0];
  }

  const existingArchive = getStoredWhaleArchive();
  const previousSnapshot = existingArchive.find(s => s.date !== marketDate);

  // Merge incoming floorsheet into cumulative session registry to prevent morning trade eviction (Loophole 1 Fix)
  if (!SESSION_FLOORSHEET_REGISTRY.has(marketDate)) {
    SESSION_FLOORSHEET_REGISTRY.set(marketDate, new Map());
  }
  const sessionTradesMap = SESSION_FLOORSHEET_REGISTRY.get(marketDate);
  if (Array.isArray(floorsheet) && floorsheet.length > 0) {
    floorsheet.forEach((t, idx) => {
      const sym = String(t.stockSymbol || t.symbol || '').toUpperCase().trim();
      if (!sym) return;
      const bBroker = String(t.buyerMemberId || t.buyerBroker || t.buyer || '').replace(/^0+/, '').trim();
      const sBroker = String(t.sellerMemberId || t.sellerBroker || t.seller || '').replace(/^0+/, '').trim();
      const qty = Number(t.contractQuantity || t.quantity || t.qty || 0);
      const rate = Number(t.contractRate || t.rate || t.price || 0);
      const key = t.contractId ? String(t.contractId) : `${sym}_${bBroker}_${sBroker}_${qty}_${rate}_${t.tradeTime || idx}`;
      sessionTradesMap.set(key, t);
    });
  }

  // Group all cumulative session trades by symbol (guarantees morning trades are never evicted!)
  const fsMap = new Map();
  sessionTradesMap.forEach(t => {
    const sym = String(t.stockSymbol || t.symbol || '').toUpperCase().trim();
    if (!sym) return;
    if (!fsMap.has(sym)) fsMap.set(sym, []);
    fsMap.get(sym).push(t);
  });

  // Find existing snapshot today to preserve morning peak metrics and entry prices
  const existingToday = existingArchive.find(s => s.date === marketDate);

  // Analyze all liquid stocks
  const evaluated = [];
  for (const s of stocks) {
    const sym = String(s.symbol || '').toUpperCase().trim();
    if (!sym || !s.ltp) continue;
    // Skip mutual funds and debentures for whale equity tracking
    const rawSecLower = String(s.sector || '').toLowerCase();
    if (sym.includes('D8') || sym.includes('D9') || sym.endsWith('MF') || sym.endsWith('BS') || sym.endsWith('SF') || sym.endsWith('EF') || sym.endsWith('GF') || sym.endsWith('FF') || rawSecLower.includes('mutual')) continue;

    const trades = fsMap.get(sym) || [];
    const conc = calculateBrokerConcentration(trades, sym, s);

    // 1. Single Top Buyer Net Absorption & 2. Aggregate Top 3 Syndicate Net Absorption Guard
    const topBuyer = conc.topBuyerBrokers?.[0];
    let netAbsorptionRatio = 1.0;
    if (topBuyer && topBuyer.volume > 0) {
      const buyerNetQty = Number(topBuyer.netQty !== undefined ? topBuyer.netQty : (conc.topNetAccumulators?.[0]?.netQty ?? topBuyer.volume));
      netAbsorptionRatio = Number((Math.max(0, buyerNetQty) / topBuyer.volume).toFixed(2));
    }

    const top3Buyers = (conc.topBuyerBrokers || []).slice(0, 3);
    const top3GrossBuy = top3Buyers.reduce((acc, b) => acc + (b.volume || 0), 0);
    const top3NetBuy = top3Buyers.reduce((acc, b) => {
      const net = b.netQty !== undefined ? b.netQty : b.volume;
      return acc + Math.max(0, net);
    }, 0);
    const top3NetAbsorptionRatio = top3GrossBuy > 0 ? Number((top3NetBuy / top3GrossBuy).toFixed(2)) : 1.0;

    // Churn detected when:
    // A) Single top broker has high gross volume but low net absorption (< 35%)
    // B) Top 3 syndicate desks have substantial gross volume (>= 1,500) but low collective net absorption (< 40%)
    const isSingleDeskChurn = Boolean(topBuyer && topBuyer.volume >= 500 && netAbsorptionRatio < 0.35);
    const isSyndicateChurn = Boolean(top3GrossBuy >= 1500 && top3NetAbsorptionRatio < 0.40);
    const isWashChurn = isSingleDeskChurn || isSyndicateChurn;

    // 3. Execution Dispersion & Block Trade Anomaly Check
    let maxSingleTradeQty = 0;
    let totalFloorsheetQty = 0;
    trades.forEach(t => {
      const q = Number(t.contractQuantity || t.quantity || t.qty || 0);
      totalFloorsheetQty += q;
      if (q > maxSingleTradeQty) maxSingleTradeQty = q;
    });
    const singleTradeConcentrationPct = totalFloorsheetQty > 0 ? Number(((maxSingleTradeQty / totalFloorsheetQty) * 100).toFixed(1)) : 0;
    // Anomaly: 1-2 huge lump transactions dominating the entire volume (e.g. negotiated promoter block deal)
    const isBlockTradeAnomaly = Boolean(
      (maxSingleTradeQty >= 50000 && trades.length <= 2) ||
      (totalFloorsheetQty >= 25000 && singleTradeConcentrationPct >= 80.0 && trades.length >= 2) ||
      (s.isBlockTrade === true)
    );

    // Upper circuit (+15%) ceiling proximity guard (SEBON Fourth Amendment 15% rule)
    const prevClose = Number(s.previousClose || s.prevClose || (s.ltp ? s.ltp / (1 + (s.pChange || 0) / 100) : 0));
    const upperCeiling = prevClose > 0 ? +(prevClose * 1.15).toFixed(1) : 0;
    const isNearUpperCircuit = upperCeiling > 0 && s.ltp >= upperCeiling * 0.985; // within 1.5% of +15% limit

    // 4. Intraday High/Low/Open/Close Range and Upper Shadow Rejection Check
    const highPrice = Number(s.high || s.highPrice || s.maxPrice || s.ltp || 0);
    const lowPrice = Number(s.low || s.lowPrice || s.minPrice || s.ltp || 0);
    const openPrice = Number(s.open || s.openPrice || prevClose || s.ltp || 0);
    const ltpPrice = Number(s.ltp || 0);

    const intradayRange = highPrice - lowPrice;
    const intradayRangePct = lowPrice > 0 ? Number(((intradayRange / lowPrice) * 100).toFixed(2)) : 0;
    const upperShadow = highPrice > 0 ? Math.max(0, highPrice - Math.max(openPrice, ltpPrice)) : 0;
    const upperShadowPct = intradayRange > 0 ? Number(((upperShadow / intradayRange) * 100).toFixed(1)) : 0;

    // Severe supply rejection: Intraday range was wide (>= 2.5%) and upper shadow >= 55%
    // (Stock pumped intraday, met heavy seller dump, and fell back near session lows)
    const isUpperShadowDump = Boolean(intradayRangePct >= 2.5 && upperShadowPct >= 55.0);

    // ── Float Normalization & Dynamic Sector Turnover Calibration (Loophole 3 Fix) ──
    const uInfo = UNIVERSE_MAP.get(sym) || {};
    const listedShares = Number(s.listedShares || s.totalListedShares || (uInfo.sharesOut ? uInfo.sharesOut * 1000000 : 0)) || 10000000;
    const sector = s.sector || uInfo.sector || 'Equities';
    const secLower = sector.toLowerCase();

    let publicFloatFraction = 0.35;
    if (secLower.includes('commercial')) publicFloatFraction = 0.40;
    else if (secLower.includes('development') || secLower.includes('finance')) publicFloatFraction = 0.40;
    else if (secLower.includes('hydro')) publicFloatFraction = 0.35;
    else if (secLower.includes('microfinance')) publicFloatFraction = 0.35;
    else if (secLower.includes('insurance')) publicFloatFraction = 0.30;
    else if (secLower.includes('manufacturing')) publicFloatFraction = 0.25;
    else if (secLower.includes('hotel')) publicFloatFraction = 0.30;

    const estFloatShares = Math.max(500000, Math.round(listedShares * publicFloatFraction));
    const floatTurnoverPct = estFloatShares > 0 ? Number(((Number(s.volume || 0) / estFloatShares) * 100).toFixed(3)) : 0;

    // Dynamic sector-calibrated turnover floor (Rs.)
    let dynamicTurnoverFloor = 3000000; // Rs. 30 Lakh default
    if (secLower.includes('commercial bank') || secLower.includes('commercial')) {
      dynamicTurnoverFloor = 15000000; // Rs. 1.5 Crore minimum for commercial bank giants
    } else if (secLower.includes('development bank') || secLower.includes('insurance')) {
      dynamicTurnoverFloor = 6000000;  // Rs. 60 Lakhs
    } else if (secLower.includes('hydro') || secLower.includes('microfinance')) {
      dynamicTurnoverFloor = 2500000;  // Rs. 25 Lakhs
    }
    // For micro-caps (< 20 Lakh float shares, e.g. ANLB, small hydros):
    if (estFloatShares < 2000000) {
      dynamicTurnoverFloor = Math.min(dynamicTurnoverFloor, 1500000); // Rs. 15 Lakhs for micro-caps
    }

    // Preserve morning peak concentration if logged earlier today
    const todayPrevAcc = existingToday?.topAccumulation?.find(p => p.symbol === sym);
    const bcr3Buy = Math.max(conc.bcr3BuyPct || 0, todayPrevAcc?.bcr3Buy || 0);
    const tradesCount = Math.max(trades.length, todayPrevAcc?.tradesCount || 0);

    const qaiResult = calculateQuietAccumulationIndex(
      { ...s, floatTurnoverPct, estFloatShares, pChange: s.pChange, ltp: s.ltp, volume: s.volume },
      conc
    );

    evaluated.push({
      symbol: sym,
      companyName: s.companyName || s.name || sym,
      sector,
      ltp: Number(s.ltp || 0),
      prevClose,
      pChange: Number(s.pChange || 0),
      turnover: Number(s.turnover || 0),
      volume: Number(s.volume || 0),
      estFloatShares,
      floatTurnoverPct,
      dynamicTurnoverFloor,
      tradesCount,
      bcr3Buy,
      bcr5Buy: conc.bcr5BuyPct || 0,
      bcr3Sell: conc.bcr3SellPct || 0,
      topBuyers: conc.topBuyerBrokers?.slice(0, 3).map(b => `#${b.broker} (${b.pct.toFixed(1)}%)`).join(', ') || 'Floor pending',
      topSellers: conc.topSellerBrokers?.slice(0, 3).map(b => `#${b.broker} (${b.pct.toFixed(1)}%)`).join(', ') || 'Floor pending',
      topNetAccumulators: conc.topNetAccumulators?.slice(0, 2).map(b => `#${b.broker} (+${b.netQty.toLocaleString()} sh)`).join(', ') || '',
      topNetDistributors: conc.topNetDistributors?.slice(0, 2).map(b => `#${b.broker} (${b.netQty.toLocaleString()} sh)`).join(', ') || '',
      smartMoneyBias: conc.smartMoneyBias || 'Neutral',
      tradeSizeRatio: conc.tradeSizeRatio || 1.0,
      netAbsorptionRatio,
      top3NetAbsorptionRatio,
      isWashChurn,
      isBlockTradeAnomaly,
      singleTradeConcentrationPct,
      isNearUpperCircuit,
      isUpperShadowDump,
      upperShadowPct,
      intradayRangePct,
      avgTicketSize: Number(s.transactions || s.totalTrades || 0) > 0 ? Math.round(Number(s.turnover || 0) / Number(s.transactions || s.totalTrades || 1)) : 0,
      volumeSurgeRatio: Number(s.volumeSurgeRatio || s.rvol || 1.0),
      stealthScore: Number(s.wyckoff?.stealthScore ?? s.stealthScore ?? s.stealthAccumulation ?? 50),
      dumpRiskScore: Number(s.wyckoff?.pumpDumpRiskScore ?? s.dumpRiskScore ?? s.pumpDumpRiskScore ?? 40),
      wyckoffStage: String(s.wyckoff?.stage || s.stage || ''),
      qaiScore: qaiResult.qaiScore,
      isDay1StealthCandidate: qaiResult.isDay1StealthCandidate,
      asymmetryRatio: qaiResult.asymmetryRatio,
      qaiResult
    });
  }

  // Check trading session continuity across weekends (e.g. Fri -> Mon is 3 calendar days)
  let isPreviousSessionContinuous = true;
  if (previousSnapshot && previousSnapshot.date) {
    const diffMs = Math.abs(new Date(marketDate).getTime() - new Date(previousSnapshot.date).getTime());
    const diffDays = diffMs / (1000 * 60 * 60 * 24);
    if (diffDays > 7) {
      isPreviousSessionContinuous = false;
    }
  }

  // A floorsheet is only considered active with broker tracking if trades contain identifiable broker numbers
  let hasBrokerDetails = false;
  for (const t of sessionTradesMap.values()) {
    const b = String(t.buyerMemberId || t.buyerBroker || t.buyer || '').trim();
    const sel = String(t.sellerMemberId || t.sellerBroker || t.seller || '').trim();
    if (b || sel) {
      hasBrokerDetails = true;
      break;
    }
  }
  const isFloorsheetActive = hasBrokerDetails;

  // 1. FILTER TOP 5 SLOW UNUSUAL ACCUMULATION
  // Criteria:
  // - Tight price action: -2.0% to +3.0% (stealth accumulation before markup)
  // - Wyckoff stealth stage OR high stealth score OR verified broker concentration (BCR3 >= 36%)
  // - Institutional turnover or significant float turnover
  // - Shielded against: +15% upper circuit traps, wash churn, block trade anomalies, and upper shadow dumps
  const accPool = evaluated
    .filter(s => {
      const tightPrice = s.pChange >= -2.0 && s.pChange <= 3.0;

      let hasWhaleConcentration = false;
      let isInstitutionalTurnover = false;

      const isWyckoffStealth = s.wyckoffStage.includes('STEALTH');

      if (isFloorsheetActive) {
        hasWhaleConcentration = isWyckoffStealth || s.bcr3Buy >= 36 || (s.bcr3Buy >= 32 && s.floatTurnoverPct >= 0.60);
        isInstitutionalTurnover = s.turnover >= s.dynamicTurnoverFloor || s.floatTurnoverPct >= 0.30;
      } else {
        hasWhaleConcentration = isWyckoffStealth || s.stealthScore >= 55 || (s.floatTurnoverPct >= 0.35 && tightPrice) || (s.volumeSurgeRatio >= 1.25 && s.floatTurnoverPct >= 0.15) || (s.avgTicketSize >= 35000 && s.turnover >= 1000000);
        isInstitutionalTurnover = s.turnover >= Math.min(s.dynamicTurnoverFloor, 800000) || s.floatTurnoverPct >= 0.15;
      }

      const highInterest = hasWhaleConcentration && isInstitutionalTurnover;
      const notCircuitTrap = !s.isNearUpperCircuit;
      const notWashChurn = !s.isWashChurn;
      const notBlockAnomaly = !s.isBlockTradeAnomaly;
      const notIntradayDump = !s.isUpperShadowDump;

      return tightPrice && highInterest && notCircuitTrap && notWashChurn && notBlockAnomaly && notIntradayDump;
    })
    .sort((a, b) => {
      // Prioritize Day 1 Stealth Candidate
      const aD1 = a.isDay1StealthCandidate ? 1 : 0;
      const bD1 = b.isDay1StealthCandidate ? 1 : 0;
      if (bD1 !== aD1) return bD1 - aD1;

      // Prioritize Wyckoff Stealth stage first
      const aStealth = a.wyckoffStage.includes('STEALTH') ? 1 : 0;
      const bStealth = b.wyckoffStage.includes('STEALTH') ? 1 : 0;
      if (bStealth !== aStealth) return bStealth - aStealth;

      if (isFloorsheetActive) {
        if (b.bcr3Buy >= 40 && a.bcr3Buy < 40) return 1;
        if (a.bcr3Buy >= 40 && b.bcr3Buy < 40) return -1;
        if (b.bcr3Buy !== a.bcr3Buy && (b.bcr3Buy > 0 || a.bcr3Buy > 0)) return b.bcr3Buy - a.bcr3Buy;
      }

      if (b.qaiScore !== a.qaiScore) return b.qaiScore - a.qaiScore;
      if (b.stealthScore !== a.stealthScore) return b.stealthScore - a.stealthScore;
      if (b.floatTurnoverPct !== a.floatTurnoverPct) return b.floatTurnoverPct - a.floatTurnoverPct;
      return b.turnover - a.turnover;
    });

  // Safety net: in production environments with full universe (> 20 stocks), ensure Top 5 Accumulation is populated
  if (evaluated.length >= 20 && accPool.length < 5) {
    const backupCandidates = evaluated
      .filter(s =>
        !accPool.some(p => p.symbol === s.symbol) &&
        !s.isWashChurn &&
        !s.isBlockTradeAnomaly &&
        !s.isNearUpperCircuit &&
        !s.isUpperShadowDump &&
        s.pChange >= -2.0 && s.pChange <= 3.0 &&
        (s.wyckoffStage.includes('STEALTH') || s.isDay1StealthCandidate || s.qaiScore >= 60 || s.stealthScore >= 55 || s.floatTurnoverPct >= 0.25) &&
        (s.turnover >= s.dynamicTurnoverFloor || s.floatTurnoverPct >= 0.20)
      )
      .sort((a, b) => {
        if (b.qaiScore !== a.qaiScore) return b.qaiScore - a.qaiScore;
        if (b.stealthScore !== a.stealthScore) return b.stealthScore - a.stealthScore;
        if (b.floatTurnoverPct !== a.floatTurnoverPct) return b.floatTurnoverPct - a.floatTurnoverPct;
        return b.turnover - a.turnover;
      });
    accPool.push(...backupCandidates.slice(0, 5 - accPool.length));
  }

  const topAccumulation = accPool.slice(0, 5).map(stock => {
    // Check if appeared in previous session (with weekend continuity)
    const prevEntry = isPreviousSessionContinuous ? previousSnapshot?.topAccumulation?.find(p => p.symbol === stock.symbol) : null;
    let consecutiveDays = 1;
    let signalBadge = '🟢 Day 1 Early Detection';
    let alertType = 'DAY_1';

    if (prevEntry) {
      consecutiveDays = (prevEntry.consecutiveDays || 1) + 1;
      if (consecutiveDays === 2) {
        signalBadge = '🔥 Day 2 Multi-Session Absorption (Prime Entry)';
        alertType = 'DAY_2_PRIME';
      } else if (consecutiveDays >= 3) {
        signalBadge = `🚀 Day ${consecutiveDays} Cornering (Ready for Markup)`;
        alertType = 'MULTI_DAY_CORNER';
      }
    } else if (previousSnapshot && isPreviousSessionContinuous) {
      // Check if it appeared in recent sessions and today is a Wyckoff volume dry-up pause
      const olderSnapshots = existingArchive.slice(1, 4);
      let priorEntry = null;
      for (const snap of olderSnapshots) {
        const found = snap.topAccumulation?.find(p => p.symbol === stock.symbol);
        if (found) {
          priorEntry = found;
          break;
        }
      }
      if (priorEntry && (stock.volume <= (priorEntry.volume * 0.75) || priorEntry.volume === 0)) {
        signalBadge = '⏳ Pause Day Supply Test (Dip Entry)';
        alertType = 'PAUSE_DAY_DIP';
      }
    } else if (stock.isDay1StealthCandidate || stock.qaiScore >= 72) {
      signalBadge = `🎯 Day 1 Stealth Detection (QAI ${stock.qaiScore})`;
      alertType = 'DAY_1_STEALTH';
    }

    // Preserve morning entry LTP if already logged today
    const loggedToday = existingToday?.topAccumulation?.find(p => p.symbol === stock.symbol);
    const entryLtp = loggedToday?.entryLtp || stock.ltp;

    return {
      ...stock,
      consecutiveDays,
      signalBadge,
      alertType,
      entryLtp,
      qaiScore: stock.qaiScore,
      asymmetryRatio: stock.asymmetryRatio,
      floatAbsorptionPct: stock.floatTurnoverPct,
      isDay1StealthCandidate: stock.isDay1StealthCandidate,
      flaggedDate: marketDate
    };
  });

  // 2. FILTER TOP 5 UNUSUAL DISTRIBUTION
  // Criteria: Stalling/falling price, high seller concentration (BCR3 >= 36%), and heavy distribution turnover
  const distPool = evaluated
    .filter(s => {
      let isHeavyDistTurnover = false;
      let hasDistConcentration = false;

      if (isFloorsheetActive) {
        isHeavyDistTurnover = s.turnover >= s.dynamicTurnoverFloor * 1.2 || s.floatTurnoverPct >= 0.45;
        hasDistConcentration = s.bcr3Sell >= 36 || (s.bcr3Sell >= 32 && s.floatTurnoverPct >= 0.60);
      } else {
        isHeavyDistTurnover = s.turnover >= 1500000 || s.floatTurnoverPct >= 0.30;
        hasDistConcentration = s.dumpRiskScore >= 60 || s.isUpperShadowDump || (s.pChange < -0.8 && s.turnover >= 2000000);
      }

      const isDumpStructure = s.tradeSizeRatio <= 1.15 || s.bcr3Sell > s.bcr3Buy || s.pChange < 0 || s.isUpperShadowDump || s.dumpRiskScore >= 60;
      const meetsDistCriteria = hasDistConcentration && isHeavyDistTurnover && isDumpStructure;
      return meetsDistCriteria;
    })
    .sort((a, b) => {
      if (b.bcr3Sell >= 40 && a.bcr3Sell < 40) return 1;
      if (a.bcr3Sell >= 40 && b.bcr3Sell < 40) return -1;
      if (b.bcr3Sell !== a.bcr3Sell && (b.bcr3Sell > 0 || a.bcr3Sell > 0)) return b.bcr3Sell - a.bcr3Sell;
      if (b.dumpRiskScore !== a.dumpRiskScore) return b.dumpRiskScore - a.dumpRiskScore;
      if (b.floatTurnoverPct !== a.floatTurnoverPct) return b.floatTurnoverPct - a.floatTurnoverPct;
      return b.turnover - a.turnover;
    });

  const topDistribution = distPool.slice(0, 5).map(stock => {
    const prevEntry = isPreviousSessionContinuous ? previousSnapshot?.topDistribution?.find(p => p.symbol === stock.symbol) : null;
    let distributionDay = 1;
    let signalBadge = '⚠️ Pre-Dump Window: 2–3 Days to Exit';
    let exitWindowNote = 'Smart money initiated distribution. Recommended exit window: 2 to 3 sessions before markdown.';
    let alertType = 'DIST_DAY_1';

    if (prevEntry) {
      distributionDay = (prevEntry.distributionDay || 1) + 1;
      signalBadge = `🚨 Day ${distributionDay} Aggressive Distribution (Urgent Exit)`;
      exitWindowNote = `Day ${distributionDay} consecutive selling by top desks. High T+2 trap risk! Stand down or liquidate.`;
      alertType = 'DIST_CONSECUTIVE';
    }

    // Preserve morning flagged LTP if already logged today
    const loggedToday = existingToday?.topDistribution?.find(p => p.symbol === stock.symbol);
    const flaggedLtp = loggedToday?.flaggedLtp || stock.ltp;

    return {
      ...stock,
      distributionDay,
      signalBadge,
      exitWindowNote,
      alertType,
      flaggedLtp,
      flaggedDate: marketDate
    };
  });

  const finalTopAccumulation = topAccumulation.length > 0
    ? topAccumulation
    : (existingToday?.topAccumulation?.length > 0 ? existingToday.topAccumulation : []);

  const finalTopDistribution = topDistribution.length > 0
    ? topDistribution
    : (existingToday?.topDistribution?.length > 0 ? existingToday.topDistribution : []);

  const newSnapshot = {
    date: marketDate,
    timestamp: Date.now(),
    totalStocksScanned: evaluated.length,
    topAccumulation: finalTopAccumulation,
    topDistribution: finalTopDistribution
  };

  // Upsert into archive
  const updatedArchive = [
    newSnapshot,
    ...existingArchive.filter(s => s.date !== marketDate)
  ].sort((a, b) => b.date.localeCompare(a.date));

  saveStoredWhaleArchive(updatedArchive);
  return newSnapshot;
}

/**
 * Calculates real-time performance tracking for all past archived signals
 * by comparing the flagged price against current live LTPs.
 */
export function calculateArchivePerformance(snapshot, liveStocksMap = {}) {
  if (!snapshot) return { accumulationTrack: [], distributionTrack: [] };

  const accumulationTrack = (snapshot.topAccumulation || []).map(item => {
    const live = liveStocksMap[item.symbol];
    const currentLtp = live ? Number(live.ltp || live.closePrice || item.ltp) : item.ltp;
    const entryPrice = item.entryLtp || item.ltp;
    const returnPct = entryPrice > 0 ? Number((((currentLtp - entryPrice) / entryPrice) * 100).toFixed(2)) : 0;

    return {
      ...item,
      currentLtp,
      entryPrice,
      returnPct,
      isProfitable: returnPct > 0,
      isFlat: returnPct === 0
    };
  });

  const distributionTrack = (snapshot.topDistribution || []).map(item => {
    const live = liveStocksMap[item.symbol];
    const currentLtp = live ? Number(live.ltp || live.closePrice || item.ltp) : item.ltp;
    const flaggedPrice = item.flaggedLtp || item.ltp;
    const dropPct = flaggedPrice > 0 ? Number((((flaggedPrice - currentLtp) / flaggedPrice) * 100).toFixed(2)) : 0;

    return {
      ...item,
      currentLtp,
      flaggedPrice,
      dropPct, // Positive dropPct means price fell (dump confirmed, loss avoided!)
      dumpConfirmed: dropPct > 0
    };
  });

  return {
    date: snapshot.date,
    accumulationTrack,
    distributionTrack
  };
}

// src/utils/cacheManager.js
// PRODUCTION GRADE NEPSE CACHE MANAGER
// Handles multi-layer caching with TTL (Time To Live), Promoter Share segregation,
// and Circuit Limit detection.

const CACHE_KEYS = {
  LIVE_QUOTES: 'nepse_live_quotes',
  FLOORSHEET: 'nepse_floorsheet',
  FUNDAMENTALS: 'nepse_fundamentals',
  USER_WACC: 'nepse_custom_wacc_map' // Remains lightweight in localStorage
};

const TTL = {
  LIVE_QUOTES: 60 * 1000,           // 1 minute
  FLOORSHEET: 5 * 60 * 1000,        // 5 minutes
  FUNDAMENTALS: 24 * 60 * 60 * 1000 // 24 hours
};

/**
 * Enhanced memory fallback for IndexedDB
 */
const MemoryStore = new Map();

/**
 * Initialize IndexedDB securely
 */
let dbPromise = null;
function getDB() {
  if (typeof window === 'undefined' || !window.indexedDB) return null;
  if (dbPromise) return dbPromise;

  dbPromise = new Promise((resolve, reject) => {
    const request = window.indexedDB.open('NepseQuantDB', 1);

    request.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains('nepsedata')) {
        db.createObjectStore('nepsedata');
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      console.warn('IndexedDB failed to initialize. Falling back to memory store.');
      resolve(null);
    };
  });

  return dbPromise;
}

/**
 * Saves heavy blobs (Floorsheet/Fundamentals) to IndexedDB with TTL
 */
export async function setCache(key, data, ttlMs = TTL.LIVE_QUOTES) {
  const payload = {
    timestamp: Date.now(),
    expiresAt: Date.now() + ttlMs,
    data
  };

  // 1. Memory Layer
  MemoryStore.set(key, payload);

  // 2. IndexedDB Layer
  const db = await getDB();
  if (db) {
    try {
      return new Promise((resolve) => {
        const tx = db.transaction('nepsedata', 'readwrite');
        const store = tx.objectStore('nepsedata');
        store.put(payload, key);
        tx.oncomplete = () => resolve(true);
        tx.onerror = () => resolve(false);
      });
    } catch (e) {
      console.warn("Failed to write to IndexedDB", e);
    }
  } else {
    // 3. Fallback to localStorage if small enough (Live Quotes)
    try {
      localStorage.setItem(key, JSON.stringify(payload));
    } catch (e) {
      // Quota exceeded
    }
  }
  return true;
}

/**
 * Retrieves valid cached blobs using TTL
 */
export async function getCache(key) {
  const now = Date.now();

  // 1. Memory Check
  if (MemoryStore.has(key)) {
    const payload = MemoryStore.get(key);
    if (payload.expiresAt > now) return payload.data;
    MemoryStore.delete(key);
  }

  // 2. IndexedDB Check
  const db = await getDB();
  if (db) {
    try {
      const payload = await new Promise((resolve) => {
        const tx = db.transaction('nepsedata', 'readonly');
        const store = tx.objectStore('nepsedata');
        const req = store.get(key);
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => resolve(null);
      });

      if (payload && payload.expiresAt > now) {
        MemoryStore.set(key, payload); // Hydrate memory
        return payload.data;
      }
    } catch (e) {
      console.warn("Failed to read from IndexedDB", e);
    }
  }

  // 3. LocalStorage Fallback
  try {
    const raw = localStorage.getItem(key);
    if (raw) {
      const payload = JSON.parse(raw);
      if (payload.expiresAt > now) return payload.data;
      localStorage.removeItem(key);
    }
  } catch (e) { }

  return null;
}

/**
 * Clears expired entries across all stores
 */
export async function evictExpiredCaches() {
  const now = Date.now();
  for (const [key, payload] of MemoryStore.entries()) {
    if (payload.expiresAt <= now) MemoryStore.delete(key);
  }

  const db = await getDB();
  if (db) {
    try {
      const tx = db.transaction('nepsedata', 'readwrite');
      const store = tx.objectStore('nepsedata');
      store.openCursor().onsuccess = (e) => {
        const cursor = e.target.result;
        if (cursor) {
          if (cursor.value.expiresAt <= now) cursor.delete();
          cursor.continue();
        }
      };
    } catch (e) { }
  }
}

/**
 * Identifies and segregates standard equity vs promoter shares.
 * Returns an object separating the two arrays.
 */
export function segregatePromoterShares(stocks = []) {
  const standard = [];
  const promoter = [];

  stocks.forEach(s => {
    // Promoter shares usually end with P, PO, P1, or are specifically labeled
    if (/P\d*$/.test(s.symbol) || s.symbol.includes('PO') || (s.sector && s.sector.toLowerCase().includes('promoter'))) {
      promoter.push(s);
    } else {
      standard.push(s);
    }
  });

  return { standard, promoter };
}

/**
 * Evaluates +/- 15% circuit limit flag for live quotes (since April 20, 2026).
 */
export function enrichWithCircuitFlags(stocks = []) {
  return stocks.map(stock => {
    const pChg = stock.pChange || stock.percentageChange || 0;
    // Individual stock circuit limit in NEPSE is +/- 15% (effective April 20, 2026)
    const isCircuitHit = Math.abs(pChg) >= 14.85;

    return {
      ...stock,
      isCircuitHit,
      circuitType: isCircuitHit ? (pChg > 0 ? 'upper' : 'lower') : 'none'
    };
  });
}

/**
 * Calculations for Nepal Stock Exchange (NEPSE) and SEBON rules
 */

/**
 * Calculates tiered broker commission for equity trading in Nepal.
 * Effective Jestha 1, 2081 BS (May 14, 2024):
 * - Up to Rs. 50,000: 0.36%
 * - Rs. 50,001 to Rs. 500,000: 0.33%
 * - Rs. 500,001 to Rs. 2,000,000: 0.31%
 * - Rs. 2,000,001 to Rs. 10,000,000: 0.27%
 * - Above Rs. 10,000,000: 0.24%
 * Note: Minimum broker commission is Rs. 10.
 */

/**
 * Formats a number to South Asian (Indian/Nepali) numbering system (Lakh/Crore)
 */
export function formatSouthAsian(number) {
  if (number === null || number === undefined || isNaN(number)) return "0.00";
  return new Intl.NumberFormat('en-IN', { maximumFractionDigits: 2, minimumFractionDigits: 2 }).format(number);
}

/**
 * Adjusts holdings after a Bonus Share distribution
 * @param {number} units 
 * @param {number} wacc 
 * @param {number} bonusPercent 
 */
export function adjustForBonusShare(units, wacc, bonusPercent) {
  const newUnits = units * (1 + (bonusPercent / 100));
  const newWacc = (units * wacc) / newUnits;
  return { newUnits: Number(newUnits.toFixed(2)), newWacc: Number(newWacc.toFixed(2)) };
}

/**
 * Adjusts holdings after a Right Share issuance
 * @param {number} units 
 * @param {number} wacc 
 * @param {number} rightRatio - E.g. 1:0.5 is 0.5
 * @param {number} subscriptionPrice - Usually 100
 */
export function adjustForRightShare(units, wacc, rightRatio, subscriptionPrice = 100) {
  const addedUnits = units * rightRatio;
  const newUnits = units + addedUnits;
  const newWacc = ((units * wacc) + (addedUnits * subscriptionPrice)) / newUnits;
  return { newUnits: Number(newUnits.toFixed(2)), newWacc: Number(newWacc.toFixed(2)) };
}

/**
 * Adjusts holdings and price after a simultaneous Bonus and Right Share distribution
 * Official NEPSE Formula: P_adj = (P_cum + (R * S)) / (1 + B + R)
 * @param {number} units - Pre-book closure units
 * @param {number} wacc - Pre-book closure WACC
 * @param {number} cumPrice - Last traded price before book closure (P_cum)
 * @param {number} bonusPercent - Bonus % e.g. 10 for 10%
 * @param {number} rightPercent - Right % e.g. 50 for 50% or 1:0.5
 * @param {number} subscriptionPrice - Par value, default 100
 */
export function adjustSimultaneousBonusAndRight(units, wacc, cumPrice, bonusPercent = 0, rightPercent = 0, subscriptionPrice = 100) {
  const bRatio = (Number(bonusPercent) || 0) / 100;
  const rRatio = (Number(rightPercent) || 0) / 100;
  const sPrice = Number(subscriptionPrice) || 100;
  const pCum = Number(cumPrice) || 0;
  const u = Number(units) || 0;
  const w = Number(wacc) || 0;

  const denominator = 1 + bRatio + rRatio;
  const adjustedPrice = denominator > 0 ? (pCum + (rRatio * sPrice)) / denominator : pCum;

  const bonusUnits = u * bRatio;
  const rightUnits = u * rRatio;
  const totalNewUnits = u + bonusUnits + rightUnits;

  const rightSubscriptionCost = rightUnits * sPrice;
  const totalCostBasis = (u * w) + rightSubscriptionCost;
  const newWacc = totalNewUnits > 0 ? totalCostBasis / totalNewUnits : w;

  return {
    adjustedPrice: Number(adjustedPrice.toFixed(2)),
    bonusUnits: Number(bonusUnits.toFixed(2)),
    rightUnits: Number(rightUnits.toFixed(2)),
    totalNewUnits: Number(totalNewUnits.toFixed(2)),
    rightSubscriptionCost: Number(rightSubscriptionCost.toFixed(2)),
    newWacc: Number(newWacc.toFixed(2))
  };
}

/**
 * Philip Fisher Bonus Dilution & Sustainability Auditor
 * Evaluates whether earnings power can sustain the expanded post-bonus equity base.
 * @param {number} currentEps - Trailing EPS
 * @param {number} bonusPercent - Declared bonus %
 * @param {number} pe - Current P/E ratio
 */
export function auditBonusDilution(currentEps, bonusPercent, pe = 0) {
  const eps = Number(currentEps) || 0;
  const b = (Number(bonusPercent) || 0) / 100;

  if (eps <= 0 || b <= 0) {
    return {
      postBonusEps: eps,
      dilutionPct: 0,
      riskLevel: 'Neutral',
      message: 'Zero or negative EPS / No bonus dividend declared.'
    };
  }

  const postBonusEps = Number((eps / (1 + b)).toFixed(2));
  const dilutionPct = Number(((b / (1 + b)) * 100).toFixed(1));

  let riskLevel = 'Low';
  let message = 'Earning capacity remains healthy post-distribution.';

  if (postBonusEps < 12 || (pe > 35 && dilutionPct > 20)) {
    riskLevel = 'High';
    message = `Severe dilution risk: Post-bonus EPS drops to Rs. ${postBonusEps}. High risk of dividend halving next fiscal year.`;
  } else if (postBonusEps < 18 || dilutionPct > 15) {
    riskLevel = 'Moderate';
    message = `Moderate dilution: Post-bonus EPS contracts by -${dilutionPct}%. Requires sustained net profit growth to maintain dividend yield.`;
  }

  return {
    postBonusEps,
    dilutionPct,
    riskLevel,
    message
  };
}

/**
 * Calculates Dividend Yield based on Cash Dividend and LTP
 */
export function calculateDividendYield(cashDivPerShare, ltp) {
  if (!ltp || ltp <= 0) return 0;
  return Number(((cashDivPerShare / ltp) * 100).toFixed(2));
}

export const SEBON_5_SLAB_EQUITY_TIERS = [
  { maxAmount: 50_000, rate: 0.0036 },       // <= Rs. 50,000: 0.36%
  { maxAmount: 500_000, rate: 0.0033 },      // Rs. 50,001 - 500,000: 0.33%
  { maxAmount: 2_000_000, rate: 0.0031 },    // Rs. 500,001 - 2,000,000: 0.31%
  { maxAmount: 10_000_000, rate: 0.0027 },   // Rs. 2,000,001 - 10,000,000: 0.27%
  { maxAmount: Infinity, rate: 0.0024 },     // > Rs. 10,000,000: 0.24%
];

export const SEBON_EQUITY_COMMISSION_TIERS = SEBON_5_SLAB_EQUITY_TIERS;
export const SEBON_FEE_RATE = 0.00015;       // 0.015%
export const CDSC_DP_CHARGE_NPR = 25;        // Flat Rs. 25 per transaction settlement
export const MIN_BROKERAGE_NPR = 10;         // Minimum Rs. 10 brokerage floor
export const NEPSE_CIRCUIT_LIMIT_PCT = 15.0; // ±15.0% Fourth Amendment 2082
export const NEPSE_CIRCUIT_SHIFT_DATE = '2026-04-20';

export function getNepseCircuitLimitPct(tradeDate = null) {
  if (tradeDate) {
    const dStr = String(tradeDate).slice(0, 10);
    if (dStr < NEPSE_CIRCUIT_SHIFT_DATE) return 10.0;
  }
  return 15.0; // Current post-April 20, 2026 statutory band
}

export function clampToNepseCircuitBand(referenceClose, targetPrice, tradeDate = null) {
  const ref = Number(referenceClose) || 0;
  const tgt = Number(targetPrice) || 0;
  if (ref <= 0 || tgt <= 0) return Math.max(0, tgt);
  const pct = getNepseCircuitLimitPct(tradeDate) / 100;
  const floor = +(ref * (1 - pct)).toFixed(2);
  const ceiling = +(ref * (1 + pct)).toFixed(2);
  return +Math.min(ceiling, Math.max(floor, tgt)).toFixed(2);
}

export function calculateBrokerageCommission(grossAmount) {
  const amt = Math.max(0, Number(grossAmount) || 0);
  if (amt <= 0) return { rate: 0, commission: 0 };
  const tier =
    SEBON_5_SLAB_EQUITY_TIERS.find(t => amt <= t.maxAmount) ||
    SEBON_5_SLAB_EQUITY_TIERS[SEBON_5_SLAB_EQUITY_TIERS.length - 1];
  const commission = +Math.max(MIN_BROKERAGE_NPR, amt * tier.rate).toFixed(2);
  return { rate: tier.rate, commission };
}

/**
 * Calculates exact NEPSE Net Return & CGT after deducting both Buy and Sell commissions,
 * SEBON 0.015% fees, and Rs. 25 DP charges.
 */
export function calculateNepseNetTrade({
  quantity = 100,
  buyPrice,
  sellPrice,
  holdingDays = 2,
  isCorporate = false,
  nepseIndexReturnPct = 0,
}) {
  const kitta = Math.max(0, Math.floor(Number(quantity) || 0));
  const bPx = Number(buyPrice) || 0;
  const sPx = Number(sellPrice) || 0;

  if (kitta <= 0 || bPx <= 0 || sPx <= 0) {
    return {
      grossBuy: 0,
      totalBuyCost: 0,
      grossSell: 0,
      netReceivable: 0,
      cgtTax: 0,
      netProfit: 0,
      netReturnPct: 0,
      nepseAlphaPct: 0,
      isT2Compliant: Number(holdingDays) >= 2,
    };
  }

  const grossBuy = +(kitta * bPx).toFixed(2);
  const { commission: buyComm } = calculateBrokerageCommission(grossBuy);
  const buySebon = +(grossBuy * SEBON_FEE_RATE).toFixed(2);
  const buyDp = 0; // Per CDSC bylaws, DP fee is charged strictly on the SELL leg upon debiting shares
  const totalBuyCost = +(grossBuy + buyComm + buySebon + buyDp).toFixed(2);

  const grossSell = +(kitta * sPx).toFixed(2);
  const { commission: sellComm } = calculateBrokerageCommission(grossSell);
  const sellSebon = +(grossSell * SEBON_FEE_RATE).toFixed(2);
  const sellDp = CDSC_DP_CHARGE_NPR;
  const netSellBeforeTax = +(grossSell - sellComm - sellSebon - sellDp).toFixed(2);

  // CGT is strictly levied on Net Capital Gain AFTER deducting buy & sell commissions, SEBON fees, and DP charges
  const netCapitalGain = Math.max(0, netSellBeforeTax - totalBuyCost);
  const cgtRate = isCorporate ? 0.10 : (Number(holdingDays) >= 365 ? 0.05 : 0.075);
  const cgtTax = +(netCapitalGain * cgtRate).toFixed(2);

  const netReceivable = +(netSellBeforeTax - cgtTax).toFixed(2);
  const netProfit = +(netReceivable - totalBuyCost).toFixed(2);
  const netReturnPct = totalBuyCost > 0 ? +((netProfit / totalBuyCost) * 100).toFixed(2) : 0;
  const nepseAlphaPct = +(netReturnPct - (Number(nepseIndexReturnPct) || 0)).toFixed(2);

  return {
    grossBuy,
    buyComm,
    buySebon,
    buyDp,
    totalBuyCost,
    grossSell,
    sellComm,
    sellSebon,
    sellDp,
    cgtRatePct: +(cgtRate * 100).toFixed(1),
    cgtTax,
    netReceivable,
    netProfit,
    netReturnPct,
    nepseAlphaPct,
    isT2Compliant: Number(holdingDays) >= 2,
  };
}

/**
 * Evaluates Day T+1 Execution Fill at VWAP (turnover / volume) with +14.9% Circuit Gap-Trap Filter
 */
export function evaluateDayTPlus1VwapFill(signalCloseDayT, candleDayTPlus1) {
  const sigClose = Number(signalCloseDayT) || 0;
  if (!candleDayTPlus1 || sigClose <= 0) {
    return { status: 'PENDING_T1_SESSION', entryVwap: null, gapPct: 0 };
  }

  const vol = Number(candleDayTPlus1.totalVolume ?? candleDayTPlus1.volume ?? 0);
  const turnover = Number(candleDayTPlus1.totalTurnover ?? candleDayTPlus1.turnover ?? 0);
  const openPx = Number(candleDayTPlus1.openPrice ?? candleDayTPlus1.open ?? 0);
  const closePx = Number(candleDayTPlus1.closePrice ?? candleDayTPlus1.close ?? 0);

  if (vol <= 0 || (turnover <= 0 && closePx <= 0)) {
    return { status: 'UNFILLABLE_SKIP', reason: 'ZERO_LIQUIDITY_T1', entryVwap: null, gapPct: 0 };
  }

  const t1Vwap = turnover > 0 ? +(turnover / vol).toFixed(2) : +closePx.toFixed(2);
  const checkPrice = openPx > 0 ? Math.max(openPx, t1Vwap) : t1Vwap;
  const gapPct = +(((checkPrice - sigClose) / sigClose) * 100).toFixed(2);

  // Gap trap >= +14.9% (upper circuit lock on Day T+1) -> UNFILLABLE_SKIP
  if (gapPct >= 14.9) {
    return {
      status: 'UNFILLABLE_SKIP',
      reason: `GAP_TRAP_CIRCUIT_LOCK (+${gapPct}% >= +14.9% ceiling)`,
      entryVwap: null,
      gapPct,
    };
  }

  return {
    status: 'FILLED_AT_T1_VWAP',
    entryVwap: t1Vwap,
    gapPct,
  };
}

export const SEBON_REGULATORY_FEE_RATE = 0.00015; // 0.015%
export const CDSC_DP_FEE_NPR = 25;                // Flat Rs. 25 per transaction settlement
export const MIN_BROKER_COMMISSION_NPR = 10;      // Minimum Rs. 10 brokerage

export function getNepseBrokerCommissionRate(orderAmount) {
  const amt = Number(orderAmount || 0);
  if (amt <= 50000) return 0.0036;       // 0.36% (<= Rs 50,000)
  if (amt <= 500000) return 0.0033;      // 0.33% (Rs 50,001 - Rs 500,000)
  if (amt <= 2000000) return 0.0031;     // 0.31% (Rs 500,001 - Rs 2,000,000)
  if (amt <= 10000000) return 0.0027;    // 0.27% (Rs 2,000,001 - Rs 10,000,000)
  return 0.0024;                         // 0.24% (> Rs 10,000,000)
}

/**
 * Returns the statutory SEBON broker commission rate and rupee amount.
 * When returnDetails is true, returns { rate, commission }. Otherwise returns numeric commission amount.
 */
export function calculateBrokerCommission(amountNpr, returnDetails = false) {
  const amt = Math.max(0, Number(amountNpr) || 0);
  if (amt <= 0) return returnDetails ? { rate: 0, commission: 0 } : 0;

  const tier =
    SEBON_EQUITY_COMMISSION_TIERS.find(t => amt <= t.maxAmount) ||
    SEBON_EQUITY_COMMISSION_TIERS[SEBON_EQUITY_COMMISSION_TIERS.length - 1];

  const rawCommission = amt * tier.rate;
  const commission = Number(Math.max(MIN_BROKER_COMMISSION_NPR, rawCommission).toFixed(2));
  if (returnDetails) {
    return { rate: tier.rate, commission };
  }
  return commission;
}

export function calculateBrokerCommissionDetails(amountNpr) {
  return calculateBrokerCommission(amountNpr, true);
}

/**
 * Calculates SEBON Regulatory Fee (0.015% of transaction amount)
 * A5 Fix: Result rounded to 2 decimal places (paisa precision).
 */
export function calculateSebonFee(amount) {
  return +((amount * 0.00015).toFixed(2));
}


/**
 * DP Charge (Depository Participant fee) is Rs. 25 per transaction per company
 */
export const DP_CHARGE = 25;

/**
 * Calculates the complete buy transaction details.
 */
export function calculateBuyDetails(quantity, price) {
  const shareValue = quantity * price;
  const commission = calculateBrokerCommission(shareValue);
  const sebonFee = calculateSebonFee(shareValue);
  const dpFee = 0; // Per CDSC regulations, DP fee (Rs. 25) is levied strictly on the SELL leg
  const totalAmount = shareValue + commission + sebonFee + dpFee;

  return {
    shareValue,
    commission,
    sebonFee,
    dpFee,
    totalAmount,
    costPerShare: quantity > 0 ? totalAmount / quantity : 0
  };
}

/**
 * Calculates the complete sell transaction details, including Capital Gains Tax (CGT).
 * @param {number} quantity - Number of shares
 * @param {number} sellPrice - Selling price per share
 * @param {number} buyPriceWacc - Purchase price per share (WACC)
 * @param {string} holdingType - 'short' (<=365 days), 'long' (>365 days), or 'institutional'
 */
export function calculateSellDetails(quantity, sellPrice, buyPriceWacc, holdingTypeOrPurchaseDate = 'short', sellDate = new Date(), options = {}) {
  const sellValue = quantity * sellPrice;
  const commission = calculateBrokerCommission(sellValue);
  const sebonFee = calculateSebonFee(sellValue);
  const dpFee = DP_CHARGE;

  // Total acquisition cost (based on WACC)
  const totalBuyingCost = quantity * buyPriceWacc;

  // Base for CGT calculation
  // Profit = Selling Value - Buying Cost - Selling Broker Commission - Selling SEBON Fee - DP Fee
  const netProfitBase = sellValue - totalBuyingCost - commission - sebonFee - dpFee;

  let isLongTerm = false;
  let isInstitutional = false;

  if (holdingTypeOrPurchaseDate === 'long') {
    isLongTerm = true;
  } else if (holdingTypeOrPurchaseDate === 'institutional') {
    isInstitutional = true;
  } else if (holdingTypeOrPurchaseDate === 'short') {
    isLongTerm = false;
  } else {
    try {
      const pDate = new Date(holdingTypeOrPurchaseDate);
      const sDate = sellDate ? new Date(sellDate) : new Date();
      const diffTime = Math.abs(sDate - pDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      isLongTerm = diffDays > 365;
    } catch(e) {
      isLongTerm = false;
    }
  }

  // Capital Gains Tax (CGT) per SEBON & Nepal Income Tax Act (Section 95Ka):
  // Finance Act 2083: Short-Term 10.0%, Long-Term 7.5%
  // Legacy / Baseline: Short-Term 7.5%, Long-Term 5.0%, Corporate 10.0%
  let cgtRate = 0.075; // Default short-term individual (7.5%)
  if (options && options.financeAct2083) {
    cgtRate = isLongTerm ? 0.075 : 0.100;
  } else if (isInstitutional) {
    cgtRate = 0.10;
  } else if (isLongTerm) {
    cgtRate = 0.05;
  }
  if (options && options.cgtRate !== undefined) {
    cgtRate = Number(options.cgtRate);
  }

  const taxableProfit = Math.max(0, netProfitBase);
  const cgt = taxableProfit * cgtRate;

  const totalExpenses = commission + sebonFee + dpFee + cgt;
  const netReceivable = sellValue - commission - sebonFee - dpFee - cgt;
  const netProfitLoss = netReceivable - totalBuyingCost;

  return {
    sellValue,
    commission,
    sebonFee,
    dpFee,
    cgt,
    cgtRate,
    isFinalTax: true,
    totalExpenses,
    netReceivable,
    netProfitLoss,
    roi: totalBuyingCost > 0 ? (netProfitLoss / totalBuyingCost) * 100 : 0
  };
}

/**
 * Calculates exact Statutory Zero-Loss Breakeven Price for a given quantity and buy price,
 * accounting for both buy-leg and sell-leg tiered broker commissions (min Rs. 10),
 * SEBON fee (0.015% per leg), and DP charge (Rs. 25 per leg).
 */
export function calculateStatutoryBreakevenPrice(quantity, buyPrice) {
  const qty = Math.max(10, Number(quantity || 10));
  const entry = Number(buyPrice || 0);
  if (entry <= 0) return 0;

  const buyDetails = calculateBuyDetails(qty, entry);
  // Iteratively solve for the exact exit price where netReceivable === buyDetails.totalAmount
  let estExit = +(buyDetails.costPerShare * 1.0045).toFixed(2);
  for (let i = 0; i < 4; i++) {
    const sellValue = qty * estExit;
    const sellComm = calculateBrokerCommission(sellValue);
    const sellSebon = calculateSebonFee(sellValue);
    const sellDp = DP_CHARGE;
    const requiredGross = buyDetails.totalAmount + sellComm + sellSebon + sellDp;
    estExit = requiredGross / qty;
  }
  const breakevenPrice = +Math.ceil(estExit * 10) / 10; // Round up to nearest 10 paisa tick
  const hurdlePct = +(((breakevenPrice - entry) / entry) * 100).toFixed(2);

  return {
    entryPrice: entry,
    quantity: qty,
    breakevenPrice,
    hurdlePct,
    totalBuyCost: +buyDetails.totalAmount.toFixed(2),
    roundTripExpenses: +((breakevenPrice * qty) - (entry * qty)).toFixed(2),
    label: `Rs. ${breakevenPrice} (+${hurdlePct}% statutory zero-loss floor)`
  };
}

/**
 * Calculates Net Post-Tax & Post-Fee Risk-to-Reward Ratio (R:R) and Stop-to-Breakeven Runner Plan.
 * Enforces statutory 7.5% Short-Term CGT, tiered broker commissions, 0.015% SEBON fee, and Rs. 25 DP fee.
 * Blocks "BUY" qualification unless Net R:R at Target 1 >= requiredNetRRR (default 3.0 : 1).
 */
export function calculateNetRiskRewardRatio({
  quantity = 100,
  entryPrice,
  stopLossPrice,
  target1Price,
  target2Price = null,
  holdingType = 'short',
  requiredNetRRR = 3.0
}) {
  const qty = Math.max(10, Number(quantity || 100));
  const entry = Number(entryPrice || 0);
  const stop = Number(stopLossPrice || 0);
  const t1 = Number(target1Price || 0);
  const t2 = Number(target2Price || (t1 > entry ? entry + (t1 - entry) * 1.6 : entry * 1.20));

  if (entry <= 0 || stop <= 0 || stop >= entry || t1 <= entry) {
    return {
      isValid: false,
      isBuyBlocked: true,
      netRRR1: 0,
      netRRR2: 0,
      requiredNetRRR,
      reason: 'Invalid price geometry (Stop-Loss must be below Entry and Target 1 above Entry).'
    };
  }

  // 1. Exact Buy Cost (shareValue + buyCommission + buySebon + Rs. 25 DP)
  const buyLeg = calculateBuyDetails(qty, entry);
  const waccPerShare = buyLeg.costPerShare;

  // 2. Exact Net Take-Home Profit at Target 1 (includes 7.5% Short-Term CGT on net gain above WACC)
  const sellT1 = calculateSellDetails(qty, t1, waccPerShare, holdingType, new Date(), { cgtRate: holdingType === 'long' ? 0.05 : 0.075 });
  const netProfitT1 = +sellT1.netProfitLoss.toFixed(2);
  const netProfitPerShareT1 = +(netProfitT1 / qty).toFixed(2);

  // 3. Exact Net Take-Home Profit at Target 2
  const sellT2 = calculateSellDetails(qty, t2, waccPerShare, holdingType, new Date(), { cgtRate: holdingType === 'long' ? 0.05 : 0.075 });
  const netProfitT2 = +sellT2.netProfitLoss.toFixed(2);
  const netProfitPerShareT2 = +(netProfitT2 / qty).toFixed(2);

  // 4. Exact Net Loss at Stop-Loss (no CGT on loss, includes full buy + sell friction)
  const sellSL = calculateSellDetails(qty, stop, waccPerShare, holdingType, new Date(), { cgtRate: 0.075 });
  const netLossSL = +Math.abs(sellSL.netProfitLoss).toFixed(2);
  const netLossPerShareSL = +(netLossSL / qty).toFixed(2);

  // 5. Net Post-Tax/Fee R:R Ratios
  const netRRR1 = netLossSL > 0 ? +(netProfitT1 / netLossSL).toFixed(2) : 0;
  const netRRR2 = netLossSL > 0 ? +(netProfitT2 / netLossSL).toFixed(2) : 0;
  const isBuyAllowed = netProfitT1 > 0 && netRRR1 >= requiredNetRRR;

  // 6. Stop-to-Breakeven Rule at Target 1 (50% scale-out, remaining 50% runner risk-free)
  const scaleOutQty = Math.max(10, Math.floor((qty * 0.5) / 10) * 10);
  const runnerQty = Math.max(0, qty - scaleOutQty);
  const breakevenObj = calculateStatutoryBreakevenPrice(Math.max(10, runnerQty), entry);

  return {
    isValid: true,
    isBuyAllowed,
    isBuyBlocked: !isBuyAllowed,
    quantity: qty,
    entryPrice: entry,
    stopLossPrice: stop,
    target1Price: t1,
    target2Price: t2,
    waccPerShare: +waccPerShare.toFixed(2),
    netProfitT1,
    netProfitPerShareT1,
    netProfitT2,
    netProfitPerShareT2,
    netLossSL,
    netLossPerShareSL,
    netRRR1,
    netRRR2,
    requiredNetRRR,
    cgtRatePct: holdingType === 'long' ? 5.0 : 7.5,
    stopToBreakevenRule: {
      enabled: true,
      triggerAtPrice: t1,
      scaleOutPct: 50,
      scaleOutQty,
      runnerQty,
      newStopLossPrice: breakevenObj.breakevenPrice,
      runnerRiskRupees: 0,
      instruction: `At Target 1 (Rs. ${t1}), sell ${scaleOutQty} kitta (50%) and immediately raise Stop-Loss on the remaining ${runnerQty} kitta to Statutory Breakeven (Rs. ${breakevenObj.breakevenPrice}) for a 100% risk-free runner.`
    }
  };
}


/**
 * Calculates Weighted Average Cost of Capital (WACC) for multiple transactions
 * with full inclusion of broker commission tiers, SEBON fee, DP fee, and corporate actions.
 * @param {Array<{ quantity: number, price: number }>} buyTransactions
 * @param {Array<{ type: 'bonus'|'right', bonusPercent?: number, rightRatio?: number, subscriptionPrice?: number }>} [corporateActions=[]]
 */
export function calculateWacc(buyTransactions, corporateActions = []) {
  if (!Array.isArray(buyTransactions) || buyTransactions.length === 0) {
    return { totalQuantity: 0, totalCost: 0, wacc: 0 };
  }
  let totalQty = 0;
  let totalCost = 0;

  buyTransactions.forEach(tx => {
    const qty = Number(tx.quantity || tx.units || 0);
    const price = Number(tx.price || tx.rate || 0);
    if (qty <= 0) return;
    const buyDetails = calculateBuyDetails(qty, price);
    totalQty += qty;
    totalCost += buyDetails.totalAmount; // includes broker commission, sebon (0.015%), dp (Rs 25)
  });

  // Apply corporate actions dynamically (bonus shares, right shares adjustments)
  if (Array.isArray(corporateActions) && corporateActions.length > 0) {
    corporateActions.forEach(ca => {
      if (ca.type === 'bonus' && Number(ca.bonusPercent) > 0) {
        const bonusUnits = totalQty * (Number(ca.bonusPercent) / 100);
        totalQty += bonusUnits;
        // Total cost basis remains identical; per-unit WACC dilutes
      } else if (ca.type === 'right' && Number(ca.rightRatio) > 0) {
        const subPrice = Number(ca.subscriptionPrice) || 100;
        const rightUnits = totalQty * Number(ca.rightRatio);
        totalQty += rightUnits;
        totalCost += (rightUnits * subPrice); // Added cash subscription outlay
      }
    });
  }

  return {
    totalQuantity: Math.round(totalQty),
    totalCost: +totalCost.toFixed(2),
    wacc: totalQty > 0 ? +(totalCost / totalQty).toFixed(2) : 0
  };
}

/**
 * Dynamically computes IPO Allotment Probability under SEBON 10-Kitta Rule.
 * Official SEBON Securities Issue and Allotment Guidelines:
 * - General public quota is divided into 10-share (10-kitta) lots.
 * - Total possible allottees = Math.floor(generalPublicUnits / 10).
 * - If oversubscription times <= 1.0: Guaranteed allotment (100% chance).
 * - If oversubscription times > 1.0: Lottery system applies.
 *   Probability = (Total Eligible Allottees / Total Applicants) * 100.
 *
 * @param {Object} params
 * @param {number} params.generalPublicUnits - Total units allocated to general public
 * @param {number} [params.totalApplicants=0] - Total verified applicant count
 * @param {number} [params.oversubscriptionTimes=0] - Subscription multiple (e.g. 5.5x)
 * @param {number} [params.appliedKitta=10] - Applied kitta (default 10)
 * @returns {Object}
 */
export function calculateIpoAllotmentProbability({
  generalPublicUnits = 0,
  totalApplicants = 0,
  oversubscriptionTimes = 0,
  appliedKitta = 10
}) {
  const units = Number(generalPublicUnits) || 0;
  let applicants = Number(totalApplicants) || 0;
  let times = Number(oversubscriptionTimes) || 0;

  const eligibleAllottees = units > 0 ? Math.floor(units / 10) : 0;

  if (times <= 0 && applicants > 0 && units > 0) {
    times = +((applicants * 10) / units).toFixed(2);
  } else if (applicants <= 0 && times > 0 && eligibleAllottees > 0) {
    applicants = Math.round(eligibleAllottees * times);
  }

  if (eligibleAllottees <= 0) {
    return {
      probabilityPct: null,
      eligibleAllottees: 0,
      totalApplicants: applicants,
      oversubscriptionTimes: times,
      isGuaranteed: false,
      status: 'insufficient_data',
      formula: 'General public issue size not disclosed',
      statusText: 'Pipeline / Pending SEBON Approval'
    };
  }

  // Undersubscribed or fully subscribed: 100% guaranteed 10 kitta
  if (times > 0 && times <= 1.0) {
    return {
      probabilityPct: 100.0,
      eligibleAllottees,
      totalApplicants: applicants,
      oversubscriptionTimes: times,
      isGuaranteed: true,
      status: 'guaranteed',
      allotmentType: 'guaranteed',
      formula: '10-kitta allotment guaranteed (Oversubscription <= 1.0x)',
      statusText: '100% Guaranteed Allotment (10+ Kitta)',
      explanation: '100% Guaranteed Allotment (10+ Kitta under SEBON rules)'
    };
  }

  // Oversubscribed lottery
  let prob = 100.0;
  if (times > 1.0) {
    prob = Math.min(100.0, Math.max(0.01, +(100 / times).toFixed(2)));
  } else if (applicants > 0 && eligibleAllottees > 0) {
    prob = Math.min(100.0, Math.max(0.01, +((eligibleAllottees / applicants) * 100).toFixed(2)));
  }

  return {
    probabilityPct: prob,
    eligibleAllottees,
    totalApplicants: applicants,
    oversubscriptionTimes: times,
    isGuaranteed: prob >= 100.0,
    status: prob >= 100.0 ? 'guaranteed' : 'lottery',
    allotmentType: prob >= 100.0 ? 'guaranteed' : 'lottery',
    formula: `Lottery: ${eligibleAllottees.toLocaleString()} winners among ${applicants ? applicants.toLocaleString() : (times + 'x')} applicants`,
    statusText: `${prob}% Mathematical Probability (${eligibleAllottees.toLocaleString()} Allottees / ${times}x Subscribed)`,
    explanation: `${prob}% Mathematical Probability under SEBON 10-Kitta Lottery Rule`
  };
}

/**
 * Parses copied trade tables or CSV exports from NEPSE Broker TMS (e.g. Broker 58, 45, etc.)
 * Extracts Buy transactions, groups by symbol, and calculates authentic WACC with commissions.
 *
 * @param {string} rawText - Raw text or CSV copied/exported from TMS
 * @returns {object} { success: boolean, count: number, holdings: { [symbol]: { symbol, wacc, totalQuantity, totalCost, source } }, error?: string }
 */
export function parseBrokerTradeBook(rawText) {
  if (!rawText || typeof rawText !== 'string') {
    return { success: false, count: 0, holdings: {}, error: 'No trade book text provided.' };
  }

  const splitLineSmart = (line, delim) => {
    if (delim === ',') {
      const out = [];
      let cur = '';
      let inQuotes = false;
      for (let i = 0; i < line.length; i++) {
        const ch = line[i];
        if (ch === '"') {
          inQuotes = !inQuotes;
        } else if (ch === ',' && !inQuotes) {
          out.push(cur.trim().replace(/^["']|["']$/g, ''));
          cur = '';
        } else {
          cur += ch;
        }
      }
      out.push(cur.trim().replace(/^["']|["']$/g, ''));
      return out;
    }
    if (delim instanceof RegExp) {
      return line.split(delim).map(c => c.trim().replace(/^["']|["']$/g, ''));
    }
    return line.split(delim).map(c => c.trim().replace(/^["']|["']$/g, ''));
  };

  const lines = rawText
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(Boolean);

  if (lines.length === 0) {
    return { success: false, count: 0, holdings: {}, error: 'Empty content.' };
  }

  // Detect delimiter across the first 10 lines
  const sampleText = lines.slice(0, 10).join('\n');
  let delimiter = /\s+/;
  if (sampleText.includes('\t')) delimiter = '\t';
  else if (lines.some(l => (l.match(/,/g) || []).length >= 2)) delimiter = ',';
  else if (sampleText.includes('|')) delimiter = '|';
  else if (sampleText.includes(';')) delimiter = ';';

  const parsedRows = lines.map(line => splitLineSmart(line, delimiter));

  // Require BOTH symbol AND (qty OR rate) on the same line to qualify as a header row
  let headerIndex = -1;
  let colSymbol = -1;
  let colQty = -1;
  let colRate = -1;
  let colType = -1;

  for (let i = 0; i < Math.min(parsedRows.length, 15); i++) {
    const row = parsedRows[i];
    let symIdx = -1, qtyIdx = -1, rateIdx = -1, typeIdx = -1;

    row.forEach((cell, idx) => {
      const c = String(cell || '').toLowerCase().replace(/[^a-z0-9/ ]/g, '').trim();
      if (!c) return;
      if (symIdx === -1 && (c === 'symbol' || c === 'scrip' || c === 'script' || c === 'stock symbol' || c === 'security' || c.includes('symbol') || c.includes('scrip'))) {
        symIdx = idx;
      }
      if (qtyIdx === -1 && (c === 'trade qty' || c === 'traded qty' || c === 'qty' || c === 'quantity' || c === 'units' || c === 'kitta' || c === 'shares' || c.includes('qty') || c.includes('quantity'))) {
        qtyIdx = idx;
      }
      if (rateIdx === -1 && !c.includes('amount') && !c.includes('value') && (c === 'trade price' || c === 'price' || c === 'rate' || c === 'order price' || c === 'unit price' || c === 'wacc' || c === 'buy price' || c.includes('price') || c.includes('rate'))) {
        rateIdx = idx;
      }
      if (typeIdx === -1 && (c === 'transaction type' || c === 'type' || c === 'side' || c === 'buy/sell' || c === 'bs' || c === 'action' || c === 'order type')) {
        typeIdx = idx;
      }
    });

    if (symIdx !== -1 && (qtyIdx !== -1 || rateIdx !== -1)) {
      headerIndex = i;
      colSymbol = symIdx;
      colQty = qtyIdx;
      colRate = rateIdx;
      colType = typeIdx;
      break;
    }
  }

  const IGNORE_WORDS = new Set([
    'BUY', 'SELL', 'TOTAL', 'DATE', 'PRICE', 'QTY', 'RATE', 'CASH', 'NRB', 'NEPSE',
    'OPEN', 'CLOSE', 'HIGH', 'LOW', 'COMPLETED', 'FILLED', 'PARTIAL', 'CANCELLED',
    'EQ', 'EQUITY', 'NORMAL', 'CONTINUOUS', 'ODD', 'LOT', 'TMS', 'NRS', 'NPR'
  ]);

  const startRow = headerIndex >= 0 ? headerIndex + 1 : 0;
  const buyTransactionsByScrip = {};

  for (let i = startRow; i < parsedRows.length; i++) {
    const row = parsedRows[i];
    if (!row || row.length < 2) continue;

    let symbol = '';
    let qty = 0;
    let rate = 0;
    let isBuy = true;

    if (colSymbol !== -1 && colQty !== -1 && colRate !== -1 && row.length > Math.max(colSymbol, colQty, colRate)) {
      symbol = String(row[colSymbol] || '').toUpperCase().replace(/[^A-Z0-9]/g, '').trim();
      qty = parseFloat(String(row[colQty] || '').replace(/,/g, '')) || 0;
      rate = parseFloat(String(row[colRate] || '').replace(/,/g, '')) || 0;
      if (colType !== -1 && row[colType] !== undefined) {
        const typeStr = String(row[colType] || '').toUpperCase().trim();
        if (typeStr.includes('SELL') || typeStr === 'S' || typeStr === '2') isBuy = false;
      }
    } else {
      const upperRowText = row.join(' ').toUpperCase();
      if (/\bSELL\b/.test(upperRowText) && !/\bBUY\b/.test(upperRowText)) {
        isBuy = false;
      }

      for (const token of row) {
        const clean = String(token || '').trim().toUpperCase();
        if (/^[A-Z]{3,8}$/.test(clean) && !IGNORE_WORDS.has(clean)) {
          symbol = clean;
          break;
        }
      }

      // Filter out dates, times, 10-16 digit TMS Contract IDs, and leading S.N. indices
      const candidateNums = [];
      row.forEach((token, idx) => {
        const raw = String(token || '').trim();
        if (!raw) return;
        if (/^\d{4}[-/]\d{1,2}[-/]\d{1,2}/.test(raw) || /^\d{1,2}:\d{2}/.test(raw)) return;
        const cleanNumStr = raw.replace(/,/g, '');
        if (!/^-?\d+(\.\d+)?$/.test(cleanNumStr)) return;
        const n = parseFloat(cleanNumStr);
        if (isNaN(n) || n <= 0) return;
        if (n > 1000000000) return; // skip 10-16 digit TMS Contract numbers / BOIDs
        if (idx === 0 && row.length >= 4 && Number.isInteger(n) && n <= 500) return; // skip S.N.
        candidateNums.push(n);
      });

      if (candidateNums.length >= 2) {
        for (let a = 0; a < candidateNums.length; a++) {
          for (let b = a + 1; b < candidateNums.length; b++) {
            const n1 = candidateNums[a];
            const n2 = candidateNums[b];
            const product = n1 * n2;
            const hasAmountMatch = candidateNums.some((c, cIdx) => cIdx !== a && cIdx !== b && Math.abs(c - product) / Math.max(1, product) < 0.02);
            if (hasAmountMatch) {
              qty = n1;
              rate = n2;
              break;
            }
          }
          if (qty > 0 && rate > 0) break;
        }

        if (qty <= 0 || rate <= 0) {
          qty = candidateNums[0];
          rate = candidateNums[1];
        }
      }
    }

    if (symbol && symbol.length >= 2 && !IGNORE_WORDS.has(symbol) && isBuy && qty > 0 && rate >= 10 && rate <= 50000) {
      if (!buyTransactionsByScrip[symbol]) {
        buyTransactionsByScrip[symbol] = [];
      }
      buyTransactionsByScrip[symbol].push({ quantity: qty, price: rate });
    }
  }

  const holdings = {};
  let totalParsed = 0;

  for (const [sym, txs] of Object.entries(buyTransactionsByScrip)) {
    const waccResult = calculateWacc(txs);
    if (waccResult.totalQuantity > 0 && waccResult.wacc > 0) {
      holdings[sym] = {
        symbol: sym,
        wacc: Number(waccResult.wacc.toFixed(2)),
        totalQuantity: waccResult.totalQuantity,
        totalCost: Number(waccResult.totalCost.toFixed(2)),
        source: 'BROKER_TMS',
        transactionsCount: txs.length
      };
      totalParsed++;
    }
  }

  if (totalParsed === 0) {
    return {
      success: false,
      count: 0,
      holdings: {},
      error: 'Could not detect valid stock buy transactions. Paste your TMS Trade Book rows or simple "SYMBOL QTY PRICE" lines (e.g., NABIL 50 540).'
    };
  }

  return {
    success: true,
    count: totalParsed,
    holdings,
    message: `Successfully parsed ${totalParsed} scrips from TMS Trade Book.`
  };
}

/**
 * Resolves standard face value / base price based on scrip nature
 * Debentures in Nepal: Rs. 1,000 per unit
 * Mutual Funds: Rs. 10 per unit
 * Equity shares: Rs. 100 per unit
 */
export function guessScripBasePrice(symbol, fallback) {
  if (fallback && fallback > 0 && fallback !== 100) return fallback;
  const s = String(symbol || '').toUpperCase().trim();
  if (/D(8[0-9]|9[0-9]|[0-9]{2})$/.test(s) || s.includes('DEB') || s.includes('BOND')) return 1000;
  if (s.endsWith('PF') || s.endsWith('MF') || s.endsWith('SEF') || s.endsWith('MMF') || s.endsWith('BF') || s.endsWith('F3') || s.endsWith('F2')) return 10;
  return 100;
}

/**
 * Loads the user's custom secondary market WACC map from localStorage
 * Scoped by accountId when provided so multiple accounts holding the same stock don't collide.
 */
export function getCustomWaccMap(userId = 'local', accountId = '') {
  try {
    if (accountId) {
      const cleanAccId = String(accountId).trim().replace(/[^a-zA-Z0-9_-]/g, '_');
      const accRaw = localStorage.getItem(`nepse_hub_${userId}_acc_${cleanAccId}_custom_wacc_map`);
      return accRaw ? (JSON.parse(accRaw) || {}) : {};
    }
    const globalRaw = localStorage.getItem(`nepse_hub_${userId}_custom_wacc_map`) || localStorage.getItem('nepse_hub_custom_wacc_map');
    return globalRaw ? (JSON.parse(globalRaw) || {}) : {};
  } catch (e) {
    return {};
  }
}

/**
 * Purges dispensable transient caches (chart histories, floorsheets, fundamentals, news)
 * to reclaim megabytes of browser storage space without losing critical user profiles/transactions.
 */
export function purgeDispensableStorageCaches() {
  if (typeof window === 'undefined' || typeof localStorage === 'undefined') return 0;
  let purgedCount = 0;
  try {
    const expendable = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;
      if (
        k.includes('cache') ||
        k.includes('chart') ||
        k.includes('history') ||
        k.includes('hist_') ||
        k.includes('floorsheet') ||
        k.includes('broker') ||
        k.includes('fundamentals') ||
        k.includes('news') ||
        k.includes('smart_alert') ||
        k.includes('lru_ring') ||
        k.startsWith('temp_') ||
        k === 'prime_pick_plan_cache' ||
        k === 'nepse_paper_orders'
      ) {
        expendable.push(k);
      }
    }
    expendable.forEach(k => {
      try {
        localStorage.removeItem(k);
        purgedCount++;
      } catch (_) {}
    });
  } catch (_) {}
  return purgedCount;
}

/**
 * Safely saves data to localStorage, catching QuotaExceededError and automatically
 * purging non-critical caches (chart history, news, prime pick cache) to prevent crashes.
 */
export function safeStorageSetItem(key, value) {
  if (typeof window === 'undefined' || typeof localStorage === 'undefined') return false;
  const str = typeof value === 'string' ? value : JSON.stringify(value);
  try {
    localStorage.setItem(key, str);
    return true;
  } catch (err) {
    console.warn(`[SafeStorage] Quota exceeded for '${key}'. Purging dispensable caches...`);
    try {
      purgeDispensableStorageCaches();
      localStorage.setItem(key, str);
      return true;
    } catch (innerErr) {
      console.error(`[SafeStorage Critical] Failed setting '${key}' even after cache eviction:`, innerErr);
      return false;
    }
  }
}

/**
 * Strips a holding object down to essential storage attributes, eliminating
 * volatile UI fields (signals, advice, raw nested CDSC payloads) to prevent quota blowups.
 */
export function stripHoldingForStorage(h) {
  if (!h || typeof h !== 'object') return null;
  const symbol = String(h.symbol || h.script || h.scrip || '').trim().toUpperCase();
  if (!symbol) return null;
  return {
    symbol,
    name: String(h.name || h.scriptDesc || h.companyName || symbol).trim(),
    units: Number(h.units || h.currentBalance || h.totalUnits || 0),
    wacc: Number(Number(h.wacc || 100).toFixed(2)),
    waccSource: h.waccSource || 'FALLBACK_BASE_PRICE',
    isCustomWacc: Boolean(h.isCustomWacc),
    currentLtp: Number(h.currentLtp || h.lastTransactionPrice || 0),
    prevClose: Number(h.prevClose || h.previousClosingPrice || 0),
    valueAsOfLTP: Number(h.valueAsOfLTP || 0),
    valueAsOfPrevClose: Number(h.valueAsOfPrevClose || 0),
    freeBalance: Number(h.freeBalance ?? h.units ?? 0),
    frozenBalance: Number(h.frozenBalance || h.freezeBalance || 0)
  };
}

/**
 * Saves a custom secondary market WACC map to localStorage
 * Scoped by accountId when provided.
 */
export function saveCustomWaccMap(waccMap, userId = 'local', accountId = '') {
  try {
    if (accountId) {
      const cleanAccId = String(accountId).trim().replace(/[^a-zA-Z0-9_-]/g, '_');
      const key = `nepse_hub_${userId}_acc_${cleanAccId}_custom_wacc_map`;
      safeStorageSetItem(key, waccMap);
    } else {
      const key = `nepse_hub_${userId}_custom_wacc_map`;
      safeStorageSetItem(key, waccMap);
      safeStorageSetItem('nepse_hub_custom_wacc_map', waccMap);
    }
  } catch (e) {
    console.error("Failed to save custom WACC map:", e);
  }
}

/**
 * Updates or sets WACC for a specific symbol, optionally scoped to a specific Demat account and source tag
 */
export function setScripCustomWacc(symbol, wacc, userId = 'local', accountId = '', source = 'CUSTOM_USER_SET') {
  const map = getCustomWaccMap(userId, accountId);
  const sym = String(symbol || '').trim().toUpperCase();
  if (sym && Number(wacc) > 0) {
    map[sym] = { wacc: Number(Number(wacc).toFixed(2)), source };
    saveCustomWaccMap(map, userId, accountId);
  }
  return map;
}

/**
 * Merges discovered WACC rates from CDSC into user's custom WACC map, optionally scoped to account
 */
export function applyDiscoveredWaccMap(discoveredMap = {}, userId = 'local', accountId = '') {
  if (!discoveredMap || typeof discoveredMap !== 'object') return getCustomWaccMap(userId, accountId);
  const currentMap = getCustomWaccMap(userId, accountId);
  let updated = false;

  for (const [sym, data] of Object.entries(discoveredMap)) {
    const cleanSym = String(sym || '').trim().toUpperCase();
    const rate = typeof data === 'object' ? Number(data.wacc) : Number(data);
    if (cleanSym && rate > 0) {
      currentMap[cleanSym] = Number(rate.toFixed(2));
      updated = true;
    }
  }

  if (updated) {
    saveCustomWaccMap(currentMap, userId, accountId);
  }
  return currentMap;
}

/**
 * Evaluates quantitative action signals (Breakout, Book Profit, Stop Loss, Hold)
 * for a portfolio holding based on cost basis, live market metrics, and technical setup.
 */
export function classifyHoldingActionSignal(holding, marketStock = null, plan = null) {
  if (!holding) return null;

  const wacc = Number(holding.wacc || 0);
  const currentPrice = Number(holding.currentPrice || holding.currentLtp || marketStock?.ltp || 0);
  const pChange = Number(marketStock?.pChange || marketStock?.percentageChange || 0);
  const rvol = Number(
    marketStock?.rvol || 
    marketStock?.volumeSurgeRatio || 
    (marketStock?.volume && marketStock?.avgVolume ? (marketStock.volume / marketStock.avgVolume) : 
    (marketStock?.volume && marketStock?.averageVolume ? (marketStock.volume / marketStock.averageVolume) : 1))
  );
  const rsi = Number(marketStock?.rsi || (50 + Math.max(-25, Math.min(25, (pChange * 3.5)))));

  const gainPct = wacc > 0 && currentPrice > 0 
    ? ((currentPrice - wacc) / wacc) * 100 
    : Number(holding.plPercent || 0);

  // 1. Target 2 Super Gain (Gain >= 25% or above Target 2)
  if (gainPct >= 25.0 || (plan?.levels?.target2?.price && currentPrice >= Number(plan.levels.target2.price))) {
    return {
      type: 'SUPER_GAIN',
      category: 'profit',
      label: 'TARGET 2 REACHED',
      badge: `🏆 Super Gain (+${gainPct.toFixed(1)}%)`,
      action: 'Secure 75% Profit',
      color: '#10b981',
      bg: 'rgba(16, 185, 129, 0.15)',
      border: 'rgba(16, 185, 129, 0.35)',
      icon: 'trophy',
      advice: 'Target 2 reached! Take 75% profit off the table and let the remaining 25% ride with a trailing stop.'
    };
  }

  // 2. Target 1 Book Profit (Gain >= 12% or above Target 1)
  if (gainPct >= 12.0 || (plan?.levels?.target1?.price && currentPrice >= Number(plan.levels.target1.price))) {
    return {
      type: 'BOOK_PROFIT',
      category: 'profit',
      label: 'BOOK 50% PROFIT',
      badge: `🎯 Book Profit (+${gainPct.toFixed(1)}%)`,
      action: 'Sell 50% & Trail Stop',
      color: '#34d399',
      bg: 'rgba(16, 185, 129, 0.12)',
      border: 'rgba(16, 185, 129, 0.3)',
      icon: 'target',
      advice: 'Zero-Loss Rule: Sell 50% here to lock in solid alpha, then trail your stop loss to your entry price.'
    };
  }

  // 3. Stop Loss Violation (Loss >= 8% or below Entry/Exit plan Stop Loss)
  if (gainPct <= -8.0 || (plan?.levels?.stopLoss?.price && currentPrice <= Number(plan.levels.stopLoss.price))) {
    return {
      type: 'STOP_LOSS',
      category: 'risk',
      label: 'STOP LOSS RISK',
      badge: `🛑 Stop Loss (${gainPct.toFixed(1)}%)`,
      action: 'Capital Defense Exit',
      color: '#f43f5e',
      bg: 'rgba(244, 63, 94, 0.15)',
      border: 'rgba(244, 63, 94, 0.35)',
      icon: 'shield-alert',
      advice: 'Downside risk limit breached. Cut loss or hedge immediately to preserve capital and prevent compounding drawdown.'
    };
  }

  // 4. Heavy Selling Pressure Warning
  if (gainPct < -3.0 && pChange <= -3.5) {
    return {
      type: 'DEFENSE_ALERT',
      category: 'risk',
      label: 'DEFENSE ALERT',
      badge: `⚠️ Selling Pressure (${pChange.toFixed(1)}%)`,
      action: 'Tighten Stop Loss',
      color: '#fb7185',
      bg: 'rgba(251, 113, 133, 0.12)',
      border: 'rgba(251, 113, 133, 0.3)',
      icon: 'alert-triangle',
      advice: 'Heavy distribution observed today. Tighten your stop loss to protect against gap-downs.'
    };
  }

  // 5. Breakout Volume Surge (RVOL >= 1.5x and Price >= +2.0%)
  if (rvol >= 1.5 && pChange >= 2.0) {
    return {
      type: 'BREAKOUT',
      category: 'opportunity',
      label: 'BREAKOUT SURGE',
      badge: `🚀 Breakout (${rvol.toFixed(1)}x Vol)`,
      action: 'Opportunity to Add',
      color: '#fbbf24',
      bg: 'rgba(245, 158, 11, 0.15)',
      border: 'rgba(245, 158, 11, 0.35)',
      icon: 'flame',
      advice: 'High institutional buying surge detected with RVOL > 1.5x. Good momentum candidate to scale in.'
    };
  }

  // 6. Upward Accumulation Setup (Healthy RSI and Positive Trend)
  if (rsi >= 55 && rsi <= 68 && pChange > 0) {
    return {
      type: 'ACCUMULATE',
      category: 'opportunity',
      label: 'ACCUMULATE',
      badge: '🟢 Accumulate',
      action: 'Buy on Pullback',
      color: '#38bdf8',
      bg: 'rgba(56, 189, 248, 0.12)',
      border: 'rgba(56, 189, 248, 0.3)',
      icon: 'trending-up',
      advice: 'Constructive bullish structure. Quality consolidation setup suitable for gradual accumulation.'
    };
  }

  // 7. Profitable Position Trend Intact (Hold & Ride)
  if (gainPct > 0) {
    return {
      type: 'HOLD_RIDE',
      category: 'hold',
      label: 'HOLD & RIDE',
      badge: `🛡️ Trend Intact (+${gainPct.toFixed(1)}%)`,
      action: 'Ride Trend',
      color: '#60a5fa',
      bg: 'rgba(96, 165, 250, 0.12)',
      border: 'rgba(96, 165, 250, 0.3)',
      icon: 'shield-check',
      advice: 'Position is green and trading healthily above cost. Continue holding with an upward trailing stop.'
    };
  }

  // 8. Normal Consolidation / Rangebound
  return {
    type: 'HOLD_WAIT',
    category: 'hold',
    label: 'HOLD / WAIT',
    badge: '⏸️ Hold & Watch',
    action: 'Watch Support',
    color: '#94a3b8',
    bg: 'rgba(148, 163, 184, 0.1)',
    border: 'rgba(148, 163, 184, 0.25)',
    icon: 'clock',
    advice: 'Price consolidating within normal volatility bounds. Maintain risk discipline.'
  };
}

/**
 * Sanitizes and repairs MeroShare holdings records with full CDSC field compatibility
 * and preserves user's secondary market custom WACC rates and CDSC origin tiers.
 * Scoped by accountId when provided.
 */
export function sanitizeMeroShareHoldings(holdings = [], userId = 'local', accountId = '') {
  if (!Array.isArray(holdings)) return [];
  const customMap = getCustomWaccMap(userId, accountId);

  return holdings.map(h => {
    const symbol = (h.symbol || h.script || h.scrip || '').trim().toUpperCase();
    const units = Number(h.units || h.totalUnits || h.currentBalance || h.dematQty || 0);
    const freeBalance = Number(h.freeBalance ?? units);
    const frozenBalance = Number(h.freezeBalance || h.frozenBalance || 0);
    const base = guessScripBasePrice(symbol, h.wacc || h.purchasePrice);

    const ltpRaw = Number(h.lastTransactionPrice || h.lastTradedPrice || h.currentLtp || h.ltp || h.currentPrice || 0);
    const prevCloseRaw = Number(h.previousClosingPrice || h.closingPrice || h.prevClose || h.prevClosingPrice || 0);

    const currentLtp = ltpRaw > 0 ? ltpRaw : (prevCloseRaw > 0 ? prevCloseRaw : base);
    const prevClose = prevCloseRaw > 0 ? prevCloseRaw : currentLtp;

    const valLtpRaw = Number(h.valueAsOfLastTransactionPrice || h.valueOfLastTransactionPrice || h.valueAsOfLTP || h.totalAmount || h.totalValue || 0);
    const valCloseRaw = Number(h.valueAsOfPreviousClosingPrice || h.valueOfPreviousClosingPrice || h.valueAsOfPrevClose || 0);

    const valueAsOfLTP = valLtpRaw > 0 ? valLtpRaw : Number((units * currentLtp).toFixed(2));
    const valueAsOfPrevClose = valCloseRaw > 0 ? valCloseRaw : Number((units * prevClose).toFixed(2));
    const currentMarketValue = valueAsOfLTP > 0 ? valueAsOfLTP : (units * currentLtp);

    // Custom secondary market WACC priority & origin classification:
    let wacc = base;
    let waccSource = 'FALLBACK_BASE_PRICE';

    const customEntry = customMap[symbol];
    const customRate = (customEntry && typeof customEntry === 'object') ? Number(customEntry.wacc) : Number(customEntry);
    const customSource = (customEntry && typeof customEntry === 'object' && customEntry.source) ? customEntry.source : 'CUSTOM_USER_SET';

    if (customRate > 0) {
      wacc = customRate;
      waccSource = customSource;
    } else if (h.waccSource === 'CDSC_MY_HOLDING_DECLARED' || h.source === 'CDSC_MY_HOLDING_DECLARED') {
      wacc = Number(h.wacc || h.purchasePrice || base);
      waccSource = 'CDSC_MY_HOLDING_DECLARED';
    } else if (h.waccSource === 'BROKER_TMS' || h.source === 'BROKER_TMS') {
      wacc = Number(h.wacc || h.purchasePrice || base);
      waccSource = 'BROKER_TMS';
    } else if (h.waccSource && String(h.waccSource).startsWith('ESTIMATED_')) {
      wacc = Number(h.wacc || base);
      waccSource = h.waccSource;
    } else if (h.waccSource === 'CDSC_PURCHASE_SOURCE_UNCONFIRMED' || h.source === 'CDSC_PURCHASE_SOURCE_UNCONFIRMED') {
      wacc = Number(h.wacc || h.purchasePrice || base);
      waccSource = 'CDSC_PURCHASE_SOURCE_UNCONFIRMED';
    } else if (h.waccSource === 'IPO_ALLOTMENT' || h.source === 'IPO_ALLOTMENT' || h.isIPO || h.isAllotted) {
      wacc = Number(h.wacc || base);
      waccSource = 'IPO_ALLOTMENT';
    } else if (h.isCustomWacc && Number(h.wacc) > 0) {
      wacc = Number(h.wacc);
      waccSource = h.waccSource || 'CUSTOM_USER_SET';
    } else if (h.wacc && Number(h.wacc) > 0 && Number(h.wacc) !== 100) {
      wacc = Number(h.wacc);
      waccSource = 'CUSTOM_USER_SET';
    } else if (h.purchasePrice && Number(h.purchasePrice) > 0 && Number(h.purchasePrice) !== 100) {
      wacc = Number(h.purchasePrice);
      waccSource = 'CUSTOM_USER_SET';
    } else {
      // If base is 10 (Mutual fund) or 1000 (Debenture)
      if (base === 10) waccSource = 'NAV_PAR_FUND';
      else if (base === 1000) waccSource = 'PAR_VALUE_DEB';
      else waccSource = 'FALLBACK_BASE_PRICE';
    }

    const totalInvestment = Number((units * wacc).toFixed(2));
    const profitLoss = Number((currentMarketValue - totalInvestment).toFixed(2));
    const plPercent = totalInvestment > 0 ? Number(((profitLoss / totalInvestment) * 100).toFixed(2)) : 0;

    return {
      symbol,
      name: h.name || h.scriptDesc || h.companyName || symbol,
      units,
      totalUnits: units,
      freeBalance,
      frozenBalance,
      currentLtp,
      prevClose,
      valueAsOfLTP,
      valueAsOfPrevClose,
      currentMarketValue,
      totalInvestment,
      profitLoss,
      plPercent,
      wacc: Number(wacc.toFixed(2)),
      waccSource,
      isCustomWacc: Boolean(waccSource !== 'FALLBACK_BASE_PRICE')
    };
  }).filter(h => h.symbol && h.units > 0);
}

