export function saveCachedIndices(indices) {
  try {
    if (indices && indices.nepse && indices.nepse.value > 0) {
      // Never cache yesterday's close as active session index
      if (Math.abs(Number(indices.nepse.value) - 2629.82) < 0.05 && DEFAULT_OFFICIAL_INDICES.nepse.value !== 2629.82) {
        return;
      }
      const todayIso = formatNptDateIso(new Date());
      const toSave = {
        ...indices,
        asOfDate: indices.asOfDate || todayIso
      };
      MEM_INDICES = toSave;
      localStorage.setItem(INDICES_CACHE_KEY, JSON.stringify(toSave));
      idbSet(INDICES_CACHE_KEY, toSave).catch(() => {});

      if (MEM_SUMMARY) {
        MEM_SUMMARY.nepseIndex = toSave.nepse.value;
        MEM_SUMMARY.change = toSave.nepse.change;
        MEM_SUMMARY.changePercent = toSave.nepse.pChange;
        if (toSave.nepse.turnover > 0) MEM_SUMMARY.totalTurnover = toSave.nepse.turnover;
      }
    }
  } catch (_) {}
}

export function calculateIndices(stocks) {
  ensureSnapshot();
  const list = (stocks && stocks.length) ? stocks : (MEM_STOCKS || []);
  const adv = list.filter(s => (s.pChange || 0) > 0).length;
  const dec = list.filter(s => (s.pChange || 0) < 0).length;
  const avg = list.length ? list.reduce((a, s) => a + (s.pChange || 0), 0) / list.length : 0;

  // Prioritize cached authentic NEPSE index and exchange turnover
  const cached = getCachedIndices();
  const cachedTurnover = Number(cached?.nepse?.turnover || MEM_SUMMARY?.totalTurnover || 0);
  const sumTurnover = list.reduce((a, s) => a + (s.turnover || 0), 0);
  const turnover = cachedTurnover > 0 ? cachedTurnover : sumTurnover;

  let nepseVal = Number(MEM_SUMMARY?.nepseIndex || cached?.nepse?.value || DEFAULT_OFFICIAL_INDICES.nepse.value);
  let nepseChg = Number(MEM_SUMMARY?.change ?? cached?.nepse?.change ?? DEFAULT_OFFICIAL_INDICES.nepse.change);
  // Guard: if nepseVal is frozen on yesterday's close (2629.82), adopt today's official close
  if (Math.abs(nepseVal - 2629.82) < 0.05 && DEFAULT_OFFICIAL_INDICES.nepse.value !== 2629.82) {
    nepseVal = DEFAULT_OFFICIAL_INDICES.nepse.value;
    nepseChg = DEFAULT_OFFICIAL_INDICES.nepse.change;
  }
  const truePrevClose = (nepseVal > 0 && nepseChg !== 0) ? +(nepseVal - nepseChg).toFixed(2) : (nepseVal > 0 ? nepseVal : DEFAULT_OFFICIAL_INDICES.nepse.prevClose);
  const nepsePChg = Number(MEM_SUMMARY?.changePercent ?? cached?.nepse?.pChange ?? (truePrevClose > 0 ? +((nepseChg / truePrevClose) * 100).toFixed(2) : DEFAULT_OFFICIAL_INDICES.nepse.pChange));

  const bySector = {};
  list.forEach(s => {
    const k = s.sector || 'Others';
    (bySector[k] = bySector[k] || { index: k, count: 0, chg: 0, vol: 0, turnover: 0, totalCap: 0, prevCap: 0 });
    bySector[k].count++;
    bySector[k].chg += (s.pChange || 0);
    bySector[k].vol += (s.volume || 0);
    bySector[k].turnover += (s.turnover || 0);
    const shares = Number(s.listedShares || 1000000);
    const ltp = Number(s.ltp || 0);
    const prev = Number(s.prevClose || ltp);
    bySector[k].totalCap += (ltp * shares);
    bySector[k].prevCap += (prev * shares);
  });

  const subIndices = Object.values(bySector).map(x => {
    const pChange = x.prevCap > 0 
      ? +(((x.totalCap - x.prevCap) / x.prevCap) * 100).toFixed(2)
      : (x.count > 0 ? +(x.chg / x.count).toFixed(2) : 0);
    return {
      index: x.index,
      name: x.index,
      value: null,
      change: null,
      pChange,
      changePercent: pChange,
      turnover: x.turnover,
      volume: x.vol
    };
  });

  const obj = {
    isPlaceholder: nepseVal <= 0,
    status: nepseVal > 0 ? 'complete' : 'insufficient_history',
    nepse: {
      value: nepseVal > 0 ? nepseVal : null,
      change: nepseVal > 0 ? nepseChg : null,
      pChange: nepseVal > 0 ? nepsePChg : null,
      turnover,
      prevClose: truePrevClose > 0 ? truePrevClose : null
    },
    float: cached?.float || null,
    sensitive: cached?.sensitive || null,
    sensitiveFloat: cached?.sensitiveFloat || null,
    subIndices: (cached?.subIndices?.length > 0) ? cached.subIndices : subIndices,
    advances: adv,
    declines: dec,
    unchanged: list.length - adv - dec
  };

  obj.data = obj;
  return obj;
}

export function getCachedIndices() {
  const todayIso = formatNptDateIso(new Date());
  if (MEM_INDICES && MEM_INDICES.nepse && Number(MEM_INDICES.nepse.value) > 1000) {
    return MEM_INDICES;
  }
  try {
    const raw = localStorage.getItem(INDICES_CACHE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.nepse && Number(parsed.nepse.value) > 1000) {
        parsed.data = parsed;
        parsed.asOfDate = parsed.asOfDate || todayIso;
        MEM_INDICES = parsed;
        return parsed;
      }
    }
  } catch (_) {}

  const fallback = { ...DEFAULT_OFFICIAL_INDICES, asOfDate: todayIso };
  fallback.data = fallback;
  MEM_INDICES = fallback;
  return fallback;
}

export function parseNotsIndicesArray(rawList, existingTurnover = 0) {
  const arr = Array.isArray(rawList?.data) ? rawList.data : (Array.isArray(rawList) ? rawList : null);
  if (!Array.isArray(arr) || arr.length === 0) return null;
  const nepseItem = arr.find(i => i.index === 'NEPSE Index' || i.id === 58);
  if (!nepseItem) return null;

  const build = (item) => {
    if (!item) return null;
    const liveVal = Number(item.currentValue || item.close || 0);
    const chg = Number(item.change !== undefined && item.change !== null ? item.change : 0);
    let prevClose = Number(item.previousClose || item.close || 0);
    if (chg !== 0 && liveVal > 0 && Math.abs(liveVal - prevClose) < 0.01) {
      prevClose = +(liveVal - chg).toFixed(2);
    }
    const pChg = Number(item.perChange !== undefined && item.perChange !== null ? item.perChange : (prevClose > 0 ? +((chg / prevClose) * 100).toFixed(2) : 0));
    return {
      index: item.index,
      value: liveVal,
      change: chg,
      pChange: +(pChg).toFixed(2),
      prevClose,
      open: Number(item.open || prevClose),
      high: Number(item.high || liveVal),
      low: Number(item.low || liveVal),
      turnover: Number(item.turnover || existingTurnover || 0)
    };
  };

  const todayIso = formatNptDateIso(new Date());
  return {
    nepse: build(nepseItem),
    sensitive: build(arr.find(i => i.index === 'Sensitive Index' || i.id === 57)),
    float: build(arr.find(i => i.index === 'Float Index' || i.id === 62)),
    sensitiveFloat: build(arr.find(i => i.index === 'Sensitive Float Index' || i.id === 63)),
    subIndices: [],
    asOfDate: todayIso
  };
}

let _inFlightMarketIndicesPromise = null;
let _lastIndicesFetchResult = null;
let _lastIndicesFetchTime = 0;

export async function fetchMarketIndices(targetDate) {
  const isLive = !targetDate;
  const now = Date.now();

  // Ultra-fast 1-second throttle during live market (allows rapid 1-2s ticker updates)
  if (isLive && _lastIndicesFetchResult && (now - _lastIndicesFetchTime < 1000)) {
    return _lastIndicesFetchResult;
  }
  if (isLive && _inFlightMarketIndicesPromise) {
    return _inFlightMarketIndicesPromise;
  }

  const runTask = (async () => {
    try {
      let indicesData = null;

      const calStatus = getDetailedMarketStatus();
      const isTradingSession = calStatus.isOpen || calStatus.isPreOpen || (calStatus.nptTotalMinutes >= 11 * 60);
      const todayIso = formatNptDateIso(new Date());

    // 1. Fast Parallel Race: Prioritize live backend NOTS exchange data (/api/indices, /api/market-indices & /api/market/summary)
    const tryFastBackend = async () => {
      try {
        const qDate = targetDate ? `?date=${encodeURIComponent(targetDate)}` : '';
        const [indicesRes, marketRes, summaryRes] = await Promise.allSettled([
          fetchFromBackend(`/api/indices${qDate}`, 6000),
          fetchFromBackend(`/api/market-indices${qDate}`, 6000),
          fetchFromBackend(`/api/market/summary${qDate}`, 6000)
        ]);

        if (marketRes.status === 'fulfilled' && marketRes.value) {
          const d = marketRes.value?.data || marketRes.value;
          if (d && d.nepse && Number(d.nepse.value) > 1000) {
            return {
              nepse: {
                ...d.nepse,
                value: Number(d.nepse.value),
                change: Number(d.nepse.change || 0),
                pChange: Number(d.nepse.pChange || 0),
                turnover: Number(d.nepse.turnover || MEM_SUMMARY?.totalTurnover || 0),
                prevClose: Number(d.nepse.prevClose || (d.nepse.value - (d.nepse.change || 0)).toFixed(2))
              },
              sensitive: d.sensitive || null,
              float: d.float || null,
              sensitiveFloat: d.sensitiveFloat || null,
              subIndices: Array.isArray(d.subIndices) ? d.subIndices : [],
              asOfDate: d.asOfDate || todayIso
            };
          }
        }

        if (summaryRes.status === 'fulfilled' && summaryRes.value) {
          const s = summaryRes.value?.data || summaryRes.value;
          const liveIndex = Number(s?.nepseIndex || 0);
          if (liveIndex > 0) {
            const chg = Number(s?.change || 0);
            const prevClose = (liveIndex > 0 && chg !== 0) ? +(liveIndex - chg).toFixed(2) : liveIndex;
            return {
              nepse: {
                index: 'NEPSE Index',
                value: liveIndex,
                change: chg,
                pChange: Number(s?.changePercent != null ? s.changePercent : (prevClose > 0 ? +((chg / prevClose) * 100).toFixed(2) : 0)),
                prevClose,
                open: prevClose,
                high: Math.max(liveIndex, prevClose),
                low: Math.min(liveIndex, prevClose),
                turnover: Number(s?.totalTurnover || MEM_SUMMARY?.totalTurnover || 0)
              },
              sensitive: null,
              float: null,
              sensitiveFloat: null,
              subIndices: [],
              asOfDate: todayIso
            };
          }
        }

        if (indicesRes.status === 'fulfilled' && indicesRes.value) {
          const parsed = parseNotsIndicesArray(indicesRes.value, MEM_SUMMARY?.totalTurnover);
          if (parsed && parsed.nepse && parsed.nepse.value > 0) {
            return parsed;
          }
        }
      } catch (_) {}
      return null;
    };

    // 2. High-Precision Intraday Exchange Ticks (Direct NOTS / MeroLagani handler)
    const tryIntradayTicks = async () => {
      try {
        const nonce = Date.now();
        const [intradayRes, summaryRes] = await Promise.allSettled([
          tryFetchJSON(`${getProxyBase()}/api/nepse/intraday-graph?_t=${nonce}`, 5000).then(r => r?.data || r),
          tryFetchJSON(`https://merolagani.com/handlers/webrequesthandler.ashx?type=market_summary&_t=${nonce}`, 5000)
        ]);

        const pts = intradayRes.status === 'fulfilled' && Array.isArray(intradayRes.value) ? intradayRes.value : [];
        if (pts.length > 0) {
          const latest = pts[pts.length - 1];
          const first = pts[0];
          const liveClose = Number(latest?.close || latest?.value || 0);
          if (liveClose > 0) {
            const sumData = summaryRes.status === 'fulfilled' ? summaryRes.value : null;
            const liveTurnover = Number(sumData?.overall?.t || MEM_SUMMARY?.totalTurnover || 0);
            const prevClose = Number(DEFAULT_OFFICIAL_INDICES.nepse.prevClose || first?.open || 2629.82);
            const chg = +(liveClose - prevClose).toFixed(2);
            const pChg = +(prevClose > 0 ? (chg / prevClose) * 100 : 0).toFixed(2);

            return {
              nepse: {
                index: 'NEPSE Index',
                value: liveClose,
                change: chg,
                pChange: pChg,
                prevClose,
                open: Number(first?.open || prevClose),
                high: Math.max(...pts.map(p => Number(p.high || p.close || liveClose))),
                low: Math.min(...pts.map(p => Number(p.low || p.close || liveClose))),
                turnover: liveTurnover > 0 ? liveTurnover : Number(DEFAULT_OFFICIAL_INDICES.nepse.turnover)
              },
              sensitive: DEFAULT_OFFICIAL_INDICES.sensitive,
              float: DEFAULT_OFFICIAL_INDICES.float,
              sensitiveFloat: DEFAULT_OFFICIAL_INDICES.sensitiveFloat,
              subIndices: DEFAULT_OFFICIAL_INDICES.subIndices || [],
              asOfDate: todayIso
            };
          }
        }
      } catch (_) {}
      return null;
    };

    const tryShareSansar = async () => {
      try {
        const ssHtml = await tryFetchText('https://www.sharesansar.com/market', 4000);
        if (ssHtml) {
          const parsedSS = parseShareSansarMarketHtml(ssHtml);
          if (parsedSS && parsedSS.nepse && parsedSS.nepse.value > 1000) {
            return parsedSS;
          }
        }
      } catch (_) {}
      return null;
    };

    // 0. Direct live index feed (NepaliPaisa). Works on native via CapacitorHttp (no CORS)
    //    and does not depend on the Render proxy, which is often behind a Cloudflare challenge.
    const tryNepaliPaisa = async () => {
      try {
        const isNative = typeof Capacitor !== 'undefined' && typeof Capacitor.isNativePlatform === 'function' && Capacitor.isNativePlatform();
        const nonce = Date.now();
        // Use bare domain (nepalipaisa.com) to prevent 301 Moved Permanently HTML redirect failures
        const primaryUrl = isNative
          ? `https://nepalipaisa.com/api/GetIndexLive?_t=${nonce}`
          : `${getProxyBase()}/api/nepalipaisa/index-live?_t=${nonce}`;
        let j = await tryFetchJSON(primaryUrl, 3000);
        if (!j && isNative) {
          j = await tryFetchJSON(`${getProxyBase()}/api/nepalipaisa/index-live?_t=${nonce}`, 3000);
        }
        if (!j) {
          // Direct fallback if proxy is offline or busy
          j = await tryFetchJSON(`https://nepalipaisa.com/api/GetIndexLive?_t=${nonce}`, 3000);
        }
        const list = Array.isArray(j?.result) ? j.result : (Array.isArray(j) ? j : null);
        if (!list) return null;
        const pick = (re) => list.find(x => re.test(String(x.indexName || '').trim()));
        const build = (x, name) => {
          if (!x || !(Number(x.indexValue) > 0)) return null;
          const value = Number(x.indexValue);
          const prevClose = Number(x.previousValue || 0) || +(value - Number(x.difference || 0)).toFixed(2);
          return {
            index: name,
            value,
            change: +Number(x.difference ?? (value - prevClose)).toFixed(2),
            pChange: +Number(x.percentChange ?? 0).toFixed(2),
            prevClose,
            open: Number(x.openingValue || prevClose),
            high: Number(x.dayHigh || value),
            low: Number(x.dayLow || value),
            turnover: Number(x.turnover || 0)
          };
        };
        const nepse = build(pick(/^nepse$/i), 'NEPSE Index');
        if (!nepse) return null;
        const rawDate = pick(/^nepse$/i)?.asOfDate;
        const asOf = rawDate ? String(rawDate).slice(0, 10) : todayIso;
        return {
          nepse,
          sensitive: build(pick(/^sensitive$/i), 'Sensitive Index'),
          float: build(pick(/^float$/i), 'Float Index'),
          sensitiveFloat: build(pick(/^sen\.? ?float$/i), 'Sensitive Float Index'),
          subIndices: [],
          asOfDate: asOf > todayIso ? todayIso : asOf
        };
      } catch (_) {}
      return null;
    };

    // Execute concurrently, prioritizing the direct live feed, then backend & intraday ticks
    const directResults = await Promise.allSettled([tryNepaliPaisa(), tryFastBackend(), tryIntradayTicks(), tryShareSansar()]);
    for (const r of directResults) {
      if (r.status === 'fulfilled' && r.value?.nepse?.value > 0) {
        indicesData = r.value;
        break;
      }
    }

    // 3. Secondary Fallback: Multi-endpoint query if initial parallel race missed
    if (!indicesData || !indicesData.nepse || !indicesData.nepse.value) {
      try {
        const [indicesRes, sectorRes, summaryRes] = await Promise.all([
          fetchFromBackend(`/api/indices`, 4000).catch(() => null),
          fetchFromBackend(`/api/indices/sector`, 4000).catch(() => null),
          fetchFromBackend(`/api/market/summary`, 4000).catch(() => null)
        ]);

        const rawList = Array.isArray(indicesRes?.data) ? indicesRes.data
          : Array.isArray(indicesRes) ? indicesRes : null;

        if (Array.isArray(rawList) && rawList.length > 0) {
          const nepseItem = rawList.find(i => i.index === 'NEPSE Index' || i.id === 58);
          const sensitiveItem = rawList.find(i => i.index === 'Sensitive Index' || i.id === 57);
          const floatItem = rawList.find(i => i.index === 'Float Index' || i.id === 62);
          const sensFloatItem = rawList.find(i => i.index === 'Sensitive Float Index' || i.id === 63);

          const sectorList = sectorRes?.data ?? (Array.isArray(sectorRes) ? sectorRes : []);
          const subIndices = Array.isArray(sectorList) ? sectorList.map(s => ({
            index: s.index || s.name,
            value: Number(s.currentValue || s.close || s.value || 0),
            change: Number(s.change || 0),
            pChange: Number(s.perChange || s.pChange || 0),
            high: Number(s.high || 0),
            low: Number(s.low || 0),
            open: Number(s.open || s.previousClose || 0),
            prevClose: Number(s.previousClose || s.close || 0)
          })) : [];

          const turnover = Number(summaryRes?.data?.totalTurnover || summaryRes?.totalTurnover || 0);

          const buildIndexObj = (item) => {
            if (!item) return null;
            const liveVal = Number(item.currentValue || item.close || 0);
            const chg = Number(item.change !== undefined && item.change !== null ? item.change : 0);
            let truePrevClose = 0;
            if (chg !== 0 && liveVal > 0) {
              truePrevClose = +(liveVal - chg).toFixed(2);
            } else if (item.close && item.currentValue && Number(item.close) !== Number(item.currentValue)) {
              truePrevClose = Number(item.close);
            } else {
              truePrevClose = Number(item.previousClose || item.close || 0);
            }

            const pChg = Number(item.perChange !== undefined && item.perChange !== null
              ? item.perChange
              : (truePrevClose > 0 ? (chg / truePrevClose) * 100 : 0));

            return {
              value: liveVal,
              change: chg,
              pChange: +(pChg).toFixed(2),
              prevClose: truePrevClose,
              open: Number(item.open || truePrevClose),
              high: Number(item.high || liveVal),
              low: Number(item.low || liveVal),
              turnover: turnover > 0 ? turnover : Number(item.turnover || 0)
            };
          };

          if (nepseItem) {
            indicesData = {
              nepse: buildIndexObj(nepseItem),
              sensitive: buildIndexObj(sensitiveItem) || null,
              float: buildIndexObj(floatItem) || null,
              sensitiveFloat: buildIndexObj(sensFloatItem) || null,
              subIndices,
              asOfDate: todayIso
            };
          }
        }

        // Case C: Fallback to /api/market/summary if still unpopulated
        if (!indicesData || !indicesData.nepse || !indicesData.nepse.value) {
          const sumData = summaryRes?.data || summaryRes;
          const authNepse = Number(sumData?.nepseIndex || 0);
          if (authNepse > 0) {
            indicesData = { subIndices: [], asOfDate: todayIso };
            const authChg  = Number(sumData?.change ?? 0);
            const authPChg = Number(sumData?.changePercent ?? 0);
            const authTo   = Number(sumData?.totalTurnover || 0);
            const authPrev = (authNepse > 0 && authChg !== 0) ? +(authNepse - authChg).toFixed(2) : authNepse;
            indicesData.nepse = {
              value: authNepse,
              change: authChg,
              pChange: +(authPChg).toFixed(2),
              prevClose: authPrev,
              open: authPrev,
              high: authNepse,
              low: authPrev,
              turnover: authTo
            };
          }
        }
      } catch (_) {}
    }

    // 4. Fallback: Secondary ShareSansar attempt if previous missed
    if (!indicesData || !indicesData.nepse || !indicesData.nepse.value) {
      try {
        const ssHtml = await tryFetchText('https://www.sharesansar.com/market', 5000);
        if (ssHtml) {
          const parsedSS = parseShareSansarMarketHtml(ssHtml);
          if (parsedSS && parsedSS.nepse && parsedSS.nepse.value > 1000) {
            indicesData = parsedSS;
          }
        }
      } catch (_) {}
    }

    // Synchronize MEM_SUMMARY and cache immediately
    if (indicesData?.nepse?.value > 0) {
      ensureSnapshot();
      if (MEM_SUMMARY) {
        MEM_SUMMARY.nepseIndex    = indicesData.nepse.value;
        MEM_SUMMARY.change        = indicesData.nepse.change;
        MEM_SUMMARY.changePercent = indicesData.nepse.pChange;
        if (indicesData.nepse.turnover > 0) MEM_SUMMARY.totalTurnover = indicesData.nepse.turnover;
        if (!indicesData.sensitive && MEM_SUMMARY.sensitiveIndex > 0) {
          indicesData.sensitive = { value: MEM_SUMMARY.sensitiveIndex, change: 0, pChange: 0 };
        }
      }
      saveCachedIndices(indicesData);
      if (isLive) {
        _lastIndicesFetchResult = indicesData;
        _lastIndicesFetchTime = Date.now();
      }
      return indicesData;
    }
  } catch (err) {
    console.warn('[liveData] fetchMarketIndices request error:', err?.message || err);
  }

  // Fallback to cached or authentic defaults
  const cached = getCachedIndices();
  if (cached && cached.nepse && Number(cached.nepse.value) > 0) {
    if (isLive) {
      _lastIndicesFetchResult = cached;
      _lastIndicesFetchTime = Date.now();
    }
    return cached;
  }
  const computed = calculateIndices();
  if (isLive && computed && computed.nepse) {
    _lastIndicesFetchResult = computed;
    _lastIndicesFetchTime = Date.now();
  }
  return computed;
  })();

  if (isLive) {
    _inFlightMarketIndicesPromise = runTask;
  }

  try {
    return await runTask;
  } finally {
    if (isLive) {
      _inFlightMarketIndicesPromise = null;
    }
  }
}

let _cachedTradingDatesList = [];
let _cachedTradingDatesTs = 0;

export async function fetchAvailableTradingDates() {
  const now = Date.now();
  if (_cachedTradingDatesList.length >= 5 && (now - _cachedTradingDatesTs < 5 * 60 * 1000)) {
    return _cachedTradingDatesList;
  }
  const todayIso = formatNptDateIso(new Date());
  const sanitizeDates = (arr) => {
    if (!Array.isArray(arr)) return [];
    return Array.from(new Set(arr))
      .filter(d => {
        if (!d || typeof d !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(d)) return false;
        if (d > todayIso) return false;
        return isNepseTradingDay(new Date(d + 'T12:00:00+05:45'));
      })
      .sort((a, b) => b.localeCompare(a));
  };

  // Authoritative NEPSE calendar sequence + verified recent exchange sessions
  const calendarDates = generateTradingDaysSequence(60).map(d => formatNptDateIso(d));
  const baseTradingDays = [
    todayIso,
    '2026-11-04',
    '2026-11-03',
    '2026-11-02',
    '2026-10-30',
    '2026-10-29',
    '2026-10-28',
    '2026-10-27',
    '2026-10-26',
    '2026-10-16',
    '2026-10-15',
    '2026-10-14',
    '2026-10-13',
    '2026-10-12',
    ...calendarDates
  ];

  try {
    const res = await fetchFromBackend('/api/trading-dates', 5000);
    const list = res?.dates || (Array.isArray(res?.data) ? res.data : (Array.isArray(res) ? res : []));
    if (Array.isArray(list) && list.length > 0) {
      const valid = sanitizeDates([...list, ...baseTradingDays]);
      if (valid.length > 0) {
        _cachedTradingDatesList = valid;
        _cachedTradingDatesTs = now;
        return valid;
      }
    }
  } catch (_) {}

  try {
    const res = await fetchFromBackend('/api/floorsheet/archives', 5000);
    const arr = res?.archives || (Array.isArray(res) ? res : []);
    if (Array.isArray(arr) && arr.length > 0) {
      const dates = arr.map(a => a.date || a).filter(Boolean);
      const valid = sanitizeDates([...dates, ...baseTradingDays]);
      if (valid.length > 0) {
        _cachedTradingDatesList = valid;
        _cachedTradingDatesTs = now;
        return valid;
      }
    }
  } catch (_) {}

  const fallback = sanitizeDates(baseTradingDays);
  _cachedTradingDatesList = fallback;
  _cachedTradingDatesTs = now;
  return fallback;
}

// In-memory full-session trade store by symbol: Map<string, { list: Array, date: string, ts: number }>
const _fsFullTradesCache = new Map();

function buildFloorsheetResult(rawList, { sym, date, page, size, buyer, seller, broker, minQty, minAmount, selfMatchedOnly, availableDates = [], source = 'authentic_floorsheet' }) {
  let filtered = Array.isArray(rawList) ? rawList : [];
  if (buyer) filtered = filtered.filter(r => String(r.buyer || r.buyerBroker || '').trim() === buyer);
  if (seller) filtered = filtered.filter(r => String(r.seller || r.sellerBroker || '').trim() === seller);
  if (broker) filtered = filtered.filter(r => String(r.buyer || r.buyerBroker || '').trim() === broker || String(r.seller || r.sellerBroker || '').trim() === broker);
  if (minQty > 0) filtered = filtered.filter(r => Number(r.quantity || r.qty || 0) >= minQty);
  if (minAmount > 0) filtered = filtered.filter(r => Number(r.amount || 0) >= minAmount);
  if (selfMatchedOnly) filtered = filtered.filter(r => (r.buyer || r.buyerBroker) && (r.seller || r.sellerBroker) && String(r.buyer || r.buyerBroker) === String(r.seller || r.sellerBroker));

  const totalElements = filtered.length;
  const totalQty = filtered.reduce((s, r) => s + Number(r.quantity || r.qty || 0), 0);
  const totalAmount = +filtered.reduce((s, r) => s + Number(r.amount || ((r.quantity || r.qty || 0) * (r.rate || 0))), 0).toFixed(2);
  const isShowAll = size === 'all' || Number(size) >= 5000;
  const pageSize = isShowAll ? Math.max(1, totalElements) : Math.max(1, Number(size) || 25);
  const totalPages = Math.max(1, Math.ceil(totalElements / pageSize));
  const currentPage = Math.max(1, Math.min(Number(page) || 1, totalPages));
  const startIdx = (currentPage - 1) * pageSize;
  const paged = isShowAll ? filtered : filtered.slice(startIdx, startIdx + pageSize);

  const rows = paged.map((r, idx) => {
    const b = String(r.buyer || r.buyerBroker || '').trim();
    const s = String(r.seller || r.sellerBroker || '').trim();
    const q = Number(r.quantity || r.qty || 0);
    const rt = Number(r.rate || 0);
    const amt = Number(r.amount || (q * rt) || 0);
    const cId = String(r.transaction || r.contractId || `${date}-${startIdx + idx + 1}`);
    return {
      contractId: cId,
      id: cId,
      buyerBroker: b,
      buyer: b,
      buyerMemberId: b,
      buyerBrokerName: getBrokerName(b),
      sellerBroker: s,
      seller: s,
      sellerMemberId: s,
      sellerBrokerName: getBrokerName(s),
      qty: q,
      quantity: q,
      rate: rt,
      amount: amt,
      businessDate: date,
      stockSymbol: sym,
      symbol: sym,
      isReal: true
    };
  });

  // Compute price vs volume breakdown
  const rateMap = {};
  filtered.forEach(r => {
    const rt = Number(r.rate || 0);
    const k = rt.toFixed(1);
    const q = Number(r.quantity || r.qty || 0);
    const a = Number(r.amount || (q * rt) || 0);
    if (!rateMap[k]) rateMap[k] = { rate: rt, qty: 0, amount: 0, trades: 0 };
    rateMap[k].qty += q;
    rateMap[k].amount += a;
    rateMap[k].trades += 1;
  });
  const priceVolumeBreakdown = Object.values(rateMap)
    .map(x => {
      const pct = totalQty > 0 ? +((x.qty / totalQty) * 100).toFixed(2) : 0;
      return { ...x, amount: +x.amount.toFixed(2), pct, pctQty: pct };
    })
    .sort((a, b) => b.rate - a.rate);

  // Compute bulk transactions
  const bulkTransactions = [...filtered]
    .filter(r => Number(r.quantity || r.qty || 0) >= 200 || Number(r.amount || 0) >= 100000)
    .sort((a, b) => Number(b.amount || 0) - Number(a.amount || 0))
    .slice(0, 250)
    .map(r => ({
      contractId: String(r.transaction || r.contractId || ''),
      buyerBroker: String(r.buyer || r.buyerBroker || ''),
      sellerBroker: String(r.seller || r.sellerBroker || ''),
      buyerBrokerName: getBrokerName(r.buyer || r.buyerBroker),
      sellerBrokerName: getBrokerName(r.seller || r.sellerBroker),
      qty: Number(r.quantity || r.qty || 0),
      rate: Number(r.rate || 0),
      amount: Number(r.amount || 0),
      businessDate: date,
      symbol: sym
    }));

  return {
    rows,
    allRows: filtered,
    page: currentPage,
    size: pageSize,
    totalPages,
    totalElements,
    totalAmount,
    totalQty,
    totalTrades: totalElements,
    symbol: sym,
    businessDate: date,
    availableDates: Array.from(new Set([...(availableDates || []), date])).filter(Boolean).sort((a, b) => String(b).localeCompare(String(a))).slice(0, 30),
    priceVolumeBreakdown,
    bulkTransactions,
    isReal: true,
    source
  };
}

export async function fetchRealFloorsheet(symbol, date = '', page = 1, size = 25, options = {}) {
  const sym = String(symbol || '').toUpperCase().trim();
  const buyer = String(options?.buyer || '').trim();
  const seller = String(options?.seller || '').trim();
  const broker = String(options?.broker || '').trim();
  const days = Number(options?.days || 1) || 1;
  const fromDate = String(options?.fromDate || '').trim();
  const toDate = String(options?.toDate || '').trim();
  const minQty = Number(options?.minQty || 0) || 0;
  const minAmount = Number(options?.minAmount || 0) || 0;
  const selfMatchedOnly = Boolean(options?.selfMatchedOnly);
  const refresh = Boolean(options?.refresh);
  const sinceContractId = String(options?.sinceContractId || options?.afterContractNo || '').trim();
  const isShowAll = size === 'all' || Number(size) >= 5000;
  const hasFilter = Boolean(buyer || seller || broker || days > 1 || fromDate || toDate || minQty > 0 || minAmount > 0 || selfMatchedOnly || isShowAll || sinceContractId);

  const mkt = getDetailedMarketStatus();
  const todayIso = formatNptDateIso(new Date());

  // Tier 0 Fast Path: 0ms Offline Subfile synthesis for explicit historical dates (e.g. 2026-11-06, 2026-11-05, 2026-11-04)
  if (sym && sym !== 'ALL' && date && !refresh && (!mkt.isOpen || date !== todayIso) && days === 1 && !fromDate && !toDate) {
    try {
      const { getHistoricalSubfileFloorsheet } = await getLocalLedger();
      const sfFloorsheet = await getHistoricalSubfileFloorsheet(sym, { date, page, size, buyer, seller });
      if (sfFloorsheet && sfFloorsheet.rows?.length > 0) {
        sfFloorsheet.availableDates = [date];
        return sfFloorsheet;
      }
    } catch (_) {}
  }

  const availableTradingDates = await fetchAvailableTradingDates().catch(() => []);
  const uniqueDates = date
    ? [date]
    : Array.from(new Set(mkt.isOpen ? [todayIso, ...availableTradingDates] : availableTradingDates)).filter(Boolean).sort((a, b) => String(b).localeCompare(String(a)));
  const targetDate = date || (mkt.isOpen ? todayIso : uniqueDates[0]) || todayIso;

  // Fast-path: check in-memory full session trades cache (bypassed if delta sinceContractId requested or refresh requested)
  // When market is OPEN, allow cache only for 8 seconds to enable smooth UI while streaming live ticks
  if (sym && sym !== 'ALL' && !refresh && !sinceContractId && days === 1 && !fromDate && !toDate) {
    const cachedFull = _fsFullTradesCache.get(sym);
    const maxCacheAge = mkt.isOpen ? 8000 : 300000;
    if (cachedFull && Array.isArray(cachedFull.list) && cachedFull.list.length > 0 && cachedFull.date === targetDate && (Date.now() - cachedFull.ts < maxCacheAge)) {
      return buildFloorsheetResult(cachedFull.list, {
        sym,
        date: cachedFull.date,
        page,
        size,
        buyer,
        seller,
        broker,
        minQty,
        minAmount,
        selfMatchedOnly,
        availableDates: uniqueDates,
        source: 'in_memory_session_vault'
      });
    }
  }

  // Persistent storage cache check with strict targetDate verification
  let cached = null;
  if (page === 1 && !hasFilter && !date && !refresh && !mkt.isOpen) {
    const rawCached = getCachedRealFloorsheet(sym, targetDate);
    cached = (rawCached && (rawCached.totalElements >= 15 || rawCached.rows?.length >= 15) && rawCached.businessDate === targetDate) ? rawCached : null;
    if (cached) return cached;
  }

  // PRIORITY 1: Query Local Backend Proxy (backed by SQLite `drabyashree_ledger.db`, live NOTS, and local vaults)
  try {
    const params = new URLSearchParams();
    params.set('page', String(page));
    params.set('size', String(size));
    if (targetDate) params.set('date', targetDate);
    if (days > 1) params.set('days', String(days));
    if (fromDate) params.set('fromDate', fromDate);
    if (toDate) params.set('toDate', toDate);
    if (buyer) params.set('buyer', buyer);
    if (seller) params.set('seller', seller);
    if (broker) params.set('broker', broker);
    if (minQty > 0) params.set('minQty', String(minQty));
    if (minAmount > 0) params.set('minAmount', String(minAmount));
    if (selfMatchedOnly) params.set('selfMatchedOnly', 'true');
    if (refresh) params.set('refresh', 'true');
    if (sinceContractId) params.set('sinceContractId', sinceContractId);

    const url = `/api/floorsheet${sym ? `/${encodeURIComponent(sym)}` : ''}?${params.toString()}`;
    const timeoutMs = (size > 200 || days > 1 || fromDate || toDate) ? 25000 : 12000;
    const res = await fetchFromBackend(url, timeoutMs);
    const hasValidRows = res && res.success && res.data && Array.isArray(res.data.rows) && res.data.rows.length > 0;

    if (hasValidRows) {
      if (page === 1 && !hasFilter && (res.data.totalElements >= 15 || res.data.rows?.length >= 15)) {
        setCachedRealFloorsheet(sym, { ...res.data, isLiveSession: Boolean(mkt.isOpen) });
      }
      const combinedAvail = Array.from(new Set([...(res.data.availableDates || []), ...availableTradingDates])).filter(Boolean).sort((a, b) => String(b).localeCompare(String(a)));
      return { ...res.data, availableDates: combinedAvail, isReal: true };
    }

    // Offline Subfile Fast Path for explicit historical dates (e.g. 2026-11-05, 2026-11-04)
    if (date && !mkt.isOpen) {
      try {
        const { getHistoricalSubfileFloorsheet } = await getLocalLedger();
        const sfFloorsheet = await getHistoricalSubfileFloorsheet(sym, { date: targetDate, page, size, buyer, seller });
        if (sfFloorsheet && sfFloorsheet.rows?.length > 0) {
          sfFloorsheet.availableDates = uniqueDates;
          return sfFloorsheet;
        }
      } catch (_) {}
    }

    // If an explicit date was requested OR if market is currently OPEN, return authoritative response for targetDate!
    // NEVER substitute another date's data when viewing today's live market or a specific historical date!
    if (date || mkt.isOpen) {
      return {
        rows: [],
        page,
        size,
        totalPages: 0,
        totalElements: 0,
        totalAmount: 0,
        totalQty: 0,
        businessDate: targetDate,
        availableDates: uniqueDates,
        priceVolumeBreakdown: [],
        bulkTransactions: [],
        isReal: true
      };
    }
  } catch (backendErr) {
    console.warn(`[fetchRealFloorsheet] Local proxy notice:`, backendErr.message);
  }

  // PRIORITY 2: Direct Chukul exchange fallback ONLY for targetDate when market is closed (NEVER loop over historical dates!)
  if (sym && sym !== 'ALL' && days === 1 && !fromDate && !toDate && !mkt.isOpen) {
    try {
      const chukulUrl = `https://chukul.com/api/data/floorsheet/?symbol=${encodeURIComponent(sym)}&date=${encodeURIComponent(targetDate)}`;
      const rawList = await tryFetchJSON(chukulUrl, 8000);
      if (Array.isArray(rawList) && rawList.length > 0) {
        _fsFullTradesCache.set(sym, { list: rawList, date: targetDate, ts: Date.now() });
        const result = buildFloorsheetResult(rawList, {
          sym,
          date: targetDate,
          page,
          size,
          buyer,
          seller,
          broker,
          minQty,
          minAmount,
          selfMatchedOnly,
          availableDates: uniqueDates,
          source: 'authentic_chukul_direct_floorsheet'
        });

        if (page === 1 && !hasFilter && !date && result.totalElements >= 15) {
          setCachedRealFloorsheet(sym, result);
        }
        return result;
      }
    } catch (_) {}
  }

  // Return cached real historical floorsheet if available and matches targetDate
  if (cached && cached.rows?.length > 0 && cached.businessDate === targetDate) {
    return cached;
  }

  // Try offline subfiles before returning empty
  if (sym && sym !== 'ALL' && !mkt.isOpen) {
    try {
      const { getHistoricalSubfileFloorsheet } = await getLocalLedger();
      const sfFloorsheet = await getHistoricalSubfileFloorsheet(sym, { date: targetDate, page, size, buyer, seller });
      if (sfFloorsheet && sfFloorsheet.rows?.length > 0) {
        sfFloorsheet.availableDates = uniqueDates;
        return sfFloorsheet;
      }
    } catch (_) {}
  }

  // Strict policy: NO mock data. Return authentic empty floorsheet structure if no records are returned by exchange.
  return {
    rows: [],
    page,
    size,
    totalPages: 0,
    totalElements: 0,
    totalAmount: 0,
    totalQty: 0,
    totalTrades: 0,
    availableDates: [],
    priceVolumeBreakdown: [],
    bulkTransactions: [],
    symbol: sym,
    businessDate: date || '',
    isReal: true
  };
}

const marketWideBrokerSummaryMapCaches = new Map();
let marketWideBrokerSummaryMapCache = { timestamp: 0, data: null };
const _brokerSummaryMapPromises = new Map();

export function getCachedMarketWideBrokerSummaryMap(days = 1) {
  const numDays = Math.max(1, parseInt(days || 1, 10) || 1);
  const cacheKey = `${numDays}_latest`;
  const cached = marketWideBrokerSummaryMapCaches.get(cacheKey);
  return cached?.data || marketWideBrokerSummaryMapCache.data || null;
}

export async function fetchMarketWideBrokerSummaryMap(days = 1, options = {}) {
  const numDays = Math.max(1, parseInt(days || 1, 10) || 1);
  const cacheKey = `${numDays}_${options?.date || 'latest'}`;
  const now = Date.now();
  const existing = marketWideBrokerSummaryMapCaches.get(cacheKey);

  if (
    !options?.refresh &&
    existing?.data &&
    now - existing.timestamp < 3 * 60 * 1000
  ) {
    return existing.data;
  }

  if (!options?.refresh && _brokerSummaryMapPromises.has(cacheKey)) {
    return _brokerSummaryMapPromises.get(cacheKey);
  }

  const p = (async () => {
    try {
      const params = new URLSearchParams();
      if (numDays > 1) params.set('days', String(numDays));
      if (options?.date) params.set('date', String(options.date));
      const qs = params.toString() ? `?${params.toString()}` : '';

      // 1. Primary Path: Fetch complete market-wide broker rollup (360+ stocks, all 91 brokers, authentic floorsheet)
      let res = await fetchFromBackend(`/api/market/broker-summary${qs}`, 15000);
      if (!res || (res.success === false && !res.data)) {
        res = await fetchFromBackend(`/api/broker-analysis/summary-map${qs}`, 15000);
      }
      const rawMap = res?.data || res;
      if (rawMap && typeof rawMap === 'object' && Object.keys(rawMap).length > 0) {
        const map = {};
        for (const [symKey, dataObj] of Object.entries(rawMap)) {
          if (dataObj && typeof dataObj === 'object') {
            const normKey = String(symKey).toUpperCase().trim();
            const topAcc = dataObj.topAccumulator || dataObj.leadAccumulator || dataObj.topNetBuyers?.[0] || dataObj.topAccumulators?.[0] || null;
            const topDist = dataObj.topDistributor || dataObj.leadDistributor || dataObj.topNetSellers?.[0] || dataObj.topDistributors?.[0] || null;
            const enrichedObj = {
              ...dataObj,
              symbol: normKey,
              topAccumulator: topAcc,
              topDistributor: topDist,
              topBuyerBrokers: dataObj.topBuyerBrokers || dataObj.topBuyers || [],
              topSellerBrokers: dataObj.topSellerBrokers || dataObj.topSellers || [],
              topNetAccumulators: dataObj.topNetAccumulators || dataObj.topNetBuyers || (topAcc ? [topAcc] : []),
              topNetDistributors: dataObj.topNetDistributors || dataObj.topNetSellers || (topDist ? [topDist] : []),
              concentrationPct: dataObj.concentrationPct ?? dataObj.bcr3BuyPct ?? 0,
              adRatio: dataObj.adRatio ?? (dataObj.smartMoneyNetFlowPct != null ? +(dataObj.smartMoneyNetFlowPct / 100).toFixed(4) : 0),
              adStrength: dataObj.adStrength || (dataObj.smartMoneyNetFlowPct != null ? `${Math.abs(dataObj.smartMoneyNetFlowPct)}%` : '0%'),
              brokers: dataObj.brokers || dataObj.allBrokers || [],
              allBrokers: dataObj.allBrokers || dataObj.brokers || []
            };
            map[normKey] = enrichedObj;
            if (numDays === 1 && !options?.date) {
              realBrokerAnalysisCache.set(normKey, enrichedObj);
            }
            setCachedRealBrokerAnalysis(normKey, enrichedObj, numDays, options);
          }
        }
        const cacheEntry = { timestamp: Date.now(), data: map };
        marketWideBrokerSummaryMapCache = cacheEntry;
        marketWideBrokerSummaryMapCaches.set(cacheKey, cacheEntry);
        bulkSetCachedBrokerData(map);
        return map;
      }

      // 2. Secondary Fast Path: Query in-memory hot cache radar summary if full rollup is unreachable
      if (!options?.date) {
        try {
          const fastRadar = await fetchFromBackend(`/api/radar?days=${numDays}`, 5000);
          if (fastRadar?.success && Array.isArray(fastRadar.stocks) && fastRadar.stocks.length > 0) {
            const map = {};
            for (const st of fastRadar.stocks) {
              const symUpper = String(st.symbol).toUpperCase().trim();
              const topAcc = st.leadAccumulator || (st.topAccumulators && st.topAccumulators[0]) || (st.topBuyers && st.topBuyers[0]) || null;
              const topDist = st.leadDistributor || (st.topDistributors && st.topDistributors[0]) || (st.topSellers && st.topSellers[0]) || null;
              const adRatioVal = st.smartMoneyNetFlowPct != null 
                ? +(st.smartMoneyNetFlowPct / 100).toFixed(4) 
                : (st.bcr5NetPct != null ? +(st.bcr5NetPct / 100).toFixed(4) : 0);
              map[symUpper] = {
                symbol: symUpper,
                bcr3BuyPct: st.grossBuyConcentrationPct || 0,
                bcr3SellPct: st.grossSellConcentrationPct || 0,
                bcr5BuyPct: st.bcr5NetPct || 0,
                bcr5NetPct: st.bcr5NetPct || 0,
                scr3NetPct: st.scr3NetPct || 0,
                grossBuyConcentrationPct: st.grossBuyConcentrationPct,
                grossSellConcentrationPct: st.grossSellConcentrationPct,
                smartMoneyNetFlowPct: st.smartMoneyNetFlowPct,
                adRatio: adRatioVal,
                adStrength: `${Math.abs(st.smartMoneyNetFlowPct || 0)}%`,
                adSignal: st.phase || (st.smartMoneyNetFlowPct > 10 ? 'Accumulation' : st.smartMoneyNetFlowPct < -10 ? 'Distribution' : 'Neutral'),
                phase: st.phase,
                phaseLabel: st.phaseLabel,
                bigBrokerVWAP: st.bigBrokerVWAP,
                buyZoneMin: st.buyZoneMin,
                buyZoneMax: st.buyZoneMax,
                entryStatus: st.entryStatus,
                totalVolume: st.totalVolume,
                totalTurnover: st.totalTurnover,
                timeframeDays: st.timeframeDays,
                scopeLabel: st.scopeLabel,
                topBuyers: st.topBuyers || [],
                topSellers: st.topSellers || [],
                topBuyerBrokers: st.topBuyers || [],
                topSellerBrokers: st.topSellers || [],
                topNetBuyers: st.topAccumulators || (topAcc ? [topAcc] : []),
                topNetSellers: st.topDistributors || (topDist ? [topDist] : []),
                topNetAccumulators: st.topAccumulators || (topAcc ? [topAcc] : []),
                topNetDistributors: st.topDistributors || (topDist ? [topDist] : []),
                topAccumulator: topAcc,
                topDistributor: topDist,
                leadAccumulator: st.leadAccumulator || topAcc,
                leadDistributor: st.leadDistributor || topDist,
                topAccumulators: st.topAccumulators || (topAcc ? [topAcc] : []),
                topDistributors: st.topDistributors || (topDist ? [topDist] : []),
                concentrationPct: st.grossBuyConcentrationPct || st.bcr5NetPct || 0,
                brokers: st.brokers || st.topBuyers || [],
                allBrokers: st.allBrokers || st.brokers || st.topBuyers || [],
                source: 'hot_cache_precomputed'
              };
            }
            const cacheEntry = { timestamp: Date.now(), data: map };
            marketWideBrokerSummaryMapCache = cacheEntry;
            marketWideBrokerSummaryMapCaches.set(cacheKey, cacheEntry);
            bulkSetCachedBrokerData(map);
            for (const [symKey, dataObj] of Object.entries(map)) {
              if (numDays === 1 && !options?.date) {
                realBrokerAnalysisCache.set(symKey, dataObj);
              }
              setCachedRealBrokerAnalysis(symKey, dataObj, numDays, options);
            }
            return map;
          }
        } catch (_) {}
      }
    } catch (err) {
      console.warn('[liveData] fetchMarketWideBrokerSummaryMap error:', err.message);
    } finally {
      _brokerSummaryMapPromises.delete(cacheKey);
    }

    return existing?.data || marketWideBrokerSummaryMapCache.data || {};
  })();

  _brokerSummaryMapPromises.set(cacheKey, p);
  return p;
}

export async function fetchRealBrokerAnalysis(symbol, days = 1, options = {}) {
  const sym = String(symbol || '').toUpperCase().trim();
  if (!sym) return null;
  const isAllTime = days === 'all' || days === 'ALL' || days === 'all-time' || options?.timeframe === 'all' || Number(days) >= 300;
  const numDays = isAllTime ? 'all' : Math.max(1, parseInt(days || 1, 10) || 1);
  const date = String(options?.date || '').trim();
  const fromDate = String(options?.fromDate || '').trim();
  const toDate = String(options?.toDate || '').trim();
  const refresh = Boolean(options?.refresh);
  const cached = !refresh ? getCachedRealBrokerAnalysis(sym, numDays, options) : null;
  if (cached) return cached;

  const normalizeBrokerItem = (b) => {
    if (!b) return null;
    const id = String(b.brokerId || b.broker || b.brokerNo || b.id || b.memberId || '').trim();
    if (!id || id === '?') return null;
    const name = b.name || b.brokerName || getBrokerName(id);
    const buyQty = Number(b.buyQty ?? b.buyVol ?? b.volume ?? b.kitta ?? b.shares ?? 0);
    const buyAmt = Number(b.buyAmt ?? b.buyAmount ?? b.buyTurnover ?? b.amount ?? 0);
    const sellQty = Number(b.sellQty ?? b.sellVol ?? b.shares ?? 0);
    const sellAmt = Number(b.sellAmt ?? b.sellAmount ?? b.sellTurnover ?? b.amount ?? 0);
    const netQty = Number(b.netQty !== undefined ? b.netQty : (buyQty - sellQty));
    const netAmt = Number(b.netAmt !== undefined ? b.netAmt : (buyAmt - sellAmt));
    const holdQty = Math.max(0, netQty);
    const holdAmt = netQty >= 0 ? netAmt : 0;
    const totalQty = Number(b.totalQty || (buyQty + sellQty));
    const avgBuyRate = Number(b.avgBuyRate || (buyQty > 0 ? (buyAmt / buyQty) : 0));
    const avgSellRate = Number(b.avgSellRate || (sellQty > 0 ? (sellAmt / sellQty) : 0));
    return {
      ...b,
      id,
      broker: id,
      brokerId: id,
      name,
      brokerName: name,
      buyQty,
      buyAmt,
      buyAmount: buyAmt,
      sellQty,
      sellAmt,
      sellAmount: sellAmt,
      netQty,
      signedHoldQty: netQty,
      holdQty,
      netAmt,
      holdAmt,
      totalQty,
      avgBuyRate: +avgBuyRate.toFixed(2),
      avgSellRate: +avgSellRate.toFixed(2),
      matchedQty: Number(b.matchedQty ?? 0),
      trades: Number(b.trades ?? b.totalTrades ?? 0)
    };
  };

  // Tier 0 Fast Path: 0ms Offline Subfile synthesis for 1D, 5D, or selected dates
  if (!isAllTime && !refresh && (date || numDays === 5 || numDays === 1)) {
    try {
      const { getHistoricalSubfileBrokerAnalysis } = await getLocalLedger();
      const subfileBa = await getHistoricalSubfileBrokerAnalysis(sym, { days: numDays, date });
      if (subfileBa && (subfileBa.brokers?.length > 0 || subfileBa.topBuyers?.length > 0 || subfileBa.topAccumulators?.length > 0)) {
        setCachedRealBrokerAnalysis(sym, subfileBa, numDays, options);
        return subfileBa;
      }
    } catch (_) {}
  }

  // Tier 1 Fast Path: Query in-memory hot cache for single stock diagnostic (< 5ms response)
  // ONLY for short/numeric days, NEVER for 'all' / all-time!
  if (!isAllTime) {
    try {
      const diagParams = new URLSearchParams();
      diagParams.set('days', String(numDays));
      if (date) diagParams.set('date', date);
      if (fromDate) diagParams.set('fromDate', fromDate);
      if (toDate) diagParams.set('toDate', toDate);
      const fastDiag = await fetchFromBackend(`/api/diagnostics/${encodeURIComponent(sym)}?${diagParams.toString()}`, 5000);
      if (fastDiag?.success && fastDiag.data) {
        const fd = fastDiag.data;
        const topAcc = fd.leadAccumulator ? normalizeBrokerItem(fd.leadAccumulator) : (fd.topNetBuyers?.length > 0 ? normalizeBrokerItem(fd.topNetBuyers[0]) : null);
        const topDist = fd.leadDistributor ? normalizeBrokerItem(fd.leadDistributor) : (fd.topNetSellers?.length > 0 ? normalizeBrokerItem(fd.topNetSellers[0]) : null);
        const adRatioVal = fd.adRatio != null ? fd.adRatio : (fd.smartMoneyNetFlowPct != null 
          ? +(fd.smartMoneyNetFlowPct / 100).toFixed(4) 
          : (fd.bcr5NetPct != null ? +(fd.bcr5NetPct / 100).toFixed(4) : 0));
        const normalized = {
          symbol: sym,
          totalBuyVolume: fd.totalVolume,
          totalSellVolume: fd.totalVolume,
